CREATE OR REPLACE FUNCTION "app_private"."delivery_pin_for_session"("p_session_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app_private', 'public', 'extensions'
    AS $$
  select lpad(
    (
      (
        ('x' || substr(
          encode(
            extensions.hmac(
              convert_to(p_session_id::text, 'utf8'),
              convert_to(s.secret, 'utf8'),
              'sha256'::text
            ),
            'hex'
          ),
          1,
          12
        ))::bit(48)::bigint % 1000000
      )::text
    ),
    6,
    '0'
  )
  from app_private.delivery_pin_secrets s
  where s.id = true;
$$;


ALTER FUNCTION "app_private"."delivery_pin_for_session"("p_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "club"."apply_redeem_debit"("p_loyalty_redemption_id" "uuid", "p_amount_minor" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'club', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_redemption record;
  v_wallet club.wallet_accounts%rowtype;
  v_debit_ledger_id uuid;
begin
  if v_user_id is null then
    raise exception 'auth.uid() is null';
  end if;
  if p_amount_minor is null or p_amount_minor <= 0 then
    raise exception 'p_amount_minor must be greater than zero';
  end if;

  select lr.id, lr.user_id
  into v_redemption
  from public.loyalty_redemptions lr
  where lr.id = p_loyalty_redemption_id
  limit 1;

  if v_redemption.id is null then
    raise exception 'redemption not found';
  end if;

  if v_redemption.user_id is distinct from v_user_id then
    raise exception 'redemption does not belong to auth user';
  end if;

  if exists (
    select 1
    from club.redemption_links rl
    where rl.loyalty_redemption_id = p_loyalty_redemption_id
  ) then
    return jsonb_build_object(
      'success', true,
      'already_linked', true
    );
  end if;

  insert into club.wallet_accounts (user_id)
  values (v_user_id)
  on conflict (user_id) do nothing;

  select *
  into v_wallet
  from club.wallet_accounts
  where user_id = v_user_id
  for update;

  if coalesce(v_wallet.available_minor, 0) < p_amount_minor then
    raise exception 'insufficient club wallet balance';
  end if;

  insert into club.wallet_ledger (
    user_id, kind, amount_minor, reference_type, reference_id, description, metadata
  )
  values (
    v_user_id,
    'redeem_debit',
    -p_amount_minor,
    'redemption',
    p_loyalty_redemption_id,
    'Debito por redencion en Vento Pass',
    jsonb_build_object('loyalty_redemption_id', p_loyalty_redemption_id)
  )
  returning id into v_debit_ledger_id;

  update club.wallet_accounts
  set
    available_minor = available_minor - p_amount_minor,
    updated_at = now()
  where user_id = v_user_id;

  insert into club.redemption_links (
    user_id,
    loyalty_redemption_id,
    debit_ledger_id,
    amount_minor
  )
  values (
    v_user_id,
    p_loyalty_redemption_id,
    v_debit_ledger_id,
    p_amount_minor
  );

  return jsonb_build_object(
    'success', true,
    'amount_minor', p_amount_minor,
    'debit_ledger_id', v_debit_ledger_id
  );
end;
$$;


ALTER FUNCTION "club"."apply_redeem_debit"("p_loyalty_redemption_id" "uuid", "p_amount_minor" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "club"."can_access_beta"() RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'club', 'auth'
    AS $$
  select exists (
    select 1
    from club.beta_access b
    where b.user_id = auth.uid()
      and b.enabled = true
  );
$$;


ALTER FUNCTION "club"."can_access_beta"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "club"."get_my_membership"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'club', 'auth'
    AS $$
  with ent as (
    select
      e.club_active,
      e.plan_code,
      e.effective_from,
      e.effective_until,
      e.updated_at
    from club.entitlements e
    where e.user_id = auth.uid()
    limit 1
  ),
  sub as (
    select
      s.status,
      s.current_period_start,
      s.current_period_end,
      s.cancel_at_period_end,
      p.name as plan_name,
      p.currency,
      p.price_minor
    from club.subscriptions s
    left join club.plans p on p.id = s.plan_id
    where s.user_id = auth.uid()
    order by s.created_at desc
    limit 1
  )
  select jsonb_build_object(
    'beta_access', club.can_access_beta(),
    'club_active', coalesce((select club_active from ent), false),
    'plan_code', (select plan_code from ent),
    'effective_from', (select effective_from from ent),
    'effective_until', (select effective_until from ent),
    'subscription', (
      select jsonb_build_object(
        'status', sub.status,
        'current_period_start', sub.current_period_start,
        'current_period_end', sub.current_period_end,
        'cancel_at_period_end', sub.cancel_at_period_end,
        'plan_name', sub.plan_name,
        'currency', sub.currency,
        'price_minor', sub.price_minor
      )
      from sub
    )
  );
$$;


ALTER FUNCTION "club"."get_my_membership"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "club"."get_my_wallet"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'club', 'auth'
    AS $$
  with account as (
    select
      a.available_minor,
      a.pending_minor,
      a.currency,
      a.updated_at
    from club.wallet_accounts a
    where a.user_id = auth.uid()
    limit 1
  )
  select jsonb_build_object(
    'available_minor', coalesce((select available_minor from account), 0),
    'pending_minor', coalesce((select pending_minor from account), 0),
    'currency', coalesce((select currency from account), 'COP'),
    'updated_at', (select updated_at from account)
  );
$$;


ALTER FUNCTION "club"."get_my_wallet"() OWNER TO "postgres";

SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "club"."wallet_ledger" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "kind" "text" NOT NULL,
    "amount_minor" integer NOT NULL,
    "reference_type" "text",
    "reference_id" "uuid",
    "description" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "wallet_ledger_kind_check" CHECK (("kind" = ANY (ARRAY['cashback_pending'::"text", 'cashback_approved'::"text", 'redeem_debit'::"text", 'adjustment'::"text", 'reversal'::"text"])))
);


ALTER TABLE "club"."wallet_ledger" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "club"."list_my_wallet_ledger"("p_limit" integer DEFAULT 50, "p_before" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS SETOF "club"."wallet_ledger"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'club', 'auth'
    AS $$
  select wl.*
  from club.wallet_ledger wl
  where wl.user_id = auth.uid()
    and (p_before is null or wl.created_at < p_before)
  order by wl.created_at desc
  limit greatest(1, least(coalesce(p_limit, 50), 200));
$$;


ALTER FUNCTION "club"."list_my_wallet_ledger"("p_limit" integer, "p_before" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "club"."preview_booster_for_order"("p_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'club', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_rule club.cashback_rules%rowtype;
  v_order record;
  v_order_minor integer := 0;
  v_month_start timestamptz := date_trunc('month', now());
  v_month_used integer := 0;
  v_raw integer := 0;
  v_after_order_cap integer := 0;
  v_remaining_month integer := 0;
  v_final integer := 0;
  v_has_entitlement boolean := false;
begin
  if v_user_id is null then
    raise exception 'auth.uid() is null';
  end if;

  select (e.club_active = true and (e.effective_until is null or e.effective_until > now()))
  into v_has_entitlement
  from club.entitlements e
  where e.user_id = v_user_id;

  if not coalesce(v_has_entitlement, false) then
    return jsonb_build_object(
      'eligible', false,
      'reason', 'no_entitlement',
      'booster_minor', 0
    );
  end if;

  select r.*
  into v_rule
  from club.cashback_rules r
  where r.is_active = true
  order by r.created_at desc
  limit 1;

  if v_rule.id is null then
    return jsonb_build_object(
      'eligible', false,
      'reason', 'no_active_rule',
      'booster_minor', 0
    );
  end if;

  select o.id, o.client_id, o.source, o.status, coalesce(o.total_amount, 0) as total_amount
  into v_order
  from public.orders o
  where o.id = p_order_id
  limit 1;

  if v_order.id is null then
    return jsonb_build_object(
      'eligible', false,
      'reason', 'order_not_found',
      'booster_minor', 0
    );
  end if;

  if v_order.client_id is distinct from v_user_id then
    return jsonb_build_object(
      'eligible', false,
      'reason', 'order_not_owned',
      'booster_minor', 0
    );
  end if;

  if coalesce(v_order.source, '') <> 'vento_pass' then
    return jsonb_build_object(
      'eligible', false,
      'reason', 'source_not_eligible',
      'booster_minor', 0
    );
  end if;

  if coalesce(v_order.status, '') not in ('paid', 'completed', 'delivered') then
    return jsonb_build_object(
      'eligible', false,
      'reason', 'order_status_not_eligible',
      'booster_minor', 0
    );
  end if;

  v_order_minor := greatest(0, round((v_order.total_amount::numeric) * 100)::integer);

  if v_order_minor < coalesce(v_rule.min_order_total_minor, 0) then
    return jsonb_build_object(
      'eligible', false,
      'reason', 'below_minimum_order_total',
      'booster_minor', 0,
      'order_total_minor', v_order_minor
    );
  end if;

  select coalesce(sum(greatest(wl.amount_minor, 0)), 0)
  into v_month_used
  from club.wallet_ledger wl
  where wl.user_id = v_user_id
    and wl.kind = 'cashback_approved'
    and wl.created_at >= v_month_start;

  v_raw := floor((v_order_minor::numeric * v_rule.percent_bps::numeric) / 10000.0)::integer;
  v_after_order_cap := case
    when coalesce(v_rule.cap_per_order_minor, 0) > 0
      then least(v_raw, v_rule.cap_per_order_minor)
    else v_raw
  end;
  v_remaining_month := case
    when coalesce(v_rule.cap_monthly_minor, 0) > 0
      then greatest(v_rule.cap_monthly_minor - v_month_used, 0)
    else v_after_order_cap
  end;
  v_final := greatest(least(v_after_order_cap, v_remaining_month), 0);

  return jsonb_build_object(
    'eligible', (v_final > 0),
    'reason', case when v_final > 0 then null else 'monthly_cap_reached' end,
    'booster_minor', v_final,
    'raw_minor', v_raw,
    'order_total_minor', v_order_minor,
    'month_used_minor', v_month_used,
    'month_remaining_minor', v_remaining_month,
    'rule', jsonb_build_object(
      'code', v_rule.code,
      'percent_bps', v_rule.percent_bps,
      'min_order_total_minor', v_rule.min_order_total_minor,
      'cap_per_order_minor', v_rule.cap_per_order_minor,
      'cap_monthly_minor', v_rule.cap_monthly_minor,
      'settlement_delay_hours', v_rule.settlement_delay_hours
    )
  );
end;
$$;


ALTER FUNCTION "club"."preview_booster_for_order"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "club"."reverse_redeem_debit"("p_loyalty_redemption_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'club', 'auth'
    AS $$
declare
  v_link club.redemption_links%rowtype;
  v_reverse_ledger_id uuid;
begin
  if auth.role() <> 'service_role' then
    raise exception 'service_role required';
  end if;

  select *
  into v_link
  from club.redemption_links rl
  where rl.loyalty_redemption_id = p_loyalty_redemption_id
  for update;

  if v_link.id is null then
    return jsonb_build_object('success', false, 'error', 'link_not_found');
  end if;

  if v_link.reversed_at is not null then
    return jsonb_build_object('success', true, 'already_reversed', true);
  end if;

  insert into club.wallet_ledger (
    user_id, kind, amount_minor, reference_type, reference_id, description, metadata
  )
  values (
    v_link.user_id,
    'reversal',
    v_link.amount_minor,
    'redemption',
    p_loyalty_redemption_id,
    coalesce(p_reason, 'Reversion de debito por redencion'),
    jsonb_build_object('loyalty_redemption_id', p_loyalty_redemption_id)
  )
  returning id into v_reverse_ledger_id;

  update club.wallet_accounts
  set
    available_minor = available_minor + v_link.amount_minor,
    updated_at = now()
  where user_id = v_link.user_id;

  update club.redemption_links
  set
    reversed_at = now(),
    reverse_ledger_id = v_reverse_ledger_id
  where id = v_link.id;

  return jsonb_build_object(
    'success', true,
    'reverse_ledger_id', v_reverse_ledger_id
  );
end;
$$;


ALTER FUNCTION "club"."reverse_redeem_debit"("p_loyalty_redemption_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pass"."catalog_item_allowed_option_groups"("p_catalog_item_id" "uuid") RETURNS TABLE("id" "uuid", "catalog_item_id" "uuid", "code" "text", "name" "text", "description" "text", "selection_type" "text", "is_required" boolean, "min_select" integer, "max_select" integer, "sort_order" integer, "is_active" boolean, "metadata" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pass', 'public'
    AS $$
  with own_groups as (
    select
      option_group.id,
      option_group.catalog_item_id,
      option_group.code,
      option_group.name,
      option_group.description,
      option_group.selection_type,
      option_group.is_required,
      option_group.min_select,
      option_group.max_select,
      option_group.sort_order,
      option_group.is_active,
      option_group.metadata,
      0 as template_sort_order
    from pass.catalog_item_option_groups option_group
    where option_group.catalog_item_id = p_catalog_item_id
      and option_group.is_active = true
  ),
  template_groups as (
    select
      option_group.id,
      option_group.catalog_item_id,
      option_group.code,
      option_group.name,
      option_group.description,
      option_group.selection_type,
      option_group.is_required,
      option_group.min_select,
      option_group.max_select,
      option_group.sort_order,
      option_group.is_active,
      option_group.metadata,
      assignment.sort_order + template_group.sort_order as template_sort_order
    from pass.catalog_item_customization_template_assignments assignment
    join pass.catalog_item_customization_templates template
      on template.id = assignment.template_id
     and template.is_active = true
    join pass.catalog_item_customization_template_groups template_group
      on template_group.template_id = template.id
     and template_group.is_active = true
    join pass.catalog_item_option_groups option_group
      on option_group.id = template_group.option_group_id
     and option_group.is_active = true
    join pass.catalog_items item
      on item.id = assignment.catalog_item_id
     and item.is_active = true
    join pass.catalog_items owner_item
      on owner_item.id = option_group.catalog_item_id
     and owner_item.is_active = true
     and owner_item.site_id = item.site_id
    where assignment.catalog_item_id = p_catalog_item_id
      and assignment.is_active = true
      and not exists (
        select 1
        from pass.catalog_item_option_groups own_group
        where own_group.catalog_item_id = p_catalog_item_id
          and own_group.code = option_group.code
          and own_group.is_active = true
      )
  )
  select distinct on (merged.id)
    merged.id,
    merged.catalog_item_id,
    merged.code,
    merged.name,
    merged.description,
    merged.selection_type,
    merged.is_required,
    merged.min_select,
    merged.max_select,
    merged.sort_order,
    merged.is_active,
    merged.metadata
  from (
    select * from own_groups
    union all
    select * from template_groups
  ) merged
  order by merged.id, merged.template_sort_order, merged.sort_order, merged.name;
$$;


ALTER FUNCTION "pass"."catalog_item_allowed_option_groups"("p_catalog_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pass"."catalog_item_option_group_is_allowed"("p_catalog_item_id" "uuid", "p_option_group_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pass', 'public'
    AS $$
  select exists (
    select 1
    from pass.catalog_item_option_groups option_group
    where option_group.id = p_option_group_id
      and option_group.catalog_item_id = p_catalog_item_id
      and option_group.is_active = true
  )
  or exists (
    select 1
    from pass.catalog_item_customization_template_assignments assignment
    join pass.catalog_item_customization_templates template
      on template.id = assignment.template_id
     and template.is_active = true
    join pass.catalog_item_customization_template_groups template_group
      on template_group.template_id = template.id
     and template_group.option_group_id = p_option_group_id
     and template_group.is_active = true
    join pass.catalog_item_option_groups option_group
      on option_group.id = template_group.option_group_id
     and option_group.is_active = true
    join pass.catalog_items item
      on item.id = assignment.catalog_item_id
     and item.is_active = true
    join pass.catalog_items owner_item
      on owner_item.id = option_group.catalog_item_id
     and owner_item.is_active = true
     and owner_item.site_id = item.site_id
    where assignment.catalog_item_id = p_catalog_item_id
      and assignment.is_active = true
  );
$$;


ALTER FUNCTION "pass"."catalog_item_option_group_is_allowed"("p_catalog_item_id" "uuid", "p_option_group_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pass"."cleanup_delivery_quotes"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pass', 'public'
    AS $$
declare
  v_expired_unused integer := 0;
  v_old_used integer := 0;
begin
  delete from pass.delivery_quotes
  where used_at is null
    and expires_at < now()
  ;
  get diagnostics v_expired_unused = row_count;

  delete from pass.delivery_quotes
  where used_at is not null
    and used_at < now() - interval '30 days'
  ;
  get diagnostics v_old_used = row_count;

  return jsonb_build_object(
    'ok', true,
    'expired_unused_deleted', v_expired_unused,
    'old_used_deleted', v_old_used
  );
end;
$$;


ALTER FUNCTION "pass"."cleanup_delivery_quotes"() OWNER TO "postgres";


COMMENT ON FUNCTION "pass"."cleanup_delivery_quotes"() IS 'Elimina cotizaciones de domicilio vencidas sin usar y cotizaciones usadas con mas de 30 dias.';



CREATE OR REPLACE FUNCTION "pass"."ensure_commercial_category"("p_site_id" "uuid", "p_name" "text", "p_code" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pass'
    AS $$
declare
  v_name text := nullif(btrim(coalesce(p_name, '')), '');
  v_base_code text;
  v_code text;
  v_category_id uuid;
  v_suffix integer := 1;
begin
  if p_site_id is null then
    raise exception 'site_required';
  end if;

  if v_name is null then
    return null;
  end if;

  select id
    into v_category_id
  from pass.commercial_categories
  where site_id = p_site_id
    and lower(btrim(name)) = lower(v_name)
  order by is_active desc, sort_order asc, name asc
  limit 1;

  if v_category_id is not null then
    return v_category_id;
  end if;

  v_base_code := case
    when nullif(btrim(coalesce(p_code, '')), '') is not null
      then pass.normalize_commercial_category_code(p_code)
    else pass.normalize_commercial_category_code(v_name)
  end;
  v_code := v_base_code;

  while exists (
    select 1
    from pass.commercial_categories
    where site_id = p_site_id
      and code = v_code
  ) loop
    v_suffix := v_suffix + 1;
    v_code := v_base_code || '-' || v_suffix::text;
  end loop;

  insert into pass.commercial_categories (site_id, code, name, metadata)
  values (
    p_site_id,
    v_code,
    v_name,
    jsonb_build_object('created_from', 'catalog_item_category_label')
  )
  returning id into v_category_id;

  return v_category_id;
end;
$$;


ALTER FUNCTION "pass"."ensure_commercial_category"("p_site_id" "uuid", "p_name" "text", "p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pass"."ensure_commercial_collection_category"("p_collection_id" "uuid", "p_commercial_category_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pass'
    AS $$
declare
  v_link_id uuid;
begin
  if p_collection_id is null or p_commercial_category_id is null then
    return null;
  end if;

  insert into pass.commercial_collection_categories (
    collection_id,
    commercial_category_id,
    is_active,
    metadata
  )
  values (
    p_collection_id,
    p_commercial_category_id,
    true,
    jsonb_build_object('created_from', 'catalog_item_assignment')
  )
  on conflict (collection_id, commercial_category_id)
  do update set
    is_active = true,
    updated_at = now(),
    metadata = coalesce(pass.commercial_collection_categories.metadata, '{}'::jsonb)
      || jsonb_build_object(
        'last_ensured_from', 'catalog_item_assignment',
        'last_ensured_at', now()
      )
  returning id into v_link_id;

  return v_link_id;
end;
$$;


