CREATE OR REPLACE FUNCTION "pass"."get_order_reschedule_slots_admin"("p_site_id" "uuid", "p_from_date" "date" DEFAULT NULL::"date", "p_to_date" "date" DEFAULT NULL::"date", "p_timezone" "text" DEFAULT 'America/Bogota'::"text") RETURNS TABLE("window_start" timestamp with time zone, "window_end" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pass', 'auth'
    AS $$
  with bounds as (
    select
      greatest(coalesce(p_from_date, (now() at time zone p_timezone)::date), (now() at time zone p_timezone)::date) as from_date,
      least(coalesce(p_to_date, (now() at time zone p_timezone)::date + 30), (now() at time zone p_timezone)::date + 60) as to_date
  ), dates as (
    select generate_series(b.from_date, b.to_date, interval '1 day')::date as local_date
    from bounds b
  ), effective_hours as (
    select
      d.local_date,
      case
        when ex.exception_type = 'closed' then null
        when ex.exception_type = 'special_hours' then ex.opens_at
        when coalesce(h.is_closed, true) then null
        else h.opens_at
      end as opens_at,
      case
        when ex.exception_type = 'closed' then null
        when ex.exception_type = 'special_hours' then ex.closes_at
        when coalesce(h.is_closed, true) then null
        else h.closes_at
      end as closes_at
    from dates d
    left join pass.site_business_hours h
      on h.site_id = p_site_id
     and h.iso_weekday = extract(isodow from d.local_date)::smallint
    left join pass.site_schedule_exceptions ex
      on ex.site_id = p_site_id
     and ex.exception_date = d.local_date
  ), generated as (
    select
      gs::timestamp without time zone as local_start,
      (gs + interval '30 minutes')::timestamp without time zone as local_end
    from effective_hours e
    cross join lateral generate_series(
      e.local_date + e.opens_at,
      e.local_date + e.closes_at - interval '30 minutes',
      interval '30 minutes'
    ) gs
    where e.opens_at is not null
      and e.closes_at is not null
      and e.closes_at > e.opens_at
  )
  select
    g.local_start at time zone p_timezone,
    g.local_end at time zone p_timezone
  from generated g
  where g.local_start at time zone p_timezone > now()
  order by 1;
$$;


ALTER FUNCTION "pass"."get_order_reschedule_slots_admin"("p_site_id" "uuid", "p_from_date" "date", "p_to_date" "date", "p_timezone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pass"."get_site_order_status"("p_site_id" "uuid", "p_fulfillment_type" "text", "p_items" "jsonb", "p_timezone" "text" DEFAULT 'America/Bogota'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pass', 'auth'
    AS $$
declare
  v_timezone text := coalesce(nullif(trim(p_timezone), ''), 'America/Bogota');
  v_fulfillment text := lower(trim(coalesce(p_fulfillment_type, '')));
  v_local_now timestamp without time zone := now() at time zone v_timezone;
  v_local_date date := v_local_now::date;
  v_open time;
  v_close time;
  v_exception_type text;
  v_customer_message text;
  v_is_open boolean := false;
  v_next_start timestamptz;
  v_next_end timestamptz;
begin
  if auth.uid() is null then raise exception 'authentication_required'; end if;
  if p_site_id is null then raise exception 'site_required'; end if;
  if v_fulfillment not in ('delivery', 'pickup', 'on_premise') then raise exception 'invalid_fulfillment_type'; end if;

  select ex.exception_type, ex.opens_at, ex.closes_at, ex.customer_message
  into v_exception_type, v_open, v_close, v_customer_message
  from pass.site_schedule_exceptions ex
  where ex.site_id = p_site_id
    and ex.exception_date = v_local_date;

  if v_exception_type = 'closed' then
    v_is_open := false;
  elsif v_exception_type = 'special_hours' then
    v_is_open := v_open is not null and v_close is not null
      and v_local_now::time >= v_open
      and v_local_now::time < v_close;
  else
    select h.opens_at, h.closes_at
    into v_open, v_close
    from pass.site_business_hours h
    where h.site_id = p_site_id
      and h.iso_weekday = extract(isodow from v_local_date)::smallint
      and h.is_closed = false;

    v_is_open := v_open is not null and v_close is not null
      and v_local_now::time >= v_open
      and v_local_now::time < v_close;
  end if;

  if not v_is_open then
    select s.window_start, s.window_end
    into v_next_start, v_next_end
    from public.get_order_delivery_slots(
      p_site_id,
      v_fulfillment,
      v_local_date,
      v_local_date + 30,
      p_items,
      v_timezone
    ) s
    order by s.window_start
    limit 1;
  end if;

  return jsonb_build_object(
    'immediate_available', v_is_open,
    'reason', case
      when v_is_open then null
      when v_exception_type = 'closed' then 'site_closed_exception'
      when v_exception_type = 'special_hours' then 'outside_special_hours'
      else 'outside_business_hours'
    end,
    'customer_message', v_customer_message,
    'opens_at', v_open,
    'closes_at', v_close,
    'next_window_start', v_next_start,
    'next_window_end', v_next_end,
    'timezone', v_timezone
  );
end;
$$;


ALTER FUNCTION "pass"."get_site_order_status"("p_site_id" "uuid", "p_fulfillment_type" "text", "p_items" "jsonb", "p_timezone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pass"."grant_loyalty_points"("p_user_id" "uuid", "p_points" integer, "p_description" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pass'
    AS $$
declare
  v_current_balance integer;
  v_new_balance integer;
  v_transaction_id uuid;
begin
  if not public.is_active_staff() then
    return jsonb_build_object('success', false, 'error', 'No autorizado (staff requerido)');
  end if;

  if p_user_id is null then
    return jsonb_build_object('success', false, 'error', 'user_id es requerido');
  end if;

  if p_points is null or p_points <= 0 then
    return jsonb_build_object('success', false, 'error', 'p_points debe ser mayor a 0');
  end if;

  select u.loyalty_points
    into v_current_balance
  from public.users u
  where u.id = p_user_id
  for update;

  if v_current_balance is null then
    return jsonb_build_object('success', false, 'error', 'Usuario no encontrado');
  end if;

  v_new_balance := coalesce(v_current_balance, 0) + p_points;

  insert into pass.loyalty_transactions (
    user_id,
    kind,
    points_delta,
    description,
    metadata
  ) values (
    p_user_id,
    'earn',
    p_points,
    coalesce(p_description, 'Puntos otorgados'),
    coalesce(p_metadata, '{}'::jsonb) || jsonb_build_object('staff_user_id', auth.uid())
  )
  returning id into v_transaction_id;

  update public.users
  set loyalty_points = v_new_balance,
      updated_at = now()
  where id = p_user_id;

  return jsonb_build_object(
    'success', true,
    'new_balance', v_new_balance,
    'points_awarded', p_points,
    'transaction_id', v_transaction_id
  );
exception
  when others then
    return jsonb_build_object('success', false, 'error', sqlerrm);
end;
$$;


ALTER FUNCTION "pass"."grant_loyalty_points"("p_user_id" "uuid", "p_points" integer, "p_description" "text", "p_metadata" "jsonb") OWNER TO "postgres";


