CREATE OR REPLACE FUNCTION "pass"."order_required_lead_minutes"("p_site_id" "uuid", "p_items" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pass', 'public', 'auth'
    AS $_$
declare
  v_item jsonb;
  v_catalog_item_id uuid;
  v_metadata jsonb;
  v_raw_lead text;
  v_lead integer;
  v_required integer := 0;
  v_requires_scheduling boolean;
begin
  if auth.uid() is null then raise exception 'authentication_required'; end if;
  if p_site_id is null then raise exception 'site_required'; end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'items_required';
  end if;

  for v_item in select * from jsonb_array_elements(p_items)
  loop
    v_catalog_item_id := nullif(v_item ->> 'catalog_item_id', '')::uuid;
    if v_catalog_item_id is null then continue; end if;

    select coalesce(item.metadata, '{}'::jsonb)
    into v_metadata
    from pass.catalog_items item
    where item.id = v_catalog_item_id
      and item.site_id = p_site_id
      and item.is_active = true;

    if not found then raise exception 'catalog_item_invalid'; end if;

    v_raw_lead := nullif(trim(coalesce(v_metadata ->> 'minimum_lead_minutes', '')), '');
    if v_raw_lead is null then
      v_lead := 0;
    elsif v_raw_lead ~ '^[0-9]+$' then
      v_lead := v_raw_lead::integer;
    else
      raise exception 'catalog_item_invalid_lead_time';
    end if;

    v_requires_scheduling :=
      lower(coalesce(v_metadata ->> 'availability_mode', 'immediate')) = 'made_to_order'
      or lower(coalesce(v_metadata ->> 'scheduling_required', 'false')) = 'true'
      or v_lead > 0;

    if v_requires_scheduling and v_lead <= 0 then
      raise exception 'catalog_item_invalid_lead_time';
    end if;

    if v_requires_scheduling then
      v_required := greatest(v_required, v_lead);
    end if;
  end loop;

  return v_required;
end;
$_$;


ALTER FUNCTION "pass"."order_required_lead_minutes"("p_site_id" "uuid", "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pass"."process_loyalty_earning"("p_order_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pass'
    AS $$
declare
  point_conversion_rate constant integer := 1000;
  v_order record;
  v_points integer;
begin
  select
    o.id,
    o.client_id,
    o.payment_status,
    o.loyalty_processed,
    o.total_amount,
    o.loyalty_points_awarded
  into v_order
  from public.orders o
  where o.id = p_order_id
  for update;

  if not found then
    raise exception 'Order % not found', p_order_id using errcode = 'P0001';
  end if;

  if v_order.payment_status <> 'paid' then
    raise exception 'Order % is not paid', p_order_id using errcode = 'P0001';
  end if;

  if v_order.loyalty_processed then
    raise exception 'Order % already processed for loyalty', p_order_id using errcode = 'P0001';
  end if;

  v_points := floor(coalesce(v_order.total_amount, 0) / point_conversion_rate);

  if v_points <= 0 then
    update public.orders
      set loyalty_processed = true,
          loyalty_points_awarded = 0
    where id = p_order_id;
    return;
  end if;

  insert into pass.loyalty_transactions (
    user_id,
    order_id,
    kind,
    points_delta,
    description
  ) values (
    v_order.client_id,
    p_order_id,
    'earn',
    v_points,
    'Order paid: loyalty earning'
  );

  update public.users
    set loyalty_points = coalesce(loyalty_points, 0) + v_points
  where id = v_order.client_id;

  update public.orders
    set loyalty_processed = true,
        loyalty_points_awarded = v_points
  where id = p_order_id;
end;
$$;


ALTER FUNCTION "pass"."process_loyalty_earning"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pass"."reconcile_catalog_items_after_collection_status_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pass'
    AS $$
begin
  if old.is_active is not distinct from new.is_active then
    return new;
  end if;

  if new.is_active = false then
    update pass.catalog_item_collections cic
    set is_primary = false,
        updated_at = now()
    where cic.commercial_collection_id = new.id
      and cic.is_primary = true;

    with affected_items as (
      select distinct catalog_item_id
      from pass.catalog_item_collections
      where commercial_collection_id = new.id
    ), replacements as (
      select distinct on (cic.catalog_item_id)
        cic.catalog_item_id,
        cic.commercial_collection_id
      from pass.catalog_item_collections cic
      join pass.commercial_collections cc
        on cc.id = cic.commercial_collection_id
       and cc.is_active = true
      where cic.catalog_item_id in (select catalog_item_id from affected_items)
        and cic.is_active = true
      order by cic.catalog_item_id, cic.is_primary desc, cic.sort_order asc, cic.created_at asc
    )
    update pass.catalog_item_collections cic
    set is_primary = true,
        updated_at = now()
    from replacements replacement
    where cic.catalog_item_id = replacement.catalog_item_id
      and cic.commercial_collection_id = replacement.commercial_collection_id
      and cic.is_primary = false;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "pass"."reconcile_catalog_items_after_collection_status_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pass"."reschedule_scheduled_order_admin"("p_site_id" "uuid", "p_order_id" "uuid", "p_exception_date" "date", "p_new_window_start" timestamp with time zone, "p_new_window_end" timestamp with time zone, "p_decided_by" "uuid", "p_note" "text" DEFAULT NULL::"text", "p_timezone" "text" DEFAULT 'America/Bogota'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pass', 'auth'
    AS $$
declare
  v_order public.orders%rowtype;
  v_exception pass.site_schedule_exceptions%rowtype;
  v_local_start timestamp without time zone;
  v_local_end timestamp without time zone;
  v_local_date date;
  v_open time;
  v_close time;
  v_exception_type text;
  v_prepare_offset interval;
begin
  if p_site_id is null or p_order_id is null or p_exception_date is null or p_decided_by is null then
    raise exception 'required_fields_missing';
  end if;
  if p_new_window_start is null or p_new_window_end is null or p_new_window_end <= p_new_window_start then
    raise exception 'delivery_window_invalid';
  end if;
  if p_new_window_start <= now() or p_new_window_end - p_new_window_start <> interval '30 minutes' then
    raise exception 'delivery_window_invalid';
  end if;

  select * into v_order
  from public.orders
  where id = p_order_id
    and site_id = p_site_id
    and schedule_mode = 'scheduled'
    and status <> 'cancelled'
    and voided_at is null
  for update;

  if not found then raise exception 'order_not_found'; end if;

  select * into v_exception
  from pass.site_schedule_exceptions
  where site_id = p_site_id and exception_date = p_exception_date;

  if not found then raise exception 'source_exception_not_found'; end if;
  if (v_order.delivery_window_start at time zone p_timezone)::date <> p_exception_date then
    raise exception 'source_exception_mismatch';
  end if;

  v_local_start := p_new_window_start at time zone p_timezone;
  v_local_end := p_new_window_end at time zone p_timezone;
  v_local_date := v_local_start::date;

  if v_local_end::date <> v_local_date
     or extract(second from v_local_start) <> 0
     or extract(minute from v_local_start)::integer not in (0, 30) then
    raise exception 'delivery_slot_unavailable';
  end if;

  select ex.exception_type, ex.opens_at, ex.closes_at
  into v_exception_type, v_open, v_close
  from pass.site_schedule_exceptions ex
  where ex.site_id = p_site_id and ex.exception_date = v_local_date;

  if v_exception_type = 'closed' then
    raise exception 'site_closed';
  elsif v_exception_type is distinct from 'special_hours' then
    select h.opens_at, h.closes_at into v_open, v_close
    from pass.site_business_hours h
    where h.site_id = p_site_id
      and h.iso_weekday = extract(isodow from v_local_date)::smallint
      and h.is_closed = false;
  end if;

  if v_open is null or v_close is null
     or v_local_start::time < v_open
     or v_local_end::time > v_close then
    raise exception 'delivery_slot_unavailable';
  end if;

  v_prepare_offset := case
    when v_order.prepare_by is not null and v_order.delivery_window_start is not null
      then greatest(v_order.delivery_window_start - v_order.prepare_by, interval '0 minutes')
    else interval '0 minutes'
  end;

  update public.orders
  set requested_for = p_new_window_start,
      delivery_window_start = p_new_window_start,
      delivery_window_end = p_new_window_end,
      prepare_by = p_new_window_start - v_prepare_offset,
      timezone = coalesce(nullif(trim(p_timezone), ''), 'America/Bogota'),
      updated_at = now()
  where id = p_order_id;

  insert into pass.site_schedule_exception_resolutions (
    site_id, order_id, exception_date, decision, note, decided_by, decided_at, updated_at,
    previous_window_start, previous_window_end, new_window_start, new_window_end
  ) values (
    p_site_id, p_order_id, p_exception_date, 'rescheduled', nullif(trim(coalesce(p_note, '')), ''),
    p_decided_by, now(), now(), v_order.delivery_window_start, v_order.delivery_window_end,
    p_new_window_start, p_new_window_end
  )
  on conflict (order_id, exception_date) do update
  set decision = excluded.decision,
      note = excluded.note,
      decided_by = excluded.decided_by,
      decided_at = excluded.decided_at,
      updated_at = excluded.updated_at,
      previous_window_start = excluded.previous_window_start,
      previous_window_end = excluded.previous_window_end,
      new_window_start = excluded.new_window_start,
      new_window_end = excluded.new_window_end;
end;
$$;


ALTER FUNCTION "pass"."reschedule_scheduled_order_admin"("p_site_id" "uuid", "p_order_id" "uuid", "p_exception_date" "date", "p_new_window_start" timestamp with time zone, "p_new_window_end" timestamp with time zone, "p_decided_by" "uuid", "p_note" "text", "p_timezone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pass"."resolve_scheduled_order_contact_admin"("p_site_id" "uuid", "p_order_id" "uuid", "p_exception_date" "date", "p_decision" "text", "p_decided_by" "uuid", "p_note" "text", "p_timezone" "text" DEFAULT 'America/Bogota'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pass', 'auth'
    AS $$
declare
  v_order public.orders%rowtype;
  v_exception pass.site_schedule_exceptions%rowtype;
  v_contact_name text;
  v_contact_phone text;
  v_new_status text;
begin
  if p_site_id is null or p_order_id is null or p_exception_date is null or p_decided_by is null then
    raise exception 'required_fields_missing';
  end if;
  if p_decision not in ('contact_required', 'cancelled') then
    raise exception 'invalid_decision';
  end if;
  if nullif(trim(coalesce(p_note, '')), '') is null then
    raise exception 'reason_required';
  end if;

  select * into v_order
  from public.orders
  where id = p_order_id
    and site_id = p_site_id
    and schedule_mode = 'scheduled'
    and voided_at is null
  for update;

  if not found then raise exception 'order_not_found'; end if;
  if (v_order.delivery_window_start at time zone p_timezone)::date <> p_exception_date then
    raise exception 'source_exception_mismatch';
  end if;

  select * into v_exception
  from pass.site_schedule_exceptions
  where site_id = p_site_id and exception_date = p_exception_date;

  if not found then raise exception 'source_exception_not_found'; end if;

  v_contact_name := nullif(trim(coalesce(v_order.guest_info ->> 'contact_name', '')), '');
  v_contact_phone := coalesce(
    nullif(trim(coalesce(v_order.contact_phone, '')), ''),
    nullif(trim(coalesce(v_order.guest_info ->> 'contact_phone', '')), '')
  );
  v_new_status := case when p_decision = 'cancelled' then 'cancelled' else v_order.status end;

  if p_decision = 'cancelled' then
    update public.orders
    set status = 'cancelled', updated_at = now()
    where id = p_order_id;
  end if;

  insert into pass.site_schedule_exception_resolutions (
    site_id, order_id, exception_date, decision, note, decided_by, decided_at, updated_at,
    contact_name, contact_phone, previous_order_status, new_order_status
  ) values (
    p_site_id, p_order_id, p_exception_date, p_decision,
    nullif(trim(p_note), ''), p_decided_by, now(), now(),
    v_contact_name, v_contact_phone, v_order.status, v_new_status
  )
  on conflict (order_id, exception_date) do update
  set decision = excluded.decision,
      note = excluded.note,
      decided_by = excluded.decided_by,
      decided_at = excluded.decided_at,
      updated_at = excluded.updated_at,
      contact_name = excluded.contact_name,
      contact_phone = excluded.contact_phone,
      previous_order_status = excluded.previous_order_status,
      new_order_status = excluded.new_order_status;
end;
$$;


ALTER FUNCTION "pass"."resolve_scheduled_order_contact_admin"("p_site_id" "uuid", "p_order_id" "uuid", "p_exception_date" "date", "p_decision" "text", "p_decided_by" "uuid", "p_note" "text", "p_timezone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pass"."seed_catalog_items_from_sell_products"("p_site_id" "uuid" DEFAULT NULL::"uuid", "p_only_missing" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pass'
    AS $_$
declare
  v_row record;
  v_existing_id uuid;
  v_inserted integer := 0;
  v_updated integer := 0;
  v_skipped integer := 0;
  v_slug text;
  v_code text;
  v_now timestamptz := now();
begin
  if auth.uid() is not null and not (public.is_owner() or public.is_global_manager()) then
    return jsonb_build_object('success', false, 'error', 'No autorizado.');
  end if;

  for v_row in
    select
      sps.site_id,
      sps.product_id,
      sps.name,
      sps.description,
      sps.sku,
      sps.base_price,
      sps.recipe_cost_amount,
      sps.base_margin_amount,
      sps.base_margin_pct,
      p.catalog_image_url,
      p.image_url as product_image_url
    from pass.sell_products_by_site sps
    join public.products p
      on p.id = sps.product_id
    where p_site_id is null or sps.site_id = p_site_id
    order by sps.site_id, sps.name
  loop
    select ci.id
      into v_existing_id
    from pass.catalog_items ci
    where ci.site_id = v_row.site_id
      and ci.product_id = v_row.product_id
    order by ci.is_active desc, ci.updated_at desc, ci.created_at desc
    limit 1;

    v_slug := lower(
      regexp_replace(
        coalesce(nullif(trim(v_row.sku), ''), nullif(trim(v_row.name), ''), 'item'),
        '[^a-zA-Z0-9]+',
        '-',
        'g'
      )
    );
    v_slug := regexp_replace(v_slug, '(^-+|-+$)', '', 'g');
    if coalesce(v_slug, '') = '' then
      v_slug := 'item';
    end if;
    v_code := v_slug || '-' || substring(replace(v_row.product_id::text, '-', '') from 1 for 6);

    if v_existing_id is null then
      insert into pass.catalog_items (
        site_id,
        product_id,
        code,
        name,
        description,
        category_label,
        commercial_category_id,
        image_url,
        remission_image_url,
        price_amount,
        is_active,
        is_featured,
        badges,
        fulfillment_modes,
        metadata,
        sort_order
      ) values (
        v_row.site_id,
        v_row.product_id,
        v_code,
        coalesce(v_row.name, 'Producto'),
        v_row.description,
        null,
        null,
        coalesce(v_row.catalog_image_url, v_row.product_image_url),
        v_row.product_image_url,
        greatest(coalesce(v_row.base_price, 0), 0),
        true,
        false,
        '{}'::text[],
        array['delivery', 'pickup', 'on_premise']::text[],
        jsonb_strip_nulls(
          jsonb_build_object(
            'seed_source', 'products_sell',
            'seed_synced_at', v_now,
            'recipe_cost_amount', v_row.recipe_cost_amount,
            'margin_amount', v_row.base_margin_amount,
            'margin_pct', v_row.base_margin_pct
          )
        ),
        0
      );

      v_inserted := v_inserted + 1;
    elsif p_only_missing then
      v_skipped := v_skipped + 1;
    else
      update pass.catalog_items ci
      set
        site_id = v_row.site_id,
        product_id = v_row.product_id,
        image_url = coalesce(ci.image_url, v_row.catalog_image_url, v_row.product_image_url),
        remission_image_url = coalesce(ci.remission_image_url, v_row.product_image_url),
        price_amount = case
          when coalesce(ci.price_amount, 0) <= 0 then greatest(coalesce(v_row.base_price, 0), 0)
          else ci.price_amount
        end,
        metadata = jsonb_strip_nulls(
          coalesce(ci.metadata, '{}'::jsonb)
          || jsonb_build_object(
            'seed_source', 'products_sell',
            'seed_synced_at', v_now,
            'recipe_cost_amount', v_row.recipe_cost_amount,
            'margin_amount', case
              when coalesce(ci.price_amount, 0) > 0 and v_row.recipe_cost_amount is not null
                then ci.price_amount - v_row.recipe_cost_amount
              else v_row.base_margin_amount
            end,
            'margin_pct', case
              when coalesce(ci.price_amount, 0) > 0 and v_row.recipe_cost_amount is not null
                then round(((ci.price_amount - v_row.recipe_cost_amount) / ci.price_amount) * 100, 2)
              else v_row.base_margin_pct
            end
          )
        ),
        updated_at = v_now
      where ci.id = v_existing_id;

      v_updated := v_updated + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'success', true,
    'inserted', v_inserted,
    'updated', v_updated,
    'skipped', v_skipped
  );
exception
  when others then
    return jsonb_build_object(
      'success', false,
      'error', sqlerrm,
      'inserted', v_inserted,
      'updated', v_updated,
      'skipped', v_skipped
    );
end;
$_$;


ALTER FUNCTION "pass"."seed_catalog_items_from_sell_products"("p_site_id" "uuid", "p_only_missing" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pass"."sync_active_category_to_main_collections"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pass'
    AS $$
begin
  if new.is_active = true then
    insert into pass.commercial_collection_categories (
      collection_id,
      commercial_category_id,
      sort_order
    )
    select
      collection.id,
      new.id,
      coalesce(new.sort_order, 0)
    from pass.commercial_collections collection
    where collection.site_id = new.site_id
      and collection.is_active = true
      and collection.kind = 'main'
    on conflict (collection_id, commercial_category_id) do update
    set sort_order = excluded.sort_order;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "pass"."sync_active_category_to_main_collections"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pass"."sync_main_collection_categories"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pass'
    AS $$
begin
  if new.is_active = true and new.kind = 'main' then
    insert into pass.commercial_collection_categories (
      collection_id,
      commercial_category_id,
      sort_order
    )
    select
      new.id,
      category.id,
      coalesce(category.sort_order, 0)
    from pass.commercial_categories category
    where category.site_id = new.site_id
      and category.is_active = true
    on conflict (collection_id, commercial_category_id) do update
    set sort_order = excluded.sort_order;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "pass"."sync_main_collection_categories"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pass"."update_catalog_item_image"("p_item_id" "uuid", "p_image_url" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pass', 'public'
    AS $$
declare
  v_image_url text;
begin
  if not public.has_permission('viso.menu.images.manage') then
    raise exception 'permission_denied'
      using errcode = '42501';
  end if;

  v_image_url := nullif(trim(coalesce(p_image_url, '')), '');

  update pass.catalog_items
  set image_url = v_image_url,
      updated_at = now()
  where id = p_item_id;

  if not found then
    raise exception 'catalog_item_not_found'
      using errcode = 'P0002';
  end if;
end;
$$;


ALTER FUNCTION "pass"."update_catalog_item_image"("p_item_id" "uuid", "p_image_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pass"."update_loyalty_balance"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pass'
    AS $$
begin
  if (tg_op = 'INSERT') then
    update public.users
    set loyalty_points = loyalty_points + new.points_delta,
        updated_at = now()
    where id = new.user_id;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "pass"."update_loyalty_balance"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pass"."validate_catalog_item_collection_site"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pass'
    AS $$
declare
  v_item_site_id uuid;
  v_item_category_id uuid;
  v_collection_site_id uuid;
begin
  select site_id, commercial_category_id
  into v_item_site_id, v_item_category_id
  from pass.catalog_items
  where id = new.catalog_item_id;

  if not found then
    raise exception 'Item comercial % no existe.', new.catalog_item_id;
  end if;

  select site_id
  into v_collection_site_id
  from pass.commercial_collections
  where id = new.commercial_collection_id;

  if not found then
    raise exception 'Coleccion comercial % no existe.', new.commercial_collection_id;
  end if;

  if v_item_site_id is distinct from v_collection_site_id then
    raise exception 'La coleccion comercial no pertenece a la sede del item.';
  end if;

  if v_item_category_id is not null then
    perform pass.ensure_commercial_collection_category(
      new.commercial_collection_id,
      v_item_category_id
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "pass"."validate_catalog_item_collection_site"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pass"."validate_catalog_item_option_consumption_rule"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pass', 'public'
    AS $$
declare
  v_item_site_id uuid;
  v_profile_product_id uuid;
  v_location_site_id uuid;
  v_position record;
begin
  select item.site_id
    into v_item_site_id
  from pass.catalog_item_options option_row
  join pass.catalog_item_option_groups option_group
    on option_group.id = option_row.option_group_id
  join pass.catalog_items item
    on item.id = option_group.catalog_item_id
  where option_row.id = new.option_id;

  if v_item_site_id is null then
    raise exception 'option does not belong to a catalog item with site';
  end if;

  if new.input_uom_profile_id is not null then
    select profile.product_id
      into v_profile_product_id
    from public.product_uom_profiles profile
    where profile.id = new.input_uom_profile_id
      and coalesce(profile.is_active, true) = true;

    if v_profile_product_id is null then
      raise exception 'input_uom_profile_id not found or inactive';
    end if;

    if v_profile_product_id <> new.product_id then
      raise exception 'input_uom_profile_id must belong to product_id';
    end if;
  end if;

  if new.source_location_strategy in ('explicit_location', 'explicit_position') then
    select loc.site_id
      into v_location_site_id
    from public.inventory_locations loc
    where loc.id = new.source_location_id
      and coalesce(loc.is_active, true) = true;

    if v_location_site_id is null then
      raise exception 'source_location_id not found or inactive';
    end if;

    if v_location_site_id <> v_item_site_id then
      raise exception 'source_location_id must belong to catalog item site';
    end if;
  end if;

  if new.source_location_strategy = 'explicit_position' then
    select pos.id, pos.location_id, pos.site_id
      into v_position
    from public.inventory_location_positions pos
    where pos.id = new.source_location_position_id
      and coalesce(pos.is_active, true) = true;

    if v_position.id is null then
      raise exception 'source_location_position_id not found or inactive';
    end if;

    if v_position.location_id <> new.source_location_id then
      raise exception 'source_location_position_id must belong to source_location_id';
    end if;

    if v_position.site_id <> v_item_site_id then
      raise exception 'source_location_position_id must belong to catalog item site';
    end if;
  end if;

  if new.input_quantity_per_option is not null then
    if new.input_unit_code is null and new.input_uom_profile_id is null then
      raise exception 'input_unit_code or input_uom_profile_id is required when input_quantity_per_option is set';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "pass"."validate_catalog_item_option_consumption_rule"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pass"."validate_catalog_item_option_rappi_level"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pass', 'public'
    AS $$
declare
  v_option_site_id uuid;
  v_linked_site_id uuid;
begin
  if new.linked_catalog_item_id is null then
    return new;
  end if;

  select item.site_id
    into v_option_site_id
  from pass.catalog_item_option_groups option_group
  join pass.catalog_items item
    on item.id = option_group.catalog_item_id
  where option_group.id = new.option_group_id;

  select linked_item.site_id
    into v_linked_site_id
  from pass.catalog_items linked_item
  where linked_item.id = new.linked_catalog_item_id
    and linked_item.is_active = true;

  if v_linked_site_id is null then
    raise exception 'linked_catalog_item_id not found or inactive';
  end if;

  if v_option_site_id is null or v_linked_site_id <> v_option_site_id then
    raise exception 'linked_catalog_item_id must belong to same site as option catalog item';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "pass"."validate_catalog_item_option_rappi_level"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pass"."validate_catalog_item_option_recipe_effect"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pass', 'public'
    AS $$
declare
  v_catalog_product_id uuid;
  v_recipe_match boolean;
begin
  select item.product_id
    into v_catalog_product_id
  from pass.catalog_item_options option_row
  join pass.catalog_item_option_groups option_group
    on option_group.id = option_row.option_group_id
  join pass.catalog_items item
    on item.id = option_group.catalog_item_id
  where option_row.id = new.option_id;

  if v_catalog_product_id is null then
    raise exception 'option does not belong to a catalog item with product_id';
  end if;

  select exists (
    select 1
    from public.recipes recipe
    where recipe.product_id = v_catalog_product_id
      and recipe.ingredient_product_id = new.target_ingredient_product_id
      and coalesce(recipe.is_active, true) = true
  )
  into v_recipe_match;

  if not coalesce(v_recipe_match, false) then
    raise exception 'target_ingredient_product_id must be an active ingredient of the catalog item product recipe';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "pass"."validate_catalog_item_option_recipe_effect"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pass"."validate_catalog_item_product_site"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pass'
    AS $_$
declare
  v_product record;
  v_category record;
begin
  if tg_op = 'UPDATE'
    and new.image_url is distinct from old.image_url
    and (to_jsonb(new) - array['image_url', 'updated_at'])
      = (to_jsonb(old) - array['image_url', 'updated_at'])
  then
    return new;
  end if;

  if new.product_id is null then
    raise exception 'El item comercial debe estar asociado a un producto operacional vendible.';
  end if;

  select
    product_id,
    site_id,
    name,
    sku,
    description,
    base_price as price
  into v_product
  from pass.sell_products_by_site
  where product_id = new.product_id
    and site_id = new.site_id;

  if not found then
    raise exception 'El producto % no esta habilitado para venta en esta sede.', new.product_id;
  end if;

  if coalesce(trim(new.name), '') = '' then
    new.name := coalesce(v_product.name, 'Producto');
  end if;

  if coalesce(trim(new.description), '') = '' then
    new.description := v_product.description;
  end if;

  if coalesce(trim(new.code), '') = '' then
    new.code := lower(regexp_replace(coalesce(v_product.sku, v_product.name, 'item'), '[^a-zA-Z0-9]+', '-', 'g'));
    new.code := regexp_replace(new.code, '(^-+|-+$)', '', 'g');
    if coalesce(new.code, '') = '' then
      new.code := 'item';
    end if;
  end if;

  if coalesce(new.price_amount, 0) = 0 and v_product.price is not null and v_product.price > 0 then
    new.price_amount := v_product.price;
  end if;

  if new.commercial_category_id is null then
    raise exception 'Categoria comercial obligatoria. Crea o selecciona una categoria de venta; no se crean categorias desde texto libre.';
  end if;

  select id, site_id, name, is_active
    into v_category
  from pass.commercial_categories
  where id = new.commercial_category_id;

  if not found then
    raise exception 'Categoria comercial % no existe.', new.commercial_category_id;
  end if;

  if v_category.site_id is distinct from new.site_id then
    raise exception 'Categoria comercial no pertenece a la sede del item.';
  end if;

  if coalesce(v_category.is_active, true) = false then
    raise exception 'Categoria comercial inactiva.';
  end if;

  new.category_label := v_category.name;
  return new;
end;
$_$;


