CREATE OR REPLACE FUNCTION "pass"."validate_order_requested_for"("p_site_id" "uuid", "p_items" "jsonb", "p_requested_for" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pass', 'public', 'auth'
    AS $_$
declare
  v_item jsonb;
  v_catalog_item_id uuid;
  v_metadata jsonb;
  v_raw_lead text;
  v_minimum_lead_minutes integer;
  v_required_lead_minutes integer := 0;
  v_requires_scheduling boolean;
  v_now timestamptz := now();
  v_earliest_requested_for timestamptz;
begin
  if p_site_id is null then
    raise exception 'site_required';
  end if;

  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'items_required';
  end if;

  for v_item in select * from jsonb_array_elements(p_items)
  loop
    v_catalog_item_id := nullif(v_item ->> 'catalog_item_id', '')::uuid;

    if v_catalog_item_id is null then
      continue;
    end if;

    select coalesce(item.metadata, '{}'::jsonb)
    into v_metadata
    from pass.catalog_items item
    where item.id = v_catalog_item_id
      and item.site_id = p_site_id
      and item.is_active = true;

    if not found then
      raise exception 'catalog_item_invalid';
    end if;

    v_raw_lead := nullif(trim(coalesce(v_metadata ->> 'minimum_lead_minutes', '')), '');

    if v_raw_lead is null then
      v_minimum_lead_minutes := 0;
    elsif v_raw_lead ~ '^[0-9]+$' then
      v_minimum_lead_minutes := v_raw_lead::integer;
    else
      raise exception 'catalog_item_invalid_lead_time';
    end if;

    v_requires_scheduling :=
      lower(coalesce(v_metadata ->> 'availability_mode', 'immediate')) = 'made_to_order'
      or lower(coalesce(v_metadata ->> 'scheduling_required', 'false')) = 'true'
      or v_minimum_lead_minutes > 0;

    if v_requires_scheduling and v_minimum_lead_minutes <= 0 then
      raise exception 'catalog_item_invalid_lead_time';
    end if;

    if v_requires_scheduling then
      v_required_lead_minutes := greatest(v_required_lead_minutes, v_minimum_lead_minutes);
    end if;
  end loop;

  if p_requested_for is not null and p_requested_for < v_now then
    raise exception 'requested_for_in_past';
  end if;

  if v_required_lead_minutes > 0 then
    if p_requested_for is null then
      raise exception 'requested_for_required';
    end if;

    v_earliest_requested_for := v_now + make_interval(mins => v_required_lead_minutes);

    if p_requested_for < v_earliest_requested_for then
      raise exception 'requested_for_too_soon';
    end if;
  end if;

  return jsonb_build_object(
    'required_lead_minutes', v_required_lead_minutes,
    'requested_for', p_requested_for,
    'earliest_requested_for', case
      when v_required_lead_minutes > 0 then v_now + make_interval(mins => v_required_lead_minutes)
      else null
    end
  );
end;
$_$;


ALTER FUNCTION "pass"."validate_order_requested_for"("p_site_id" "uuid", "p_items" "jsonb", "p_requested_for" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "pass"."validate_order_requested_for"("p_site_id" "uuid", "p_items" "jsonb", "p_requested_for" timestamp with time zone) IS 'Validates requested_for against authoritative catalog item scheduling metadata and returns the maximum required lead time.';



CREATE OR REPLACE FUNCTION "pass"."validate_order_schedule"("p_site_id" "uuid", "p_items" "jsonb", "p_fulfillment_type" "text", "p_schedule_mode" "text", "p_window_start" timestamp with time zone, "p_window_end" timestamp with time zone, "p_timezone" "text" DEFAULT 'America/Bogota'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pass', 'auth'
    AS $$
declare
  v_mode text := lower(trim(coalesce(p_schedule_mode, 'immediate')));
  v_fulfillment text := lower(trim(coalesce(p_fulfillment_type, '')));
  v_timezone text := coalesce(nullif(trim(p_timezone), ''), 'America/Bogota');
  v_schedule jsonb;
  v_status jsonb;
  v_local_start timestamp without time zone;
  v_local_end timestamp without time zone;
  v_local_date date;
  v_open time;
  v_close time;
  v_exception_type text;
  v_slot_id uuid;
begin
  if auth.uid() is null then raise exception 'authentication_required'; end if;
  if p_site_id is null then raise exception 'site_required'; end if;
  if v_fulfillment not in ('delivery', 'pickup', 'on_premise') then raise exception 'invalid_fulfillment_type'; end if;
  if v_mode not in ('immediate', 'scheduled') then raise exception 'invalid_schedule_mode'; end if;

  if v_mode = 'immediate' then
    if p_window_start is not null or p_window_end is not null then
      raise exception 'immediate_order_has_delivery_window';
    end if;

    v_status := pass.get_site_order_status(p_site_id, v_fulfillment, p_items, v_timezone);
    if not coalesce((v_status ->> 'immediate_available')::boolean, false) then
      raise exception 'site_closed_for_immediate_orders';
    end if;

    v_schedule := pass.validate_order_requested_for(p_site_id, p_items, null);
    return v_schedule || jsonb_build_object('schedule_mode', 'immediate');
  end if;

  if p_window_start is null or p_window_end is null then raise exception 'delivery_window_required'; end if;
  if p_window_end <= p_window_start then raise exception 'delivery_window_invalid'; end if;
  if p_window_start <= now() then raise exception 'requested_for_in_past'; end if;
  if p_window_end - p_window_start <> interval '30 minutes' then raise exception 'delivery_window_invalid'; end if;

  v_local_start := p_window_start at time zone v_timezone;
  v_local_end := p_window_end at time zone v_timezone;
  v_local_date := v_local_start::date;

  if v_local_end::date <> v_local_date
     or extract(second from v_local_start) <> 0
     or extract(minute from v_local_start)::integer not in (0, 30) then
    raise exception 'delivery_slot_unavailable';
  end if;

  select ex.exception_type, ex.opens_at, ex.closes_at
  into v_exception_type, v_open, v_close
  from pass.site_schedule_exceptions ex
  where ex.site_id = p_site_id
    and ex.exception_date = v_local_date;

  if v_exception_type = 'closed' then
    raise exception 'site_closed';
  elsif v_exception_type is distinct from 'special_hours' then
    select h.opens_at, h.closes_at
    into v_open, v_close
    from pass.site_business_hours h
    where h.site_id = p_site_id
      and h.iso_weekday = extract(isodow from v_local_date)::smallint
      and h.is_closed = false;
  end if;

  if v_open is null or v_close is null
     or v_local_start::time < v_open
     or v_local_end::time > v_close then
    raise exception 'delivery_slot_unavailable';
  end if;

  v_schedule := pass.validate_order_requested_for(p_site_id, p_items, p_window_start);

  v_slot_id := (
    substr(md5(p_site_id::text || ':' || v_fulfillment || ':' || p_window_start::text || ':' || p_window_end::text), 1, 8) || '-' ||
    substr(md5(p_site_id::text || ':' || v_fulfillment || ':' || p_window_start::text || ':' || p_window_end::text), 9, 4) || '-' ||
    substr(md5(p_site_id::text || ':' || v_fulfillment || ':' || p_window_start::text || ':' || p_window_end::text), 13, 4) || '-' ||
    substr(md5(p_site_id::text || ':' || v_fulfillment || ':' || p_window_start::text || ':' || p_window_end::text), 17, 4) || '-' ||
    substr(md5(p_site_id::text || ':' || v_fulfillment || ':' || p_window_start::text || ':' || p_window_end::text), 21, 12)
  )::uuid;

  return v_schedule || jsonb_build_object(
    'schedule_mode', 'scheduled',
    'slot_id', v_slot_id,
    'delivery_window_start', p_window_start,
    'delivery_window_end', p_window_end,
    'timezone', v_timezone
  );
end;
$$;


ALTER FUNCTION "pass"."validate_order_schedule"("p_site_id" "uuid", "p_items" "jsonb", "p_fulfillment_type" "text", "p_schedule_mode" "text", "p_window_start" timestamp with time zone, "p_window_end" timestamp with time zone, "p_timezone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_navigation_slugify"("p_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $_$
  select coalesce(
    nullif(
      regexp_replace(
        regexp_replace(
          lower(
            translate(
              btrim(coalesce(p_value, '')),
              'áéíóúÁÉÍÓÚñÑüÜ',
              'aeiouAEIOUnNuU'
            )
          ),
          '[^a-z0-9]+',
          '_',
          'g'
        ),
        '^_+|_+$',
        '',
        'g'
      ),
      ''
    ),
    'item'
  );
$_$;


ALTER FUNCTION "public"."_navigation_slugify"("p_value" "text") OWNER TO "postgres";


