CREATE OR REPLACE FUNCTION "public"."anima_diagnostic_employee_push_tokens"("p_employee_id" "uuid") RETURNS TABLE("id" "uuid", "employee_id" "uuid", "platform" "text", "device_id" "text", "is_active" boolean, "last_seen" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "token_preview" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_requester_email text;
begin
  select lower(btrim(u.email))
    into v_requester_email
  from auth.users u
  where u.id = auth.uid();

  if v_requester_email not in (
    'carlosaaibarra@gmail.com',
    'nathalia@ventocafe.com'
  ) then
    raise exception 'not authorized';
  end if;

  return query
  select
    t.id,
    t.employee_id,
    t.platform,
    t.device_id,
    t.is_active,
    t.last_seen,
    t.created_at,
    t.updated_at,
    case
      when t.token is null then null
      when length(t.token) <= 12 then repeat('*', length(t.token))
      else left(t.token, 8) || '...' || right(t.token, 6)
    end as token_preview
  from public.employee_push_tokens t
  where t.employee_id = p_employee_id
  order by t.updated_at desc nulls last, t.created_at desc;
end;
$$;


ALTER FUNCTION "public"."anima_diagnostic_employee_push_tokens"("p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."anima_diagnostic_push_token_coverage"() RETURNS TABLE("employee_id" "uuid", "full_name" "text", "alias" "text", "role" "text", "site_id" "uuid", "site_name" "text", "has_active_token" boolean, "active_token_count" bigint, "latest_token_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_requester_email text;
begin
  select lower(btrim(u.email))
    into v_requester_email
  from auth.users u
  where u.id = auth.uid();

  if v_requester_email not in (
    'carlosaaibarra@gmail.com',
    'nathalia@ventocafe.com'
  ) then
    raise exception 'not authorized';
  end if;

  return query
  select
    e.id as employee_id,
    e.full_name,
    e.alias,
    e.role,
    e.site_id,
    s.name as site_name,
    coalesce(count(t.id) filter (where t.is_active = true), 0) > 0 as has_active_token,
    coalesce(count(t.id) filter (where t.is_active = true), 0) as active_token_count,
    max(coalesce(t.last_seen, t.updated_at, t.created_at)) as latest_token_at
  from public.employees e
  left join public.sites s on s.id = e.site_id
  left join public.employee_push_tokens t on t.employee_id = e.id
  where e.is_active = true
  group by e.id, e.full_name, e.alias, e.role, e.site_id, s.name
  order by has_active_token asc, e.full_name asc nulls last;
end;
$$;


