CREATE OR REPLACE FUNCTION "public"."apply_default_remission_uom_on_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'storage', 'extensions'
    AS $$
declare
  profile_row record;
  stock_code text;
begin
  if new.request_policy_id is not null then
    return new;
  end if;

  if new.input_uom_profile_id is not null then
    return new;
  end if;

  select stock_unit_code into stock_code
  from public.products
  where id = new.product_id;

  select id, input_unit_code, qty_in_input_unit, qty_in_stock_unit
  into profile_row
  from public.product_uom_profiles
  where product_id = new.product_id
    and is_active = true
    and is_default = true
    and usage_context = 'remission'
  order by case when source = 'manual' then 0 else 1 end, updated_at desc
  limit 1;

  if profile_row.id is null then
    return new;
  end if;

  if lower(coalesce(new.input_unit_code, stock_code, '')) <> lower(coalesce(stock_code, '')) then
    return new;
  end if;

  if lower(profile_row.input_unit_code) = lower(coalesce(stock_code, ''))
     and profile_row.qty_in_input_unit = profile_row.qty_in_stock_unit then
    return new;
  end if;

  new.input_qty := coalesce(new.input_qty, new.quantity);
  new.input_unit_code := profile_row.input_unit_code;
  new.input_uom_profile_id := profile_row.id;
  new.conversion_factor_to_stock := profile_row.qty_in_stock_unit / profile_row.qty_in_input_unit;
  new.stock_unit_code := coalesce(new.stock_unit_code, stock_code);
  new.unit := coalesce(new.unit, stock_code);
  new.quantity := round(new.input_qty * new.conversion_factor_to_stock, 6);

  return new;
end;
$$;


ALTER FUNCTION "public"."apply_default_remission_uom_on_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_inventory_count_adjustments"("p_session_id" "uuid", "p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_session record;
  v_line record;
  v_applied integer := 0;
  v_new_site_qty numeric;
  v_new_loc_qty numeric;
  v_new_pos_qty numeric;
  v_has_entries boolean;
begin
  select *
  into v_session
  from public.inventory_count_sessions s
  where s.id = p_session_id
  for update;

  if not found then
    raise exception 'Sesion no encontrada';
  end if;

  if coalesce(v_session.status, '') <> 'closed' then
    raise exception 'Sesion debe estar cerrada';
  end if;

  for v_line in
    select
      l.id,
      l.product_id,
      l.location_position_id,
      coalesce(l.quantity_counted, 0) as counted_qty,
      coalesce(l.quantity_delta, 0) as delta,
      coalesce(l.input_quantity, abs(coalesce(l.quantity_delta, 0))) as input_quantity,
      coalesce(l.input_unit_code, l.stock_unit_code, p.stock_unit_code, p.unit, 'un') as input_unit_code,
      l.input_uom_profile_id,
      coalesce(l.stock_unit_code, p.stock_unit_code, p.unit, 'un') as stock_unit_code
    from public.inventory_count_lines l
    left join public.products p on p.id = l.product_id
    where l.session_id = p_session_id
      and l.adjustment_applied_at is null
    order by l.product_id, l.location_position_id nulls first
    for update of l
  loop
    if v_line.delta <> 0 then
      insert into public.inventory_movements (
        site_id,
        product_id,
        movement_type,
        quantity,
        input_qty,
        input_unit_code,
        conversion_factor_to_stock,
        stock_unit_code,
        input_uom_profile_id,
        location_id,
        location_position_id,
        note,
        created_by
      )
      values (
        v_session.site_id,
        v_line.product_id,
        'adjustment',
        v_line.delta,
        abs(v_line.delta),
        coalesce(v_line.input_unit_code, v_line.stock_unit_code, 'un'),
        1,
        coalesce(v_line.stock_unit_code, 'un'),
        v_line.input_uom_profile_id,
        case when coalesce(v_session.scope_type, '') = 'loc' then v_session.scope_location_id else null end,
        v_line.location_position_id,
        format('Ajuste por conteo sesion %s', p_session_id),
        p_user_id
      );

      insert into public.inventory_stock_by_site (site_id, product_id, current_qty, updated_at)
      values (v_session.site_id, v_line.product_id, greatest(0, v_line.delta), now())
      on conflict (site_id, product_id) do update
        set current_qty = greatest(0, coalesce(public.inventory_stock_by_site.current_qty, 0) + v_line.delta),
            updated_at = now()
      returning current_qty into v_new_site_qty;

      if coalesce(v_session.scope_type, '') = 'loc' and v_session.scope_location_id is not null then
        insert into public.inventory_stock_by_location (location_id, product_id, current_qty, updated_at)
        values (v_session.scope_location_id, v_line.product_id, greatest(0, v_line.delta), now())
        on conflict (location_id, product_id) do update
          set current_qty = greatest(0, coalesce(public.inventory_stock_by_location.current_qty, 0) + v_line.delta),
              updated_at = now()
        returning current_qty into v_new_loc_qty;
      end if;

      if v_line.location_position_id is not null then
        insert into public.inventory_stock_by_position (position_id, product_id, current_qty, updated_at)
        values (v_line.location_position_id, v_line.product_id, greatest(0, v_line.delta), now())
        on conflict (position_id, product_id) do update
          set current_qty = greatest(0, coalesce(public.inventory_stock_by_position.current_qty, 0) + v_line.delta),
              updated_at = now()
        returning current_qty into v_new_pos_qty;
      end if;

      v_applied := v_applied + 1;
    end if;

    if coalesce(v_session.scope_type, '') = 'loc' and v_session.scope_location_id is not null then
      select exists (
        select 1
        from public.inventory_count_line_entries entry
        where entry.count_line_id = v_line.id
      )
      into v_has_entries;

      if v_has_entries then
        update public.inventory_stock_by_uom_profile stock
        set presentation_qty = 0,
            base_qty = 0,
            site_id = v_session.site_id,
            updated_at = now()
        where stock.location_id = v_session.scope_location_id
          and stock.product_id = v_line.product_id
          and (
            (v_line.location_position_id is null and stock.location_position_id is null)
            or stock.location_position_id = v_line.location_position_id
          );

        insert into public.inventory_stock_by_uom_profile (
          site_id,
          location_id,
          location_position_id,
          product_id,
          uom_profile_id,
          presentation_qty,
          base_qty,
          updated_at
        )
        select
          v_session.site_id,
          v_session.scope_location_id,
          v_line.location_position_id,
          v_line.product_id,
          entry.input_uom_profile_id,
          sum(entry.input_quantity),
          sum(entry.quantity_counted),
          now()
        from public.inventory_count_line_entries entry
        join public.product_uom_profiles profile
          on profile.id = entry.input_uom_profile_id
         and profile.product_id = entry.product_id
         and coalesce(profile.is_active, true) = true
        where entry.count_line_id = v_line.id
          and v_line.location_position_id is not null
          and entry.input_uom_profile_id is not null
          and entry.input_quantity > 0
          and entry.quantity_counted > 0
        group by entry.input_uom_profile_id
        on conflict (location_id, location_position_id, product_id, uom_profile_id) where location_position_id is not null do update
          set site_id = excluded.site_id,
              presentation_qty = excluded.presentation_qty,
              base_qty = excluded.base_qty,
              updated_at = now();

        insert into public.inventory_stock_by_uom_profile (
          site_id,
          location_id,
          location_position_id,
          product_id,
          uom_profile_id,
          presentation_qty,
          base_qty,
          updated_at
        )
        select
          v_session.site_id,
          v_session.scope_location_id,
          null,
          v_line.product_id,
          entry.input_uom_profile_id,
          sum(entry.input_quantity),
          sum(entry.quantity_counted),
          now()
        from public.inventory_count_line_entries entry
        join public.product_uom_profiles profile
          on profile.id = entry.input_uom_profile_id
         and profile.product_id = entry.product_id
         and coalesce(profile.is_active, true) = true
        where entry.count_line_id = v_line.id
          and v_line.location_position_id is null
          and entry.input_uom_profile_id is not null
          and entry.input_quantity > 0
          and entry.quantity_counted > 0
        group by entry.input_uom_profile_id
        on conflict (location_id, product_id, uom_profile_id) where location_position_id is null do update
          set site_id = excluded.site_id,
              presentation_qty = excluded.presentation_qty,
              base_qty = excluded.base_qty,
              updated_at = now();
      elsif v_line.input_uom_profile_id is not null then
        perform public.set_inventory_stock_by_uom_profile_count(
          v_session.scope_location_id,
          v_line.product_id,
          v_line.input_uom_profile_id,
          coalesce(v_line.input_quantity, 0),
          coalesce(v_line.counted_qty, 0),
          v_line.location_position_id
        );
      elsif lower(trim(coalesce(v_line.input_unit_code, ''))) = lower(trim(coalesce(v_line.stock_unit_code, ''))) then
        update public.inventory_stock_by_uom_profile stock
        set presentation_qty = 0,
            base_qty = 0,
            updated_at = now()
        where stock.location_id = v_session.scope_location_id
          and stock.product_id = v_line.product_id
          and (
            (v_line.location_position_id is null and stock.location_position_id is null)
            or stock.location_position_id = v_line.location_position_id
          );
      end if;
    end if;

    update public.inventory_count_lines
    set adjustment_applied_at = now()
    where id = v_line.id;
  end loop;

  return jsonb_build_object('applied', v_applied);
end;
$$;


ALTER FUNCTION "public"."apply_inventory_count_adjustments"("p_session_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_inventory_site_count"("p_site_id" "uuid", "p_user_id" "uuid", "p_note" "text", "p_lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_count integer := 0;
begin
  if jsonb_typeof(coalesce(p_lines, '[]'::jsonb)) <> 'array' then
    raise exception 'p_lines debe ser un arreglo JSON';
  end if;

  create temporary table tmp_site_count_lines (
    product_id uuid not null,
    quantity numeric not null
  ) on commit drop;

  insert into tmp_site_count_lines (product_id, quantity)
  select
    (entry ->> 'product_id')::uuid,
    (entry ->> 'quantity')::numeric
  from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) entry
  where coalesce((entry ->> 'quantity')::numeric, 0) > 0;

  select count(*) into v_count from tmp_site_count_lines;
  if v_count = 0 then
    raise exception 'Al menos una linea con cantidad > 0';
  end if;

  insert into public.inventory_movements (
    site_id,
    product_id,
    movement_type,
    quantity,
    input_qty,
    input_unit_code,
    conversion_factor_to_stock,
    stock_unit_code,
    note,
    created_by
  )
  select
    p_site_id,
    l.product_id,
    'initial_count',
    l.quantity,
    l.quantity,
    coalesce(p.stock_unit_code, p.unit, 'un'),
    1,
    coalesce(p.stock_unit_code, p.unit, 'un'),
    p_note,
    p_user_id
  from tmp_site_count_lines l
  left join public.products p on p.id = l.product_id;

  insert into public.inventory_stock_by_site (
    site_id,
    product_id,
    current_qty,
    updated_at
  )
  select
    p_site_id,
    l.product_id,
    l.quantity,
    now()
  from tmp_site_count_lines l
  on conflict (site_id, product_id) do update
    set current_qty = excluded.current_qty,
        updated_at = excluded.updated_at;

  return jsonb_build_object('count', v_count);
end;
$$;


ALTER FUNCTION "public"."apply_inventory_site_count"("p_site_id" "uuid", "p_user_id" "uuid", "p_note" "text", "p_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_master_inventory_profile_batch"("p_changes" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare c jsonb; pid uuid; tolerance numeric; mode text; kind text; bid uuid; total integer:=0;
begin
 if not (public.is_owner() or public.is_global_manager()) then raise exception 'No tienes permiso para aplicar configuración masiva.'; end if;
 if jsonb_typeof(p_changes)<>'array' or jsonb_array_length(p_changes)=0 then raise exception 'No hay perfiles de inventario.'; end if;
 for c in select value from jsonb_array_elements(p_changes) loop
  pid:=(c->>'product_id')::uuid; tolerance:=coalesce((c->>'default_tolerance_percent')::numeric,0); mode:=nullif(trim(c->>'measurement_mode'),''); kind:=nullif(trim(c->>'inventory_kind'),'');
  if tolerance<0 or tolerance>100 or mode not in ('fixed_presentation','variable_weight','count_with_weight','bulk_volume') or kind is null then raise exception 'Perfil de inventario inválido.'; end if;
  if not exists(select 1 from public.products where id=pid) then raise exception 'Producto inválido.'; end if;
  insert into public.product_inventory_profiles(product_id,track_inventory,inventory_kind,lot_tracking,expiry_tracking,measurement_mode,default_tolerance_percent,updated_at)
  values(pid,coalesce((c->>'track_inventory')::boolean,true),kind,coalesce((c->>'lot_tracking')::boolean,false),coalesce((c->>'expiry_tracking')::boolean,false),mode,tolerance,now())
  on conflict(product_id) do update set track_inventory=excluded.track_inventory,inventory_kind=excluded.inventory_kind,lot_tracking=excluded.lot_tracking,expiry_tracking=excluded.expiry_tracking,measurement_mode=excluded.measurement_mode,default_tolerance_percent=excluded.default_tolerance_percent,updated_at=now(); total:=total+1;
 end loop;
 insert into public.product_configuration_batches(zone,summary,product_count,created_by) values('inventory',jsonb_build_object('changes',p_changes),total,auth.uid()) returning id into bid; return bid;
end; $$;


ALTER FUNCTION "public"."apply_master_inventory_profile_batch"("p_changes" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_master_presentation_version_batch"("p_changes" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare c jsonb; p public.product_uom_profiles%rowtype; new_id uuid; label_value text; input_unit text; stock_qty numeric; batch_id uuid; total integer:=0;
begin
 if not (public.is_owner() or public.is_global_manager()) then raise exception 'No tienes permiso para aplicar configuración masiva.'; end if;
 if jsonb_typeof(p_changes)<>'array' or jsonb_array_length(p_changes)=0 then raise exception 'No hay presentaciones para aplicar.'; end if;
 for c in select value from jsonb_array_elements(p_changes) loop
  select * into p from public.product_uom_profiles where id=(c->>'profile_id')::uuid and is_active=true; if not found then raise exception 'La presentación ya no está activa.'; end if;
  label_value:=nullif(trim(c->>'label'),''); input_unit:=nullif(trim(c->>'input_unit_code'),''); stock_qty:=(c->>'qty_in_stock_unit')::numeric;
  if label_value is null or input_unit is null or stock_qty<=0 then raise exception 'Nombre, unidad y equivalencia deben ser válidos.'; end if;
  insert into public.product_uom_profiles(product_id,label,input_unit_code,qty_in_input_unit,qty_in_stock_unit,is_default,is_active,source,usage_context,image_url,catalog_image_url)
  values(p.product_id,label_value,input_unit,coalesce(p.qty_in_input_unit,1),stock_qty,p.is_default,true,'master_configurator',p.usage_context,p.image_url,p.catalog_image_url) returning id into new_id;
  update public.product_uom_profiles set is_active=false,is_default=false,updated_at=now() where id=p.id;
  update public.product_suppliers set uom_profile_id=new_id,updated_at=now() where uom_profile_id=p.id;
  total:=total+1;
 end loop;
 insert into public.product_configuration_batches(zone,summary,product_count,created_by) values('presentations',jsonb_build_object('versions',p_changes),total,auth.uid()) returning id into batch_id; return batch_id;
end; $$;


ALTER FUNCTION "public"."apply_master_presentation_version_batch"("p_changes" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_master_product_identity_batch"("p_changes" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_change jsonb;
  v_product_id uuid;
  v_name text;
  v_sku text;
  v_category_id uuid;
  v_is_active boolean;
  v_product_type text;
  v_batch_id uuid;
  v_count integer := 0;
begin
  if not (public.is_owner() or public.is_global_manager()) then
    raise exception 'No tienes permiso para aplicar configuración masiva.';
  end if;
  if jsonb_typeof(p_changes) <> 'array' or jsonb_array_length(p_changes) = 0 then
    raise exception 'No hay cambios para aplicar.';
  end if;

  for v_change in select value from jsonb_array_elements(p_changes) loop
    v_product_id := (v_change->>'product_id')::uuid;
    v_name := nullif(trim(v_change->>'name'), '');
    v_sku := nullif(trim(v_change->>'sku'), '');
    v_category_id := (v_change->>'category_id')::uuid;
    v_is_active := coalesce((v_change->>'is_active')::boolean, true);
    if v_name is null then raise exception 'El nombre es obligatorio.'; end if;

    select product_type into v_product_type from public.products where id = v_product_id;
    if not found then raise exception 'Producto no encontrado.'; end if;
    if not exists (
      select 1 from public.product_categories
      where id = v_category_id
        and is_active = true
        and applies_to_kinds @> array[v_product_type]
    ) then
      raise exception 'La categoría seleccionada no es válida para el producto.';
    end if;

    update public.products
    set name = v_name, sku = v_sku, category_id = v_category_id, is_active = v_is_active, updated_at = now()
    where id = v_product_id;
    v_count := v_count + 1;
  end loop;

  insert into public.product_configuration_batches(zone, summary, product_count, created_by)
  values ('identity', jsonb_build_object('changes', p_changes), v_count, auth.uid())
  returning id into v_batch_id;
  return v_batch_id;
end;
$$;


ALTER FUNCTION "public"."apply_master_product_identity_batch"("p_changes" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_master_product_site_batch"("p_changes" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare c jsonb; pid uuid; sid uuid; minimum numeric; bid uuid; total integer:=0;
begin
 if not (public.is_owner() or public.is_global_manager()) then raise exception 'No tienes permiso para aplicar configuración masiva.'; end if;
 if jsonb_typeof(p_changes)<>'array' or jsonb_array_length(p_changes)=0 then raise exception 'No hay configuraciones por sede.'; end if;
 for c in select value from jsonb_array_elements(p_changes) loop
  pid:=(c->>'product_id')::uuid; sid:=(c->>'site_id')::uuid; minimum:=coalesce((c->>'min_stock_qty')::numeric,0);
  if minimum<0 then raise exception 'El mínimo no puede ser negativo.'; end if;
  if not exists(select 1 from public.products where id=pid) or not exists(select 1 from public.sites where id=sid) then raise exception 'Producto o sede inválidos.'; end if;
  insert into public.product_site_settings(product_id,site_id,is_active,inventory_enabled,remission_enabled,sales_enabled,min_stock_qty,updated_at)
  values(pid,sid,coalesce((c->>'is_active')::boolean,true),coalesce((c->>'inventory_enabled')::boolean,true),coalesce((c->>'remission_enabled')::boolean,false),coalesce((c->>'sales_enabled')::boolean,false),minimum,now())
  on conflict(product_id,site_id) do update set is_active=excluded.is_active,inventory_enabled=excluded.inventory_enabled,remission_enabled=excluded.remission_enabled,sales_enabled=excluded.sales_enabled,min_stock_qty=excluded.min_stock_qty,updated_at=now(); total:=total+1;
 end loop;
 insert into public.product_configuration_batches(zone,summary,product_count,created_by) values('sites',jsonb_build_object('changes',p_changes),total,auth.uid()) returning id into bid; return bid;
end; $$;


ALTER FUNCTION "public"."apply_master_product_site_batch"("p_changes" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_master_production_route_batch"("p_changes" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare c jsonb; pid uuid; sid uuid; input_loc uuid; output_loc uuid; area text; bid uuid; total integer:=0;
begin
 if not (public.is_owner() or public.is_global_manager()) then raise exception 'No tienes permiso para aplicar configuración masiva.'; end if;
 if jsonb_typeof(p_changes)<>'array' or jsonb_array_length(p_changes)=0 then raise exception 'No hay rutas de producción.'; end if;
 for c in select value from jsonb_array_elements(p_changes) loop
  pid:=(c->>'product_id')::uuid; sid:=(c->>'site_id')::uuid; input_loc:=(c->>'input_location_id')::uuid; output_loc:=(c->>'output_location_id')::uuid; area:=nullif(trim(c->>'area_kind'),'');
  if area is null or not exists(select 1 from public.inventory_locations where id=input_loc and site_id=sid) or not exists(select 1 from public.inventory_locations where id=output_loc and site_id=sid) then raise exception 'Área o LOC inválido para la sede seleccionada.'; end if;
  insert into public.product_site_production_routes(product_id,site_id,area_kind,input_location_id,output_mode,output_location_id,is_active)
  values(pid,sid,area,input_loc,'specific_location',output_loc,true)
  on conflict(product_id,site_id) do update set area_kind=excluded.area_kind,input_location_id=excluded.input_location_id,output_mode=excluded.output_mode,output_location_id=excluded.output_location_id,is_active=true; total:=total+1;
 end loop;
 insert into public.product_configuration_batches(zone,summary,product_count,created_by) values('production',jsonb_build_object('changes',p_changes),total,auth.uid()) returning id into bid; return bid;
end; $$;


ALTER FUNCTION "public"."apply_master_production_route_batch"("p_changes" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_master_request_policy_batch"("p_changes" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare c jsonb; p public.product_request_policies%rowtype; u text; q numeric; mn numeric; st numeric; uses integer; nid uuid; bid uuid; total integer:=0;
begin
 if not (public.is_owner() or public.is_global_manager()) then raise exception 'No tienes permiso para aplicar configuración masiva.'; end if;
 if jsonb_typeof(p_changes)<>'array' or jsonb_array_length(p_changes)=0 then raise exception 'No hay cambios para aplicar.'; end if;
 for c in select value from jsonb_array_elements(p_changes) loop
  select * into p from public.product_request_policies where id=(c->>'policy_id')::uuid and is_active=true; if not found then raise exception 'La política ya no está activa.'; end if;
  u:=nullif(trim(c->>'request_unit_code'),''); q:=(c->>'base_qty_per_request_unit')::numeric; mn:=(c->>'minimum_request_qty')::numeric; st:=(c->>'request_step_qty')::numeric;
  if u is null or q<=0 or mn<=0 or st<=0 then raise exception 'Unidad, equivalencia, mínimo y paso deben ser válidos.'; end if;
  select count(*) into uses from public.restock_request_items where request_policy_id=p.id;
  if uses>0 then
   update public.product_request_policies set is_active=false,is_default=false,updated_at=now(),change_reason='Reemplazada desde configurador maestro.' where id=p.id;
   insert into public.product_request_policies(product_id,label,request_unit_code,base_unit_code,base_qty_per_request_unit,constraint_mode,minimum_request_qty,request_step_qty,allow_fraction,policy_kind,physical_uom_profile_id,is_active,is_default,source,version_number,supersedes_policy_id,change_reason,created_by) values(p.product_id,p.label,u,p.base_unit_code,q,p.constraint_mode,mn,st,p.allow_fraction,'logical_group',null,true,true,p.source,p.version_number+1,p.id,'Cambio integral desde configurador maestro.',auth.uid()) returning id into nid;
   insert into public.product_request_policy_presentations(request_policy_id,uom_profile_id,is_preferred,allow_substitution,priority) select nid,uom_profile_id,is_preferred,allow_substitution,priority from public.product_request_policy_presentations where request_policy_id=p.id;
  else update public.product_request_policies set request_unit_code=u,base_qty_per_request_unit=q,minimum_request_qty=mn,request_step_qty=st,updated_at=now() where id=p.id; end if;
  total:=total+1;
 end loop;
 insert into public.product_configuration_batches(zone,summary,product_count,created_by) values('request_policies',jsonb_build_object('changes',p_changes),total,auth.uid()) returning id into bid; return bid;
end; $$;


ALTER FUNCTION "public"."apply_master_request_policy_batch"("p_changes" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_master_request_policy_rules_batch"("p_changes" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare c jsonb; p public.product_request_policies%rowtype; n numeric; s numeric; usage_count integer; new_id uuid; batch_id uuid; total integer := 0;
begin
  if not (public.is_owner() or public.is_global_manager()) then raise exception 'No tienes permiso para aplicar configuración masiva.'; end if;
  if jsonb_typeof(p_changes) <> 'array' or jsonb_array_length(p_changes)=0 then raise exception 'No hay cambios para aplicar.'; end if;
  for c in select value from jsonb_array_elements(p_changes) loop
    select * into p from public.product_request_policies where id=(c->>'policy_id')::uuid and is_active=true;
    if not found then raise exception 'La política ya no está activa.'; end if;
    n := (c->>'minimum_request_qty')::numeric; s := (c->>'request_step_qty')::numeric;
    if n <= 0 or s <= 0 then raise exception 'El mínimo y el paso deben ser mayores que cero.'; end if;
    select count(*) into usage_count from public.restock_request_items where request_policy_id=p.id;
    if usage_count > 0 and (p.minimum_request_qty <> n or p.request_step_qty <> s) then
      update public.product_request_policies set is_active=false,is_default=false,updated_at=now(),change_reason='Reemplazada desde configurador maestro.' where id=p.id;
      insert into public.product_request_policies(product_id,label,request_unit_code,base_unit_code,base_qty_per_request_unit,constraint_mode,minimum_request_qty,request_step_qty,allow_fraction,policy_kind,physical_uom_profile_id,is_active,is_default,source,version_number,supersedes_policy_id,change_reason,created_by)
      values(p.product_id,p.label,p.request_unit_code,p.base_unit_code,p.base_qty_per_request_unit,p.constraint_mode,n,s,p.allow_fraction,p.policy_kind,p.physical_uom_profile_id,true,true,p.source,p.version_number+1,p.id,'Cambio de mínimo o paso desde configurador maestro.',auth.uid()) returning id into new_id;
      insert into public.product_request_policy_presentations(request_policy_id,uom_profile_id,is_preferred,allow_substitution,priority)
      select new_id,uom_profile_id,is_preferred,allow_substitution,priority from public.product_request_policy_presentations where request_policy_id=p.id;
    else
      update public.product_request_policies set minimum_request_qty=n,request_step_qty=s,updated_at=now() where id=p.id;
    end if; total:=total+1;
  end loop;
  insert into public.product_configuration_batches(zone,summary,product_count,created_by) values('request_policies',jsonb_build_object('rules',p_changes),total,auth.uid()) returning id into batch_id;
  return batch_id;
end; $$;


ALTER FUNCTION "public"."apply_master_request_policy_rules_batch"("p_changes" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_master_request_policy_units_batch"("p_changes" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare c jsonb; p public.product_request_policies%rowtype; unit_code text; qty numeric; usage_count integer; new_id uuid; batch_id uuid; total integer := 0;
begin
  if not (public.is_owner() or public.is_global_manager()) then raise exception 'No tienes permiso para aplicar configuración masiva.'; end if;
  if jsonb_typeof(p_changes) <> 'array' or jsonb_array_length(p_changes)=0 then raise exception 'No hay cambios para aplicar.'; end if;
  for c in select value from jsonb_array_elements(p_changes) loop
    select * into p from public.product_request_policies where id=(c->>'policy_id')::uuid and is_active=true;
    if not found then raise exception 'La política ya no está activa.'; end if;
    unit_code := nullif(trim(c->>'request_unit_code'),''); qty := (c->>'base_qty_per_request_unit')::numeric;
    if unit_code is null or qty <= 0 then raise exception 'La unidad visible y equivalencia deben ser válidas.'; end if;
    if p.base_unit_code is null then raise exception 'La política no tiene unidad base compatible.'; end if;
    select count(*) into usage_count from public.restock_request_items where request_policy_id=p.id;
    if usage_count > 0 and (p.request_unit_code<>unit_code or p.base_qty_per_request_unit<>qty) then
      update public.product_request_policies set is_active=false,is_default=false,updated_at=now(),change_reason='Reemplazada desde configurador maestro.' where id=p.id;
      insert into public.product_request_policies(product_id,label,request_unit_code,base_unit_code,base_qty_per_request_unit,constraint_mode,minimum_request_qty,request_step_qty,allow_fraction,policy_kind,physical_uom_profile_id,is_active,is_default,source,version_number,supersedes_policy_id,change_reason,created_by)
      values(p.product_id,coalesce(nullif(trim(c->>'label'),''),p.label),unit_code,p.base_unit_code,qty,p.constraint_mode,p.minimum_request_qty,p.request_step_qty,p.allow_fraction,'logical_group',null,true,true,p.source,p.version_number+1,p.id,'Cambio de unidad o equivalencia desde configurador maestro.',auth.uid()) returning id into new_id;
      insert into public.product_request_policy_presentations(request_policy_id,uom_profile_id,is_preferred,allow_substitution,priority) select new_id,uom_profile_id,is_preferred,allow_substitution,priority from public.product_request_policy_presentations where request_policy_id=p.id;
    else
      update public.product_request_policies set request_unit_code=unit_code,base_qty_per_request_unit=qty,label=coalesce(nullif(trim(c->>'label'),''),label),updated_at=now() where id=p.id;
    end if; total:=total+1;
  end loop;
  insert into public.product_configuration_batches(zone,summary,product_count,created_by) values('request_policies',jsonb_build_object('units',p_changes),total,auth.uid()) returning id into batch_id; return batch_id;
end; $$;


ALTER FUNCTION "public"."apply_master_request_policy_units_batch"("p_changes" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_master_supplier_purchase_batch"("p_changes" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare c jsonb; supplier_link uuid; price numeric; pack_qty numeric; unit_code text; primary_flag boolean; batch_id uuid; total integer:=0;
begin
 if not (public.is_owner() or public.is_global_manager()) then raise exception 'No tienes permiso para aplicar configuración masiva.'; end if;
 if jsonb_typeof(p_changes)<>'array' or jsonb_array_length(p_changes)=0 then raise exception 'No hay cambios para aplicar.'; end if;
 for c in select value from jsonb_array_elements(p_changes) loop
  supplier_link := (c->>'product_supplier_id')::uuid; price := (c->>'purchase_price')::numeric; pack_qty := (c->>'purchase_pack_qty')::numeric; unit_code:=nullif(trim(c->>'purchase_pack_unit_code'),''); primary_flag:=coalesce((c->>'is_primary')::boolean,false);
  if price<0 or pack_qty<=0 or unit_code is null then raise exception 'Precio, empaque y unidad de compra deben ser válidos.'; end if;
  if not exists(select 1 from public.product_suppliers where id=supplier_link) then raise exception 'La relación con proveedor no existe.'; end if;
  if primary_flag then update public.product_suppliers set is_primary=false where product_id=(select product_id from public.product_suppliers where id=supplier_link); end if;
  update public.product_suppliers set purchase_price=price,purchase_pack_qty=pack_qty,purchase_pack_unit_code=unit_code,is_primary=primary_flag,updated_at=now() where id=supplier_link;
  total:=total+1;
 end loop;
 insert into public.product_configuration_batches(zone,summary,product_count,created_by) values('supplier_purchase',jsonb_build_object('supplier_purchase',p_changes),total,auth.uid()) returning id into batch_id; return batch_id;
end; $$;


ALTER FUNCTION "public"."apply_master_supplier_purchase_batch"("p_changes" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_operational_profile_to_shift"("p_shift_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_shift public.employee_shifts%rowtype;
  v_profile public.employee_site_operational_profiles%rowtype;
begin
  if not (public.is_owner() or public.is_global_manager() or public.is_manager()) then
    raise exception 'Not authorized to apply operational profiles to shifts';
  end if;

  select * into v_shift
  from public.employee_shifts
  where id = p_shift_id;

  if not found then
    raise exception 'Shift not found';
  end if;

  select * into v_profile
  from public.employee_site_operational_profiles
  where employee_id = v_shift.employee_id
    and site_id = v_shift.site_id
    and is_active = true
  limit 1;

  if not found then
    return p_shift_id;
  end if;

  update public.employee_shifts
     set operational_role = coalesce(employee_shifts.operational_role, v_profile.default_operational_role),
         checkin_site_id = coalesce(employee_shifts.checkin_site_id, v_profile.default_checkin_site_id),
         checkout_site_id = coalesce(employee_shifts.checkout_site_id, v_profile.default_checkout_site_id),
         updated_at = now()
   where id = p_shift_id;

  return p_shift_id;
end;
$$;


ALTER FUNCTION "public"."apply_operational_profile_to_shift"("p_shift_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_operational_profile_to_shift"("p_shift_id" "uuid") IS 'Applies employee/site operational defaults to a shift without overriding explicit shift values.';



CREATE OR REPLACE FUNCTION "public"."apply_request_policy_to_restock_item"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'storage', 'extensions'
    AS $$
declare
  v_policy public.product_request_policies%rowtype;
  v_ratio numeric;
begin
  if new.request_policy_id is null then
    return new;
  end if;

  if tg_op = 'UPDATE'
     and new.request_policy_id is not distinct from old.request_policy_id
     and new.requested_policy_qty is not distinct from old.requested_policy_qty then
    return new;
  end if;

  select * into v_policy
  from public.product_request_policies
  where id = new.request_policy_id;

  if v_policy.id is null
     or v_policy.is_active is false
     or v_policy.product_id <> new.product_id then
    raise exception 'La política de solicitud no existe, está inactiva o pertenece a otro producto.';
  end if;

  if new.requested_policy_qty is null or new.requested_policy_qty <= 0 then
    raise exception 'La cantidad solicitada por política debe ser mayor a cero.';
  end if;

  if not v_policy.allow_fraction and new.requested_policy_qty <> trunc(new.requested_policy_qty) then
    raise exception 'Esta política no permite cantidades fraccionarias.';
  end if;

  if v_policy.minimum_request_qty is not null
     and new.requested_policy_qty < v_policy.minimum_request_qty then
    raise exception 'La cantidad solicitada es menor al mínimo permitido (%).', v_policy.minimum_request_qty;
  end if;

  if v_policy.constraint_mode = 'strict_multiple' then
    v_ratio := new.requested_policy_qty / v_policy.request_step_qty;
    if abs(v_ratio - round(v_ratio)) > 0.000001 then
      raise exception 'La cantidad solicitada debe ser múltiplo de %.', v_policy.request_step_qty;
    end if;
  end if;

  new.request_policy_kind := v_policy.policy_kind;
  new.request_policy_label := v_policy.label;
  new.request_unit_code := v_policy.request_unit_code;
  new.base_qty_per_request_unit := v_policy.base_qty_per_request_unit;
  new.request_constraint_mode := v_policy.constraint_mode;
  new.request_minimum_qty := v_policy.minimum_request_qty;
  new.request_step_qty := v_policy.request_step_qty;
  new.request_allow_fraction := v_policy.allow_fraction;
  new.input_qty := new.requested_policy_qty;
  new.input_unit_code := case
    when v_policy.policy_kind in ('base_unit','actual_quantity') then v_policy.request_unit_code
    else v_policy.base_unit_code
  end;
  new.input_uom_profile_id := case
    when v_policy.policy_kind = 'physical_presentation' then v_policy.physical_uom_profile_id
    else null
  end;
  new.conversion_factor_to_stock := v_policy.base_qty_per_request_unit;
  new.stock_unit_code := v_policy.base_unit_code;
  new.unit := v_policy.base_unit_code;
  new.quantity := round(new.requested_policy_qty * v_policy.base_qty_per_request_unit, 6);
  new.production_package_plan := '[]'::jsonb;
  new.requires_package_dispatch := false;

  return new;
end;
$$;


ALTER FUNCTION "public"."apply_request_policy_to_restock_item"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_restock_receipt"("p_request_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_request record;
  v_item record;
  v_qty numeric;
  v_aux_count numeric;
  v_aux_unit text;
begin
  select *
  into v_request
  from public.restock_requests
  where id = p_request_id;

  if v_request.id is null then
    raise exception 'restock_request not found: %', p_request_id;
  end if;

  if v_request.to_site_id is null then
    raise exception 'to_site_id requerido para recepcion de remision';
  end if;

  if not public.has_permission('nexo.inventory.remissions.receive', v_request.to_site_id) then
    raise exception 'permission denied: remissions.receive';
  end if;

  for v_item in
    select *
    from public.restock_request_items
    where request_id = p_request_id
  loop
    v_qty := coalesce(v_item.received_quantity, 0);
    if v_qty <= 0 then
      continue;
    end if;

    v_aux_count := v_item.received_aux_count;
    v_aux_unit := nullif(btrim(coalesce(v_item.aux_count_unit_code, '')), '');

    if v_aux_count is not null and v_aux_count <= 0 then
      v_aux_count := null;
    end if;

    insert into public.inventory_movements (
      site_id,
      product_id,
      movement_type,
      quantity,
      note,
      related_restock_request_id,
      aux_count,
      aux_count_unit_code
    )
    values (
      v_request.to_site_id,
      v_item.product_id,
      'transfer_in',
      v_qty,
      'Recepcion remision ' || p_request_id::text,
      p_request_id,
      v_aux_count,
      v_aux_unit
    );

    insert into public.inventory_stock_by_site (site_id, product_id, current_qty, updated_at)
    values (v_request.to_site_id, v_item.product_id, v_qty, now())
    on conflict (site_id, product_id)
    do update set
      current_qty = public.inventory_stock_by_site.current_qty + excluded.current_qty,
      updated_at = now();
  end loop;
end;
$$;


ALTER FUNCTION "public"."apply_restock_receipt"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_restock_shipment"("p_request_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_request record;
  v_item record;
  v_qty numeric;
  v_aux_count numeric;
  v_aux_unit text;
begin
  select *
  into v_request
  from public.restock_requests
  where id = p_request_id;

  if v_request.id is null then
    raise exception 'restock_request not found: %', p_request_id;
  end if;

  if v_request.from_site_id is null then
    raise exception 'from_site_id requerido para salida de remision';
  end if;

  if not public.has_permission('nexo.inventory.remissions.prepare', v_request.from_site_id) then
    raise exception 'permission denied: remissions.prepare';
  end if;

  for v_item in
    select *
    from public.restock_request_items
    where request_id = p_request_id
  loop
    v_qty := coalesce(v_item.shipped_quantity, 0);
    if v_qty <= 0 then
      continue;
    end if;

    v_aux_count := v_item.shipped_aux_count;
    v_aux_unit := nullif(btrim(coalesce(v_item.aux_count_unit_code, '')), '');

    if v_aux_count is not null and v_aux_count <= 0 then
      v_aux_count := null;
    end if;

    insert into public.inventory_movements (
      site_id,
      product_id,
      movement_type,
      quantity,
      note,
      related_restock_request_id,
      aux_count,
      aux_count_unit_code
    )
    values (
      v_request.from_site_id,
      v_item.product_id,
      'transfer_out',
      v_qty,
      'Salida remision ' || p_request_id::text,
      p_request_id,
      v_aux_count,
      v_aux_unit
    );

    insert into public.inventory_stock_by_site (site_id, product_id, current_qty, updated_at)
    values (v_request.from_site_id, v_item.product_id, -v_qty, now())
    on conflict (site_id, product_id)
    do update set
      current_qty = public.inventory_stock_by_site.current_qty + excluded.current_qty,
      updated_at = now();

    if v_item.source_location_id is not null then
      perform public.upsert_inventory_stock_by_location(
        v_item.source_location_id,
        v_item.product_id,
        -v_qty
      );
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "public"."apply_restock_shipment"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_restock_shipment_from_picks"("p_request_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_request record;
  v_pick record;
  v_item record;
  v_pick_count integer := 0;
  v_total_base_qty numeric := 0;
  v_available_site numeric := 0;
  v_available_loc numeric := 0;
  v_available_position numeric := 0;
  v_positioned_qty numeric := 0;
begin
  select *
    into v_request
  from public.restock_requests
  where id = p_request_id
  for update;

  if not found then
    raise exception 'restock_request not found: %', p_request_id;
  end if;

  if v_request.from_site_id is null then
    raise exception 'from_site_id requerido para salida de remision';
  end if;

  if not public.has_permission('nexo.inventory.remissions.prepare', v_request.from_site_id) then
    raise exception 'permission denied: remissions.prepare';
  end if;

  if exists (
    select 1
    from public.inventory_movements movements
    where movements.related_restock_request_id = p_request_id
      and movements.movement_type = 'transfer_out'
  ) then
    raise exception 'shipment already applied for restock request %', p_request_id;
  end if;

  select count(*)
    into v_pick_count
  from public.restock_request_item_picks pick
  where pick.request_id = p_request_id;

  if coalesce(v_pick_count, 0) <= 0 then
    raise exception 'no picks found for restock request %', p_request_id;
  end if;

  -- Sincroniza cantidades preparadas/enviadas por línea a partir del plan físico.
  for v_item in
    select
      item.id,
      item.product_id,
      item.quantity,
      coalesce(sum(pick.base_qty), 0) as picked_qty
    from public.restock_request_items item
    left join public.restock_request_item_picks pick on pick.item_id = item.id
    where item.request_id = p_request_id
    group by item.id, item.product_id, item.quantity
  loop
    if coalesce(v_item.picked_qty, 0) <= 0 then
      raise exception 'item % has no prepared picks', v_item.id;
    end if;

    if v_item.picked_qty > coalesce(v_item.quantity, 0) + 0.000001 then
      raise exception 'picked quantity (%) exceeds requested quantity (%) for item %',
        v_item.picked_qty, v_item.quantity, v_item.id;
    end if;

    update public.restock_request_items
    set prepared_quantity = v_item.picked_qty,
        shipped_quantity = v_item.picked_qty
    where id = v_item.id;
  end loop;

  -- Valida stock agregado por sede.
  for v_pick in
    select product_id, sum(base_qty) as total_qty
    from public.restock_request_item_picks
    where request_id = p_request_id
    group by product_id
  loop
    select coalesce(stock.current_qty, 0)
      into v_available_site
    from public.inventory_stock_by_site stock
    where stock.site_id = v_request.from_site_id
      and stock.product_id = v_pick.product_id
    for update;

    v_available_site := coalesce(v_available_site, 0);

    if v_pick.total_qty > v_available_site + 0.000001 then
      raise exception 'insufficient site stock for product %. Requested %, available %',
        v_pick.product_id, v_pick.total_qty, v_available_site;
    end if;
  end loop;

  -- Valida stock agregado por LOC.
  for v_pick in
    select source_location_id, product_id, sum(base_qty) as total_qty
    from public.restock_request_item_picks
    where request_id = p_request_id
    group by source_location_id, product_id
  loop
    select coalesce(stock.current_qty, 0)
      into v_available_loc
    from public.inventory_stock_by_location stock
    where stock.location_id = v_pick.source_location_id
      and stock.product_id = v_pick.product_id
    for update;

    v_available_loc := coalesce(v_available_loc, 0);

    if v_pick.total_qty > v_available_loc + 0.000001 then
      raise exception 'insufficient LOC stock for product %. Requested %, available %',
        v_pick.product_id, v_pick.total_qty, v_available_loc;
    end if;
  end loop;

  -- Valida stock agregado por posición interna.
  for v_pick in
    select source_location_position_id, product_id, sum(base_qty) as total_qty
    from public.restock_request_item_picks
    where request_id = p_request_id
      and source_location_position_id is not null
    group by source_location_position_id, product_id
  loop
    select coalesce(stock.current_qty, 0)
      into v_available_position
    from public.inventory_stock_by_position stock
    where stock.position_id = v_pick.source_location_position_id
      and stock.product_id = v_pick.product_id
    for update;

    v_available_position := coalesce(v_available_position, 0);

    if v_pick.total_qty > v_available_position + 0.000001 then
      raise exception 'insufficient internal position stock for product %. Requested %, available %',
        v_pick.product_id, v_pick.total_qty, v_available_position;
    end if;
  end loop;

  -- Valida stock no posicionado cuando el pick no trae posición interna.
  for v_pick in
    select source_location_id, product_id, sum(base_qty) as total_qty
    from public.restock_request_item_picks
    where request_id = p_request_id
      and source_location_position_id is null
    group by source_location_id, product_id
  loop
    select coalesce(stock.current_qty, 0)
      into v_available_loc
    from public.inventory_stock_by_location stock
    where stock.location_id = v_pick.source_location_id
      and stock.product_id = v_pick.product_id
    for update;

    select coalesce(sum(coalesce(position_stock.current_qty, 0)), 0)
      into v_positioned_qty
    from public.inventory_stock_by_position position_stock
    join public.inventory_location_positions position
      on position.id = position_stock.position_id
    where position.location_id = v_pick.source_location_id
      and position_stock.product_id = v_pick.product_id;

    v_available_loc := greatest(0, coalesce(v_available_loc, 0) - coalesce(v_positioned_qty, 0));

    if v_pick.total_qty > v_available_loc + 0.000001 then
      raise exception 'insufficient unpositioned LOC stock for product %. Requested %, available %',
        v_pick.product_id, v_pick.total_qty, v_available_loc;
    end if;
  end loop;

  for v_pick in
    select *
    from public.restock_request_item_picks
    where request_id = p_request_id
    order by created_at, id
  loop
    if v_pick.uom_profile_id is not null then
      perform public.consume_inventory_stock_by_uom_profile(
        v_pick.source_location_id,
        v_pick.product_id,
        v_pick.uom_profile_id,
        v_pick.presentation_qty,
        v_pick.base_qty,
        v_pick.source_location_position_id
      );
    end if;

    insert into public.inventory_movements (
      site_id,
      product_id,
      movement_type,
      quantity,
      note,
      related_restock_request_id,
      created_by,
      input_qty,
      input_unit_code,
      conversion_factor_to_stock,
      stock_unit_code,
      location_position_id,
      input_uom_profile_id
    )
    select
      v_request.from_site_id,
      v_pick.product_id,
      'transfer_out',
      v_pick.base_qty,
      coalesce(
        nullif(trim(v_pick.note), ''),
        'Salida remision ' || p_request_id::text
      ),
      p_request_id,
      coalesce(v_pick.created_by, auth.uid()),
      case when v_pick.uom_profile_id is not null then v_pick.presentation_qty else v_pick.base_qty end,
      coalesce(profile.input_unit_code, product.stock_unit_code, product.unit, 'un'),
      case
        when profile.id is not null
          and coalesce(profile.qty_in_input_unit, 0) > 0
          then profile.qty_in_stock_unit / profile.qty_in_input_unit
        else 1
      end,
      coalesce(product.stock_unit_code, product.unit, 'un'),
      v_pick.source_location_position_id,
      v_pick.uom_profile_id
    from public.products product
    left join public.product_uom_profiles profile on profile.id = v_pick.uom_profile_id
    where product.id = v_pick.product_id;

    insert into public.inventory_stock_by_site (site_id, product_id, current_qty, updated_at)
    values (v_request.from_site_id, v_pick.product_id, -v_pick.base_qty, now())
    on conflict (site_id, product_id)
    do update set
      current_qty = public.inventory_stock_by_site.current_qty + excluded.current_qty,
      updated_at = now();

    perform public.upsert_inventory_stock_by_location(
      v_pick.source_location_id,
      v_pick.product_id,
      -v_pick.base_qty
    );

    if v_pick.source_location_position_id is not null then
      insert into public.inventory_stock_by_position (
        position_id,
        product_id,
        current_qty,
        updated_at
      )
      values (
        v_pick.source_location_position_id,
        v_pick.product_id,
        -v_pick.base_qty,
        now()
      )
      on conflict (position_id, product_id) do update
        set current_qty = public.inventory_stock_by_position.current_qty + excluded.current_qty,
            updated_at = now();
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "public"."apply_restock_shipment_from_picks"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_shared_device_template_actor_policies_v1"("p_device_id" "uuid", "p_template_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_inserted integer := 0;
begin
  insert into public.shared_operational_device_actor_policies (
    device_id,
    policy_type,
    site_id,
    area_id,
    role_code,
    employee_id,
    is_active,
    notes
  )
  select
    d.id,
    tp.policy_type,
    case
      when tp.scope_strategy in ('device_site', 'device_area') then d.site_id
      else null
    end as site_id,
    case
      when tp.scope_strategy = 'device_area' then d.area_id
      else null
    end as area_id,
    tp.role_code,
    tp.employee_id,
    true,
    tp.notes
  from public.shared_operational_devices d
  join public.shared_operational_device_template_actor_policies tp
    on tp.template_id = p_template_id
   and tp.is_active
  where d.id = p_device_id;

  get diagnostics v_inserted = row_count;
  return v_inserted;
end;
$$;


