CREATE OR REPLACE FUNCTION "public"."checkout_record_payment_webhook_event"("p_provider" "text", "p_provider_event_id" "text", "p_transaction_id" "uuid", "p_signature_valid" boolean, "p_processed" boolean, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'payments'
    AS $$
declare
  v_result jsonb;
begin
  insert into payments.webhook_events (
    provider,
    provider_event_id,
    transaction_id,
    signature_valid,
    processed,
    processed_at,
    payload
  )
  values (
    p_provider,
    p_provider_event_id,
    p_transaction_id,
    coalesce(p_signature_valid, false),
    coalesce(p_processed, false),
    case when coalesce(p_processed, false) then now() else null end,
    coalesce(p_payload, '{}'::jsonb)
  )
  on conflict (provider, provider_event_id)
  do update set
    transaction_id = coalesce(excluded.transaction_id, payments.webhook_events.transaction_id),
    signature_valid = excluded.signature_valid,
    processed = excluded.processed,
    processed_at = case
      when excluded.processed then coalesce(payments.webhook_events.processed_at, now())
      else payments.webhook_events.processed_at
    end,
    payload = excluded.payload
  returning jsonb_build_object(
    'id', id,
    'processed', processed,
    'transaction_id', transaction_id
  )
  into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."checkout_record_payment_webhook_event"("p_provider" "text", "p_provider_event_id" "text", "p_transaction_id" "uuid", "p_signature_valid" boolean, "p_processed" boolean, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_inventory_count_session"("p_session_id" "uuid", "p_closed_by" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_session record;
  v_count integer := 0;
begin
  select *
  into v_session
  from public.inventory_count_sessions s
  where s.id = p_session_id
  for update;

  if not found then
    raise exception 'Sesion no encontrada';
  end if;

  if coalesce(v_session.status, '') <> 'open' then
    raise exception 'Sesion debe estar abierta';
  end if;

  update public.inventory_count_lines l
  set
    current_qty_at_close =
      case
        when l.location_position_id is not null then coalesce(pos_stock.current_qty, 0)
        when coalesce(v_session.scope_type, '') = 'loc' and v_session.scope_location_id is not null then coalesce(loc_stock.current_qty, 0)
        when coalesce(v_session.scope_type, '') = 'zone' and coalesce(v_session.scope_zone, '') <> '' then coalesce(zone_stock.current_qty, 0)
        else coalesce(site_stock.current_qty, 0)
      end,
    quantity_delta =
      coalesce(l.quantity_counted, 0) -
      case
        when l.location_position_id is not null then coalesce(pos_stock.current_qty, 0)
        when coalesce(v_session.scope_type, '') = 'loc' and v_session.scope_location_id is not null then coalesce(loc_stock.current_qty, 0)
        when coalesce(v_session.scope_type, '') = 'zone' and coalesce(v_session.scope_zone, '') <> '' then coalesce(zone_stock.current_qty, 0)
        else coalesce(site_stock.current_qty, 0)
      end
  from public.inventory_count_lines line_ref
  left join public.inventory_stock_by_position pos_stock
    on pos_stock.position_id = line_ref.location_position_id
   and pos_stock.product_id = line_ref.product_id
  left join public.inventory_stock_by_location loc_stock
    on loc_stock.location_id = v_session.scope_location_id
   and loc_stock.product_id = line_ref.product_id
  left join lateral (
    select coalesce(sum(s.current_qty), 0) as current_qty
    from public.inventory_locations il
    left join public.inventory_stock_by_location s
      on s.location_id = il.id
     and s.product_id = line_ref.product_id
    where il.site_id = v_session.site_id
      and il.zone = v_session.scope_zone
      and il.is_active is true
  ) zone_stock on coalesce(v_session.scope_type, '') = 'zone'
  left join public.inventory_stock_by_site site_stock
    on site_stock.site_id = v_session.site_id
   and site_stock.product_id = line_ref.product_id
  where l.id = line_ref.id
    and l.session_id = p_session_id;

  update public.inventory_count_sessions
  set
    status = 'closed',
    closed_at = now(),
    closed_by = p_closed_by
  where id = p_session_id;

  select count(*) into v_count
  from public.inventory_count_lines
  where session_id = p_session_id;

  return jsonb_build_object('sessionId', p_session_id, 'count', v_count);
end;
$$;


ALTER FUNCTION "public"."close_inventory_count_session"("p_session_id" "uuid", "p_closed_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_open_attendance_day_end"("p_timezone" "text" DEFAULT 'America/Bogota'::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_today date := (now() at time zone p_timezone)::date;
  v_closed int := 0;
begin
  with last_logs as (
    select distinct on (al.employee_id)
      al.employee_id,
      al.site_id,
      al.action,
      al.occurred_at,
      al.shift_id,
      (((al.occurred_at at time zone p_timezone)::date + 1)::timestamp - interval '1 second') at time zone p_timezone as local_day_end
    from public.attendance_logs al
    join public.employees e on e.id = al.employee_id
    where coalesce(e.is_active, false) = true
    order by al.employee_id, al.occurred_at desc, al.created_at desc
  ),
  inserted as (
    insert into public.attendance_logs (
      employee_id,
      site_id,
      action,
      source,
      occurred_at,
      latitude,
      longitude,
      accuracy_meters,
      device_info,
      notes,
      shift_id
    )
    select
      l.employee_id,
      l.site_id,
      'check_out',
      'system',
      l.local_day_end,
      s.latitude,
      s.longitude,
      0,
      jsonb_build_object(
        'auto_close',
        true,
        'reason',
        'day_end',
        'timezone',
        p_timezone
      ),
      'Cierre automatico: turno abierto cerrado por el sistema al final del dia',
      l.shift_id
    from last_logs l
    join public.sites s on s.id = l.site_id
    where l.action = 'check_in'
      and (l.occurred_at at time zone p_timezone)::date < v_today
      and not exists (
        select 1
        from public.attendance_logs ao
        where ao.employee_id = l.employee_id
          and ao.action = 'check_out'
          and ao.occurred_at > l.occurred_at
          and ao.occurred_at <= l.local_day_end
      )
    returning 1
  )
  select count(*) into v_closed from inserted;

  return v_closed;
end;
$$;


ALTER FUNCTION "public"."close_open_attendance_day_end"("p_timezone" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."close_open_attendance_day_end"("p_timezone" "text") IS 'Cierra turnos abiertos de dias locales anteriores al final exacto del dia del check-in para empleados activos.';



CREATE OR REPLACE FUNCTION "public"."close_stale_open_attendance_shifts"("p_now" timestamp with time zone DEFAULT "now"(), "p_timezone" "text" DEFAULT 'America/Bogota'::"text") RETURNS TABLE("employee_id" "uuid", "full_name" "text", "check_in_at" timestamp with time zone, "check_out_at" timestamp with time zone, "site_id" "uuid", "site_name" "text", "shift_id" "uuid", "close_reason" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  return query
  with ordered_logs as (
    select
      al.*,
      row_number() over (
        partition by al.employee_id
        order by al.occurred_at desc, al.created_at desc
      ) as rn
    from public.attendance_logs al
  ),
  open_logs as (
    select
      al.employee_id,
      al.site_id,
      al.geofence_site_id,
      al.shift_id,
      al.occurred_at as check_in_at
    from ordered_logs al
    where al.rn = 1
      and al.action = 'check_in'
      and (al.occurred_at at time zone p_timezone)::date < (p_now at time zone p_timezone)::date
  ),
  resolved as (
    select
      ol.*,
      e.full_name,
      s.name as site_name,
      case
        when es.id is not null then
          greatest(
            (
              es.shift_date::timestamp
              + es.end_time
              + case
                  when es.end_time <= es.start_time then interval '1 day'
                  else interval '0 day'
                end
            ) at time zone p_timezone,
            ol.check_in_at + interval '1 minute'
          )
        else
          greatest(
            (
              ((ol.check_in_at at time zone p_timezone)::date::timestamp + time '23:59:59')
              at time zone p_timezone
            ),
            ol.check_in_at + interval '1 minute'
          )
      end as target_check_out_at,
      case
        when es.id is not null then 'scheduled_shift_end_time'
        else 'local_day_end_fallback'
      end as close_reason
    from open_logs ol
    join public.employees e on e.id = ol.employee_id
    left join public.sites s on s.id = ol.site_id
    left join public.employee_shifts es
      on es.id = ol.shift_id
      and es.employee_id = ol.employee_id
      and es.shift_kind <> 'descanso'
  ),
  normalized as (
    select
      r.*,
      least(r.target_check_out_at, p_now) as check_out_at
    from resolved r
    where least(r.target_check_out_at, p_now) > r.check_in_at
  ),
  closed_breaks as (
    update public.attendance_breaks b
    set
      ended_at = n.check_out_at,
      end_source = coalesce(b.end_source, 'system'),
      end_notes = coalesce(
        b.end_notes,
        'Cierre automatico server-side por turno abierto de dia anterior.'
      )
    from normalized n
    where b.employee_id = n.employee_id
      and b.ended_at is null
    returning b.employee_id
  ),
  inserted as (
    insert into public.attendance_logs (
      employee_id,
      site_id,
      geofence_site_id,
      shift_id,
      action,
      source,
      occurred_at,
      latitude,
      longitude,
      accuracy_meters,
      notes,
      device_info
    )
    select
      n.employee_id,
      n.site_id,
      n.geofence_site_id,
      n.shift_id,
      'check_out',
      'system',
      n.check_out_at,
      null,
      null,
      null,
      'Cierre automatico server-side por turno abierto de dia anterior.',
      jsonb_build_object(
        'autoCheckout', true,
        'origin', 'server_stale_open_shift_processor',
        'sourceDetail', 'system_stale_auto_close',
        'closeReason', n.close_reason,
        'checkInAt', n.check_in_at,
        'processedAt', p_now
      )
    from normalized n
    where not exists (
      select 1
      from public.attendance_logs ao
      where ao.employee_id = n.employee_id
        and ao.action = 'check_out'
        and ao.occurred_at > n.check_in_at
    )
    returning
      attendance_logs.employee_id,
      attendance_logs.site_id,
      attendance_logs.shift_id,
      attendance_logs.occurred_at
  )
  select
    n.employee_id,
    n.full_name,
    n.check_in_at,
    i.occurred_at as check_out_at,
    n.site_id,
    n.site_name,
    n.shift_id,
    n.close_reason
  from inserted i
  join normalized n
    on n.employee_id = i.employee_id
    and n.site_id = i.site_id
    and (n.shift_id is not distinct from i.shift_id);
end;
$$;


ALTER FUNCTION "public"."close_stale_open_attendance_shifts"("p_now" timestamp with time zone, "p_timezone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_restock_item_status"("p_requested_qty" numeric, "p_prepared_qty" numeric, "p_shipped_qty" numeric, "p_received_qty" numeric, "p_shortage_qty" numeric) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'auth', 'storage', 'extensions'
    AS $$
declare
  v_requested_qty numeric := round(coalesce(p_requested_qty, 0)::numeric, 2);
  v_prepared_qty numeric := round(coalesce(p_prepared_qty, 0)::numeric, 2);
  v_shipped_qty numeric := round(coalesce(p_shipped_qty, 0)::numeric, 2);
  v_received_qty numeric := round(coalesce(p_received_qty, 0)::numeric, 2);
  v_accounted_qty numeric := round(coalesce(p_received_qty, 0)::numeric + coalesce(p_shortage_qty, 0)::numeric, 2);
begin
  if v_shipped_qty > 0 then
    if v_received_qty >= v_shipped_qty then
      return 'received';
    end if;

    if v_accounted_qty > 0 then
      return 'partial';
    end if;

    return 'in_transit';
  end if;

  if v_prepared_qty > 0 then
    return 'preparing';
  end if;

  if v_requested_qty > 0 then
    return 'pending';
  end if;

  return 'pending';
end;
$$;


ALTER FUNCTION "public"."compute_restock_item_status"("p_requested_qty" numeric, "p_prepared_qty" numeric, "p_shipped_qty" numeric, "p_received_qty" numeric, "p_shortage_qty" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_remission_shipment_receipt"("p_shipment_id" "uuid", "p_items" "jsonb", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_shipment public.remission_shipments%rowtype;
  v_shipment_item public.remission_shipment_items%rowtype;
  v_receipt_id uuid;
  v_item jsonb;
  v_shipment_item_id uuid;
  v_received_qty numeric;
  v_expected_total numeric := 0;
  v_received_total numeric := 0;
begin
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'Debes confirmar al menos una línea recibida.';
  end if;

  select * into v_shipment
  from public.remission_shipments
  where id = p_shipment_id
  for update;

  if not found then
    raise exception 'El envío no existe o no está disponible.';
  end if;
  if v_shipment.status <> 'in_transit' then
    raise exception 'Solo se pueden recibir envíos que estén en tránsito.';
  end if;

  insert into public.remission_receipts (
    shipment_id, status, received_at, received_by, notes, created_by, updated_by
  ) values (
    p_shipment_id, 'confirmed', now(), auth.uid(), nullif(trim(p_notes), ''), auth.uid(), auth.uid()
  ) returning id into v_receipt_id;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    begin
      v_shipment_item_id := (v_item ->> 'shipment_item_id')::uuid;
      v_received_qty := (v_item ->> 'received_base_qty')::numeric;
    exception when others then
      raise exception 'Una línea de recepción es inválida.';
    end;

    if v_received_qty < 0 then
      raise exception 'La cantidad recibida no puede ser negativa.';
    end if;

    select * into v_shipment_item
    from public.remission_shipment_items
    where id = v_shipment_item_id
      and shipment_id = p_shipment_id
    for update;

    if not found then
      raise exception 'Una línea no pertenece a este envío.';
    end if;
    if v_received_qty > v_shipment_item.base_qty then
      raise exception 'No puedes recibir más de lo que fue despachado.';
    end if;

    insert into public.remission_receipt_items (
      receipt_id, shipment_item_id, received_base_qty, accepted_base_qty, created_by
    ) values (
      v_receipt_id, v_shipment_item.id, v_received_qty, v_received_qty, auth.uid()
    );

    if v_received_qty < v_shipment_item.base_qty then
      insert into public.remission_exceptions (
        request_item_id, fulfillment_id, shipment_id, shipment_item_id, product_id,
        stage, exception_type, status, affected_base_qty, description, created_by, updated_by
      ) values (
        v_shipment_item.request_item_id, v_shipment_item.fulfillment_id, p_shipment_id,
        v_shipment_item.id, v_shipment_item.product_id,
        'receipt', 'shortage', 'open', v_shipment_item.base_qty - v_received_qty,
        'Faltante confirmado durante la recepción.', auth.uid(), auth.uid()
      );
    end if;

    v_expected_total := v_expected_total + v_shipment_item.base_qty;
    v_received_total := v_received_total + v_received_qty;
  end loop;

  if (select count(*) from public.remission_shipment_items where shipment_id = p_shipment_id) <> jsonb_array_length(p_items) then
    raise exception 'Debes confirmar todas las líneas del envío.';
  end if;

  update public.remission_shipments
  set status = case when v_received_total = v_expected_total then 'received' else 'partial_receipt' end,
      arrived_at = now(),
      updated_at = now(),
      updated_by = auth.uid()
  where id = p_shipment_id;

  return v_receipt_id;
end;
$$;


ALTER FUNCTION "public"."confirm_remission_shipment_receipt"("p_shipment_id" "uuid", "p_items" "jsonb", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."consume_inventory_stock_by_uom_profile"("p_location_id" "uuid", "p_product_id" "uuid", "p_uom_profile_id" "uuid", "p_presentation_qty" numeric, "p_base_qty" numeric, "p_location_position_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_site_id uuid;
  v_stock record;
begin
  select checked.site_id
    into v_site_id
  from public.assert_inventory_uom_profile_stock_input(
    p_location_id,
    p_location_position_id,
    p_product_id,
    p_uom_profile_id,
    coalesce(p_presentation_qty, 0),
    coalesce(p_base_qty, 0)
  ) checked;

  if coalesce(p_presentation_qty, 0) <= 0 or coalesce(p_base_qty, 0) <= 0 then
    raise exception 'presentation and base quantities must be greater than zero';
  end if;

  if not (
    public.has_permission('nexo.inventory.stock', v_site_id)
    or public.has_permission('nexo.inventory.transfers', v_site_id)
    or public.has_permission('nexo.inventory.withdraw', v_site_id)
    or public.has_permission('nexo.inventory.remissions.prepare', v_site_id)
  ) then
    raise exception 'permission denied';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_location_id::text || ':' || p_product_id::text || ':' || p_uom_profile_id::text || ':' || coalesce(p_location_position_id::text, ''), 0));

  select stock.id, stock.presentation_qty, stock.base_qty
    into v_stock
  from public.inventory_stock_by_uom_profile stock
  where stock.location_id = p_location_id
    and stock.product_id = p_product_id
    and stock.uom_profile_id = p_uom_profile_id
    and (
      (p_location_position_id is null and stock.location_position_id is null)
      or stock.location_position_id = p_location_position_id
    )
  for update;

  if not found or coalesce(v_stock.presentation_qty, 0) + 0.000001 < p_presentation_qty then
    raise exception 'insufficient physical stock for selected presentation';
  end if;

  if coalesce(v_stock.base_qty, 0) + 0.000001 < p_base_qty then
    raise exception 'insufficient base stock for selected presentation';
  end if;

  update public.inventory_stock_by_uom_profile
  set presentation_qty = presentation_qty - p_presentation_qty,
      base_qty = base_qty - p_base_qty,
      updated_at = now()
  where id = v_stock.id;
end;
$$;


ALTER FUNCTION "public"."consume_inventory_stock_by_uom_profile"("p_location_id" "uuid", "p_product_id" "uuid", "p_uom_profile_id" "uuid", "p_presentation_qty" numeric, "p_base_qty" numeric, "p_location_position_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."consume_inventory_stock_from_positions"("p_location_id" "uuid", "p_product_id" "uuid", "p_quantity" numeric, "p_created_by" "uuid" DEFAULT "auth"."uid"(), "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_location record;
  v_product record;
  v_remaining numeric := coalesce(p_quantity, 0);
  v_consumed_total numeric := 0;
  v_take numeric := 0;
  v_stock_unit_code text;
  v_position_count integer := 0;
  v_row record;
begin
  if p_location_id is null or p_product_id is null then
    raise exception 'location and product are required';
  end if;

  if coalesce(p_quantity, 0) <= 0 then
    return jsonb_build_object(
      'locationId', p_location_id,
      'productId', p_product_id,
      'requestedQty', coalesce(p_quantity, 0),
      'consumedQty', 0,
      'unpositionedQty', 0,
      'positionsTouched', 0
    );
  end if;

  select loc.id, loc.site_id, loc.code
    into v_location
  from public.inventory_locations loc
  where loc.id = p_location_id
    and coalesce(loc.is_active, true) = true;

  if not found then
    raise exception 'active LOC not found';
  end if;

  if not (
    public.has_permission('nexo.inventory.withdraw', v_location.site_id)
    or public.has_permission('nexo.inventory.stock', v_location.site_id)
  ) then
    raise exception 'permission denied';
  end if;

  select p.id, p.name, p.unit, p.stock_unit_code
    into v_product
  from public.products p
  where p.id = p_product_id;

  if not found then
    raise exception 'product not found';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_location_id::text || ':' || p_product_id::text, 0));

  for v_row in
    select sp.position_id, sp.current_qty, pos.name, pos.code, pos.sort_order
    from public.inventory_stock_by_position sp
    join public.inventory_location_positions pos on pos.id = sp.position_id
    where pos.location_id = p_location_id
      and sp.product_id = p_product_id
      and sp.current_qty > 0
      and coalesce(pos.is_active, true) = true
    order by sp.current_qty asc, coalesce(pos.sort_order, 0) asc, pos.code asc, sp.position_id asc
    for update of sp
  loop
    exit when v_remaining <= 0;

    v_take := least(v_remaining, coalesce(v_row.current_qty, 0));
    if v_take <= 0 then
      continue;
    end if;

    update public.inventory_stock_by_position
    set current_qty = current_qty - v_take,
        updated_at = now()
    where position_id = v_row.position_id
      and product_id = p_product_id;

    v_remaining := v_remaining - v_take;
    v_consumed_total := v_consumed_total + v_take;
    v_position_count := v_position_count + 1;
  end loop;

  if v_consumed_total > 0 then
    v_stock_unit_code := coalesce(nullif(v_product.stock_unit_code, ''), nullif(v_product.unit, ''), 'un');

    insert into public.inventory_movements (
      site_id,
      product_id,
      movement_type,
      quantity,
      input_qty,
      input_unit_code,
      conversion_factor_to_stock,
      stock_unit_code,
      note,
      created_by
    )
    values (
      v_location.site_id,
      p_product_id,
      'stock_consume_position',
      -v_consumed_total,
      v_consumed_total,
      v_stock_unit_code,
      1,
      v_stock_unit_code,
      coalesce(
        nullif(trim(p_note), ''),
        format(
          'Consumo interno %s: menor stock primero, %s posiciones',
          coalesce(v_location.code, p_location_id::text),
          v_position_count
        )
      ),
      p_created_by
    );
  end if;

  return jsonb_build_object(
    'locationId', p_location_id,
    'productId', p_product_id,
    'requestedQty', p_quantity,
    'consumedQty', v_consumed_total,
    'unpositionedQty', greatest(0, v_remaining),
    'positionsTouched', v_position_count,
    'rule', 'smallest_position_stock_first'
  );
end;
$$;


ALTER FUNCTION "public"."consume_inventory_stock_from_positions"("p_location_id" "uuid", "p_product_id" "uuid", "p_quantity" numeric, "p_created_by" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_gift_aware_scheduled_order_checkout_draft"("p_site_id" "uuid", "p_satellite_name" "text", "p_fulfillment_type" "text", "p_contact_name" "text", "p_contact_phone" "text", "p_address_line" "text", "p_address_reference" "text", "p_notes" "text", "p_items" "jsonb", "p_delivery_fee_amount" numeric, "p_source" "text", "p_delivery_distance_km" integer, "p_delivery_quote_id" "uuid", "p_invoice_requested" boolean, "p_billing_data" "jsonb", "p_schedule_mode" "text", "p_delivery_window_start" timestamp with time zone, "p_delivery_window_end" timestamp with time zone, "p_timezone" "text" DEFAULT 'America/Bogota'::"text", "p_gift_data" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pass', 'auth'
    AS $$
declare
  v_result jsonb;
  v_order_id uuid;
  v_saved_address_id uuid;
begin
  if auth.uid() is null then
    raise exception 'authentication_required';
  end if;

  v_result := public.create_scheduled_order_checkout_draft(
    p_site_id,
    p_satellite_name,
    p_fulfillment_type,
    p_contact_name,
    p_contact_phone,
    p_address_line,
    p_address_reference,
    p_notes,
    p_items,
    p_delivery_fee_amount,
    p_source,
    p_delivery_distance_km,
    p_delivery_quote_id,
    p_invoice_requested,
    p_billing_data,
    p_schedule_mode,
    p_delivery_window_start,
    p_delivery_window_end,
    p_timezone,
    p_gift_data
  );

  v_order_id := nullif(v_result ->> 'order_id', '')::uuid;
  v_saved_address_id := nullif(p_gift_data ->> 'saved_address_id', '')::uuid;

  if coalesce((p_gift_data ->> 'is_gift')::boolean, false)
     and v_saved_address_id is not null then
    perform public.link_gift_order_delivery_address(v_order_id, v_saved_address_id);
  end if;

  return v_result || jsonb_build_object('saved_address_id', v_saved_address_id);
end;
$$;


ALTER FUNCTION "public"."create_gift_aware_scheduled_order_checkout_draft"("p_site_id" "uuid", "p_satellite_name" "text", "p_fulfillment_type" "text", "p_contact_name" "text", "p_contact_phone" "text", "p_address_line" "text", "p_address_reference" "text", "p_notes" "text", "p_items" "jsonb", "p_delivery_fee_amount" numeric, "p_source" "text", "p_delivery_distance_km" integer, "p_delivery_quote_id" "uuid", "p_invoice_requested" boolean, "p_billing_data" "jsonb", "p_schedule_mode" "text", "p_delivery_window_start" timestamp with time zone, "p_delivery_window_end" timestamp with time zone, "p_timezone" "text", "p_gift_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_inventory_count_session_with_lines"("p_site_id" "uuid", "p_scope_type" "text", "p_scope_zone" "text", "p_scope_location_id" "uuid", "p_name" "text", "p_created_by" "uuid", "p_lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_scope_type text := lower(coalesce(nullif(trim(p_scope_type), ''), 'site'));
  v_scope_zone text := nullif(trim(coalesce(p_scope_zone, '')), '');
  v_session_id uuid;
  v_count integer := 0;
begin
  if jsonb_typeof(coalesce(p_lines, '[]'::jsonb)) <> 'array' then
    raise exception 'p_lines debe ser un arreglo JSON';
  end if;

  if v_scope_type not in ('site', 'zone', 'loc') then
    raise exception 'scope_type invalido: %', v_scope_type;
  end if;

  if v_scope_type = 'loc' then
    if p_scope_location_id is null then
      raise exception 'scope_location_id requerido para scope_type=loc';
    end if;

    if not exists (
      select 1
      from public.inventory_locations loc
      where loc.id = p_scope_location_id
        and loc.site_id = p_site_id
        and coalesce(loc.is_active, true) = true
    ) then
      raise exception 'LOC no pertenece a la sede del conteo';
    end if;
  end if;

  if v_scope_type = 'zone' and v_scope_zone is null then
    raise exception 'scope_zone requerido para scope_type=zone';
  end if;

  create temporary table tmp_count_lines_input (
    entry_order integer not null,
    product_id uuid not null,
    quantity numeric not null,
    input_quantity numeric null,
    input_unit_code text null,
    input_uom_profile_id uuid null,
    stock_unit_code text null,
    location_position_id uuid null
  ) on commit drop;

  insert into tmp_count_lines_input (
    entry_order,
    product_id,
    quantity,
    input_quantity,
    input_unit_code,
    input_uom_profile_id,
    stock_unit_code,
    location_position_id
  )
  select
    entry.ordinality::integer,
    (entry.value ->> 'product_id')::uuid,
    (entry.value ->> 'quantity')::numeric,
    nullif(trim(coalesce(entry.value ->> 'input_quantity', '')), '')::numeric,
    nullif(trim(coalesce(entry.value ->> 'input_unit_code', '')), ''),
    nullif(trim(coalesce(entry.value ->> 'uom_profile_id', '')), '')::uuid,
    nullif(trim(coalesce(entry.value ->> 'stock_unit_code', '')), ''),
    nullif(trim(coalesce(entry.value ->> 'position_id', '')), '')::uuid
  from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) with ordinality entry(value, ordinality)
  where nullif(trim(coalesce(entry.value ->> 'product_id', '')), '') is not null
    and coalesce((entry.value ->> 'quantity')::numeric, -1) >= 0;

  select count(*) into v_count from tmp_count_lines_input;
  if v_count = 0 then
    raise exception 'Al menos una linea capturada';
  end if;

  if exists (
    select 1
    from tmp_count_lines_input line
    left join public.products p on p.id = line.product_id
    where p.id is null
  ) then
    raise exception 'Una o mas lineas tienen producto invalido';
  end if;

  if exists (
    select 1
    from tmp_count_lines_input line
    join public.product_uom_profiles profile
      on profile.id = line.input_uom_profile_id
    where profile.product_id <> line.product_id
       or coalesce(profile.is_active, false) <> true
  ) then
    raise exception 'Una o mas presentaciones no pertenecen al producto o estan inactivas';
  end if;

  if exists (
    select 1
    from tmp_count_lines_input line
    where line.input_uom_profile_id is not null
      and not exists (
        select 1
        from public.product_uom_profiles profile
        where profile.id = line.input_uom_profile_id
      )
  ) then
    raise exception 'Una o mas presentaciones no existen';
  end if;

  if v_scope_type <> 'loc' and exists (
    select 1 from tmp_count_lines_input where location_position_id is not null
  ) then
    raise exception 'Las ubicaciones internas solo aplican para conteos por LOC';
  end if;

  if v_scope_type = 'loc' and exists (
    select 1
    from tmp_count_lines_input line
    where line.location_position_id is not null
      and not exists (
        select 1
        from public.inventory_location_positions pos
        where pos.id = line.location_position_id
          and pos.location_id = p_scope_location_id
          and pos.site_id = p_site_id
          and coalesce(pos.is_active, true) = true
      )
  ) then
    raise exception 'Una o mas ubicaciones internas no pertenecen al LOC del conteo';
  end if;

  create temporary table tmp_count_lines_agg (
    product_id uuid not null,
    location_position_id uuid null,
    quantity numeric not null,
    input_quantity numeric null,
    input_unit_code text null,
    input_uom_profile_id uuid null,
    stock_unit_code text null
  ) on commit drop;

  insert into tmp_count_lines_agg (
    product_id,
    location_position_id,
    quantity,
    input_quantity,
    input_unit_code,
    input_uom_profile_id,
    stock_unit_code
  )
  select
    product_id,
    location_position_id,
    sum(quantity) as quantity,
    case when count(distinct coalesce(input_unit_code, '')) = 1 then sum(coalesce(input_quantity, quantity)) else null end,
    case when count(distinct coalesce(input_unit_code, '')) = 1 then max(input_unit_code) else null end,
    case
      when count(distinct input_uom_profile_id) filter (where input_uom_profile_id is not null) = 1
        and count(*) filter (where input_uom_profile_id is null) = 0
        then (array_agg(input_uom_profile_id) filter (where input_uom_profile_id is not null))[1]
      else null
    end,
    (array_agg(stock_unit_code) filter (where stock_unit_code is not null))[1]
  from tmp_count_lines_input
  group by product_id, location_position_id;

  insert into public.inventory_count_sessions (
    site_id,
    status,
    scope_type,
    scope_zone,
    scope_location_id,
    name,
    created_by
  )
  values (
    p_site_id,
    'open',
    v_scope_type,
    case when v_scope_type = 'zone' then v_scope_zone else null end,
    case when v_scope_type = 'loc' then p_scope_location_id else null end,
    coalesce(
      nullif(trim(p_name), ''),
      case
        when v_scope_type = 'zone' then format('Conteo zona %s', v_scope_zone)
        when v_scope_type = 'loc' then 'Conteo por LOC'
        else 'Conteo'
      end
    ),
    p_created_by
  )
  returning id into v_session_id;

  insert into public.inventory_count_lines (
    session_id,
    product_id,
    quantity_counted,
    input_quantity,
    input_unit_code,
    input_uom_profile_id,
    stock_unit_code,
    location_position_id,
    current_qty_at_open
  )
  select
    v_session_id,
    li.product_id,
    li.quantity,
    li.input_quantity,
    li.input_unit_code,
    li.input_uom_profile_id,
    coalesce(li.stock_unit_code, p.stock_unit_code, p.unit, 'un'),
    li.location_position_id,
    case
      when li.location_position_id is not null then coalesce(pos_stock.current_qty, 0)
      when v_scope_type = 'loc' then coalesce(loc_stock.current_qty, 0)
      when v_scope_type = 'zone' then coalesce(zone_stock.current_qty, 0)
      else coalesce(site_stock.current_qty, 0)
    end
  from tmp_count_lines_agg li
  left join public.products p
    on p.id = li.product_id
  left join public.inventory_stock_by_position pos_stock
    on pos_stock.position_id = li.location_position_id
   and pos_stock.product_id = li.product_id
  left join public.inventory_stock_by_location loc_stock
    on loc_stock.location_id = p_scope_location_id
   and loc_stock.product_id = li.product_id
  left join lateral (
    select coalesce(sum(s.current_qty), 0) as current_qty
    from public.inventory_locations il
    left join public.inventory_stock_by_location s
      on s.location_id = il.id
     and s.product_id = li.product_id
    where il.site_id = p_site_id
      and il.zone = v_scope_zone
      and il.is_active is true
  ) zone_stock on v_scope_type = 'zone'
  left join public.inventory_stock_by_site site_stock
    on site_stock.site_id = p_site_id
   and site_stock.product_id = li.product_id;

  insert into public.inventory_count_line_entries (
    count_line_id,
    session_id,
    product_id,
    location_position_id,
    input_quantity,
    input_unit_code,
    input_uom_profile_id,
    quantity_counted,
    stock_unit_code,
    entry_order
  )
  select
    line.id,
    v_session_id,
    input.product_id,
    input.location_position_id,
    coalesce(input.input_quantity, input.quantity),
    coalesce(input.input_unit_code, input.stock_unit_code, p.stock_unit_code, p.unit, 'un'),
    input.input_uom_profile_id,
    input.quantity,
    coalesce(input.stock_unit_code, p.stock_unit_code, p.unit, 'un'),
    input.entry_order
  from tmp_count_lines_input input
  join public.inventory_count_lines line
    on line.session_id = v_session_id
   and line.product_id = input.product_id
   and line.location_position_id is not distinct from input.location_position_id
  left join public.products p
    on p.id = input.product_id
  order by input.entry_order;

  return jsonb_build_object('countSessionId', v_session_id, 'count', v_count);
end;
$$;


ALTER FUNCTION "public"."create_inventory_count_session_with_lines"("p_site_id" "uuid", "p_scope_type" "text", "p_scope_zone" "text", "p_scope_location_id" "uuid", "p_name" "text", "p_created_by" "uuid", "p_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_order_checkout_draft"("p_site_id" "uuid", "p_satellite_name" "text", "p_fulfillment_type" "text", "p_contact_name" "text", "p_contact_phone" "text", "p_address_line" "text", "p_address_reference" "text", "p_notes" "text", "p_items" "jsonb", "p_delivery_fee_amount" numeric DEFAULT 0, "p_source" "text" DEFAULT 'vento_pass'::"text", "p_delivery_distance_km" integer DEFAULT NULL::integer, "p_delivery_quote_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pass'
    AS $_$
declare
  v_uid uuid := auth.uid();
  v_order_id uuid;
  v_order_item_id uuid;
  v_tx_id uuid;
  v_item jsonb;
  v_option jsonb;
  v_validated_items jsonb := '[]'::jsonb;
  v_selected_options jsonb := '[]'::jsonb;
  v_product_id uuid;
  v_catalog_item_id uuid;
  v_option_id uuid;
  v_quantity numeric;
  v_original_unit_price numeric;
  v_unit_price numeric;
  v_catalog_base_price numeric;
  v_option_delta numeric;
  v_subtotal numeric := 0;
  v_delivery numeric := 0;
  v_total numeric := 0;
  v_fulfillment text := lower(trim(coalesce(p_fulfillment_type, 'delivery')));
  v_order_type text := 'takeaway';
  v_delivery_address jsonb := '{}'::jsonb;
  v_delivery_zone text := null;
  v_quote pass.delivery_quotes%rowtype;
  v_idempotency_key text := gen_random_uuid()::text;
  v_payment_status text := 'pending_payment';
  v_payment_provider text := null;
  v_checkout_expires_at timestamptz := null;
  v_option_row record;
  v_group_rule record;
  v_selected_count integer;
  v_min_select integer;
  v_max_select integer;
  v_option_count integer;
  v_distinct_option_count integer;
  v_group_preset text;
  v_linked_catalog_item_id uuid;
  v_option_metadata jsonb;
  v_consumption_rules jsonb;
  v_recipe_effects jsonb;
  v_canonical_selected_options jsonb := '[]'::jsonb;
begin
  if v_uid is null then
    raise exception 'authentication_required';
  end if;

  if p_site_id is null then
    raise exception 'site_required';
  end if;

  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'items_required';
  end if;

  if v_fulfillment not in ('delivery', 'pickup', 'on_premise') then
    raise exception 'invalid_fulfillment_type';
  end if;

  if v_fulfillment = 'on_premise' then
    v_order_type := 'dine_in';
  end if;

  if v_fulfillment = 'delivery' then
    v_payment_status := 'pending_payment';
    v_payment_provider := 'wompi';
    v_checkout_expires_at := now() + interval '20 minutes';

    if p_delivery_quote_id is null then
      raise exception 'delivery_quote_required';
    end if;

    select *
    into v_quote
    from pass.delivery_quotes
    where id = p_delivery_quote_id
      and user_id = v_uid
      and site_id = p_site_id
      and used_at is null
      and expires_at > now()
    for update;

    if v_quote.id is null then
      raise exception 'delivery_quote_invalid_or_expired';
    end if;

    v_delivery := v_quote.customer_fee_amount;
    v_delivery_zone := v_quote.billed_distance_km::text || ' km';
    v_delivery_address := jsonb_build_object(
      'line1', nullif(trim(coalesce(p_address_line, v_quote.destination_address, '')), ''),
      'reference', nullif(trim(coalesce(p_address_reference, '')), ''),
      'label', nullif(trim(coalesce(v_quote.destination_label, '')), ''),
      'latitude', v_quote.destination_latitude,
      'longitude', v_quote.destination_longitude,
      'distance_meters', v_quote.distance_meters,
      'distance_km', v_quote.distance_km,
      'billed_distance_km', v_quote.billed_distance_km,
      'duration_seconds', v_quote.duration_seconds,
      'delivery_quote_id', v_quote.id
    );

    if coalesce(v_delivery_address ->> 'line1', '') = '' then
      raise exception 'delivery_address_required';
    end if;
  else
    v_payment_status := 'not_required';
    v_payment_provider := null;
    v_checkout_expires_at := null;
    v_delivery := 0;
    v_delivery_zone := null;
    v_delivery_address := '{}'::jsonb;
  end if;

  for v_item in select * from jsonb_array_elements(p_items)
  loop
    v_product_id := nullif(v_item ->> 'product_id', '')::uuid;
    v_catalog_item_id := nullif(v_item ->> 'catalog_item_id', '')::uuid;
    v_quantity := greatest(coalesce((v_item ->> 'quantity')::numeric, 0), 0);
    v_original_unit_price := greatest(coalesce((v_item ->> 'unit_price')::numeric, 0), 0);
    v_unit_price := v_original_unit_price;
    v_catalog_base_price := null;
    v_option_delta := 0;

    if v_item ? 'selected_options' then
      if jsonb_typeof(v_item -> 'selected_options') <> 'array' then
        raise exception 'invalid_selected_options';
      end if;

      v_selected_options := coalesce(v_item -> 'selected_options', '[]'::jsonb);
    else
      v_selected_options := '[]'::jsonb;
    end if;

    v_canonical_selected_options := '[]'::jsonb;

    if v_product_id is null then
      raise exception 'item_product_required';
    end if;

    if v_quantity <= 0 then
      raise exception 'invalid_item_quantity';
    end if;

    if v_original_unit_price < 0 then
      raise exception 'invalid_item_price';
    end if;

    if v_catalog_item_id is null and jsonb_array_length(v_selected_options) > 0 then
      raise exception 'catalog_item_required_for_selected_options';
    end if;

    if v_catalog_item_id is not null then
      select item.price_amount
      into v_catalog_base_price
      from pass.catalog_items item
      where item.id = v_catalog_item_id
        and item.site_id = p_site_id
        and item.product_id = v_product_id
        and item.is_active = true;

      if not found then
        raise exception 'catalog_item_invalid';
      end if;

      select count(*), count(distinct selected.value ->> 'option_id')
      into v_option_count, v_distinct_option_count
      from jsonb_array_elements(v_selected_options) selected;

      if coalesce(v_option_count, 0) <> coalesce(v_distinct_option_count, 0) then
        raise exception 'duplicate_selected_options';
      end if;

      v_canonical_selected_options := '[]'::jsonb;

      for v_option in select * from jsonb_array_elements(v_selected_options)
      loop
        v_option_id := nullif(v_option ->> 'option_id', '')::uuid;

        if v_option_id is null then
          raise exception 'selected_option_required';
        end if;

        select
          opt_group.id as group_id,
          opt_group.code as group_code,
          opt_group.name as group_name,
          opt_group.selection_type,
          opt_group.metadata as group_metadata,
          case
            when lower(coalesce(opt_group.metadata ->> 'preset', '')) in (
              'choice',
              'extras',
              'replacements',
              'replacement',
              'removals',
              'preferences',
              'recommendations'
            )
              then case
                when lower(coalesce(opt_group.metadata ->> 'preset', '')) = 'replacement'
                  then 'replacements'
                else lower(coalesce(opt_group.metadata ->> 'preset', ''))
              end
            when lower(coalesce(opt_group.code, '')) like '%recomend%'
              or lower(coalesce(opt_group.name, '')) like '%recomend%'
              or lower(coalesce(opt_group.name, '')) like '%suger%'
              then 'recommendations'
            when lower(coalesce(opt_group.code, '')) like '%reemplaz%'
              or lower(coalesce(opt_group.code, '')) like '%cambio%'
              or lower(coalesce(opt_group.name, '')) like '%reemplaz%'
              or lower(coalesce(opt_group.name, '')) like '%cambio%'
              then 'replacements'
            when lower(coalesce(opt_group.code, '')) like '%quitar%'
              or lower(coalesce(opt_group.code, '')) like '%sin-%'
              or lower(coalesce(opt_group.name, '')) like '%quitar%'
              or lower(coalesce(opt_group.name, '')) like 'sin %'
              then 'removals'
            when lower(coalesce(opt_group.code, '')) like '%extra%'
              or lower(coalesce(opt_group.code, '')) like '%adicion%'
              or lower(coalesce(opt_group.name, '')) like '%extra%'
              or lower(coalesce(opt_group.name, '')) like '%adicion%'
              or lower(coalesce(opt_group.name, '')) like '%topping%'
              then 'extras'
            when lower(coalesce(opt_group.code, '')) like '%prefer%'
              or lower(coalesce(opt_group.name, '')) like '%prefer%'
              or lower(coalesce(opt_group.name, '')) like '%instru%'
              then 'preferences'
            else 'choice'
          end as group_preset,
          opt.id as option_id,
          opt.code as option_code,
          opt.name as option_name,
          opt.price_delta_amount,
          opt.effect_type,
          opt.metadata as option_metadata
        into v_option_row
        from pass.catalog_item_options opt
        join pass.catalog_item_option_groups opt_group
          on opt_group.id = opt.option_group_id
        where opt.id = v_option_id
          and opt.is_active = true
          and opt_group.is_active = true
          and pass.catalog_item_option_group_is_allowed(v_catalog_item_id, opt_group.id);

        if not found then
          raise exception 'selected_option_invalid';
        end if;

        v_group_preset := coalesce(v_option_row.group_preset, 'choice');
        v_option_metadata := coalesce(v_option_row.option_metadata, '{}'::jsonb);

        v_linked_catalog_item_id := case
          when coalesce(v_option_metadata ->> 'linked_catalog_item_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            then (v_option_metadata ->> 'linked_catalog_item_id')::uuid
          else null
        end;

        select coalesce(jsonb_agg(to_jsonb(rule) order by rule.sort_order, rule.name), '[]'::jsonb)
        into v_consumption_rules
        from pass.catalog_item_option_consumption_rules rule
        where rule.option_id = v_option_row.option_id
          and rule.is_active = true;

        select coalesce(jsonb_agg(to_jsonb(effect) order by effect.sort_order, effect.id), '[]'::jsonb)
        into v_recipe_effects
        from pass.catalog_item_option_recipe_effects effect
        where effect.option_id = v_option_row.option_id
          and effect.is_active = true;

        if v_group_preset = 'extras' and jsonb_array_length(v_consumption_rules) = 0 then
          raise exception 'option_consumption_rule_required';
        end if;

        if v_group_preset = 'replacements' or v_option_row.effect_type = 'replacement' then
          if jsonb_array_length(v_consumption_rules) = 0 then
            raise exception 'replacement_consumption_rule_required';
          end if;

          if not exists (
            select 1
            from jsonb_array_elements(v_recipe_effects) effect
            where effect ->> 'effect_type' = 'replacement'
          ) then
            raise exception 'replacement_recipe_effect_required';
          end if;
        end if;

        if v_group_preset = 'removals' or v_option_row.effect_type = 'removal' then
          if not exists (
            select 1
            from jsonb_array_elements(v_recipe_effects) effect
            where effect ->> 'effect_type' = 'removal'
          ) then
            raise exception 'removal_recipe_effect_required';
          end if;
        end if;

        if v_group_preset = 'recommendations' then
          if v_linked_catalog_item_id is null then
            raise exception 'linked_catalog_item_required';
          end if;

          perform 1
          from pass.catalog_items linked_item
          where linked_item.id = v_linked_catalog_item_id
            and linked_item.site_id = p_site_id
            and linked_item.is_active = true;

          if not found then
            raise exception 'linked_catalog_item_invalid';
          end if;
        end if;

        v_option_delta := v_option_delta + greatest(coalesce(v_option_row.price_delta_amount, 0), 0);

        v_canonical_selected_options := v_canonical_selected_options || jsonb_build_array(
          jsonb_build_object(
            'group_id', v_option_row.group_id,
            'group_code', v_option_row.group_code,
            'group_name', v_option_row.group_name,
            'group_preset', v_group_preset,
            'selection_type', v_option_row.selection_type,
            'option_id', v_option_row.option_id,
            'option_code', v_option_row.option_code,
            'option_name', v_option_row.option_name,
            'price_delta_amount', greatest(coalesce(v_option_row.price_delta_amount, 0), 0),
            'effect_type', v_option_row.effect_type,
            'linked_catalog_item_id', v_linked_catalog_item_id,
            'linked_catalog_item_price_amount', nullif(v_option_metadata ->> 'linked_catalog_item_price_amount', '')::numeric,
            'metadata', v_option_metadata,
            'consumption_rules', v_consumption_rules,
            'recipe_effects', v_recipe_effects,
            'client_snapshot', v_option
          )
        );
      end loop;

      for v_group_rule in
        select id, name, selection_type, is_required, min_select, max_select
        from pass.catalog_item_allowed_option_groups(v_catalog_item_id)
      loop
        v_min_select := greatest(
          case when coalesce(v_group_rule.is_required, false) then 1 else 0 end,
          coalesce(v_group_rule.min_select, 0)
        );

        v_max_select := case
          when v_group_rule.selection_type = 'single' then 1
          else greatest(1, coalesce(v_group_rule.max_select, 1), v_min_select)
        end;

        select count(distinct opt.id)
        into v_selected_count
        from jsonb_array_elements(v_selected_options) selected
        join pass.catalog_item_options opt
          on opt.id::text = selected.value ->> 'option_id'
        where opt.option_group_id = v_group_rule.id
          and opt.is_active = true;

        if coalesce(v_selected_count, 0) < v_min_select then
          raise exception 'option_group_min_select_required';
        end if;

        if coalesce(v_selected_count, 0) > v_max_select then
          raise exception 'option_group_max_select_exceeded';
        end if;
      end loop;

      v_unit_price := greatest(coalesce(v_catalog_base_price, 0), 0) + greatest(coalesce(v_option_delta, 0), 0);

      if abs(v_original_unit_price - v_unit_price) > 0.01 then
        raise exception 'invalid_item_price';
      end if;
    end if;

    v_subtotal := v_subtotal + (v_quantity * v_unit_price);

    v_validated_items := v_validated_items || jsonb_build_array(
      jsonb_build_object(
        'product_id', v_product_id,
        'catalog_item_id', v_catalog_item_id,
        'quantity', v_quantity,
        'unit_price', v_unit_price,
        'base_unit_price', coalesce(v_catalog_base_price, v_unit_price),
        'option_total_amount', greatest(coalesce(v_option_delta, 0), 0),
        'notes', nullif(trim(coalesce(v_item ->> 'notes', '')), ''),
        'line_key', nullif(trim(coalesce(v_item ->> 'line_key', '')), ''),
        'selected_options', v_canonical_selected_options
      )
    );
  end loop;

  v_total := v_subtotal + v_delivery;

  insert into public.orders (
    client_id,
    order_type,
    source,
    status,
    payment_status,
    total_amount,
    subtotal_amount,
    notes,
    site_id,
    guest_info,
    fulfillment_type,
    contact_phone,
    delivery_address,
    delivery_zone,
    delivery_fee_amount,
    payment_provider,
    checkout_expires_at
  )
  values (
    v_uid,
    v_order_type,
    coalesce(nullif(trim(coalesce(p_source, '')), ''), 'vento_pass'),
    'pending',
    v_payment_status,
    v_total,
    v_subtotal,
    nullif(trim(coalesce(p_notes, '')), ''),
    p_site_id,
    jsonb_build_object(
      'contact_name', nullif(trim(coalesce(p_contact_name, '')), ''),
      'contact_phone', nullif(trim(coalesce(p_contact_phone, '')), ''),
      'fulfillment_type', v_fulfillment,
      'satellite_name', nullif(trim(coalesce(p_satellite_name, '')), '')
    ),
    v_fulfillment,
    nullif(trim(coalesce(p_contact_phone, '')), ''),
    v_delivery_address,
    v_delivery_zone,
    v_delivery,
    v_payment_provider,
    v_checkout_expires_at
  )
  returning id into v_order_id;

  for v_item in select * from jsonb_array_elements(v_validated_items)
  loop
    v_selected_options := coalesce(v_item -> 'selected_options', '[]'::jsonb);
    v_quantity := (v_item ->> 'quantity')::numeric;
    v_unit_price := (v_item ->> 'unit_price')::numeric;
    v_catalog_item_id := nullif(v_item ->> 'catalog_item_id', '')::uuid;

    insert into public.order_items (
      order_id,
      product_id,
      quantity,
      unit_price,
      total_amount,
      notes
    )
    values (
      v_order_id,
      (v_item ->> 'product_id')::uuid,
      v_quantity,
      v_unit_price,
      (v_quantity * v_unit_price),
      nullif(trim(coalesce(v_item ->> 'notes', '')), '')
    )
    returning id into v_order_item_id;

    if v_catalog_item_id is not null and jsonb_array_length(v_selected_options) > 0 then
      for v_option in select * from jsonb_array_elements(v_selected_options)
      loop
        v_option_id := nullif(v_option ->> 'option_id', '')::uuid;

        select
          opt_group.id as group_id,
          opt_group.code as group_code,
          opt_group.name as group_name,
          opt_group.selection_type,
          opt.id as option_id,
          opt.code as option_code,
          opt.name as option_name,
          opt.price_delta_amount,
          opt.effect_type
        into v_option_row
        from pass.catalog_item_options opt
        join pass.catalog_item_option_groups opt_group
          on opt_group.id = opt.option_group_id
        where opt.id = v_option_id
          and opt.is_active = true
          and opt_group.is_active = true
          and pass.catalog_item_option_group_is_allowed(v_catalog_item_id, opt_group.id);

        if not found then
          raise exception 'selected_option_invalid';
        end if;

        insert into public.order_item_options (
          order_item_id,
          option_group_id,
          option_id,
          group_code,
          group_name,
          option_code,
          option_name,
          quantity,
          price_delta_amount,
          total_delta_amount,
          metadata
        )
        values (
          v_order_item_id,
          v_option_row.group_id,
          v_option_row.option_id,
          v_option_row.group_code,
          v_option_row.group_name,
          v_option_row.option_code,
          v_option_row.option_name,
          v_quantity,
          greatest(coalesce(v_option_row.price_delta_amount, 0), 0),
          v_quantity * greatest(coalesce(v_option_row.price_delta_amount, 0), 0),
          jsonb_build_object(
            'line_key', v_item ->> 'line_key',
            'catalog_item_id', v_catalog_item_id,
            'base_unit_price', (v_item ->> 'base_unit_price')::numeric,
            'option_total_amount', (v_item ->> 'option_total_amount')::numeric,
            'group_preset', v_option ->> 'group_preset',
            'selection_type', v_option_row.selection_type,
            'effect_type', v_option_row.effect_type,
            'linked_catalog_item_id', nullif(v_option ->> 'linked_catalog_item_id', ''),
            'linked_catalog_item_price_amount',
              nullif(v_option ->> 'linked_catalog_item_price_amount', '')::numeric,
            'option_metadata', coalesce(v_option -> 'metadata', '{}'::jsonb),
            'selection_snapshot', v_option,
            'client_snapshot', coalesce(v_option -> 'client_snapshot', v_option),
            'consumption_rules', coalesce(v_option -> 'consumption_rules', '[]'::jsonb),
            'recipe_effects', coalesce(v_option -> 'recipe_effects', '[]'::jsonb)
          )
        );
      end loop;
    end if;
  end loop;

  if v_quote.id is not null then
    update pass.delivery_quotes
    set used_at = now()
    where id = v_quote.id;
  end if;

  if v_fulfillment = 'delivery' then
    insert into payments.transactions (
      order_id,
      user_id,
      site_id,
      provider,
      idempotency_key,
      amount_minor,
      currency,
      status,
      metadata
    )
    values (
      v_order_id,
      v_uid,
      p_site_id,
      'wompi',
      v_idempotency_key,
      round(v_total * 100)::bigint,
      'COP',
      'pending',
      jsonb_build_object(
        'source', 'create_order_checkout_draft',
        'delivery_quote_id', p_delivery_quote_id,
        'delivery_distance_km', coalesce(v_quote.billed_distance_km, p_delivery_distance_km),
        'fulfillment_type', v_fulfillment
      )
    )
    returning id into v_tx_id;

    update public.orders
    set payment_intent_id = v_tx_id
    where id = v_order_id;
  end if;

  return jsonb_build_object(
    'ok', true,
    'order_id', v_order_id,
    'transaction_id', v_tx_id,
    'idempotency_key', case when v_fulfillment = 'delivery' then v_idempotency_key else null end,
    'amount_minor', round(v_total * 100)::bigint,
    'currency', 'COP',
    'payment_status', v_payment_status,
    'payment_provider', v_payment_provider,
    'checkout_expires_at', v_checkout_expires_at
  );
end;
$_$;


