CREATE OR REPLACE FUNCTION "public"."create_order_checkout_draft"("p_site_id" "uuid", "p_satellite_name" "text", "p_fulfillment_type" "text", "p_contact_name" "text", "p_contact_phone" "text", "p_address_line" "text", "p_address_reference" "text", "p_notes" "text", "p_items" "jsonb", "p_delivery_fee_amount" numeric, "p_source" "text", "p_delivery_distance_km" integer, "p_delivery_quote_id" "uuid", "p_requested_for" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pass'
    AS $$
declare
  v_result jsonb;
  v_order_id uuid;
  v_schedule jsonb;
begin
  v_schedule := pass.validate_order_requested_for(
    p_site_id,
    p_items,
    p_requested_for
  );

  v_result := public.create_order_checkout_draft(
    p_site_id,
    p_satellite_name,
    p_fulfillment_type,
    p_contact_name,
    p_contact_phone,
    p_address_line,
    p_address_reference,
    p_notes,
    p_items,
    p_delivery_fee_amount,
    p_source,
    p_delivery_distance_km,
    p_delivery_quote_id
  );

  v_order_id := nullif(v_result ->> 'order_id', '')::uuid;
  if v_order_id is null then
    raise exception 'order_creation_failed';
  end if;

  update public.orders
  set requested_for = p_requested_for
  where id = v_order_id
    and client_id = auth.uid();

  if not found then
    raise exception 'order_requested_for_update_failed';
  end if;

  return v_result || jsonb_build_object(
    'requested_for', p_requested_for,
    'required_lead_minutes', coalesce((v_schedule ->> 'required_lead_minutes')::integer, 0)
  );
end;
$$;


