CREATE OR REPLACE FUNCTION "public"."create_order_delivery_courier_link"("p_order_id" "uuid", "p_site_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'app_private', 'extensions'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_order public.orders%rowtype;
  v_session public.order_delivery_sessions%rowtype;
  v_session_id uuid;
  v_token text;
  v_pin text;
begin
  if v_uid is null then
    raise exception 'authentication_required';
  end if;

  if not public.has_permission('pulso.pos.main', p_site_id, null) then
    raise exception 'permission_denied';
  end if;

  select * into v_order
  from public.orders
  where id = p_order_id and site_id = p_site_id
  for update;

  if v_order.id is null then
    raise exception 'order_not_found';
  end if;

  if v_order.fulfillment_type <> 'delivery' then
    raise exception 'delivery_required';
  end if;

  if v_order.status in ('delivered','cancelled') then
    raise exception 'order_closed';
  end if;

  select * into v_session
  from public.order_delivery_sessions
  where order_id = p_order_id
  for update;

  if v_session.id is null then
    v_session_id := gen_random_uuid();
    v_pin := app_private.delivery_pin_for_session(v_session_id);

    insert into public.order_delivery_sessions (
      id, order_id, site_id, status, confirmation_pin_hash, expires_at, metadata
    ) values (
      v_session_id,
      v_order.id,
      v_order.site_id,
      case when v_order.dispatch_status = 'on_the_way' or v_order.status = 'on_the_way' then 'in_transit' else 'pending' end,
      encode(extensions.digest(v_pin, 'sha256'::text), 'hex'),
      now() + interval '12 hours',
      jsonb_build_object('created_by', v_uid, 'created_from', 'pulso')
    )
    returning * into v_session;
  elsif v_session.status in ('confirmed','cancelled') then
    raise exception 'delivery_session_closed';
  end if;

  v_token := encode(extensions.gen_random_bytes(32), 'hex');

  update public.order_delivery_sessions
  set access_token_hash = encode(extensions.digest(v_token, 'sha256'::text), 'hex'),
      expires_at = greatest(expires_at, now() + interval '12 hours'),
      updated_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'link_generated_by', v_uid,
        'link_generated_at', now()
      )
  where id = v_session.id
  returning * into v_session;

  return jsonb_build_object(
    'ok', true,
    'order_id', v_order.id,
    'session_id', v_session.id,
    'token', v_token,
    'url', 'https://clzdpinthhtknkmefsxx.supabase.co/functions/v1/delivery-portal?token=' || v_token,
    'expires_at', v_session.expires_at
  );
end;
$$;


ALTER FUNCTION "public"."create_order_delivery_courier_link"("p_order_id" "uuid", "p_site_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_remission_shipment_from_fulfillments"("p_origin_site_id" "uuid", "p_destination_site_id" "uuid", "p_dispatch_run_id" "uuid", "p_items" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_shipment_id uuid;
  v_item jsonb;
  v_fulfillment record;
  v_requested numeric;
  v_available numeric;
  v_qty numeric;
  v_current_user uuid := auth.uid();
begin
  if p_origin_site_id is null or p_destination_site_id is null or p_origin_site_id = p_destination_site_id then
    raise exception 'Origen y destino válidos son obligatorios.';
  end if;
  if coalesce(jsonb_typeof(p_items), '') <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'Selecciona al menos una cantidad lista para cargar.';
  end if;
  if not (
    public.has_permission('nexo.inventory.remissions.all_sites')
    or public.has_permission('nexo.inventory.remissions.transit', p_origin_site_id)
    or public.has_permission('nexo.inventory.remissions.prepare', p_origin_site_id)
  ) then
    raise exception 'No tienes permiso para armar una salida desde esta sede.';
  end if;
  if p_dispatch_run_id is not null and not exists (
    select 1 from public.remission_dispatch_runs r
    where r.id = p_dispatch_run_id and r.origin_site_id = p_origin_site_id and r.status in ('draft', 'loading')
  ) then
    raise exception 'La salida logística no está disponible para este origen.';
  end if;

  insert into public.remission_shipments (
    dispatch_run_id, origin_site_id, destination_site_id, shipment_code, status, created_by, updated_by
  ) values (
    p_dispatch_run_id, p_origin_site_id, p_destination_site_id,
    'ENV-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8)),
    'loading', v_current_user, v_current_user
  ) returning id into v_shipment_id;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    v_qty := round(coalesce((v_item ->> 'base_qty')::numeric, 0), 6);
    if v_qty <= 0 then
      raise exception 'La cantidad a cargar debe ser mayor que cero.';
    end if;

    select
      f.id, f.request_item_id, f.product_id, f.source_location_id, f.destination_location_id,
      f.ready_base_qty, f.allocated_base_qty, f.status,
      i.stock_unit_code, i.request_policy_id, i.request_policy_label
    into v_fulfillment
    from public.restock_item_fulfillments f
    join public.restock_request_items i on i.id = f.request_item_id
    where f.id = (v_item ->> 'fulfillment_id')::uuid
      and f.from_site_id = p_origin_site_id
      and f.to_site_id = p_destination_site_id
      and f.status in ('partially_ready', 'ready', 'allocated')
    for update of f;

    if not found then
      raise exception 'Una tarea seleccionada ya no está lista para cargar.';
    end if;

    v_available := round(v_fulfillment.ready_base_qty - v_fulfillment.allocated_base_qty, 6);
    if v_qty > v_available then
      raise exception 'La cantidad solicitada (%) supera lo disponible para cargar (%) en una tarea.', v_qty, v_available;
    end if;

    insert into public.remission_shipment_items (
      shipment_id, request_item_id, fulfillment_id, product_id, source_location_id,
      destination_location_id, base_qty, stock_unit_code, request_policy_id,
      request_policy_label, created_by
    ) values (
      v_shipment_id, v_fulfillment.request_item_id, v_fulfillment.id, v_fulfillment.product_id,
      v_fulfillment.source_location_id, v_fulfillment.destination_location_id, v_qty,
      v_fulfillment.stock_unit_code, v_fulfillment.request_policy_id,
      v_fulfillment.request_policy_label, v_current_user
    );

    update public.restock_item_fulfillments
    set allocated_base_qty = allocated_base_qty + v_qty,
        status = case when ready_base_qty - (allocated_base_qty + v_qty) > 0 then 'partially_ready' else 'allocated' end,
        updated_by = v_current_user,
        updated_at = now()
    where id = v_fulfillment.id;
  end loop;

  return v_shipment_id;
end;
$$;


ALTER FUNCTION "public"."create_remission_shipment_from_fulfillments"("p_origin_site_id" "uuid", "p_destination_site_id" "uuid", "p_dispatch_run_id" "uuid", "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_scheduled_order_checkout_draft"("p_site_id" "uuid", "p_satellite_name" "text", "p_fulfillment_type" "text", "p_contact_name" "text", "p_contact_phone" "text", "p_address_line" "text", "p_address_reference" "text", "p_notes" "text", "p_items" "jsonb", "p_delivery_fee_amount" numeric, "p_source" "text", "p_delivery_distance_km" integer, "p_delivery_quote_id" "uuid", "p_invoice_requested" boolean, "p_billing_data" "jsonb", "p_schedule_mode" "text", "p_delivery_window_start" timestamp with time zone, "p_delivery_window_end" timestamp with time zone, "p_timezone" "text" DEFAULT 'America/Bogota'::"text", "p_gift_data" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pass', 'auth'
    AS $$
declare
  v_result jsonb;
  v_order_id uuid;
  v_schedule jsonb;
  v_mode text := lower(trim(coalesce(p_schedule_mode, 'immediate')));
  v_schedule_items jsonb := '[]'::jsonb;
  v_is_gift boolean := coalesce((p_gift_data ->> 'is_gift')::boolean, false);
  v_recipient_name text;
  v_recipient_phone text;
  v_recipient_relationship text;
  v_is_surprise boolean;
  v_contact_policy text;
  v_fallback_contact_policy text;
  v_card_requested boolean;
  v_card_message text;
  v_card_to text;
  v_card_from text;
  v_hide_prices boolean;
  v_gift_snapshot jsonb;
  v_saved_recipient_id uuid;
  v_requested_saved_recipient_id uuid;
  v_save_recipient boolean := false;
begin
  if auth.uid() is null then
    raise exception 'authentication_required';
  end if;

  v_schedule := pass.validate_order_schedule(
    p_site_id,
    p_items,
    p_fulfillment_type,
    v_mode,
    p_delivery_window_start,
    p_delivery_window_end,
    p_timezone
  );

  if v_is_gift then
    v_recipient_name := nullif(trim(p_gift_data ->> 'recipient_name'), '');
    v_recipient_phone := nullif(trim(p_gift_data ->> 'recipient_phone'), '');
    v_recipient_relationship := nullif(trim(p_gift_data ->> 'recipient_relationship'), '');
    v_is_surprise := coalesce((p_gift_data ->> 'is_surprise')::boolean, false);
    v_contact_policy := coalesce(nullif(trim(p_gift_data ->> 'contact_policy'), ''), 'buyer_first');
    v_fallback_contact_policy := coalesce(nullif(trim(p_gift_data ->> 'fallback_contact_policy'), ''), 'recipient_allowed');
    v_card_requested := coalesce((p_gift_data ->> 'card_requested')::boolean, false);
    v_card_message := nullif(trim(p_gift_data ->> 'card_message'), '');
    v_card_to := nullif(trim(p_gift_data ->> 'card_to'), '');
    v_card_from := nullif(trim(p_gift_data ->> 'card_from'), '');
    v_hide_prices := coalesce((p_gift_data ->> 'hide_prices')::boolean, true);
    v_save_recipient := coalesce((p_gift_data ->> 'save_recipient')::boolean, false);
    v_requested_saved_recipient_id := nullif(p_gift_data ->> 'saved_recipient_id', '')::uuid;

    if v_recipient_name is null then raise exception 'gift_recipient_name_required'; end if;
    if v_recipient_phone is null then raise exception 'gift_recipient_phone_required'; end if;
    if v_contact_policy not in ('buyer_first', 'recipient_allowed') then raise exception 'invalid_gift_contact_policy'; end if;
    if v_fallback_contact_policy not in ('recipient_allowed', 'buyer_only') then raise exception 'invalid_gift_fallback_contact_policy'; end if;
    if v_card_requested and v_card_message is null then raise exception 'gift_card_message_required'; end if;
    if char_length(coalesce(v_card_message, '')) > 300
      or char_length(coalesce(v_card_to, '')) > 80
      or char_length(coalesce(v_card_from, '')) > 80 then
      raise exception 'gift_card_text_too_long';
    end if;

    if v_requested_saved_recipient_id is not null then
      select gr.id
      into v_saved_recipient_id
      from public.gift_recipients gr
      where gr.id = v_requested_saved_recipient_id
        and gr.owner_id = auth.uid();

      if v_saved_recipient_id is null then
        raise exception 'saved_gift_recipient_not_found';
      end if;

      update public.gift_recipients
      set name = v_recipient_name,
          phone = v_recipient_phone,
          relationship = v_recipient_relationship,
          last_used_at = now(),
          updated_at = now()
      where id = v_saved_recipient_id;
    elsif v_save_recipient then
      v_saved_recipient_id := public.save_or_touch_gift_recipient(
        v_recipient_name,
        v_recipient_phone,
        v_recipient_relationship
      );
    end if;
  end if;

  v_result := public.create_order_checkout_draft(
    p_site_id,
    p_satellite_name,
    p_fulfillment_type,
    p_contact_name,
    p_contact_phone,
    p_address_line,
    p_address_reference,
    p_notes,
    p_items,
    p_delivery_fee_amount,
    p_source,
    p_delivery_distance_km,
    p_delivery_quote_id,
    p_invoice_requested,
    p_billing_data
  );

  v_order_id := nullif(v_result ->> 'order_id', '')::uuid;
  if v_order_id is null then raise exception 'order_creation_failed'; end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'catalog_item_id', nullif(item ->> 'catalog_item_id', ''),
    'product_id', nullif(item ->> 'product_id', ''),
    'quantity', coalesce((item ->> 'quantity')::numeric, 0)
  )), '[]'::jsonb)
  into v_schedule_items
  from jsonb_array_elements(p_items) item;

  if v_is_gift then
    v_gift_snapshot := jsonb_strip_nulls(jsonb_build_object(
      'is_gift', true,
      'saved_recipient_id', v_saved_recipient_id,
      'buyer_name', trim(p_contact_name),
      'buyer_phone', trim(p_contact_phone),
      'recipient_name', v_recipient_name,
      'recipient_phone', v_recipient_phone,
      'recipient_relationship', v_recipient_relationship,
      'is_surprise', v_is_surprise,
      'contact_policy', v_contact_policy,
      'fallback_contact_policy', v_fallback_contact_policy,
      'card_requested', v_card_requested,
      'card_message', case when v_card_requested then v_card_message else null end,
      'card_to', case when v_card_requested then v_card_to else null end,
      'card_from', case when v_card_requested then v_card_from else null end,
      'card_status', case when v_card_requested then 'pending' else 'not_requested' end,
      'hide_prices', v_hide_prices
    ));

    insert into public.order_gift_details (
      order_id, purchaser_id, saved_recipient_id,
      buyer_name, buyer_phone,
      recipient_name, recipient_phone, recipient_relationship,
      is_surprise, contact_policy, fallback_contact_policy,
      card_requested, card_message, card_to, card_from, card_status, hide_prices
    ) values (
      v_order_id, auth.uid(), v_saved_recipient_id,
      trim(p_contact_name), trim(p_contact_phone),
      v_recipient_name, v_recipient_phone, v_recipient_relationship,
      v_is_surprise, v_contact_policy, v_fallback_contact_policy,
      v_card_requested,
      case when v_card_requested then v_card_message else null end,
      case when v_card_requested then v_card_to else null end,
      case when v_card_requested then v_card_from else null end,
      case when v_card_requested then 'pending' else 'not_requested' end,
      v_hide_prices
    );
  end if;

  update public.orders
  set schedule_mode = v_mode,
      requested_for = case when v_mode = 'scheduled' then p_delivery_window_start else null end,
      delivery_window_start = case when v_mode = 'scheduled' then p_delivery_window_start else null end,
      delivery_window_end = case when v_mode = 'scheduled' then p_delivery_window_end else null end,
      timezone = coalesce(nullif(trim(p_timezone), ''), 'America/Bogota'),
      is_gift = v_is_gift,
      guest_info = coalesce(guest_info, '{}'::jsonb)
        || jsonb_build_object('schedule_items', v_schedule_items)
        || case when v_is_gift then jsonb_build_object('gift', v_gift_snapshot) else '{}'::jsonb end
  where id = v_order_id
    and client_id = auth.uid();

  if not found then raise exception 'order_schedule_update_failed'; end if;

  return v_result || jsonb_build_object(
    'schedule_mode', v_mode,
    'requested_for', case when v_mode = 'scheduled' then p_delivery_window_start else null end,
    'delivery_window_start', case when v_mode = 'scheduled' then p_delivery_window_start else null end,
    'delivery_window_end', case when v_mode = 'scheduled' then p_delivery_window_end else null end,
    'timezone', coalesce(nullif(trim(p_timezone), ''), 'America/Bogota'),
    'required_lead_minutes', coalesce((v_schedule ->> 'required_lead_minutes')::integer, 0),
    'is_gift', v_is_gift,
    'saved_recipient_id', v_saved_recipient_id
  );
end;
$$;


ALTER FUNCTION "public"."create_scheduled_order_checkout_draft"("p_site_id" "uuid", "p_satellite_name" "text", "p_fulfillment_type" "text", "p_contact_name" "text", "p_contact_phone" "text", "p_address_line" "text", "p_address_reference" "text", "p_notes" "text", "p_items" "jsonb", "p_delivery_fee_amount" numeric, "p_source" "text", "p_delivery_distance_km" integer, "p_delivery_quote_id" "uuid", "p_invoice_requested" boolean, "p_billing_data" "jsonb", "p_schedule_mode" "text", "p_delivery_window_start" timestamp with time zone, "p_delivery_window_end" timestamp with time zone, "p_timezone" "text", "p_gift_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."current_actor_shift_for_shared_device_v1"("p_actor_employee_id" "uuid", "p_site_id" "uuid" DEFAULT NULL::"uuid", "p_area_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("actor_shift_id" "uuid", "active_site_id" "uuid", "active_area_id" "uuid", "active_role" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
  with last_attendance as (
    select
      al.employee_id,
      al.action,
      al.site_id,
      al.shift_id,
      al.device_info
    from public.attendance_logs al
    where al.employee_id = p_actor_employee_id
      and al.action in ('check_in', 'check_out')
    order by al.occurred_at desc, al.created_at desc
    limit 1
  ),
  actor as (
    select e.id, e.role, e.site_id, e.area_id
    from public.employees e
    where e.id = p_actor_employee_id
      and e.is_active is true
  )
  select
    la.shift_id as actor_shift_id,
    coalesce(
      nullif(la.device_info #>> '{operationalContext,siteId}', '')::uuid,
      la.site_id,
      a.site_id
    ) as active_site_id,
    coalesce(
      nullif(la.device_info #>> '{operationalContext,areaId}', '')::uuid,
      a.area_id
    ) as active_area_id,
    coalesce(
      nullif(la.device_info #>> '{operationalContext,operationalRole}', ''),
      a.role
    ) as active_role
  from last_attendance la
  join actor a on a.id = la.employee_id
  where la.action = 'check_in'
    and (p_site_id is null or coalesce(nullif(la.device_info #>> '{operationalContext,siteId}', '')::uuid, la.site_id, a.site_id) = p_site_id)
    and (p_area_id is null or coalesce(nullif(la.device_info #>> '{operationalContext,areaId}', '')::uuid, a.area_id) = p_area_id)
  limit 1;
$$;


ALTER FUNCTION "public"."current_actor_shift_for_shared_device_v1"("p_actor_employee_id" "uuid", "p_site_id" "uuid", "p_area_id" "uuid") OWNER TO "postgres";


