COMMENT ON FUNCTION "public"."current_shared_device_can_access_app"("app_code_input" "text") IS 'Indica si el auth.uid() actual es un dispositivo compartido activo con acceso a una app.';



CREATE OR REPLACE FUNCTION "public"."current_shared_device_can_access_nexo_remission_catalog"("p_product_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
  with device as (
    select
      d.id,
      d.site_id,
      d.area_id,
      d.navigation_role
    from public.shared_operational_devices d
    where d.auth_user_id = auth.uid()
      and d.is_active
      and d.activation_status = 'active'
      and d.site_id is not null
      and nullif(trim(coalesce(d.navigation_role, '')), '') is not null
    limit 1
  )
  select exists (
    select 1
    from device d
    join public.shared_operational_device_apps da
      on da.device_id = d.id
     and da.app_code = 'nexo'
     and da.is_active
    join public.product_site_settings pss
      on pss.site_id = d.site_id
     and pss.product_id = p_product_id
     and pss.is_active
     and coalesce(pss.remission_enabled, true)
    join public.products p
      on p.id = pss.product_id
     and coalesce(p.is_active, true)
    where public.has_operational_role_permission(
      d.navigation_role,
      'nexo.inventory.remissions.request',
      d.site_id,
      d.area_id,
      'nexo'
    )
    or public.has_operational_role_permission(
      d.navigation_role,
      'nexo.inventory.remissions.prepare',
      d.site_id,
      d.area_id,
      'nexo'
    )
    or public.has_operational_role_permission(
      d.navigation_role,
      'nexo.inventory.remissions.receive',
      d.site_id,
      d.area_id,
      'nexo'
    )
  );
$$;


ALTER FUNCTION "public"."current_shared_device_can_access_nexo_remission_catalog"("p_product_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."current_shared_device_can_access_nexo_remission_catalog"("p_product_id" "uuid") IS 'Permite a dispositivos compartidos leer solo productos/perfiles habilitados para remisiones en su sede operativa NEXO.';



CREATE OR REPLACE FUNCTION "public"."current_shared_operational_device_v1"() RETURNS TABLE("id" "uuid", "code" "text", "label" "text", "description" "text", "device_type" "text", "site_id" "uuid", "area_id" "uuid", "navigation_role" "text", "default_app_code" "text", "requires_actor_pin" boolean, "requires_active_actor_shift" boolean, "allow_actor_without_pin" boolean, "allow_actions_without_actor" boolean, "allowed_app_codes" "text"[], "metadata" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
  select
    d.id,
    d.code,
    d.label,
    d.description,
    d.device_type,
    d.site_id,
    d.area_id,
    d.navigation_role,
    d.default_app_code,
    d.requires_actor_pin,
    d.requires_active_actor_shift,
    d.allow_actor_without_pin,
    d.allow_actions_without_actor,
    coalesce(
      array_agg(da.app_code order by da.app_code) filter (where da.is_active),
      '{}'::text[]
    ) as allowed_app_codes,
    d.metadata
  from public.shared_operational_devices d
  left join public.shared_operational_device_apps da on da.device_id = d.id
  where d.auth_user_id = auth.uid()
    and d.is_active
    and d.activation_status = 'active'
  group by d.id;
$$;


ALTER FUNCTION "public"."current_shared_operational_device_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."current_shared_operational_device_v1"() IS 'Retorna el dispositivo compartido autenticado con apps permitidas y navigation_role interpretado como operational_role para shells y navegacion.';



CREATE OR REPLACE FUNCTION "public"."deactivate_master_request_policy_batch"("p_policy_ids" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_policy_id uuid;
  v_product_id uuid;
  v_is_default boolean;
  v_replacement_id uuid;
  v_batch_id uuid;
  v_count integer := 0;
begin
  if not (public.is_owner() or public.is_global_manager()) then
    raise exception 'No tienes permiso para aplicar configuración masiva.';
  end if;
  if jsonb_typeof(p_policy_ids) <> 'array' or jsonb_array_length(p_policy_ids) = 0 then
    raise exception 'No hay políticas para desactivar.';
  end if;

  for v_policy_id in select value::text::uuid from jsonb_array_elements(p_policy_ids) loop
    select product_id, is_default into v_product_id, v_is_default
    from public.product_request_policies
    where id = v_policy_id and is_active = true;
    if not found then raise exception 'La política ya no está activa o no existe.'; end if;

    select id into v_replacement_id
    from public.product_request_policies
    where product_id = v_product_id and is_active = true and id <> v_policy_id
    order by is_default desc, created_at asc
    limit 1;
    if v_replacement_id is null then
      raise exception 'No puedes desactivar la única política activa de un producto.';
    end if;
  end loop;

  for v_policy_id in select value::text::uuid from jsonb_array_elements(p_policy_ids) loop
    select product_id, is_default into v_product_id, v_is_default
    from public.product_request_policies where id = v_policy_id;
    if v_is_default then
      select id into v_replacement_id
      from public.product_request_policies
      where product_id = v_product_id and is_active = true and id <> v_policy_id
      order by is_default desc, created_at asc limit 1;
      update public.product_request_policies set is_default = false, updated_at = now() where id = v_policy_id;
      update public.product_request_policies set is_default = true, updated_at = now() where id = v_replacement_id;
    end if;
    update public.product_request_policies
    set is_active = false, is_default = false,
      change_reason = 'Desactivada desde el configurador maestro de productos.', updated_at = now()
    where id = v_policy_id;
    v_count := v_count + 1;
  end loop;

  insert into public.product_configuration_batches(zone, summary, product_count, created_by)
  values ('request_policies', jsonb_build_object('deactivated_policy_ids', p_policy_ids), v_count, auth.uid())
  returning id into v_batch_id;
  return v_batch_id;
end;
$$;


ALTER FUNCTION "public"."deactivate_master_request_policy_batch"("p_policy_ids" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."device_info_has_blocking_warnings"("di" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'auth', 'storage', 'extensions'
    AS $$
  select exists (
    select 1
    from jsonb_array_elements_text(
      case
        when di is null then '[]'::jsonb
        when jsonb_typeof(di->'validationWarnings') = 'array' then di->'validationWarnings'
        else '[]'::jsonb
      end
    ) as w(txt)
    where lower(w.txt) like any (
      array[
        '%mock%',
        '%simulada%',
        '%spoof%',
        '%punto nulo%',
        '%patron sospechoso%',
        '%digitos repetidos%'
      ]
    )
  );
$$;


ALTER FUNCTION "public"."device_info_has_blocking_warnings"("di" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."employee_wallet_eligibility"("p_employee_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("employee_id" "uuid", "contract_active" boolean, "contract_document_id" "uuid", "contract_start_date" "date", "contract_end_date" "date", "documents_complete" boolean, "missing_required_document_type_ids" "uuid"[], "wallet_eligible" boolean, "wallet_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_today date := current_date;
  v_emp_id uuid;
  v_contract_doc_id uuid;
  v_contract_start date;
  v_contract_end date;
  v_contract_ok boolean := false;
  v_required_ids uuid[];
  v_missing_ids uuid[] := array[]::uuid[];
  v_docs_ok boolean := true;
  v_emp_active boolean;
  v_card_status text;
  v_rule record;
  v_has_doc boolean;
begin
  for v_emp_id in
    select e.id
    from public.employees e
    where p_employee_id is null or e.id = p_employee_id
  loop
    v_contract_doc_id := null;
    v_contract_start := null;
    v_contract_end := null;
    v_contract_ok := false;
    v_missing_ids := array[]::uuid[];
    v_docs_ok := true;

    select d.id, (d.issue_date)::date, (d.expiry_date)::date
    into v_contract_doc_id, v_contract_start, v_contract_end
    from public.documents d
    join public.document_types dt on dt.id = d.document_type_id and dt.system_key = 'employment_contract'
    where d.target_employee_id = v_emp_id
      and d.scope = 'employee'
      and d.status <> 'rejected'
      and d.issue_date is not null
      and ((d.expiry_date)::date is null or (d.expiry_date)::date >= v_today)
      and (d.issue_date)::date <= v_today
    order by (d.expiry_date)::date desc nulls first
    limit 1;

    v_contract_ok := v_contract_doc_id is not null;

    select array_agg(r.document_type_id order by r.display_order, r.document_type_id)
    into v_required_ids
    from public.required_document_rules r
    where r.active = true
      and r.is_required = true
      and (r.site_id is null or r.site_id = (
        select coalesce(es.site_id, e.site_id)
        from public.employees e
        left join public.employee_sites es on es.employee_id = e.id and es.is_primary = true
        where e.id = v_emp_id
        limit 1
      ))
      and (r.role is null or r.role = (select e.role from public.employees e where e.id = v_emp_id limit 1));

    if v_required_ids is not null then
      for v_rule in
        select unnest(v_required_ids) as doc_type_id
      loop
        select exists (
          select 1
          from public.documents d
          where d.target_employee_id = v_emp_id
            and d.document_type_id = v_rule.doc_type_id
            and d.scope = 'employee'
            and d.status <> 'rejected'
        ) into v_has_doc;
        if not v_has_doc then
          v_missing_ids := array_append(v_missing_ids, v_rule.doc_type_id);
          v_docs_ok := false;
        end if;
      end loop;
    end if;

    if v_required_ids is null or array_length(v_required_ids, 1) is null then
      v_docs_ok := true;
    end if;

    select e.is_active from public.employees e where e.id = v_emp_id limit 1 into v_emp_active;

    select coalesce(c.status::text, 'eligible')
    into v_card_status
    from public.employee_wallet_cards c
    where c.employee_id = v_emp_id
    limit 1;

    employee_id := v_emp_id;
    contract_active := v_contract_ok;
    contract_document_id := v_contract_doc_id;
    contract_start_date := v_contract_start;
    contract_end_date := v_contract_end;
    documents_complete := v_docs_ok;
    missing_required_document_type_ids := v_missing_ids;
    wallet_eligible := coalesce(v_emp_active, false) and v_contract_ok and v_docs_ok;
    wallet_status := v_card_status;
    return next;
  end loop;
end;
$$;


ALTER FUNCTION "public"."employee_wallet_eligibility"("p_employee_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."employee_wallet_eligibility"("p_employee_id" "uuid") IS 'Elegibilidad para carnet laboral: contrato activo, documentos requeridos y estado del carnet.';



CREATE OR REPLACE FUNCTION "public"."employee_wallet_mark_issued"("p_employee_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_eligible boolean;
begin
  if auth.uid() is null or auth.uid() <> p_employee_id then
    return;
  end if;
  select e.wallet_eligible into v_eligible
  from public.employee_wallet_eligibility(p_employee_id) e
  limit 1;
  if not coalesce(v_eligible, false) then
    return;
  end if;
  insert into public.employee_wallet_cards (employee_id, status, serial_number, last_issued_at, updated_at)
  values (p_employee_id, 'issued', 'emp-' || p_employee_id::text, now(), now())
  on conflict (employee_id) do update set
    status = 'issued',
    serial_number = 'emp-' || p_employee_id::text,
    last_issued_at = now(),
    last_revoked_at = null,
    revocation_reason = null,
    updated_at = now();
end;
$$;


ALTER FUNCTION "public"."employee_wallet_mark_issued"("p_employee_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."employee_wallet_mark_issued"("p_employee_id" "uuid") IS 'Marca el carnet laboral del empleado como emitido (solo el propio usuario, solo si elegible).';



CREATE OR REPLACE FUNCTION "public"."employee_wallet_sync_eligibility"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row record;
  v_elig record;
  v_revoked_count int := 0;
  v_checked_count int := 0;
  v_reason text;
  v_revoked_ids uuid[] := array[]::uuid[];
begin
  for v_row in
    select c.id, c.employee_id
    from public.employee_wallet_cards c
    where c.status = 'issued'
  loop
    v_checked_count := v_checked_count + 1;

    select *
    into v_elig
    from public.employee_wallet_eligibility(v_row.employee_id)
    limit 1;

    if v_elig.wallet_eligible then
      null;
    else
      if not v_elig.contract_active then
        v_reason := 'contract_expired';
      elsif not v_elig.documents_complete then
        v_reason := 'documents_incomplete';
      else
        v_reason := 'no_longer_eligible';
      end if;

      update public.employee_wallet_cards
      set
        status = 'revoked',
        last_revoked_at = now(),
        revocation_reason = v_reason,
        updated_at = now()
      where id = v_row.id;

      v_revoked_count := v_revoked_count + 1;
      v_revoked_ids := array_append(v_revoked_ids, v_row.employee_id);
    end if;
  end loop;

  return jsonb_build_object(
    'checked_count', v_checked_count,
    'revoked_count', v_revoked_count,
    'revoked_employee_ids', to_jsonb(v_revoked_ids)
  );
end;
$$;


ALTER FUNCTION "public"."employee_wallet_sync_eligibility"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."employee_wallet_sync_eligibility"() IS 'Reevalúa elegibilidad de carnets emitidos y revoca los que ya no cumplan (contrato/documentos). Invocable por cron o Edge Function.';



CREATE TABLE IF NOT EXISTS "public"."attendance_breaks" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "employee_id" "uuid" NOT NULL,
    "site_id" "uuid" NOT NULL,
    "started_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "ended_at" timestamp with time zone,
    "start_source" "text" DEFAULT 'mobile'::"text" NOT NULL,
    "end_source" "text",
    "start_notes" "text",
    "end_notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "attendance_breaks_end_source_check" CHECK ((("end_source" IS NULL) OR ("end_source" = ANY (ARRAY['mobile'::"text", 'web'::"text", 'kiosk'::"text", 'system'::"text"])))),
    CONSTRAINT "attendance_breaks_start_source_check" CHECK (("start_source" = ANY (ARRAY['mobile'::"text", 'web'::"text", 'kiosk'::"text", 'system'::"text"]))),
    CONSTRAINT "attendance_breaks_time_check" CHECK ((("ended_at" IS NULL) OR ("ended_at" >= "started_at")))
);


ALTER TABLE "public"."attendance_breaks" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."end_attendance_break"("p_source" "text" DEFAULT 'mobile'::"text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "public"."attendance_breaks"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_employee_id uuid;
  v_open_break public.attendance_breaks%rowtype;
  v_result public.attendance_breaks%rowtype;
begin
  v_employee_id := auth.uid();
  if v_employee_id is null then
    raise exception 'No autenticado';
  end if;

  select *
    into v_open_break
  from public.attendance_breaks
  where employee_id = v_employee_id
    and ended_at is null
  order by started_at desc
  limit 1
  for update;

  if not found then
    raise exception 'No hay descanso activo para finalizar';
  end if;

  update public.attendance_breaks
  set
    ended_at = now(),
    end_source = coalesce(p_source, 'mobile'),
    end_notes = p_notes
  where id = v_open_break.id
  returning *
    into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."end_attendance_break"("p_source" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_attendance_geofence"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_site record;
  v_emp record;
  v_geofence_site_id uuid;

  v_requires_geo boolean;
  v_max_acc integer;
  v_radius integer;
  v_policy_check_in_max_acc integer;
  v_policy_check_out_max_acc integer;
  v_policy_default_radius integer;
  v_site_policy_radius integer;
  v_site_policy_requires_geo boolean;

  v_distance double precision;
  v_accuracy double precision;
begin
  if coalesce(new.source, 'mobile') <> 'system' then
    new.occurred_at := now();
  end if;

  v_geofence_site_id := coalesce(new.geofence_site_id, new.site_id);
  new.geofence_site_id := v_geofence_site_id;

  if coalesce(new.source, 'mobile') = 'system' then
    new.geofence_distance_meters := null;
    return new;
  end if;

  select
    geofence_check_in_max_accuracy_meters,
    geofence_check_out_max_accuracy_meters,
    default_radius_meters
    into v_policy_check_in_max_acc,
      v_policy_check_out_max_acc,
      v_policy_default_radius
  from public.attendance_policy
  order by created_at asc
  limit 1;

  if not found then
    v_policy_check_in_max_acc := 25;
    v_policy_check_out_max_acc := 25;
    v_policy_default_radius := null;
  end if;

  select id, site_id, is_active
    into v_emp
  from public.employees
  where id = new.employee_id;

  if not found then
    raise exception 'Empleado no encontrado';
  end if;

  if v_emp.is_active is false then
    raise exception 'Empleado inactivo';
  end if;

  if new.action = 'check_in'
    and v_emp.site_id is distinct from new.site_id
    and not exists (
      select 1
      from public.employee_sites es
      where es.employee_id = new.employee_id
        and es.site_id = new.site_id
        and es.is_active is true
    )
  then
    raise exception 'No autorizado: check-in solo permitido en una sede asignada';
  end if;

  select id, name, type, is_active, latitude, longitude, checkin_radius_meters
    into v_site
  from public.sites
  where id = v_geofence_site_id;

  if not found then
    raise exception 'Punto de marcacion no encontrado';
  end if;

  if v_site.is_active is false then
    raise exception 'Punto de marcacion inactivo';
  end if;

  select checkin_radius_meters, requires_geofence
    into v_site_policy_radius, v_site_policy_requires_geo
  from public.site_attendance_policy
  where site_id = v_geofence_site_id;

  v_requires_geo := coalesce(
    v_site_policy_requires_geo,
    v_site.latitude is not null and v_site.longitude is not null
  );

  if v_requires_geo then
    if v_site.latitude is null or v_site.longitude is null then
      raise exception 'Configuracion invalida: el punto % no tiene coordenadas', v_site.name;
    end if;

    if new.latitude is null or new.longitude is null or new.accuracy_meters is null then
      raise exception 'Ubicacion requerida para registrar asistencia';
    end if;

    if public.device_info_has_blocking_warnings(new.device_info) then
      raise exception 'Ubicacion no valida: senales de ubicacion simulada detectadas';
    end if;

    if new.action = 'check_in' then
      v_max_acc := coalesce(v_policy_check_in_max_acc, 25);
    elsif new.action = 'check_out' then
      v_max_acc := coalesce(v_policy_check_out_max_acc, 25);
    else
      raise exception 'Accion invalida: %', new.action;
    end if;

    v_radius := coalesce(
      v_site_policy_radius,
      v_site.checkin_radius_meters,
      v_policy_default_radius,
      50
    );
    v_accuracy := new.accuracy_meters::double precision;

    if v_accuracy > v_max_acc then
      raise exception 'Precision GPS insuficiente: %m (maximo %m)', round(v_accuracy), v_max_acc;
    end if;

    v_distance := public.haversine_m(new.latitude, new.longitude, v_site.latitude, v_site.longitude);
    new.geofence_distance_meters := round(v_distance::numeric, 2);

    if v_distance > v_radius then
      raise exception 'Fuera de rango: %m > radio %m (precision %m)',
        round(v_distance), v_radius, round(v_accuracy);
    end if;
  else
    new.geofence_distance_meters := null;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_attendance_geofence"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_attendance_sequence"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'storage', 'extensions'
    AS $$
declare
  v_last_action text;
  v_last_site_id uuid;
  v_last_occurred_at timestamptz;
begin
  -- Serializa operaciones por empleado (evita doble insert concurrente)
  perform pg_advisory_xact_lock(hashtext(new.employee_id::text)::bigint);

  -- Validar acción (por si entra algo raro)
  if new.action not in ('check_in','check_out') then
    raise exception 'Acción inválida: %', new.action;
  end if;

  -- Tomar el último evento del empleado (global, no solo "hoy")
  select action, site_id, occurred_at
    into v_last_action, v_last_site_id, v_last_occurred_at
  from public.attendance_logs
  where employee_id = new.employee_id
  order by occurred_at desc, created_at desc
  limit 1;

  if v_last_action is null then
    -- Primer evento debe ser check_in
    if new.action <> 'check_in' then
      raise exception 'Secuencia inválida: el primer registro debe ser check_in';
    end if;

    return new;
  end if;

  -- (Opcional pero recomendado) evitar inserts "hacia atrás" en el tiempo
  if new.occurred_at < v_last_occurred_at then
    raise exception 'Secuencia inválida: occurred_at no puede ser menor al último registro';
  end if;

  -- No permitir dos acciones iguales seguidas
  if new.action = v_last_action then
    raise exception 'Secuencia inválida: no puedes registrar % dos veces seguidas', new.action;
  end if;

  -- Si es check_out, debe cerrar el mismo sitio del check_in anterior
  if new.action = 'check_out' and v_last_action = 'check_in' then
    if new.site_id <> v_last_site_id then
      raise exception 'Secuencia inválida: el check_out debe ser en la misma sede del check_in anterior';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_attendance_sequence"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_employee_inventory_location_assignment_site"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'storage', 'extensions'
    AS $$
declare
  v_employee_site uuid;
  v_location_site uuid;
begin
  select site_id into v_employee_site
  from public.employees
  where id = new.employee_id;

  select site_id into v_location_site
  from public.inventory_locations
  where id = new.location_id;

  if v_location_site is null then
    raise exception 'LOC invalido para asignacion de trabajador.';
  end if;

  if v_employee_site is distinct from new.site_id then
    if not exists (
      select 1
      from public.employee_sites es
      where es.employee_id = new.employee_id
        and es.site_id = new.site_id
        and es.is_active = true
    ) then
      raise exception 'El trabajador no pertenece a la sede seleccionada.';
    end if;
  end if;

  if v_location_site <> new.site_id then
    raise exception 'El LOC no pertenece a la sede seleccionada.';
  end if;

  new.updated_at = now();
  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_employee_inventory_location_assignment_site"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_employee_role_site"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'storage', 'extensions'
    AS $$
declare
  st public.site_type;
begin
  select s.site_type into st
  from public.sites s
  where s.id = new.site_id;

  if st is null then
    raise exception 'site_id invalido o sede sin site_type';
  end if;

  if not exists (
    select 1
    from public.role_site_type_rules r
    where r.role = new.role
      and r.site_type = st
      and r.is_allowed = true
  ) then
    raise exception 'Rol "%" no permitido para site_type="%"', new.role, st;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_employee_role_site"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_inventory_location_area_site"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_area_site_id uuid;
begin
  select a.site_id
    into v_area_site_id
  from public.areas a
  where a.id = new.area_id;

  if v_area_site_id is null then
    raise exception 'area not found for LOC';
  end if;

  if v_area_site_id <> new.site_id then
    raise exception 'LOC area must belong to the same site';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_inventory_location_area_site"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_inventory_location_parent_same_site"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'storage', 'extensions'
    AS $$
begin
  if new.parent_location_id is null then
    return new;
  end if;

  -- no puede ser su propio padre
  if new.parent_location_id = new.id then
    raise exception 'inventory_locations: parent_location_id cannot equal id';
  end if;

  -- el padre debe pertenecer al mismo site_id
  if not exists (
    select 1
    from public.inventory_locations p
    where p.id = new.parent_location_id
      and p.site_id = new.site_id
  ) then
    raise exception 'inventory_locations: parent_location_id must belong to the same site_id';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_inventory_location_parent_same_site"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_inventory_location_position_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_location_site_id uuid;
  v_parent_location_id uuid;
begin
  select loc.site_id
    into v_location_site_id
  from public.inventory_locations loc
  where loc.id = new.location_id;

  if v_location_site_id is null then
    raise exception 'LOC not found for internal position';
  end if;

  new.site_id := v_location_site_id;

  if new.parent_position_id is not null then
    select parent.location_id
      into v_parent_location_id
    from public.inventory_location_positions parent
    where parent.id = new.parent_position_id;

    if v_parent_location_id is null then
      raise exception 'parent position not found';
    end if;

    if v_parent_location_id <> new.location_id then
      raise exception 'parent position must belong to the same LOC';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_inventory_location_position_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_order_conversation"("p_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_order public.orders%rowtype;
  v_conversation public.order_conversations%rowtype;
begin
  if v_uid is null then
    raise exception 'authentication_required';
  end if;

  select *
  into v_order
  from public.orders
  where id = p_order_id
    and client_id = v_uid;

  if v_order.id is null then
    raise exception 'order_not_found';
  end if;

  insert into public.order_conversations (order_id, site_id, client_id, status)
  values (v_order.id, v_order.site_id, v_uid, 'open')
  on conflict (order_id) do update
    set updated_at = now()
  returning * into v_conversation;

  return jsonb_build_object(
    'ok', true,
    'conversation_id', v_conversation.id,
    'order_id', v_conversation.order_id,
    'site_id', v_conversation.site_id,
    'client_id', v_conversation.client_id,
    'status', v_conversation.status
  );
end;
$$;


ALTER FUNCTION "public"."ensure_order_conversation"("p_order_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ensure_order_conversation"("p_order_id" "uuid") IS 'Crea o devuelve la conversación de un pedido propio del cliente.';



CREATE OR REPLACE FUNCTION "public"."estimate_internal_price_unit"("p_product_id" "uuid", "p_seller_cost_center_id" "uuid" DEFAULT NULL::"uuid", "p_uom_profile_id" "uuid" DEFAULT NULL::"uuid", "p_margin_pct" numeric DEFAULT 0) RETURNS TABLE("base_unit_cost" numeric, "base_cost_source" "text", "suggested_unit_price" numeric, "pricing_factor_to_stock" numeric, "stock_unit_cost" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_seller_site_id uuid;
  v_factor numeric := 1;
  v_stock_unit_cost numeric := 0;
  v_source text := 'none';
  v_margin numeric := greatest(coalesce(p_margin_pct, 0), 0);
begin
  select cc.site_id
    into v_seller_site_id
  from public.cost_centers cc
  where cc.id = p_seller_cost_center_id;

  if p_uom_profile_id is not null then
    select
      case
        when coalesce(p.qty_in_input_unit, 0) > 0
          then p.qty_in_stock_unit / p.qty_in_input_unit
        else 1
      end
      into v_factor
    from public.product_uom_profiles p
    where p.id = p_uom_profile_id
      and p.product_id = p_product_id;
  end if;

  v_factor := greatest(coalesce(v_factor, 1), 0);

  if v_seller_site_id is not null then
    select nullif(iss.avg_unit_cost, 0)
      into v_stock_unit_cost
    from public.inventory_stock_by_site iss
    where iss.site_id = v_seller_site_id
      and iss.product_id = p_product_id;

    if coalesce(v_stock_unit_cost, 0) > 0 then
      v_source := 'stock_avg_cost';
    end if;
  end if;

  if coalesce(v_stock_unit_cost, 0) <= 0 then
    select nullif(pce.cost_after, 0)
      into v_stock_unit_cost
    from public.product_cost_events pce
    where pce.product_id = p_product_id
      and (v_seller_site_id is null or pce.site_id = v_seller_site_id or pce.site_id is null)
    order by
      case when pce.source = 'production' then 0 else 1 end,
      pce.created_at desc
    limit 1;

    if coalesce(v_stock_unit_cost, 0) > 0 then
      v_source := 'production_or_cost_event';
    end if;
  end if;

  if coalesce(v_stock_unit_cost, 0) <= 0 then
    select nullif(avg(c.avg_stock_unit_cost), 0)
      into v_stock_unit_cost
    from public.procurement_supplier_product_costs c
    where c.product_id = p_product_id
      and c.is_active = true
      and c.avg_stock_unit_cost > 0;

    if coalesce(v_stock_unit_cost, 0) > 0 then
      v_source := 'procurement_avg_cost';
    end if;
  end if;

  if coalesce(v_stock_unit_cost, 0) <= 0 then
    select nullif(p.cost, 0)
      into v_stock_unit_cost
    from public.products p
    where p.id = p_product_id;

    if coalesce(v_stock_unit_cost, 0) > 0 then
      v_source := 'product_cost';
    end if;
  end if;

  v_stock_unit_cost := greatest(coalesce(v_stock_unit_cost, 0), 0);

  return query select
    round(v_stock_unit_cost * v_factor, 6) as base_unit_cost,
    v_source as base_cost_source,
    round((v_stock_unit_cost * v_factor) * (1 + (v_margin / 100.0)), 2) as suggested_unit_price,
    v_factor as pricing_factor_to_stock,
    v_stock_unit_cost as stock_unit_cost;
end;
$$;


ALTER FUNCTION "public"."estimate_internal_price_unit"("p_product_id" "uuid", "p_seller_cost_center_id" "uuid", "p_uom_profile_id" "uuid", "p_margin_pct" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."estimate_internal_price_unit"("p_product_id" "uuid", "p_seller_cost_center_id" "uuid", "p_uom_profile_id" "uuid", "p_margin_pct" numeric) IS 'Estimates an internal price per selected pricing unit/presentation using stock/production/procurement/product cost plus a margin percentage.';



CREATE OR REPLACE FUNCTION "public"."fogo_create_production_batch_from_recipe"("p_recipe_card_id" "uuid", "p_produced_qty" numeric, "p_destination_location_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_employee_id uuid := auth.uid();
  v_recipe record;
  v_destination record;
  v_configured_production_location_id uuid;
  v_scale numeric;
  v_total_cost numeric := 0;
  v_unit_cost numeric := null;
  v_batch_id uuid;
  v_batch_code text;
  v_ingredient record;
  v_location record;
  v_remaining numeric;
  v_required_qty numeric;
  v_take numeric;
  v_stock_unit_code text;
  v_movement_id uuid;
begin
  if v_employee_id is null then
    raise exception 'not authenticated';
  end if;

  if p_recipe_card_id is null then
    raise exception 'recipe_card_id is required';
  end if;

  if coalesce(p_produced_qty, 0) <= 0 then
    raise exception 'produced_qty must be greater than zero';
  end if;

  if p_destination_location_id is null then
    raise exception 'destination_location_id is required';
  end if;

  select
    rc.id,
    rc.product_id,
    rc.site_id,
    rc.area_id,
    rc.yield_qty,
    rc.yield_unit,
    rc.status,
    p.name as product_name,
    p.unit as product_unit,
    p.stock_unit_code as product_stock_unit_code
  into v_recipe
  from public.recipe_cards rc
  join public.products p on p.id = rc.product_id
  where rc.id = p_recipe_card_id
    and coalesce(rc.is_active, true) = true;

  if not found then
    raise exception 'recipe not found';
  end if;

  if v_recipe.status <> 'published' then
    raise exception 'recipe must be published';
  end if;

  if v_recipe.site_id is null then
    raise exception 'recipe must have a site';
  end if;

  if v_recipe.area_id is null then
    raise exception 'recipe must have an area';
  end if;

  if coalesce(v_recipe.yield_qty, 0) <= 0 then
    raise exception 'recipe yield must be greater than zero';
  end if;

  if not public.has_permission('fogo.production.batches.create', v_recipe.site_id, v_recipe.area_id) then
    raise exception 'permission denied';
  end if;

  if not public.can_access_recipe_scope(v_recipe.site_id, v_recipe.area_id) then
    raise exception 'recipe scope denied';
  end if;

  select id, site_id, code
  into v_destination
  from public.inventory_locations
  where id = p_destination_location_id
    and coalesce(is_active, true) = true;

  if not found then
    raise exception 'destination LOC not found';
  end if;

  if v_destination.site_id <> v_recipe.site_id then
    raise exception 'destination LOC must belong to recipe site';
  end if;

  select production_location_id
    into v_configured_production_location_id
  from public.product_site_settings
  where product_id = v_recipe.product_id
    and site_id = v_recipe.site_id
    and coalesce(is_active, true) = true
    and production_location_id is not null
  order by updated_at desc nulls last, created_at desc nulls last
  limit 1;

  if v_configured_production_location_id is not null
     and v_configured_production_location_id <> p_destination_location_id then
    raise exception 'destination LOC must match configured production LOC for this product';
  end if;

  v_scale := p_produced_qty / v_recipe.yield_qty;

  insert into public.production_batches (
    site_id,
    product_id,
    recipe_card_id,
    produced_qty,
    produced_unit,
    status,
    notes,
    created_by,
    destination_location_id,
    recipe_consumed
  )
  values (
    v_recipe.site_id,
    v_recipe.product_id,
    v_recipe.id,
    p_produced_qty,
    coalesce(nullif(v_recipe.yield_unit, ''), nullif(v_recipe.product_stock_unit_code, ''), nullif(v_recipe.product_unit, ''), 'un'),
    'posted',
    nullif(trim(coalesce(p_notes, '')), ''),
    v_employee_id,
    p_destination_location_id,
    true
  )
  returning id, batch_code into v_batch_id, v_batch_code;

  for v_ingredient in
    select
      r.ingredient_product_id,
      r.quantity,
      p.name,
      p.unit,
      p.stock_unit_code,
      coalesce(p.cost, 0) as cost
    from public.recipes r
    join public.products p on p.id = r.ingredient_product_id
    where r.product_id = v_recipe.product_id
      and coalesce(r.is_active, true) = true
    order by r.created_at asc, r.id asc
  loop
    v_required_qty := coalesce(v_ingredient.quantity, 0) * v_scale;
    if v_required_qty <= 0 then
      continue;
    end if;

    v_remaining := v_required_qty;
    v_stock_unit_code := coalesce(
      nullif(v_ingredient.stock_unit_code, ''),
      nullif(v_ingredient.unit, ''),
      'un'
    );
    v_total_cost := v_total_cost + (v_required_qty * coalesce(v_ingredient.cost, 0));

    perform pg_advisory_xact_lock(hashtextextended(v_recipe.site_id::text || ':' || v_ingredient.ingredient_product_id::text, 0));

    for v_location in
      select
        loc.id as location_id,
        loc.code as location_code,
        coalesce(stock.current_qty, 0) as current_qty
      from public.inventory_locations loc
      join public.inventory_stock_by_location stock
        on stock.location_id = loc.id
       and stock.product_id = v_ingredient.ingredient_product_id
       and stock.current_qty > 0
      left join public.site_production_pick_order pick
        on pick.site_id = v_recipe.site_id
       and pick.location_id = loc.id
       and coalesce(pick.is_active, true) = true
      where loc.site_id = v_recipe.site_id
        and coalesce(loc.is_active, true) = true
        and (
          v_configured_production_location_id is null
          or loc.id = v_configured_production_location_id
        )
      order by
        case when pick.location_id is null then 1 else 0 end,
        coalesce(pick.priority, 100000) asc,
        stock.current_qty desc,
        loc.code asc
      for update of stock
    loop
      exit when v_remaining <= 0;
      v_take := least(v_remaining, v_location.current_qty);
      if v_take <= 0 then
        continue;
      end if;

      update public.inventory_stock_by_location
      set current_qty = current_qty - v_take,
          updated_at = now()
      where location_id = v_location.location_id
        and product_id = v_ingredient.ingredient_product_id
        and current_qty >= v_take;

      if not found then
        raise exception 'stock changed while consuming ingredient %', v_ingredient.name;
      end if;

      insert into public.inventory_movements (
        site_id,
        product_id,
        movement_type,
        quantity,
        input_qty,
        input_unit_code,
        conversion_factor_to_stock,
        stock_unit_code,
        unit_cost,
        note,
        related_production_batch_id,
        created_by
      )
      values (
        v_recipe.site_id,
        v_ingredient.ingredient_product_id,
        'production_consume',
        -v_take,
        v_take,
        v_stock_unit_code,
        1,
        v_stock_unit_code,
        coalesce(v_ingredient.cost, 0),
        format('Consumo lote %s desde %s', coalesce(v_batch_code, v_batch_id::text), coalesce(v_location.location_code, v_location.location_id::text)),
        v_batch_id,
        v_employee_id
      )
      returning id into v_movement_id;

      insert into public.production_batch_consumptions (
        batch_id,
        ingredient_product_id,
        location_id,
        required_qty,
        consumed_qty,
        stock_unit_code,
        movement_id,
        created_by
      )
      values (
        v_batch_id,
        v_ingredient.ingredient_product_id,
        v_location.location_id,
        v_take,
        v_take,
        v_stock_unit_code,
        v_movement_id,
        v_employee_id
      );

      v_remaining := v_remaining - v_take;
    end loop;

    if v_remaining > 0.000001 then
      raise exception 'insufficient stock for ingredient %: required %, missing %',
        v_ingredient.name,
        v_required_qty,
        v_remaining;
    end if;
  end loop;

  v_unit_cost := case when p_produced_qty > 0 then v_total_cost / p_produced_qty else null end;

  update public.production_batches
  set total_cost = v_total_cost,
      unit_cost = v_unit_cost
  where id = v_batch_id;

  insert into public.inventory_stock_by_location (location_id, product_id, current_qty, updated_at)
  values (p_destination_location_id, v_recipe.product_id, p_produced_qty, now())
  on conflict (location_id, product_id) do update
    set current_qty = public.inventory_stock_by_location.current_qty + excluded.current_qty,
        updated_at = now();

  insert into public.inventory_movements (
    site_id,
    product_id,
    movement_type,
    quantity,
    input_qty,
    input_unit_code,
    conversion_factor_to_stock,
    stock_unit_code,
    unit_cost,
    note,
    related_production_batch_id,
    created_by
  )
  values (
    v_recipe.site_id,
    v_recipe.product_id,
    'production_output',
    p_produced_qty,
    p_produced_qty,
    coalesce(nullif(v_recipe.product_stock_unit_code, ''), nullif(v_recipe.product_unit, ''), coalesce(nullif(v_recipe.yield_unit, ''), 'un')),
    1,
    coalesce(nullif(v_recipe.product_stock_unit_code, ''), nullif(v_recipe.product_unit, ''), coalesce(nullif(v_recipe.yield_unit, ''), 'un')),
    v_unit_cost,
    format('Ingreso lote %s a %s', coalesce(v_batch_code, v_batch_id::text), coalesce(v_destination.code, p_destination_location_id::text)),
    v_batch_id,
    v_employee_id
  );

  return jsonb_build_object(
    'batchId', v_batch_id,
    'batchCode', v_batch_code,
    'recipeCardId', v_recipe.id,
    'productId', v_recipe.product_id,
    'siteId', v_recipe.site_id,
    'areaId', v_recipe.area_id,
    'producedQty', p_produced_qty,
    'producedUnit', coalesce(nullif(v_recipe.yield_unit, ''), nullif(v_recipe.product_stock_unit_code, ''), nullif(v_recipe.product_unit, ''), 'un'),
    'destinationLocationId', p_destination_location_id,
    'totalCost', v_total_cost,
    'unitCost', v_unit_cost
  );
end;
$$;


ALTER FUNCTION "public"."fogo_create_production_batch_from_recipe"("p_recipe_card_id" "uuid", "p_produced_qty" numeric, "p_destination_location_id" "uuid", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fogo_create_real_production_batch"("p_recipe_card_id" "uuid", "p_produced_qty" numeric, "p_destination_location_id" "uuid", "p_ingredients" "jsonb" DEFAULT '[]'::"jsonb", "p_packages" "jsonb" DEFAULT '[]'::"jsonb", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_employee_id uuid := auth.uid();
  v_recipe record;

  v_route record;
  v_route_id uuid := null;
  v_route_found boolean := false;
  v_configured_production_location_id uuid := null;

  v_input_location_id uuid := null;
  v_input_location record;

  v_output_mode text := 'inventory_stock';
  v_output_location_id uuid := null;
  v_output_position_id uuid := null;
  v_destination record;
  v_output_position record;

  v_scale numeric;
  v_expected_qty numeric;
  v_produced_unit text;
  v_total_cost numeric := 0;
  v_unit_cost numeric := null;
  v_batch_id uuid;
  v_batch_code text;
  v_ingredient record;
  v_location record;
  v_remaining numeric;
  v_required_qty numeric;
  v_consumed_qty numeric;
  v_take numeric;
  v_stock_unit_code text;
  v_movement_id uuid;
  v_custom_ingredients boolean := false;
  v_invalid_ingredients integer := 0;
  v_packages_count integer := 0;
  v_package record;
  v_package_index integer := 0;
  v_package_total numeric := 0;
  v_package_unit text;
  v_expected_package_qty numeric;
  v_package_label text;
  v_package_profile_id uuid;
  v_packaging_status text;
begin
  if v_employee_id is null then
    raise exception 'not authenticated';
  end if;

  if p_recipe_card_id is null then
    raise exception 'recipe_card_id is required';
  end if;

  if coalesce(p_produced_qty, 0) <= 0 then
    raise exception 'produced_qty must be greater than zero';
  end if;

  if p_ingredients is null or jsonb_typeof(p_ingredients) <> 'array' then
    raise exception 'ingredients must be a json array';
  end if;

  if p_packages is null or jsonb_typeof(p_packages) <> 'array' then
    raise exception 'packages must be a json array';
  end if;

  select
    rc.id,
    rc.product_id,
    rc.site_id,
    rc.area_id,
    a.kind as area_kind,
    rc.yield_qty,
    rc.yield_unit,
    rc.portion_size,
    rc.portion_unit,
    rc.status,
    p.name as product_name,
    p.unit as product_unit,
    p.stock_unit_code as product_stock_unit_code
  into v_recipe
  from public.recipe_cards rc
  join public.products p on p.id = rc.product_id
  left join public.areas a on a.id = rc.area_id
  where rc.id = p_recipe_card_id
    and coalesce(rc.is_active, true) = true;

  if not found then
    raise exception 'recipe not found';
  end if;

  if v_recipe.status <> 'published' then
    raise exception 'recipe must be published';
  end if;

  if v_recipe.site_id is null then
    raise exception 'recipe must have a site';
  end if;

  if v_recipe.area_id is null then
    raise exception 'recipe must have an area';
  end if;

  if nullif(trim(coalesce(v_recipe.area_kind, '')), '') is null then
    raise exception 'recipe area must have an area kind';
  end if;

  if coalesce(v_recipe.yield_qty, 0) <= 0 then
    raise exception 'recipe yield must be greater than zero';
  end if;

  if not public.has_permission('fogo.production.batches.create', v_recipe.site_id, v_recipe.area_id) then
    raise exception 'permission denied';
  end if;

  if not public.can_access_recipe_scope(v_recipe.site_id, v_recipe.area_id) then
    raise exception 'recipe scope denied';
  end if;

  select r.*
    into v_route
  from public.product_site_production_routes r
  where r.product_id = v_recipe.product_id
    and r.site_id = v_recipe.site_id
    and r.area_kind = v_recipe.area_kind
    and coalesce(r.is_active, true) = true
    and (
      r.external_recipe_id is null
      or nullif(trim(r.external_recipe_id), '') is null
      or r.external_recipe_id = v_recipe.id::text
    )
  order by
    case when r.external_recipe_id = v_recipe.id::text then 0 else 1 end,
    case when coalesce(r.is_default, false) then 0 else 1 end,
    r.updated_at desc nulls last,
    r.created_at desc nulls last
  limit 1;

  if found then
    v_route_found := true;
    v_route_id := v_route.id;
    v_input_location_id := v_route.input_location_id;
    v_output_mode := coalesce(nullif(trim(v_route.output_mode), ''), 'inventory_stock');
    v_output_location_id := v_route.output_location_id;
    v_output_position_id := v_route.output_position_id;
  else
    select production_location_id
      into v_configured_production_location_id
    from public.product_site_settings
    where product_id = v_recipe.product_id
      and site_id = v_recipe.site_id
      and coalesce(is_active, true) = true
      and production_location_id is not null
    order by updated_at desc nulls last, created_at desc nulls last
    limit 1;

    v_input_location_id := coalesce(v_configured_production_location_id, p_destination_location_id);
    v_output_mode := 'inventory_stock';
    v_output_location_id := p_destination_location_id;
    v_output_position_id := null;
  end if;

  if v_output_mode not in ('inventory_stock', 'sellable_stock', 'order_fulfillment') then
    raise exception 'invalid production output mode: %', v_output_mode;
  end if;

  if v_output_mode = 'order_fulfillment' then
    v_output_location_id := null;
    v_output_position_id := null;
  elsif v_output_location_id is null then
    raise exception 'destination_location_id is required for output mode %', v_output_mode;
  end if;

  if v_input_location_id is null then
    raise exception 'input production LOC is required';
  end if;

  select id, site_id, code
    into v_input_location
  from public.inventory_locations
  where id = v_input_location_id
    and coalesce(is_active, true) = true;

  if not found then
    raise exception 'input production LOC not found';
  end if;

  if v_input_location.site_id <> v_recipe.site_id then
    raise exception 'input production LOC must belong to recipe site';
  end if;

  if v_output_location_id is not null then
    select id, site_id, code
      into v_destination
    from public.inventory_locations
    where id = v_output_location_id
      and coalesce(is_active, true) = true;

    if not found then
      raise exception 'destination LOC not found';
    end if;

    if v_destination.site_id <> v_recipe.site_id then
      raise exception 'destination LOC must belong to recipe site';
    end if;
  end if;

  if v_output_position_id is not null then
    select id, site_id, location_id, code, name
      into v_output_position
    from public.inventory_location_positions
    where id = v_output_position_id
      and coalesce(is_active, true) = true;

    if not found then
      raise exception 'destination position not found';
    end if;

    if v_output_position.site_id <> v_recipe.site_id then
      raise exception 'destination position must belong to recipe site';
    end if;

    if v_output_position.location_id <> v_output_location_id then
      raise exception 'destination position must belong to destination LOC';
    end if;
  end if;

  if v_output_mode = 'order_fulfillment' and jsonb_array_length(p_packages) > 0 then
    raise exception 'order_fulfillment routes cannot create stock packages';
  end if;

  v_scale := p_produced_qty / v_recipe.yield_qty;
  v_expected_qty := v_recipe.yield_qty;
  v_produced_unit := coalesce(
    nullif(v_recipe.yield_unit, ''),
    nullif(v_recipe.product_stock_unit_code, ''),
    nullif(v_recipe.product_unit, ''),
    'un'
  );

  v_custom_ingredients := jsonb_array_length(p_ingredients) > 0;

  if v_custom_ingredients then
    with provided as (
      select distinct x.ingredient_product_id
      from jsonb_to_recordset(p_ingredients) as x(
        ingredient_product_id uuid,
        required_qty numeric,
        actual_qty numeric,
        location_id uuid
      )
    )
    select count(*)
      into v_invalid_ingredients
    from provided pi
    where not exists (
      select 1
      from public.recipes r
      where r.product_id = v_recipe.product_id
        and r.ingredient_product_id = pi.ingredient_product_id
        and coalesce(r.is_active, true) = true
    );

    if v_invalid_ingredients > 0 then
      raise exception 'provided ingredients do not match active recipe';
    end if;
  end if;

  v_packages_count := jsonb_array_length(p_packages);

  if v_packages_count > 0 then
    for v_package in
      select *
      from jsonb_to_recordset(p_packages) as x(
        package_index integer,
        label text,
        expected_qty numeric,
        actual_qty numeric,
        unit_code text,
        uom_profile_id uuid,
        notes text
      )
    loop
      v_package_unit := coalesce(nullif(trim(v_package.unit_code), ''), v_produced_unit);

      if coalesce(v_package.actual_qty, 0) <= 0 then
        raise exception 'package actual_qty must be greater than zero';
      end if;

      if v_package.uom_profile_id is not null and not exists (
        select 1
        from public.product_uom_profiles pup
        where pup.id = v_package.uom_profile_id
          and pup.product_id = v_recipe.product_id
          and coalesce(pup.is_active, true) = true
      ) then
        raise exception 'package uom profile does not belong to the produced product';
      end if;

      if not exists (select 1 from public.inventory_units u where u.code = v_package_unit) then
        raise exception 'package unit % does not exist', v_package_unit;
      end if;

      v_package_total := v_package_total + coalesce(v_package.actual_qty, 0);
    end loop;

    if abs(v_package_total - p_produced_qty) > 0.001 then
      raise exception 'package total (%) must match produced_qty (%)', v_package_total, p_produced_qty;
    end if;
  end if;

  insert into public.production_batches (
    site_id,
    product_id,
    recipe_card_id,
    production_route_id,
    output_mode,
    produced_qty,
    produced_unit,
    expected_qty,
    expected_unit,
    packaged_qty,
    packaged_unit,
    package_count,
    packaging_status,
    status,
    notes,
    created_by,
    destination_location_id,
    destination_position_id,
    recipe_consumed
  ) values (
    v_recipe.site_id,
    v_recipe.product_id,
    v_recipe.id,
    v_route_id,
    v_output_mode,
    p_produced_qty,
    v_produced_unit,
    v_expected_qty,
    v_produced_unit,
    case when v_packages_count > 0 then v_package_total else null end,
    case when v_packages_count > 0 then v_produced_unit else null end,
    v_packages_count,
    case when v_packages_count > 0 then 'packaged' else 'not_packaged' end,
    'posted',
    nullif(trim(coalesce(p_notes, '')), ''),
    v_employee_id,
    v_output_location_id,
    v_output_position_id,
    true
  ) returning id, batch_code into v_batch_id, v_batch_code;

  for v_ingredient in
    with provided as (
      select *
      from jsonb_to_recordset(p_ingredients) as x(
        ingredient_product_id uuid,
        required_qty numeric,
        actual_qty numeric,
        location_id uuid
      )
    )
    select
      r.ingredient_product_id,
      p.name,
      p.unit,
      p.stock_unit_code,
      coalesce(p.cost, 0) as cost,
      coalesce(pi.required_qty, r.quantity * v_scale) as required_qty,
      coalesce(pi.actual_qty, r.quantity * v_scale) as consumed_qty,
      pi.location_id as requested_location_id
    from public.recipes r
    join public.products p on p.id = r.ingredient_product_id
    left join provided pi on pi.ingredient_product_id = r.ingredient_product_id
    where r.product_id = v_recipe.product_id
      and coalesce(r.is_active, true) = true
      and (not v_custom_ingredients or pi.ingredient_product_id is not null)
    order by r.created_at asc, r.id asc
  loop
    v_required_qty := coalesce(v_ingredient.required_qty, 0);
    v_consumed_qty := coalesce(v_ingredient.consumed_qty, 0);

    if v_required_qty < 0 or v_consumed_qty < 0 then
      raise exception 'ingredient quantities cannot be negative';
    end if;

    if v_consumed_qty <= 0 then
      continue;
    end if;

    v_remaining := v_consumed_qty;
    v_stock_unit_code := coalesce(
      nullif(v_ingredient.stock_unit_code, ''),
      nullif(v_ingredient.unit, ''),
      'un'
    );
    v_total_cost := v_total_cost + (v_consumed_qty * coalesce(v_ingredient.cost, 0));

    perform pg_advisory_xact_lock(hashtextextended(v_recipe.site_id::text || ':' || v_ingredient.ingredient_product_id::text, 0));

    for v_location in
      select
        loc.id as location_id,
        loc.code as location_code,
        coalesce(stock.current_qty, 0) as current_qty
      from public.inventory_locations loc
      join public.inventory_stock_by_location stock
        on stock.location_id = loc.id
       and stock.product_id = v_ingredient.ingredient_product_id
       and stock.current_qty > 0
      left join public.site_production_pick_order pick
        on pick.site_id = v_recipe.site_id
       and pick.location_id = loc.id
       and coalesce(pick.is_active, true) = true
      where loc.site_id = v_recipe.site_id
        and coalesce(loc.is_active, true) = true
        and (
          (v_route_found and loc.id = v_input_location_id)
          or (
            not v_route_found
            and v_ingredient.requested_location_id is not null
            and loc.id = v_ingredient.requested_location_id
          )
          or (
            not v_route_found
            and v_ingredient.requested_location_id is null
            and v_input_location_id is not null
            and loc.id = v_input_location_id
          )
          or (
            not v_route_found
            and v_ingredient.requested_location_id is null
            and v_input_location_id is null
          )
        )
      order by
        case
          when v_route_found then 0
          when v_ingredient.requested_location_id is not null then 0
          when pick.location_id is null then 1
          else 0
        end,
        coalesce(pick.priority, 100000) asc,
        stock.current_qty desc,
        loc.code asc
      for update of stock
    loop
      exit when v_remaining <= 0;
      v_take := least(v_remaining, v_location.current_qty);
      if v_take <= 0 then
        continue;
      end if;

      update public.inventory_stock_by_location
      set current_qty = current_qty - v_take,
          updated_at = now()
      where location_id = v_location.location_id
        and product_id = v_ingredient.ingredient_product_id
        and current_qty >= v_take;

      if not found then
        raise exception 'stock changed while consuming ingredient %', v_ingredient.name;
      end if;

      insert into public.inventory_stock_by_site (
        site_id,
        product_id,
        current_qty,
        updated_at
      ) values (
        v_recipe.site_id,
        v_ingredient.ingredient_product_id,
        -v_take,
        now()
      )
      on conflict (site_id, product_id) do update
        set current_qty = greatest(0, public.inventory_stock_by_site.current_qty + excluded.current_qty),
            updated_at = now();

      insert into public.inventory_movements (
        site_id,
        product_id,
        movement_type,
        quantity,
        input_qty,
        input_unit_code,
        conversion_factor_to_stock,
        stock_unit_code,
        unit_cost,
        note,
        related_production_batch_id,
        created_by
      ) values (
        v_recipe.site_id,
        v_ingredient.ingredient_product_id,
        'production_consume',
        -v_take,
        v_take,
        v_stock_unit_code,
        1,
        v_stock_unit_code,
        coalesce(v_ingredient.cost, 0),
        format('Consumo real lote %s desde %s', coalesce(v_batch_code, v_batch_id::text), coalesce(v_location.location_code, v_location.location_id::text)),
        v_batch_id,
        v_employee_id
      ) returning id into v_movement_id;

      insert into public.production_batch_consumptions (
        batch_id,
        ingredient_product_id,
        location_id,
        required_qty,
        consumed_qty,
        stock_unit_code,
        movement_id,
        created_by
      ) values (
        v_batch_id,
        v_ingredient.ingredient_product_id,
        v_location.location_id,
        case when v_consumed_qty > 0 then (v_required_qty * (v_take / v_consumed_qty)) else 0 end,
        v_take,
        v_stock_unit_code,
        v_movement_id,
        v_employee_id
      );

      v_remaining := v_remaining - v_take;
    end loop;

    if v_remaining > 0.000001 then
      raise exception 'insufficient stock for ingredient %: required %, missing %',
        v_ingredient.name,
        v_consumed_qty,
        v_remaining;
    end if;
  end loop;

  v_unit_cost := case when p_produced_qty > 0 then v_total_cost / p_produced_qty else null end;

  update public.production_batches
  set total_cost = v_total_cost,
      unit_cost = v_unit_cost
  where id = v_batch_id;

  if v_output_mode in ('inventory_stock', 'sellable_stock') then
    insert into public.inventory_stock_by_location (location_id, product_id, current_qty, updated_at)
    values (v_output_location_id, v_recipe.product_id, p_produced_qty, now())
    on conflict (location_id, product_id) do update
      set current_qty = public.inventory_stock_by_location.current_qty + excluded.current_qty,
          updated_at = now();

    if v_output_position_id is not null then
      insert into public.inventory_stock_by_position (position_id, product_id, current_qty, updated_at)
      values (v_output_position_id, v_recipe.product_id, p_produced_qty, now())
      on conflict (position_id, product_id) do update
        set current_qty = public.inventory_stock_by_position.current_qty + excluded.current_qty,
            updated_at = now();
    end if;

    insert into public.inventory_stock_by_site (
      site_id,
      product_id,
      current_qty,
      avg_unit_cost,
      updated_at
    ) values (
      v_recipe.site_id,
      v_recipe.product_id,
      p_produced_qty,
      v_unit_cost,
      now()
    )
    on conflict (site_id, product_id) do update
      set current_qty = public.inventory_stock_by_site.current_qty + excluded.current_qty,
          avg_unit_cost = coalesce(excluded.avg_unit_cost, public.inventory_stock_by_site.avg_unit_cost),
          updated_at = now();

    insert into public.inventory_movements (
      site_id,
      product_id,
      movement_type,
      quantity,
      input_qty,
      input_unit_code,
      conversion_factor_to_stock,
      stock_unit_code,
      unit_cost,
      note,
      related_production_batch_id,
      location_position_id,
      created_by
    ) values (
      v_recipe.site_id,
      v_recipe.product_id,
      'production_output',
      p_produced_qty,
      p_produced_qty,
      coalesce(nullif(v_recipe.product_stock_unit_code, ''), nullif(v_recipe.product_unit, ''), v_produced_unit),
      1,
      coalesce(nullif(v_recipe.product_stock_unit_code, ''), nullif(v_recipe.product_unit, ''), v_produced_unit),
      v_unit_cost,
      format('Ingreso real lote %s a %s', coalesce(v_batch_code, v_batch_id::text), coalesce(v_destination.code, v_output_location_id::text)),
      v_batch_id,
      v_output_position_id,
      v_employee_id
    );
  end if;

  if v_packages_count > 0 and v_output_mode in ('inventory_stock', 'sellable_stock') then
    v_package_index := 0;
    for v_package in
      select *
      from jsonb_to_recordset(p_packages) as x(
        package_index integer,
        label text,
        expected_qty numeric,
        actual_qty numeric,
        unit_code text,
        uom_profile_id uuid,
        notes text
      )
    loop
      v_package_index := coalesce(v_package.package_index, v_package_index + 1);
      v_package_unit := coalesce(nullif(trim(v_package.unit_code), ''), v_produced_unit);
      v_expected_package_qty := coalesce(
        v_package.expected_qty,
        nullif(v_recipe.portion_size, 0),
        v_package.actual_qty
      );
      v_package_label := coalesce(
        nullif(trim(v_package.label), ''),
        format('Empaque %s', v_package_index)
      );
      v_package_profile_id := v_package.uom_profile_id;

      insert into public.production_batch_packages (
        batch_id,
        site_id,
        location_id,
        location_position_id,
        product_id,
        uom_profile_id,
        package_index,
        package_label,
        expected_qty,
        actual_qty,
        original_qty,
        remaining_qty,
        reserved_qty,
        unit_code,
        status,
        notes,
        created_by
      ) values (
        v_batch_id,
        v_recipe.site_id,
        v_output_location_id,
        v_output_position_id,
        v_recipe.product_id,
        v_package_profile_id,
        v_package_index,
        v_package_label,
        v_expected_package_qty,
        v_package.actual_qty,
        v_package.actual_qty,
        v_package.actual_qty,
        0,
        v_package_unit,
        'available',
        nullif(trim(coalesce(v_package.notes, '')), ''),
        v_employee_id
      );
    end loop;
  end if;

  v_packaging_status := case
    when v_packages_count <= 0 then 'not_packaged'
    when abs(v_package_total - p_produced_qty) <= 0.001 then 'packaged'
    else 'variance'
  end;

  update public.production_batches
  set packaged_qty = case when v_packages_count > 0 then v_package_total else packaged_qty end,
      packaged_unit = case when v_packages_count > 0 then v_produced_unit else packaged_unit end,
      package_count = v_packages_count,
      packaging_status = v_packaging_status
  where id = v_batch_id;

  return jsonb_build_object(
    'batchId', v_batch_id,
    'batchCode', v_batch_code,
    'recipeCardId', v_recipe.id,
    'productId', v_recipe.product_id,
    'siteId', v_recipe.site_id,
    'areaId', v_recipe.area_id,
    'areaKind', v_recipe.area_kind,
    'productionRouteId', v_route_id,
    'inputLocationId', v_input_location_id,
    'outputMode', v_output_mode,
    'expectedQty', v_expected_qty,
    'producedQty', p_produced_qty,
    'producedUnit', v_produced_unit,
    'destinationLocationId', v_output_location_id,
    'destinationPositionId', v_output_position_id,
    'packageCount', v_packages_count,
    'packagedQty', case when v_packages_count > 0 then v_package_total else null end,
    'totalCost', v_total_cost,
    'unitCost', v_unit_cost
  );
end;
$$;


ALTER FUNCTION "public"."fogo_create_real_production_batch"("p_recipe_card_id" "uuid", "p_produced_qty" numeric, "p_destination_location_id" "uuid", "p_ingredients" "jsonb", "p_packages" "jsonb", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fogo_create_real_production_batch"("p_recipe_card_id" "uuid", "p_produced_qty" numeric, "p_destination_location_id" "uuid", "p_ingredients" "jsonb" DEFAULT '[]'::"jsonb", "p_packages" "jsonb" DEFAULT '[]'::"jsonb", "p_outputs" "jsonb" DEFAULT '[]'::"jsonb", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_employee_id uuid := auth.uid();
  v_result jsonb;
  v_batch_id uuid;
  v_batch record;
  v_recipe record;
  v_output record;
  v_recipe_output record;
  v_output_location record;
  v_output_product record;
  v_input_unit record;
  v_stock_unit record;
  v_movement_id uuid;
  v_total_cost numeric := 0;
  v_allocated_cost numeric := 0;
  v_unit_cost numeric := null;
  v_stock_unit_cost numeric := null;
  v_stock_qty numeric := 0;
  v_conversion_factor_to_stock numeric := 1;
  v_pct_sum numeric := 0;
  v_primary_qty numeric;
  v_primary_unit_cost numeric := null;
  v_has_outputs boolean := false;
  v_global_qty_before numeric := 0;
  v_site_qty_before numeric := 0;
  v_cost_before numeric := 0;
  v_cost_after numeric := 0;
  v_site_avg_before numeric := 0;
  v_site_avg_after numeric := 0;
begin
  if p_outputs is null or jsonb_typeof(p_outputs) <> 'array' then
    raise exception 'outputs must be a json array';
  end if;

  v_has_outputs := jsonb_array_length(p_outputs) > 0;

  v_result := public.fogo_create_real_production_batch(
    p_recipe_card_id,
    p_produced_qty,
    p_destination_location_id,
    p_ingredients,
    p_packages,
    p_notes
  );

  if not v_has_outputs then
    return v_result;
  end if;

  v_batch_id := nullif(v_result->>'batchId', '')::uuid;

  select *
    into v_batch
  from public.production_batches
  where id = v_batch_id;

  if not found then
    raise exception 'production batch not found after creation';
  end if;

  select rc.id, rc.product_id, rc.site_id, rc.area_id, p.unit, p.stock_unit_code
    into v_recipe
  from public.recipe_cards rc
  join public.products p on p.id = rc.product_id
  where rc.id = p_recipe_card_id;

  v_primary_qty := p_produced_qty;
  v_total_cost := coalesce(v_batch.total_cost, 0);

  for v_output in
    select *
    from jsonb_to_recordset(p_outputs) as x(
      recipe_output_id uuid,
      product_id uuid,
      output_role text,
      produced_qty numeric,
      produced_unit text,
      destination_location_id uuid,
      cost_allocation_pct numeric
    )
  loop
    if v_output.product_id is null then
      raise exception 'output product_id is required';
    end if;

    if coalesce(v_output.produced_qty, 0) <= 0 then
      raise exception 'output produced_qty must be greater than zero';
    end if;

    if nullif(trim(coalesce(v_output.produced_unit, '')), '') is null then
      raise exception 'output produced_unit is required';
    end if;

    if coalesce(v_output.cost_allocation_pct, 0) < 0 or coalesce(v_output.cost_allocation_pct, 0) > 100 then
      raise exception 'output cost allocation pct must be between 0 and 100';
    end if;

    if v_output.recipe_output_id is not null then
      select *
        into v_recipe_output
      from public.recipe_outputs ro
      where ro.id = v_output.recipe_output_id
        and ro.recipe_card_id = p_recipe_card_id
        and ro.product_id = v_output.product_id
        and coalesce(ro.is_active, true) = true;

      if not found then
        raise exception 'output does not belong to recipe';
      end if;
    elsif v_output.product_id <> v_recipe.product_id then
      raise exception 'secondary outputs must be configured on recipe_outputs';
    end if;

    v_pct_sum := v_pct_sum + coalesce(v_output.cost_allocation_pct, 0);
  end loop;

  if abs(v_pct_sum - 100) > 0.001 then
    raise exception 'output cost allocation must sum 100%%, got %', v_pct_sum;
  end if;

  delete from public.production_batch_outputs
  where batch_id = v_batch_id;

  for v_output in
    select *
    from jsonb_to_recordset(p_outputs) as x(
      recipe_output_id uuid,
      product_id uuid,
      output_role text,
      produced_qty numeric,
      produced_unit text,
      destination_location_id uuid,
      cost_allocation_pct numeric
    )
  loop
    select id, cost, unit, stock_unit_code
      into v_output_product
    from public.products
    where id = v_output.product_id
    for update;

    if not found then
      raise exception 'output product not found: %', v_output.product_id;
    end if;

    select *
      into v_input_unit
    from public.inventory_units
    where code = v_output.produced_unit
      and coalesce(is_active, true) = true;

    if not found then
      raise exception 'output unit % is not a valid inventory unit', v_output.produced_unit;
    end if;

    select *
      into v_stock_unit
    from public.inventory_units
    where code = coalesce(nullif(v_output_product.stock_unit_code, ''), nullif(v_output_product.unit, ''), v_output.produced_unit)
      and coalesce(is_active, true) = true;

    if not found then
      raise exception 'stock unit for output product % is not valid', v_output.product_id;
    end if;

    if v_input_unit.family is distinct from v_stock_unit.family then
      raise exception 'output unit % cannot be converted to stock unit % for product %',
        v_output.produced_unit,
        v_stock_unit.code,
        v_output.product_id;
    end if;

    v_conversion_factor_to_stock := v_input_unit.factor_to_base / v_stock_unit.factor_to_base;
    v_stock_qty := round(v_output.produced_qty * v_conversion_factor_to_stock, 6);

    if v_stock_qty <= 0 then
      raise exception 'output stock quantity must be greater than zero';
    end if;

    if v_output.product_id = v_recipe.product_id and abs(v_stock_qty - v_output.produced_qty) > 0.001 then
      raise exception 'primary output unit must match product stock unit. Got %, expected %',
        v_output.produced_unit,
        v_stock_unit.code;
    end if;

    v_allocated_cost := round(v_total_cost * (coalesce(v_output.cost_allocation_pct, 0) / 100), 6);
    v_stock_unit_cost := case when v_stock_qty > 0 then round(v_allocated_cost / v_stock_qty, 6) else null end;
    v_unit_cost := case when v_output.produced_qty > 0 then round(v_allocated_cost / v_output.produced_qty, 6) else null end;
    v_movement_id := null;

    if v_output.product_id = v_recipe.product_id then
      v_primary_qty := v_output.produced_qty;
      v_primary_unit_cost := v_unit_cost;
    end if;

    if v_batch.output_mode in ('inventory_stock', 'sellable_stock') then
      v_output.destination_location_id := coalesce(v_output.destination_location_id, v_batch.destination_location_id);

      if v_output.destination_location_id is null then
        raise exception 'destination_location_id is required for output product %', v_output.product_id;
      end if;

      select id, site_id, code
        into v_output_location
      from public.inventory_locations
      where id = v_output.destination_location_id
        and coalesce(is_active, true) = true;

      if not found then
        raise exception 'output destination LOC not found';
      end if;

      if v_output_location.site_id <> v_batch.site_id then
        raise exception 'output destination LOC must belong to batch site';
      end if;

      select coalesce(sum(current_qty), 0)
        into v_global_qty_before
      from public.inventory_stock_by_site
      where product_id = v_output.product_id;

      select coalesce(current_qty, 0), coalesce(avg_unit_cost, 0)
        into v_site_qty_before, v_site_avg_before
      from public.inventory_stock_by_site
      where site_id = v_batch.site_id
        and product_id = v_output.product_id;

      if not found then
        v_site_qty_before := 0;
        v_site_avg_before := 0;
      end if;

      if v_output.product_id = v_recipe.product_id then
        v_global_qty_before := greatest(v_global_qty_before - v_stock_qty, 0);
        v_site_qty_before := greatest(v_site_qty_before - v_stock_qty, 0);

        update public.inventory_movements
        set unit_cost = v_unit_cost,
            stock_unit_cost = v_stock_unit_cost,
            line_total_cost = v_allocated_cost,
            input_qty = v_output.produced_qty,
            input_unit_code = v_output.produced_unit,
            conversion_factor_to_stock = v_conversion_factor_to_stock,
            stock_unit_code = v_stock_unit.code
        where related_production_batch_id = v_batch.id
          and product_id = v_recipe.product_id
          and movement_type = 'production_output'
        returning id into v_movement_id;
      else
        insert into public.inventory_stock_by_location (location_id, product_id, current_qty, updated_at)
        values (v_output.destination_location_id, v_output.product_id, v_stock_qty, now())
        on conflict (location_id, product_id) do update
          set current_qty = public.inventory_stock_by_location.current_qty + excluded.current_qty,
              updated_at = now();

        insert into public.inventory_movements (
          site_id,
          product_id,
          movement_type,
          quantity,
          input_qty,
          input_unit_code,
          conversion_factor_to_stock,
          stock_unit_code,
          unit_cost,
          stock_unit_cost,
          line_total_cost,
          note,
          related_production_batch_id,
          created_by
        ) values (
          v_batch.site_id,
          v_output.product_id,
          'production_output',
          v_stock_qty,
          v_output.produced_qty,
          v_output.produced_unit,
          v_conversion_factor_to_stock,
          v_stock_unit.code,
          v_unit_cost,
          v_stock_unit_cost,
          v_allocated_cost,
          format('Ingreso coproducto lote %s a %s', coalesce(v_batch.batch_code, v_batch.id::text), coalesce(v_output_location.code, v_output.destination_location_id::text)),
          v_batch.id,
          v_employee_id
        ) returning id into v_movement_id;
      end if;

      v_cost_before := coalesce(v_output_product.cost, 0);
      if v_global_qty_before + v_stock_qty > 0 then
        v_cost_after := round(
          ((greatest(v_global_qty_before, 0) * greatest(v_cost_before, 0)) + (v_stock_qty * greatest(coalesce(v_stock_unit_cost, 0), 0)))
          / nullif(greatest(v_global_qty_before, 0) + v_stock_qty, 0),
          6
        );
      else
        v_cost_after := round(greatest(coalesce(v_stock_unit_cost, v_cost_before, 0), 0), 6);
      end if;

      if v_site_qty_before + v_stock_qty > 0 then
        v_site_avg_after := round(
          ((greatest(v_site_qty_before, 0) * greatest(coalesce(v_site_avg_before, v_cost_before, 0), 0)) + (v_stock_qty * greatest(coalesce(v_stock_unit_cost, 0), 0)))
          / nullif(greatest(v_site_qty_before, 0) + v_stock_qty, 0),
          6
        );
      else
        v_site_avg_after := round(greatest(coalesce(v_stock_unit_cost, v_site_avg_before, 0), 0), 6);
      end if;

      insert into public.inventory_stock_by_site (
        site_id,
        product_id,
        current_qty,
        avg_unit_cost,
        updated_at
      ) values (
        v_batch.site_id,
        v_output.product_id,
        v_stock_qty,
        v_site_avg_after,
        now()
      )
      on conflict (site_id, product_id) do update
        set current_qty = case
              when excluded.product_id = v_recipe.product_id
                then public.inventory_stock_by_site.current_qty
              else public.inventory_stock_by_site.current_qty + excluded.current_qty
            end,
            avg_unit_cost = excluded.avg_unit_cost,
            updated_at = now();

      update public.products
      set cost = v_cost_after,
          updated_at = now()
      where id = v_output.product_id;

      insert into public.product_cost_events (
        product_id,
        site_id,
        source,
        source_production_batch_id,
        source_adjust_movement_id,
        qty_before,
        qty_in,
        cost_before,
        cost_in,
        cost_after,
        basis,
        created_by
      ) values (
        v_output.product_id,
        v_batch.site_id,
        'production',
        v_batch.id,
        v_movement_id,
        v_global_qty_before,
        v_stock_qty,
        v_cost_before,
        coalesce(v_stock_unit_cost, 0),
        v_cost_after,
        'net',
        v_employee_id
      );
    end if;

    insert into public.production_batch_outputs (
      batch_id,
      recipe_card_id,
      recipe_output_id,
      product_id,
      output_role,
      produced_qty,
      produced_unit,
      destination_location_id,
      cost_allocation_method,
      cost_allocation_pct,
      allocated_total_cost,
      unit_cost,
      inventory_movement_id,
      metadata
    ) values (
      v_batch.id,
      p_recipe_card_id,
      v_output.recipe_output_id,
      v_output.product_id,
      case when v_output.product_id = v_recipe.product_id then 'primary' else coalesce(nullif(v_output.output_role, ''), 'co_product') end,
      v_output.produced_qty,
      v_output.produced_unit,
      case when v_batch.output_mode in ('inventory_stock', 'sellable_stock') then v_output.destination_location_id else null end,
      'percentage',
      coalesce(v_output.cost_allocation_pct, 0),
      v_allocated_cost,
      v_unit_cost,
      v_movement_id,
      jsonb_build_object(
        'source', 'fogo_create_real_production_batch',
        'stockQty', v_stock_qty,
        'stockUnitCode', v_stock_unit.code,
        'stockUnitCost', v_stock_unit_cost,
        'conversionFactorToStock', v_conversion_factor_to_stock
      )
    );
  end loop;

  update public.production_batches
  set produced_qty = coalesce(v_primary_qty, produced_qty),
      unit_cost = coalesce(v_primary_unit_cost, unit_cost),
      total_cost = v_total_cost
  where id = v_batch.id;

  return v_result || jsonb_build_object(
    'multiOutput', true,
    'outputCount', jsonb_array_length(p_outputs),
    'primaryUnitCost', v_primary_unit_cost
  );
end;
$$;


ALTER FUNCTION "public"."fogo_create_real_production_batch"("p_recipe_card_id" "uuid", "p_produced_qty" numeric, "p_destination_location_id" "uuid", "p_ingredients" "jsonb", "p_packages" "jsonb", "p_outputs" "jsonb", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fogo_recipe_area_options"("p_site_id" "uuid") RETURNS TABLE("id" "uuid", "code" "text", "name" "text", "kind" "text", "site_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with current_context as (
    select
      public.current_employee_role() as role,
      public.current_employee_area_id() as employee_area_id
  ),
  allowed_kind(area_kind, sort_order) as (
    values
      ('bodega'::text, 1),
      ('cocina_caliente'::text, 2),
      ('panaderia'::text, 3),
      ('reposteria'::text, 4),
      ('cocina'::text, 5),
      ('bar'::text, 6),
      ('cocina_bar'::text, 7)
  ),
  enabled_kind as (
    select ak.area_kind, ak.sort_order
    from allowed_kind ak
    where exists (
      select 1
      from public.site_area_purpose_rules rule
      where rule.site_id = p_site_id
        and rule.purpose = 'production_recipe'
        and rule.area_kind = ak.area_kind
        and coalesce(rule.is_enabled, true) = true
    )
    or not exists (
      select 1
      from public.site_area_purpose_rules rule
      where rule.site_id = p_site_id
        and rule.purpose = 'production_recipe'
    )
  ),
  candidate as (
    select
      a.id,
      a.code,
      a.name,
      a.kind,
      a.site_id,
      case
        when upper(coalesce(a.code, '')) = 'BODEGA'
          or lower(public._vento_slugify(coalesce(a.name, ''))) in ('bodega', 'bodega-principal')
          then 'bodega'
        when upper(coalesce(a.code, '')) in ('COC-CAL', 'COCINA_CALIENTE')
          or lower(public._vento_slugify(coalesce(a.name, ''))) = 'cocina-caliente'
          then 'cocina_caliente'
        when upper(coalesce(a.code, '')) = 'PAN-GALL'
          or lower(public._vento_slugify(coalesce(a.name, ''))) = 'galleteria-y-panaderia'
          then 'panaderia'
        when upper(coalesce(a.code, '')) = 'REPOSTERIA'
          or lower(public._vento_slugify(coalesce(a.name, ''))) = 'reposteria'
          then 'reposteria'
        else a.kind
      end as canonical_kind,
      case
        when upper(coalesce(a.code, '')) in ('BODEGA', 'COC-CAL', 'PAN-GALL', 'REPOSTERIA') then 0
        else 1
      end as preference
    from public.areas a
    where a.site_id = p_site_id
      and coalesce(a.is_active, true) = true
      and not (
        upper(coalesce(a.code, '')) in ('PAN', 'PANADERIA')
        or lower(public._vento_slugify(coalesce(a.name, ''))) = 'panaderia'
      )
  ),
  scoped as (
    select c.*, ek.sort_order
    from candidate c
    join enabled_kind ek on ek.area_kind = c.canonical_kind
    cross join current_context ctx
    where
      ctx.role in ('propietario', 'gerente_general')
      or (
        ctx.role = 'gerente'
        and public.can_access_site(p_site_id)
      )
      or (
        public.has_permission('fogo.production.recipe_book.view', p_site_id, c.id)
        and ctx.employee_area_id = c.id
      )
      or public.has_permission('fogo.production.recipes.manage', p_site_id, c.id)
  ),
  deduped as (
    select *,
      row_number() over (
        partition by canonical_kind
        order by preference asc, name asc, id asc
      ) as rn
    from scoped
  )
  select id, code, name, kind, site_id
  from deduped
  where rn = 1
  order by sort_order asc, name asc;
$$;


ALTER FUNCTION "public"."fogo_recipe_area_options"("p_site_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_daily_internal_pos_documents"("p_cutoff_at" timestamp with time zone DEFAULT "now"(), "p_dry_run" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_cutoff_at timestamptz := coalesce(p_cutoff_at, now());
  v_document_date date := (coalesce(p_cutoff_at, now()) at time zone 'America/Bogota')::date;

  v_group record;
  v_document_id uuid;
  v_sequence_value integer;
  v_document_number text;
  v_group_total numeric;

  v_documents_created integer := 0;
  v_remissions_invoiced integer := 0;
  v_lines_created integer := 0;
  v_total numeric := 0;

  v_candidate_remissions integer := 0;
  v_candidate_lines integer := 0;
  v_blocked_unpriced integer := 0;
  v_blocked_variances integer := 0;

  v_result jsonb;
begin
  if not (
    current_user = 'service_role'
    or current_setting('request.jwt.claim.role', true) = 'service_role'
    or has_permission('nexo.internal_invoices.generate')
    or has_permission('internal_invoices.generate')
    or is_owner()
    or is_global_manager()
  ) then
    raise exception 'permission_denied_internal_invoices_generate';
  end if;

  -- Prevent concurrent generation for the same cutoff day.
  perform pg_advisory_xact_lock(hashtext('vento_internal_pos_documents_' || v_document_date::text));

  drop table if exists _daily_internal_pos_candidate_remissions;
  drop table if exists _daily_internal_pos_candidate_lines;

  -- Candidate remissions: closed, valued, not invoiced, before cutoff, no blocking variance,
  -- and no received item without price.
  create temp table _daily_internal_pos_candidate_remissions on commit drop as
  select
    r.id as remission_id,
    r.request_code,
    r.seller_cost_center_id,
    r.buyer_cost_center_id,
    r.to_site_id as buyer_site_id,
    r.closed_at,
    r.received_at
  from public.restock_requests r
  where r.status = 'closed'
    and r.pricing_status = 'ready_to_invoice'
    and r.internal_pos_document_id is null
    and r.closed_at is not null
    and r.closed_at <= v_cutoff_at
    and r.seller_cost_center_id is not null
    and r.buyer_cost_center_id is not null
    and exists (
      select 1
      from public.restock_request_items i
      where i.request_id = r.id
        and coalesce(i.received_quantity, 0) > 0
    )
    and not exists (
      select 1
      from public.restock_request_items i
      where i.request_id = r.id
        and coalesce(i.received_quantity, 0) > 0
        and (
          i.transfer_unit_price is null
          or i.transfer_total is null
          or i.transfer_unit_price < 0
          or i.transfer_total < 0
        )
    )
    and not exists (
      select 1
      from public.internal_transfer_variances v
      where v.remission_id = r.id
        and coalesce(v.status, '') not in ('resolved', 'approved', 'cancelled', 'closed')
    );

  create temp table _daily_internal_pos_candidate_lines on commit drop as
  select
    c.remission_id,
    i.id as remission_item_id,
    i.product_id,
    coalesce(i.received_quantity, 0) as quantity,
    coalesce(nullif(i.input_unit_code, ''), nullif(i.stock_unit_code, ''), nullif(i.unit, ''), 'un') as unit_code,
    i.transfer_unit_price as unit_price,
    i.transfer_total as subtotal,
    i.internal_price_list_id as price_list_id,
    i.internal_price_list_item_id as price_list_item_id,
    coalesce(i.priced_at, now()) as priced_at,
    coalesce(nullif(i.transfer_currency, ''), 'COP') as currency,
    c.seller_cost_center_id,
    c.buyer_cost_center_id,
    c.buyer_site_id
  from _daily_internal_pos_candidate_remissions c
  join public.restock_request_items i
    on i.request_id = c.remission_id
  where coalesce(i.received_quantity, 0) > 0;

  select count(*)
  into v_candidate_remissions
  from _daily_internal_pos_candidate_remissions;

  select count(*), coalesce(sum(subtotal), 0)
  into v_candidate_lines, v_total
  from _daily_internal_pos_candidate_lines;

  -- Diagnostics: closed ready remissions blocked by unpriced lines.
  select count(distinct r.id)
  into v_blocked_unpriced
  from public.restock_requests r
  where r.status = 'closed'
    and r.pricing_status = 'ready_to_invoice'
    and r.internal_pos_document_id is null
    and r.closed_at is not null
    and r.closed_at <= v_cutoff_at
    and exists (
      select 1
      from public.restock_request_items i
      where i.request_id = r.id
        and coalesce(i.received_quantity, 0) > 0
        and (
          i.transfer_unit_price is null
          or i.transfer_total is null
          or i.transfer_unit_price < 0
          or i.transfer_total < 0
        )
    );

  -- Diagnostics: closed ready remissions blocked by unresolved variances.
  select count(distinct r.id)
  into v_blocked_variances
  from public.restock_requests r
  where r.status = 'closed'
    and r.pricing_status = 'ready_to_invoice'
    and r.internal_pos_document_id is null
    and r.closed_at is not null
    and r.closed_at <= v_cutoff_at
    and exists (
      select 1
      from public.internal_transfer_variances v
      where v.remission_id = r.id
        and coalesce(v.status, '') not in ('resolved', 'approved', 'cancelled', 'closed')
    );

  if p_dry_run then
    return jsonb_build_object(
      'dry_run', true,
      'cutoff_at', v_cutoff_at,
      'document_date', v_document_date,
      'candidate_remissions', v_candidate_remissions,
      'candidate_lines', v_candidate_lines,
      'candidate_total', coalesce(v_total, 0),
      'blocked_unpriced_remissions', coalesce(v_blocked_unpriced, 0),
      'blocked_variance_remissions', coalesce(v_blocked_variances, 0)
    );
  end if;

  for v_group in
    select
      seller_cost_center_id,
      buyer_cost_center_id,
      buyer_site_id,
      currency,
      count(distinct remission_id) as remission_count,
      count(*) as line_count,
      coalesce(sum(subtotal), 0) as total
    from _daily_internal_pos_candidate_lines
    group by
      seller_cost_center_id,
      buyer_cost_center_id,
      buyer_site_id,
      currency
    having coalesce(sum(subtotal), 0) >= 0
    order by buyer_cost_center_id, currency
  loop
    insert into public.internal_pos_document_sequences (
      document_date,
      last_value,
      updated_at
    )
    values (
      v_document_date,
      0,
      now()
    )
    on conflict (document_date)
    do nothing;

    update public.internal_pos_document_sequences
    set
      last_value = last_value + 1,
      updated_at = now()
    where document_date = v_document_date
    returning last_value into v_sequence_value;

    v_document_number :=
      'IPOS-' ||
      to_char(v_document_date, 'YYYYMMDD') ||
      '-' ||
      lpad(v_sequence_value::text, 4, '0');

    v_document_id := gen_random_uuid();
    v_group_total := coalesce(v_group.total, 0);

    insert into public.internal_pos_documents (
      id,
      document_number,
      document_date,
      cutoff_at,
      seller_cost_center_id,
      buyer_cost_center_id,
      buyer_site_id,
      status,
      subtotal,
      total,
      currency,
      generated_by_system,
      generated_at,
      issued_at,
      notes,
      created_at,
      updated_at
    )
    values (
      v_document_id,
      v_document_number,
      v_document_date,
      v_cutoff_at,
      v_group.seller_cost_center_id,
      v_group.buyer_cost_center_id,
      v_group.buyer_site_id,
      'issued',
      v_group_total,
      v_group_total,
      v_group.currency,
      true,
      now(),
      now(),
      'Comprobante interno generado automaticamente para corte diario de las 5:00 p.m. Colombia.',
      now(),
      now()
    );

    insert into public.internal_pos_document_lines (
      id,
      document_id,
      remission_id,
      remission_item_id,
      product_id,
      quantity,
      unit_code,
      unit_price,
      subtotal,
      price_list_id,
      price_list_item_id,
      priced_at,
      created_at
    )
    select
      gen_random_uuid(),
      v_document_id,
      l.remission_id,
      l.remission_item_id,
      l.product_id,
      l.quantity,
      l.unit_code,
      l.unit_price,
      l.subtotal,
      l.price_list_id,
      l.price_list_item_id,
      l.priced_at,
      now()
    from _daily_internal_pos_candidate_lines l
    where l.seller_cost_center_id = v_group.seller_cost_center_id
      and l.buyer_cost_center_id = v_group.buyer_cost_center_id
      and coalesce(l.buyer_site_id, '00000000-0000-0000-0000-000000000000'::uuid)
          = coalesce(v_group.buyer_site_id, '00000000-0000-0000-0000-000000000000'::uuid)
      and l.currency = v_group.currency;

    get diagnostics v_lines_created = row_count;

    update public.restock_requests r
    set
      internal_pos_document_id = v_document_id,
      pricing_status = 'invoiced'
    where r.id in (
      select distinct l.remission_id
      from _daily_internal_pos_candidate_lines l
      where l.seller_cost_center_id = v_group.seller_cost_center_id
        and l.buyer_cost_center_id = v_group.buyer_cost_center_id
        and coalesce(l.buyer_site_id, '00000000-0000-0000-0000-000000000000'::uuid)
            = coalesce(v_group.buyer_site_id, '00000000-0000-0000-0000-000000000000'::uuid)
        and l.currency = v_group.currency
    );

    get diagnostics v_remissions_invoiced = row_count;

    v_documents_created := v_documents_created + 1;
  end loop;

  select jsonb_build_object(
    'dry_run', false,
    'cutoff_at', v_cutoff_at,
    'document_date', v_document_date,
    'documents_created', v_documents_created,
    'remissions_invoiced', (
      select count(distinct remission_id)
      from _daily_internal_pos_candidate_lines
    ),
    'lines_created', (
      select count(*)
      from _daily_internal_pos_candidate_lines
    ),
    'total', coalesce(v_total, 0),
    'blocked_unpriced_remissions', coalesce(v_blocked_unpriced, 0),
    'blocked_variance_remissions', coalesce(v_blocked_variances, 0)
  )
  into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."generate_daily_internal_pos_documents"("p_cutoff_at" timestamp with time zone, "p_dry_run" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."generate_daily_internal_pos_documents"("p_cutoff_at" timestamp with time zone, "p_dry_run" boolean) IS 'Generates internal POS documents for closed, valued internal remissions up to the given cutoff. Use p_dry_run=true to preview.';



CREATE OR REPLACE FUNCTION "public"."generate_inventory_sku"("p_product_type" "text" DEFAULT NULL::"text", "p_inventory_kind" "text" DEFAULT NULL::"text", "p_name" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'storage', 'extensions'
    AS $$
declare
  v_type text;
  v_name text;
  v_seq bigint;
begin
  v_type := case
    when lower(coalesce(trim(p_inventory_kind), '')) = 'asset' then 'EQP'
    when lower(coalesce(trim(p_product_type), '')) = 'venta' then 'VEN'
    when lower(coalesce(trim(p_product_type), '')) = 'preparacion' then 'PRE'
    else 'INS'
  end;

  v_name := upper(coalesce(trim(p_name), ''));
  v_name := translate(v_name,
    'ÁÀÄÂÃÉÈËÊÍÌÏÎÓÒÖÔÕÚÙÜÛÑÇáàäâãéèëêíìïîóòöôõúùüûñç',
    'AAAAAEEEEIIIIOOOOOUUUUNCaaaaaeeeeiiiiooooouuuunc'
  );
  v_name := regexp_replace(v_name, '[^A-Z0-9]+', '', 'g');
  v_name := left(nullif(v_name, ''), 6);
  if v_name is null then
    v_name := 'ITEM';
  end if;

  v_seq := nextval('public.inventory_sku_seq');

  return v_type || '-' || v_name || '-' || lpad(v_seq::text, 6, '0');
end;
$$;


ALTER FUNCTION "public"."generate_inventory_sku"("p_product_type" "text", "p_inventory_kind" "text", "p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_location_code"("p_site_code" "text", "p_zone" "text", "p_aisle" "text" DEFAULT NULL::"text", "p_level" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'auth', 'storage', 'extensions'
    AS $$
DECLARE
  v_code TEXT;
BEGIN
  v_code := 'LOC-' || UPPER(p_site_code) || '-' || UPPER(p_zone);
  IF p_aisle IS NOT NULL THEN
    v_code := v_code || '-' || UPPER(p_aisle);
  END IF;
  IF p_level IS NOT NULL THEN
    v_code := v_code || '-' || UPPER(p_level);
  END IF;
  RETURN v_code;
END;
$$;


ALTER FUNCTION "public"."generate_location_code"("p_site_code" "text", "p_zone" "text", "p_aisle" "text", "p_level" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_lpn_code"("p_site_code" "text") RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'storage', 'extensions'
    AS $$
DECLARE
  v_year_month TEXT;
  v_seq INT;
BEGIN
  v_year_month := TO_CHAR(NOW(), 'YYMM');
  v_seq := NEXTVAL('lpn_sequence');
  RETURN 'LPN-' || UPPER(p_site_code) || '-' || v_year_month || '-' || LPAD(v_seq::TEXT, 4, '0');
END;
$$;


ALTER FUNCTION "public"."generate_lpn_code"("p_site_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_manual_daily_internal_pos_documents"("p_document_date" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select public.generate_daily_internal_pos_documents(
    public.get_colombia_internal_pos_cutoff_at(p_document_date),
    false
  );
$$;


ALTER FUNCTION "public"."generate_manual_daily_internal_pos_documents"("p_document_date" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."generate_manual_daily_internal_pos_documents"("p_document_date" "date") IS 'Manual generation for daily internal POS documents using the 5:00 p.m. Colombia cutoff for the selected date. Writes documents and marks remissions as invoiced.';



CREATE OR REPLACE FUNCTION "public"."generate_product_sku"("p_product_type" "text", "p_site_id" "uuid" DEFAULT NULL::"uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_site_id uuid;
  v_brand_code text;
  v_type_code text;
  v_next integer;
begin
  v_site_id := coalesce(
    p_site_id,
    public.current_employee_selected_site_id(),
    public.current_employee_primary_site_id()
  );

  if v_site_id is null then
    select s.id into v_site_id
    from public.sites s
    where s.site_kind = 'hq'
    order by s.created_at
    limit 1;
  end if;

  if v_site_id is null then
    select s.id into v_site_id
    from public.sites s
    order by s.created_at
    limit 1;
  end if;

  if v_site_id is null then
    raise exception 'No site available to generate SKU';
  end if;

  v_brand_code := public.resolve_product_sku_brand_code(v_site_id);
  if v_brand_code is null or v_brand_code = '' then
    raise exception 'No brand code available for site %', v_site_id;
  end if;

  v_type_code := public.resolve_product_sku_type_code(p_product_type);
  if v_type_code is null or v_type_code = '' then
    v_type_code := 'GEN';
  end if;

  insert into public.product_sku_sequences (brand_code, type_code, last_value, updated_at)
  values (v_brand_code, v_type_code, 1, now())
  on conflict (brand_code, type_code)
  do update
    set last_value = public.product_sku_sequences.last_value + 1,
        updated_at = now()
  returning last_value into v_next;

  return v_brand_code || '-' || v_type_code || '-' || lpad(v_next::text, 5, '0');
end;
$$;


ALTER FUNCTION "public"."generate_product_sku"("p_product_type" "text", "p_site_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_active_context_simulation_v1"() RETURNS TABLE("id" "uuid", "user_id" "uuid", "site_id" "uuid", "area_id" "uuid", "area_kind" "text", "operational_role" "text", "administrative_role" "text", "expires_at" timestamp with time zone, "metadata" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
  select cs.id, cs.user_id, cs.site_id, cs.area_id, a.kind,
         cs.operational_role, cs.administrative_role, cs.expires_at, cs.metadata
  from public.context_simulation_sessions cs
  left join public.areas a on a.id = cs.area_id
  where cs.user_id = auth.uid()
    and cs.is_active
    and cs.ended_at is null
    and cs.expires_at > now()
    and public.can_manage_context_simulation_v1(auth.uid())
  order by cs.created_at desc
  limit 1;
$$;


