CREATE OR REPLACE FUNCTION "public"."get_client_gift_history"("p_limit" integer DEFAULT 10) RETURNS TABLE("order_id" "uuid", "created_at" timestamp with time zone, "site_id" "uuid", "total_amount" numeric, "fulfillment_type" "text", "schedule_mode" "text", "recipient_name" "text", "recipient_phone" "text", "recipient_relationship" "text", "is_surprise" boolean, "contact_policy" "text", "fallback_contact_policy" "text", "card_requested" boolean, "card_message" "text", "card_to" "text", "card_from" "text", "saved_recipient_id" "uuid")
    LANGUAGE "sql"
    SET "search_path" TO 'public'
    AS $$
  select
    o.id,
    o.created_at,
    o.site_id,
    o.total_amount,
    o.fulfillment_type,
    o.schedule_mode,
    g.recipient_name,
    g.recipient_phone,
    g.recipient_relationship,
    g.is_surprise,
    g.contact_policy,
    g.fallback_contact_policy,
    g.card_requested,
    g.card_message,
    g.card_to,
    g.card_from,
    g.saved_recipient_id
  from public.orders o
  join public.order_gift_details g on g.order_id = o.id
  where o.client_id = (select auth.uid())
    and o.is_gift = true
  order by o.created_at desc
  limit greatest(1, least(coalesce(p_limit, 10), 25));
$$;


ALTER FUNCTION "public"."get_client_gift_history"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_client_order_chat_unread_counts"("p_order_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("order_id" "uuid", "conversation_id" "uuid", "unread_count" bigint, "latest_message_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    c.order_id,
    c.id as conversation_id,
    count(m.id)::bigint as unread_count,
    max(m.created_at) as latest_message_at
  from public.order_conversations c
  left join public.order_messages m
    on m.conversation_id = c.id
   and m.author_type = 'staff'
   and m.created_at > coalesce(c.last_client_read_at, '-infinity'::timestamptz)
  where c.client_id = auth.uid()
    and (p_order_ids is null or c.order_id = any(p_order_ids))
  group by c.order_id, c.id;
$$;


