CREATE OR REPLACE FUNCTION "public"."get_delivery_portal_data_by_token"("p_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  v_session public.order_delivery_sessions%rowtype;
  v_order public.orders%rowtype;
  v_gift public.order_gift_details%rowtype;
  v_hash text;
begin
  if nullif(trim(coalesce(p_token, '')), '') is null then
    return jsonb_build_object('ok', false, 'error', 'token_required');
  end if;

  v_hash := encode(extensions.digest(trim(p_token), 'sha256'::text), 'hex');

  select * into v_session
  from public.order_delivery_sessions
  where access_token_hash = v_hash
  for update;

  if v_session.id is null then
    return jsonb_build_object('ok', false, 'error', 'invalid_token');
  end if;

  if v_session.status in ('pending','in_transit') and v_session.expires_at <= now() then
    update public.order_delivery_sessions
    set status = 'expired', updated_at = now()
    where id = v_session.id
    returning * into v_session;
  end if;

  select * into v_order from public.orders where id = v_session.order_id;
  select * into v_gift from public.order_gift_details where order_id = v_session.order_id;

  update public.order_delivery_sessions
  set opened_at = coalesce(opened_at, now()), updated_at = now()
  where id = v_session.id;

  return jsonb_build_object(
    'ok', true,
    'session', jsonb_build_object(
      'status', v_session.status,
      'expires_at', v_session.expires_at,
      'picked_up_at', v_session.picked_up_at,
      'confirmed_at', v_session.confirmed_at,
      'attempt_count', v_session.attempt_count,
      'max_attempts', v_session.max_attempts,
      'issue_code', v_session.issue_code,
      'issue_notes', v_session.issue_notes
    ),
    'order', jsonb_build_object(
      'id', v_order.id,
      'short_id', upper(left(v_order.id::text, 6)),
      'status', v_order.status,
      'dispatch_status', v_order.dispatch_status,
      'contact_phone', v_order.contact_phone,
      'delivery_address', v_order.delivery_address,
      'delivery_zone', v_order.delivery_zone,
      'notes', v_order.notes,
      'payment_status', v_order.payment_status,
      'amount_to_collect', case when v_order.payment_status = 'paid' then 0 else v_order.total_amount end,
      'dispatch_partner', v_order.dispatch_partner,
      'dispatch_reference', v_order.dispatch_reference,
      'is_gift', v_order.is_gift
    ),
    'gift', case when v_gift.id is null then null else jsonb_build_object(
      'recipient_name', v_gift.recipient_name,
      'recipient_phone', v_gift.recipient_phone,
      'is_surprise', v_gift.is_surprise,
      'contact_policy', v_gift.contact_policy,
      'fallback_contact_policy', v_gift.fallback_contact_policy,
      'hide_prices', v_gift.hide_prices
    ) end
  );
end;
$$;


ALTER FUNCTION "public"."get_delivery_portal_data_by_token"("p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_effective_context_v1"("p_app_code" "text" DEFAULT NULL::"text") RETURNS TABLE("source" "text", "session_mode" "text", "app_code" "text", "user_id" "uuid", "real_administrative_role" "text", "effective_administrative_role" "text", "effective_operational_role" "text", "site_id" "uuid", "area_id" "uuid", "area_kind" "text", "shift_id" "uuid", "simulation_id" "uuid", "shared_device_id" "uuid", "is_simulation" boolean, "is_shared_device" boolean, "bypass_applied" boolean, "can_operate" boolean, "blocked_reasons" "text"[], "metadata" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_app_code text := nullif(btrim(lower(coalesce(p_app_code, ''))), '');
  v_device record;
  v_sim record;
  v_real record;
  v_real_role text;
  v_area_kind text;
begin
  select e.role into v_real_role from public.employees e where e.id = auth.uid() limit 1;

  select * into v_device from public.current_shared_operational_device_v1() limit 1;
  if v_device.id is not null then
    select a.kind into v_area_kind from public.areas a where a.id = v_device.area_id limit 1;
    source := 'shared_device';
    session_mode := 'shared_device';
    app_code := v_app_code;
    user_id := auth.uid();
    real_administrative_role := v_real_role;
    effective_administrative_role := null;
    effective_operational_role := nullif(btrim(coalesce(v_device.navigation_role, '')), '');
    site_id := v_device.site_id;
    area_id := v_device.area_id;
    area_kind := v_area_kind;
    shift_id := null;
    simulation_id := null;
    shared_device_id := v_device.id;
    is_simulation := false;
    is_shared_device := true;
    bypass_applied := false;
    can_operate := v_app_code is null or v_app_code = any(coalesce(v_device.allowed_app_codes, '{}'::text[]));
    blocked_reasons := case when can_operate then '{}'::text[] else array['app_not_allowed']::text[] end;
    metadata := coalesce(v_device.metadata, '{}'::jsonb);
    return next;
    return;
  end if;

  select * into v_sim from public.get_active_context_simulation_v1() limit 1;
  if v_sim.id is not null then
    source := 'simulation';
    session_mode := 'employee';
    app_code := v_app_code;
    user_id := auth.uid();
    real_administrative_role := v_real_role;
    effective_administrative_role := v_sim.administrative_role;
    effective_operational_role := v_sim.operational_role;
    site_id := v_sim.site_id;
    area_id := v_sim.area_id;
    area_kind := v_sim.area_kind;
    shift_id := null;
    simulation_id := v_sim.id;
    shared_device_id := null;
    is_simulation := true;
    is_shared_device := false;
    bypass_applied := false;
    can_operate := true;
    blocked_reasons := '{}'::text[];
    metadata := coalesce(v_sim.metadata, '{}'::jsonb);
    return next;
    return;
  end if;

  select * into v_real
  from public.get_operational_context(auth.uid(), null, coalesce(v_app_code, 'nexo'))
  limit 1;

  source := case
    when coalesce(v_real.bypass_applied, false) then 'administrative_bypass'
    when coalesce(v_real.on_shift_now, false) or coalesce(v_real.checked_in_now, false) then 'anima'
    else 'real'
  end;
  session_mode := 'employee';
  app_code := coalesce(v_real.app_code, v_app_code);
  user_id := auth.uid();
  real_administrative_role := v_real_role;
  effective_administrative_role := v_real_role;
  effective_operational_role := v_real.active_operational_role;
  site_id := v_real.active_site_id;
  area_id := v_real.active_area_id;
  area_kind := v_real.active_area_kind;
  shift_id := v_real.active_shift_id;
  simulation_id := null;
  shared_device_id := null;
  is_simulation := false;
  is_shared_device := false;
  bypass_applied := coalesce(v_real.bypass_applied, false);
  can_operate := coalesce(v_real.can_operate, false);
  blocked_reasons := coalesce(v_real.blocked_reasons, '{}'::text[]);
  metadata := '{}'::jsonb;
  return next;
end;
$$;


ALTER FUNCTION "public"."get_effective_context_v1"("p_app_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_effective_context_v1"("p_app_code" "text") IS 'Resuelve un único contexto: dispositivo compartido, simulación administrativa o contexto real de ANIMA.';



CREATE OR REPLACE FUNCTION "public"."get_internal_invoice_cutoff_warnings"("p_cutoff_at" timestamp with time zone) RETURNS TABLE("warning_key" "text", "total" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  return query
  select
    'operational_not_closed'::text as warning_key,
    count(*)::bigint as total
  from public.restock_requests r
  where r.created_at <= p_cutoff_at
    and r.status not in ('closed', 'received', 'cancelled');

  return query
  select
    'partial_or_in_transit'::text as warning_key,
    count(*)::bigint as total
  from public.restock_requests r
  where r.created_at <= p_cutoff_at
    and r.status in ('partial', 'in_transit');

  return query
  select
    'closed_pending_price'::text as warning_key,
    count(*)::bigint as total
  from public.restock_requests r
  where r.closed_at is not null
    and r.closed_at <= p_cutoff_at
    and r.status in ('closed', 'received')
    and r.pricing_status = 'pending_price'
    and r.internal_pos_document_id is null;

  return query
  select
    'closed_pending_variance_resolution'::text as warning_key,
    count(*)::bigint as total
  from public.restock_requests r
  where r.closed_at is not null
    and r.closed_at <= p_cutoff_at
    and r.status in ('closed', 'received')
    and r.pricing_status = 'pending_variance_resolution'
    and r.internal_pos_document_id is null;

  return query
  select
    'ready_to_invoice'::text as warning_key,
    count(*)::bigint as total
  from public.restock_requests r
  where r.closed_at is not null
    and r.closed_at <= p_cutoff_at
    and r.status in ('closed', 'received')
    and r.pricing_status = 'ready_to_invoice'
    and r.internal_pos_document_id is null;
end;
$$;


ALTER FUNCTION "public"."get_internal_invoice_cutoff_warnings"("p_cutoff_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_internal_invoice_cutoff_warnings"("p_cutoff_at" timestamp with time zone) IS 'Returns aggregate warning counts for the future 4:30 p.m. internal billing cutoff notification.';



