CREATE OR REPLACE FUNCTION "public"."get_operational_context"("p_employee_id" "uuid" DEFAULT "auth"."uid"(), "p_site_id" "uuid" DEFAULT NULL::"uuid", "p_app_code" "text" DEFAULT 'nexo'::"text") RETURNS TABLE("employee_id" "uuid", "app_code" "text", "active_site_id" "uuid", "selected_site_id" "uuid", "employee_default_site_id" "uuid", "active_shift_id" "uuid", "active_shift_site_id" "uuid", "active_shift_area_id" "uuid", "active_operational_role" "text", "on_shift_now" boolean, "active_checkin_id" "uuid", "active_checkin_site_id" "uuid", "active_checkin_area_id" "uuid", "active_area_id" "uuid", "active_area_kind" "text", "checked_in_now" boolean, "policy_requires_shift" boolean, "policy_requires_checkin" boolean, "policy_requires_site_match" boolean, "bypass_applied" boolean, "can_operate" boolean, "blocked_reasons" "text"[])
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_policy record;
  v_selected_site_id uuid;
  v_employee_site_id uuid;
  v_active_site_id uuid;
  v_shift_id uuid;
  v_shift_site_id uuid;
  v_shift_area_id uuid;
  v_shift_operational_role text;
  v_open_checkin_id uuid;
  v_open_checkin_site_id uuid;
  v_open_checkin_area_id uuid;
  v_active_area_id uuid;
  v_active_area_kind text;
  v_on_shift boolean := false;
  v_checked_in boolean := false;
  v_now_local timestamp without time zone;
  v_today date;
  v_time_now time without time zone;
  v_bypass boolean := false;
  v_bypass_code text := null;
  v_reasons text[] := array[]::text[];
  v_can_operate boolean := true;
  v_employee_role text := null;
  v_role_is_allowed boolean := false;
begin
  select *
  into v_policy
  from public.app_operation_policies p
  where p.app_code = trim(lower(coalesce(p_app_code, 'nexo')))
    and p.is_active = true
  limit 1;

  if p_employee_id is null then
    p_employee_id := auth.uid();
  end if;

  if p_employee_id is null then
    employee_id := null;
    app_code := coalesce(v_policy.app_code, trim(lower(coalesce(p_app_code, 'nexo'))));
    active_site_id := null;
    selected_site_id := null;
    employee_default_site_id := null;
    active_shift_id := null;
    active_shift_site_id := null;
    active_shift_area_id := null;
    active_operational_role := null;
    on_shift_now := false;
    active_checkin_id := null;
    active_checkin_site_id := null;
    active_checkin_area_id := null;
    active_area_id := null;
    active_area_kind := null;
    checked_in_now := false;
    policy_requires_shift := coalesce(v_policy.requires_shift, false);
    policy_requires_checkin := coalesce(v_policy.requires_checkin, false);
    policy_requires_site_match := coalesce(v_policy.requires_site_match, false);
    bypass_applied := false;
    can_operate := false;
    blocked_reasons := array['unauthenticated'];
    return next;
    return;
  end if;

  select e.site_id, e.role
    into v_employee_site_id, v_employee_role
  from public.employees e
  where e.id = p_employee_id
  limit 1;

  select es.selected_site_id
    into v_selected_site_id
  from public.employee_settings es
  where es.employee_id = p_employee_id
  limit 1;

  v_now_local := now() at time zone 'America/Bogota';
  v_today := v_now_local::date;
  v_time_now := v_now_local::time;

  select
      s.id,
      s.site_id,
      s.area_id,
      nullif(btrim(coalesce(s.operational_role, '')), '')
    into v_shift_id, v_shift_site_id, v_shift_area_id, v_shift_operational_role
  from public.employee_shifts s
  where s.employee_id = p_employee_id
    and s.shift_date = v_today
    and s.published_at is not null
    and coalesce(s.status, 'scheduled') <> 'cancelled'
    and (
      (s.start_time <= s.end_time and v_time_now between s.start_time and s.end_time)
      or
      (s.start_time > s.end_time and (v_time_now >= s.start_time or v_time_now <= s.end_time))
    )
  order by s.start_time asc
  limit 1;

  v_on_shift := v_shift_id is not null;

  select al.id, al.site_id, null::uuid
    into v_open_checkin_id, v_open_checkin_site_id, v_open_checkin_area_id
  from public.attendance_logs al
  where al.employee_id = p_employee_id
    and al.action = 'check_in'
    and not exists (
      select 1
      from public.attendance_logs ao
      where ao.employee_id = al.employee_id
        and ao.action = 'check_out'
        and ao.occurred_at > al.occurred_at
    )
  order by al.occurred_at desc
  limit 1;

  v_checked_in := v_open_checkin_id is not null;
  v_active_site_id := coalesce(p_site_id, v_selected_site_id, v_open_checkin_site_id, v_shift_site_id, v_employee_site_id);
  v_active_area_id := coalesce(v_open_checkin_area_id, v_shift_area_id);

  select a.kind
    into v_active_area_kind
  from public.areas a
  where a.id = v_active_area_id
  limit 1;

  -- Explicit role bypass for global management (they do not operate with shifts).
  if coalesce(v_employee_role, '') in ('propietario', 'gerente_general') then
    v_bypass := true;
  end if;

  if not v_bypass and v_policy.bypass_permission_code is not null and trim(v_policy.bypass_permission_code) <> '' then
    v_bypass_code := v_policy.app_code || '.' || trim(v_policy.bypass_permission_code);
    v_bypass := public.has_permission(v_bypass_code, v_active_site_id);
  end if;

  if not v_bypass then
    if coalesce(v_policy.requires_shift, false) and not v_on_shift then
      v_reasons := array_append(v_reasons, 'out_of_shift');
    end if;

    if coalesce(v_policy.requires_checkin, false) and not v_checked_in then
      v_reasons := array_append(v_reasons, 'checkin_required');
    end if;

    if coalesce(v_policy.requires_shift, false) and v_on_shift then
      if v_shift_operational_role is null then
        v_reasons := array_append(v_reasons, 'invalid_operational_role');
      else
        select exists (
          select 1
          from public.site_operational_roles sor
          where sor.site_id = v_shift_site_id
            and sor.role_code = v_shift_operational_role
            and coalesce(sor.is_active, true) = true
            and (
              sor.area_id is null
              or (v_shift_area_id is not null and sor.area_id = v_shift_area_id)
            )
        )
        into v_role_is_allowed;

        if not coalesce(v_role_is_allowed, false) then
          v_reasons := array_append(v_reasons, 'invalid_operational_role');
        end if;
      end if;
    end if;

    if coalesce(v_policy.requires_site_match, false) then
      if v_on_shift and v_active_site_id is not null and v_shift_site_id is not null and v_shift_site_id <> v_active_site_id then
        v_reasons := array_append(v_reasons, 'shift_site_mismatch');
      end if;
      if v_checked_in and v_active_site_id is not null and v_open_checkin_site_id is not null and v_open_checkin_site_id <> v_active_site_id then
        v_reasons := array_append(v_reasons, 'checkin_site_mismatch');
      end if;
    end if;
  end if;

  v_can_operate := coalesce(array_length(v_reasons, 1), 0) = 0;

  employee_id := p_employee_id;
  app_code := coalesce(v_policy.app_code, trim(lower(coalesce(p_app_code, 'nexo'))));
  active_site_id := v_active_site_id;
  selected_site_id := v_selected_site_id;
  employee_default_site_id := v_employee_site_id;
  active_shift_id := v_shift_id;
  active_shift_site_id := v_shift_site_id;
  active_shift_area_id := v_shift_area_id;
  active_operational_role := v_shift_operational_role;
  on_shift_now := v_on_shift;
  active_checkin_id := v_open_checkin_id;
  active_checkin_site_id := v_open_checkin_site_id;
  active_checkin_area_id := v_open_checkin_area_id;
  active_area_id := v_active_area_id;
  active_area_kind := v_active_area_kind;
  checked_in_now := v_checked_in;
  policy_requires_shift := coalesce(v_policy.requires_shift, false);
  policy_requires_checkin := coalesce(v_policy.requires_checkin, false);
  policy_requires_site_match := coalesce(v_policy.requires_site_match, false);
  bypass_applied := v_bypass;
  can_operate := v_can_operate;
  blocked_reasons := v_reasons;
  return next;
end;
$$;


ALTER FUNCTION "public"."get_operational_context"("p_employee_id" "uuid", "p_site_id" "uuid", "p_app_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_operational_context"("p_employee_id" "uuid", "p_site_id" "uuid", "p_app_code" "text") IS 'Resuelve el contexto operativo vigente del trabajador y bloquea si el turno no trae un rol operativo valido para la sede/area.';



CREATE OR REPLACE FUNCTION "public"."get_order_delivery_pin"("p_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'app_private', 'extensions'
    AS $$
declare
  v_order public.orders%rowtype;
  v_session public.order_delivery_sessions%rowtype;
  v_pin text;
begin
  if auth.uid() is null then
    raise exception 'authentication_required';
  end if;

  select * into v_order
  from public.orders
  where id = p_order_id
    and client_id = auth.uid();

  if v_order.id is null then
    raise exception 'order_not_found';
  end if;

  select * into v_session
  from public.order_delivery_sessions
  where order_id = p_order_id;

  if v_session.id is null then
    return jsonb_build_object(
      'ok', true,
      'available', false,
      'status', null
    );
  end if;

  if v_session.status in ('pending','in_transit') and v_session.expires_at <= now() then
    update public.order_delivery_sessions
    set status = 'expired', updated_at = now()
    where id = v_session.id;
    v_session.status := 'expired';
  end if;

  if v_session.status = 'in_transit' then
    v_pin := app_private.delivery_pin_for_session(v_session.id);

    if encode(extensions.digest(v_pin, 'sha256'::text), 'hex') <> v_session.confirmation_pin_hash then
      raise exception 'delivery_pin_integrity_error';
    end if;
  end if;

  return jsonb_build_object(
    'ok', true,
    'available', v_session.status = 'in_transit',
    'status', v_session.status,
    'pin', case when v_session.status = 'in_transit' then v_pin else null end,
    'expires_at', v_session.expires_at,
    'confirmed_at', v_session.confirmed_at
  );
end;
$$;


ALTER FUNCTION "public"."get_order_delivery_pin"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_order_delivery_slots"("p_site_id" "uuid", "p_fulfillment_type" "text", "p_from_date" "date", "p_to_date" "date", "p_items" "jsonb", "p_timezone" "text" DEFAULT 'America/Bogota'::"text") RETURNS TABLE("slot_id" "uuid", "window_start" timestamp with time zone, "window_end" timestamp with time zone, "capacity" integer, "remaining_capacity" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pass', 'auth'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_timezone text := coalesce(nullif(trim(p_timezone), ''), 'America/Bogota');
  v_fulfillment text := lower(trim(coalesce(p_fulfillment_type, '')));
  v_today date := (now() at time zone v_timezone)::date;
  v_from date := greatest(coalesce(p_from_date, v_today), v_today);
  v_to date := least(coalesce(p_to_date, v_from + 30), v_from + 60);
  v_required_lead integer := 0;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  if p_site_id is null then raise exception 'site_required'; end if;
  if v_fulfillment not in ('delivery', 'pickup', 'on_premise') then raise exception 'invalid_fulfillment_type'; end if;
  if v_to < v_from then raise exception 'invalid_date_range'; end if;

  v_required_lead := pass.order_required_lead_minutes(p_site_id, p_items);

  return query
  with dates as (
    select generate_series(v_from, v_to, interval '1 day')::date as local_date
  ), effective_hours as (
    select
      d.local_date,
      case
        when ex.exception_type = 'closed' then null
        when ex.exception_type = 'special_hours' then ex.opens_at
        when coalesce(h.is_closed, true) then null
        else h.opens_at
      end as opens_at,
      case
        when ex.exception_type = 'closed' then null
        when ex.exception_type = 'special_hours' then ex.closes_at
        when coalesce(h.is_closed, true) then null
        else h.closes_at
      end as closes_at
    from dates d
    left join pass.site_business_hours h
      on h.site_id = p_site_id
     and h.iso_weekday = extract(isodow from d.local_date)::smallint
    left join pass.site_schedule_exceptions ex
      on ex.site_id = p_site_id
     and ex.exception_date = d.local_date
  ), generated as (
    select
      gs::timestamp without time zone as local_start,
      (gs + interval '30 minutes')::timestamp without time zone as local_end
    from effective_hours e
    cross join lateral generate_series(
      e.local_date + e.opens_at,
      e.local_date + e.closes_at - interval '30 minutes',
      interval '30 minutes'
    ) gs
    where e.opens_at is not null
      and e.closes_at is not null
      and e.closes_at > e.opens_at
  ), candidates as (
    select
      g.local_start at time zone v_timezone as window_start,
      g.local_end at time zone v_timezone as window_end
    from generated g
  )
  select
    (
      substr(md5(p_site_id::text || ':' || v_fulfillment || ':' || c.window_start::text || ':' || c.window_end::text), 1, 8) || '-' ||
      substr(md5(p_site_id::text || ':' || v_fulfillment || ':' || c.window_start::text || ':' || c.window_end::text), 9, 4) || '-' ||
      substr(md5(p_site_id::text || ':' || v_fulfillment || ':' || c.window_start::text || ':' || c.window_end::text), 13, 4) || '-' ||
      substr(md5(p_site_id::text || ':' || v_fulfillment || ':' || c.window_start::text || ':' || c.window_end::text), 17, 4) || '-' ||
      substr(md5(p_site_id::text || ':' || v_fulfillment || ':' || c.window_start::text || ':' || c.window_end::text), 21, 12)
    )::uuid,
    c.window_start,
    c.window_end,
    null::integer,
    null::integer
  from candidates c
  where c.window_start >= now() + make_interval(mins => v_required_lead)
  order by c.window_start;
end;
$$;


ALTER FUNCTION "public"."get_order_delivery_slots"("p_site_id" "uuid", "p_fulfillment_type" "text", "p_from_date" "date", "p_to_date" "date", "p_items" "jsonb", "p_timezone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_restock_request_operational_summary"("p_request_id" "uuid") RETURNS TABLE("total_lines" integer, "pending_loc_selection_lines" integer, "dispatch_ready_lines" integer, "dispatch_blocked_lines" integer, "pending_receipt_lines" integer, "shortage_lines" integer, "received_lines" integer, "can_start_prepare" boolean, "can_transit" boolean, "can_complete_receive" boolean, "can_receive_partial" boolean)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'auth', 'storage', 'extensions'
    AS $$
  with item_metrics as (
    select
      i.id,
      coalesce(i.quantity, 0)::numeric as requested_qty,
      coalesce(i.prepared_quantity, 0)::numeric as prepared_qty,
      coalesce(i.shipped_quantity, 0)::numeric as shipped_qty,
      coalesce(i.received_quantity, 0)::numeric as received_qty,
      coalesce(i.shortage_quantity, 0)::numeric as shortage_qty,
      i.source_location_id as source_location_id
    from public.restock_request_items i
    where i.request_id = p_request_id
  ),
  agg as (
    select
      count(*)::integer as total_lines,
      count(*) filter (
        where requested_qty > 0 and source_location_id is null
      )::integer as pending_loc_selection_lines,
      count(*) filter (
        where requested_qty > 0 and prepared_qty > 0
      )::integer as dispatch_ready_lines,
      count(*) filter (
        where requested_qty > 0 and prepared_qty <= 0
      )::integer as dispatch_blocked_lines,
      count(*) filter (
        -- Antes se usaba received + shortage para decidir pendiente.
        -- Ahora: el faltante es alerta, pero mientras received < shipped hay pendiente real.
        where shipped_qty > 0 and received_qty < shipped_qty
      )::integer as pending_receipt_lines,
      count(*) filter (
        where shortage_qty > 0
      )::integer as shortage_lines,
      count(*) filter (
        where received_qty > 0
      )::integer as received_lines,
      bool_and(
        case
          when requested_qty > 0 then source_location_id is not null
          else true
        end
      ) as all_locs_selected,
      bool_and(
        case
          when requested_qty > 0 then prepared_qty > 0
          else true
        end
      ) as all_lines_prepared,
      bool_and(
        case
          when shipped_qty > 0 then received_qty = shipped_qty
          else true
        end
      ) as all_received_or_short
    from item_metrics
  )
  select
    total_lines,
    pending_loc_selection_lines,
    dispatch_ready_lines,
    dispatch_blocked_lines,
    pending_receipt_lines,
    shortage_lines,
    received_lines,
    total_lines > 0 and pending_loc_selection_lines = 0 and coalesce(all_locs_selected, false) as can_start_prepare,
    total_lines > 0 and dispatch_ready_lines > 0 and dispatch_blocked_lines = 0 and coalesce(all_lines_prepared, false) as can_transit,
    total_lines > 0 and pending_receipt_lines = 0 and coalesce(all_received_or_short, false) as can_complete_receive,
    total_lines > 0 and received_lines > 0 and pending_receipt_lines > 0 as can_receive_partial
  from agg;
$$;


ALTER FUNCTION "public"."get_restock_request_operational_summary"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_site_cost_center"("p_site_id" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select cc.id
  from public.cost_centers cc
  where cc.site_id = p_site_id
    and cc.is_active is not false
  order by
    case cc.type
      when 'production_center' then 1
      when 'satellite' then 2
      when 'admin' then 3
      when 'logistics' then 4
      else 9
    end,
    cc.created_at asc
  limit 1;
$$;


