CREATE OR REPLACE FUNCTION "public"."has_effective_permission_v1"("p_permission_code" "text", "p_app_code" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_permission text := nullif(btrim(coalesce(p_permission_code, '')), '');
  v_app text := nullif(btrim(lower(coalesce(p_app_code, ''))), '');
  v_context record;
begin
  if v_permission is null then return false; end if;
  if v_app is null then v_app := split_part(v_permission, '.', 1); end if;

  select * into v_context from public.get_effective_context_v1(v_app) limit 1;
  if v_context.user_id is null or not coalesce(v_context.can_operate, false) then return false; end if;

  if v_context.source = 'simulation' then
    return (
      nullif(btrim(coalesce(v_context.effective_operational_role, '')), '') is not null
      and public.has_operational_role_permission(
        v_context.effective_operational_role, v_permission,
        v_context.site_id, v_context.area_id, v_app
      )
    ) or (
      nullif(btrim(coalesce(v_context.effective_administrative_role, '')), '') is not null
      and public.has_role_permission(
        v_context.effective_administrative_role, v_permission,
        v_context.site_id, v_context.area_id
      )
    );
  end if;

  if v_context.source = 'shared_device' then
    return nullif(btrim(coalesce(v_context.effective_operational_role, '')), '') is not null
      and public.has_operational_role_permission(
        v_context.effective_operational_role, v_permission,
        v_context.site_id, v_context.area_id, v_app
      );
  end if;

  return public.has_permission(v_permission, v_context.site_id, v_context.area_id)
    or public.has_operational_permission(v_permission, v_context.site_id, v_context.area_id, v_app);
end;
$$;


ALTER FUNCTION "public"."has_effective_permission_v1"("p_permission_code" "text", "p_app_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."has_effective_permission_v1"("p_permission_code" "text", "p_app_code" "text") IS 'Evalúa permisos administrativos u operativos contra el contexto efectivo común.';



CREATE OR REPLACE FUNCTION "public"."has_operational_permission"("p_permission_code" "text", "p_site_id" "uuid" DEFAULT NULL::"uuid", "p_area_id" "uuid" DEFAULT NULL::"uuid", "p_app_code" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_permission_code text := nullif(btrim(coalesce(p_permission_code, '')), '');
  v_app_code text := nullif(btrim(coalesce(p_app_code, '')), '');
  v_context record;
  v_site_id uuid;
  v_area_id uuid;
  v_allowed boolean := false;
begin
  if v_permission_code is null then
    return false;
  end if;

  if v_app_code is null then
    v_app_code := split_part(v_permission_code, '.', 1);
  end if;

  select *
    into v_context
  from public.get_operational_context(auth.uid(), p_site_id, v_app_code)
  limit 1;

  if v_context.employee_id is null then
    return false;
  end if;

  if coalesce(v_context.bypass_applied, false) then
    return true;
  end if;

  if not coalesce(v_context.can_operate, false) then
    return false;
  end if;

  if nullif(btrim(coalesce(v_context.active_operational_role, '')), '') is null then
    return false;
  end if;

  v_site_id := coalesce(p_site_id, v_context.active_site_id);
  v_area_id := coalesce(p_area_id, v_context.active_area_id);

  if v_site_id is not null and not exists (
    select 1
    from public.site_operational_roles sor
    where sor.site_id = v_site_id
      and sor.role_code = v_context.active_operational_role
      and coalesce(sor.is_active, true) = true
      and (
        sor.area_id is null
        or v_area_id is null
        or sor.area_id = v_area_id
      )
  ) then
    return false;
  end if;

  select exists (
    select 1
    from public.operational_role_permissions orp
    where orp.role_code = v_context.active_operational_role
      and orp.permission_code = v_permission_code
      and orp.is_allowed = true
      and (orp.site_id is null or orp.site_id = v_site_id)
      and (orp.area_id is null or orp.area_id = v_area_id)
      and (orp.area_kind is null or orp.area_kind = v_context.active_area_kind)
  )
  into v_allowed;

  return coalesce(v_allowed, false);
end;
$$;


ALTER FUNCTION "public"."has_operational_permission"("p_permission_code" "text", "p_site_id" "uuid", "p_area_id" "uuid", "p_app_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."has_operational_permission"("p_permission_code" "text", "p_site_id" "uuid", "p_area_id" "uuid", "p_app_code" "text") IS 'Evalua permisos usando el rol operativo del turno activo y public.operational_role_permissions. No reemplaza public.has_permission para configuracion administrativa.';



CREATE OR REPLACE FUNCTION "public"."has_operational_role_permission"("p_role_code" "text", "p_permission_code" "text", "p_site_id" "uuid" DEFAULT NULL::"uuid", "p_area_id" "uuid" DEFAULT NULL::"uuid", "p_app_code" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_role_code text := nullif(btrim(coalesce(p_role_code, '')), '');
  v_permission_code text := nullif(btrim(coalesce(p_permission_code, '')), '');
  v_app_code text := nullif(btrim(coalesce(p_app_code, '')), '');
  v_area_kind text;
  v_allowed boolean := false;
begin
  if v_role_code is null or v_permission_code is null then
    return false;
  end if;

  if v_app_code is null then
    v_app_code := split_part(v_permission_code, '.', 1);
  end if;

  if v_app_code is null or v_app_code = '' then
    return false;
  end if;

  if p_area_id is not null then
    select a.kind
      into v_area_kind
    from public.areas a
    where a.id = p_area_id
    limit 1;
  end if;

  if p_site_id is not null and not exists (
    select 1
    from public.site_operational_roles sor
    where sor.site_id = p_site_id
      and sor.role_code = v_role_code
      and coalesce(sor.is_active, true) = true
      and (
        sor.area_id is null
        or p_area_id is null
        or sor.area_id = p_area_id
      )
  ) then
    return false;
  end if;

  select exists (
    select 1
    from public.operational_role_permissions orp
    where orp.role_code = v_role_code
      and orp.permission_code = v_permission_code
      and orp.is_allowed = true
      and (orp.site_id is null or orp.site_id = p_site_id)
      and (orp.area_id is null or orp.area_id = p_area_id)
      and (orp.area_kind is null or orp.area_kind = v_area_kind)
  ) into v_allowed;

  return coalesce(v_allowed, false);
end;
$$;


ALTER FUNCTION "public"."has_operational_role_permission"("p_role_code" "text", "p_permission_code" "text", "p_site_id" "uuid", "p_area_id" "uuid", "p_app_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."has_operational_role_permission"("p_role_code" "text", "p_permission_code" "text", "p_site_id" "uuid", "p_area_id" "uuid", "p_app_code" "text") IS 'Evalua un role_code operativo explicito contra operational_role_permissions. Usado por shared devices: navigation_role se interpreta como operational_role. No reemplaza has_permission ni role_permissions.';



CREATE OR REPLACE FUNCTION "public"."has_permission"("p_permission_code" "text", "p_site_id" "uuid" DEFAULT NULL::"uuid", "p_area_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_employee_id uuid;
  v_role text;
  v_permission_id uuid;
  v_site_id uuid;
  v_area_id uuid;
  v_denied boolean;
  v_allowed boolean;
begin
  v_employee_id := auth.uid();

  if v_employee_id is null then
    return false;
  end if;

  select e.role
  into v_role
  from public.employees e
  where e.id = v_employee_id
    and e.is_active = true;

  if v_role is null then
    return false;
  end if;

  select ap.id
  into v_permission_id
  from public.app_permissions ap
  join public.apps a
    on a.id = ap.app_id
  where (a.code || '.' || ap.code) = p_permission_code
    and a.is_active = true
    and ap.is_active = true;

  if v_permission_id is null then
    return false;
  end if;

  v_site_id := coalesce(p_site_id, public.current_employee_site_id());
  v_area_id := p_area_id;

  select exists (
    select 1
    from public.employee_permissions ep
    where ep.employee_id = v_employee_id
      and ep.permission_id = v_permission_id
      and ep.is_allowed = false
      and public.permission_scope_matches(
        ep.scope_type,
        v_site_id,
        v_area_id,
        ep.scope_site_id,
        ep.scope_area_id,
        ep.scope_site_type,
        ep.scope_area_kind
      )
  )
  into v_denied;

  if v_denied then
    return false;
  end if;

  select exists (
    select 1
    from public.employee_permissions ep
    where ep.employee_id = v_employee_id
      and ep.permission_id = v_permission_id
      and ep.is_allowed = true
      and public.permission_scope_matches(
        ep.scope_type,
        v_site_id,
        v_area_id,
        ep.scope_site_id,
        ep.scope_area_id,
        ep.scope_site_type,
        ep.scope_area_kind
      )
  )
  into v_allowed;

  if v_allowed then
    return true;
  end if;

  select exists (
    select 1
    from public.role_permissions rp
    where rp.role = v_role
      and rp.permission_id = v_permission_id
      and rp.is_allowed = true
      and public.permission_scope_matches(
        rp.scope_type,
        v_site_id,
        v_area_id,
        rp.scope_site_id,
        rp.scope_area_id,
        rp.scope_site_type,
        rp.scope_area_kind
      )
  )
  into v_allowed;

  return coalesce(v_allowed, false);
end;
$$;


ALTER FUNCTION "public"."has_permission"("p_permission_code" "text", "p_site_id" "uuid", "p_area_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."has_role_permission"("p_role" "text", "p_permission_code" "text", "p_site_id" "uuid" DEFAULT NULL::"uuid", "p_area_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_permission_id uuid;
  v_site_id uuid;
  v_area_id uuid;
  v_allowed boolean := false;
begin
  if nullif(btrim(coalesce(p_role, '')), '') is null then
    return false;
  end if;

  select ap.id
    into v_permission_id
  from public.app_permissions ap
  join public.apps a on a.id = ap.app_id
  where (a.code || '.' || ap.code) = p_permission_code
    and a.is_active = true
    and ap.is_active = true
  limit 1;

  if v_permission_id is null then
    return false;
  end if;

  v_site_id := p_site_id;
  v_area_id := p_area_id;

  select exists (
    select 1
    from public.role_permissions rp
    where rp.role = btrim(p_role)
      and rp.permission_id = v_permission_id
      and rp.is_allowed = true
      and public.permission_scope_matches(
        rp.scope_type,
        v_site_id,
        v_area_id,
        rp.scope_site_id,
        rp.scope_area_id,
        rp.scope_site_type,
        rp.scope_area_kind
      )
  ) into v_allowed;

  return coalesce(v_allowed, false);
end;
$$;


ALTER FUNCTION "public"."has_role_permission"("p_role" "text", "p_permission_code" "text", "p_site_id" "uuid", "p_area_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."has_role_permission"("p_role" "text", "p_permission_code" "text", "p_site_id" "uuid", "p_area_id" "uuid") IS 'Evalua permisos de un rol operativo explicito. Complementa has_permission(), que usa employees.role.';



CREATE OR REPLACE FUNCTION "public"."haversine_m"("lat1" numeric, "lon1" numeric, "lat2" numeric, "lon2" numeric) RETURNS double precision
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'auth', 'storage', 'extensions'
    AS $$
  select 2 * 6371000::double precision *
    asin(
      sqrt(
        power(sin((((lat2::double precision - lat1::double precision) * pi()) / 180) / 2), 2) +
        cos((lat1::double precision * pi()) / 180) *
        cos((lat2::double precision * pi()) / 180) *
        power(sin((((lon2::double precision - lon1::double precision) * pi()) / 180) / 2), 2)
      )
    );
$$;


