CREATE OR REPLACE FUNCTION "public"."link_gift_order_delivery_address"("p_order_id" "uuid", "p_saved_address_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pass', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_saved_recipient_id uuid;
  v_existing_recipient_id uuid;
  v_address_snapshot jsonb;
begin
  if v_user_id is null then
    raise exception 'authentication_required';
  end if;

  select ogd.saved_recipient_id
  into v_saved_recipient_id
  from public.order_gift_details ogd
  join public.orders o on o.id = ogd.order_id
  where ogd.order_id = p_order_id
    and ogd.purchaser_id = v_user_id
    and o.client_id = v_user_id
    and o.is_gift = true
  for update of ogd;

  if not found then
    raise exception 'gift_order_not_found';
  end if;

  select da.gift_recipient_id,
         jsonb_strip_nulls(jsonb_build_object(
           'saved_address_id', da.id,
           'label', da.label,
           'receiver_label', da.receiver_label,
           'address', da.address,
           'latitude', da.latitude,
           'longitude', da.longitude,
           'address_type', da.address_type,
           'details', da.details,
           'delivery_option', da.delivery_option,
           'courier_instructions', da.courier_instructions
         ))
  into v_existing_recipient_id, v_address_snapshot
  from pass.delivery_addresses da
  where da.id = p_saved_address_id
    and da.user_id = v_user_id
  for update;

  if not found then
    raise exception 'gift_delivery_address_not_found';
  end if;

  if v_saved_recipient_id is not null
     and v_existing_recipient_id is not null
     and v_existing_recipient_id <> v_saved_recipient_id then
    raise exception 'gift_delivery_address_belongs_to_another_recipient';
  end if;

  if v_saved_recipient_id is not null and v_existing_recipient_id is null then
    update pass.delivery_addresses
    set gift_recipient_id = v_saved_recipient_id,
        last_used_at = now(),
        updated_at = now()
    where id = p_saved_address_id
      and user_id = v_user_id;
  else
    update pass.delivery_addresses
    set last_used_at = now(),
        updated_at = now()
    where id = p_saved_address_id
      and user_id = v_user_id;
  end if;

  update public.order_gift_details
  set saved_address_id = p_saved_address_id,
      updated_at = now()
  where order_id = p_order_id
    and purchaser_id = v_user_id;

  update public.orders
  set guest_info = jsonb_set(
        coalesce(guest_info, '{}'::jsonb),
        '{gift,delivery_address}',
        v_address_snapshot,
        true
      ),
      updated_at = now()
  where id = p_order_id
    and client_id = v_user_id;

  return jsonb_build_object(
    'order_id', p_order_id,
    'saved_address_id', p_saved_address_id,
    'saved_recipient_id', v_saved_recipient_id,
    'address_linked', true
  );
end;
$$;


ALTER FUNCTION "public"."link_gift_order_delivery_address"("p_order_id" "uuid", "p_saved_address_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_order_conversation_read"("p_conversation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_conversation public.order_conversations%rowtype;
  v_reader text;
begin
  if v_uid is null then
    raise exception 'authentication_required';
  end if;

  select *
  into v_conversation
  from public.order_conversations
  where id = p_conversation_id
  for update;

  if v_conversation.id is null then
    raise exception 'conversation_not_found';
  end if;

  if v_conversation.client_id = v_uid then
    update public.order_conversations
    set
      last_client_read_at = now(),
      status = case when status = 'waiting_client' then 'open' else status end,
      updated_at = now()
    where id = p_conversation_id;
    v_reader := 'client';
  elsif public.is_employee() and public.can_access_site(v_conversation.site_id) then
    update public.order_conversations
    set
      last_staff_read_at = now(),
      status = case when status = 'waiting_staff' then 'open' else status end,
      updated_at = now()
    where id = p_conversation_id;
    v_reader := 'staff';
  else
    raise exception 'forbidden';
  end if;

  return jsonb_build_object(
    'ok', true,
    'conversation_id', p_conversation_id,
    'reader', v_reader,
    'read_at', now()
  );
end;
$$;


ALTER FUNCTION "public"."mark_order_conversation_read"("p_conversation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mark_order_conversation_read"("p_conversation_id" "uuid") IS 'Marca una conversación de pedido como leída para el cliente o el staff autenticado.';



CREATE OR REPLACE FUNCTION "public"."mark_payment_transaction_status"("p_transaction_id" "uuid", "p_provider_reference" "text", "p_status" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'payments'
    AS $$
declare
  v_tx payments.transactions%rowtype;
  v_status text := lower(trim(coalesce(p_status, '')));
  v_order_status text;
  v_payment_status text;
begin
  if p_transaction_id is null then
    raise exception 'transaction_required';
  end if;

  if v_status not in ('approved', 'rejected', 'cancelled', 'error', 'refunded') then
    raise exception 'invalid_payment_status';
  end if;

  select *
  into v_tx
  from payments.transactions
  where id = p_transaction_id
  for update;

  if v_tx.id is null then
    raise exception 'transaction_not_found';
  end if;

  if v_status = 'approved' then
    v_order_status := 'confirmed';
    v_payment_status := 'paid';
  elsif v_status = 'refunded' then
    v_order_status := 'cancelled';
    v_payment_status := 'refunded';
  else
    v_order_status := 'cancelled';
    v_payment_status := 'failed';
  end if;

  update payments.transactions
  set
    status = v_status,
    provider_reference = coalesce(nullif(trim(coalesce(p_provider_reference, '')), ''), provider_reference),
    raw_response = coalesce(p_payload, '{}'::jsonb),
    approved_at = case when v_status = 'approved' then coalesce(approved_at, now()) else approved_at end,
    rejected_at = case when v_status in ('rejected', 'cancelled', 'error') then coalesce(rejected_at, now()) else rejected_at end,
    updated_at = now()
  where id = v_tx.id;

  update public.orders
  set
    payment_status = v_payment_status,
    status = case
      when status = 'delivered' then status
      when status = 'cancelled' then status
      else v_order_status
    end,
    cancelled_at = case
      when v_order_status = 'cancelled' and status not in ('delivered', 'cancelled')
        then coalesce(cancelled_at, now())
      else cancelled_at
    end,
    confirmed_at = case
      when v_order_status = 'confirmed'
        then coalesce(confirmed_at, now())
      else confirmed_at
    end,
    payment_reference = coalesce(nullif(trim(coalesce(p_provider_reference, '')), ''), payment_reference),
    payment_provider = coalesce(payment_provider, v_tx.provider),
    updated_at = now()
  where id = v_tx.order_id;

  return jsonb_build_object(
    'ok', true,
    'transaction_id', v_tx.id,
    'order_id', v_tx.order_id,
    'status', v_status,
    'order_status', v_order_status,
    'payment_status', v_payment_status
  );
end;
$$;


ALTER FUNCTION "public"."mark_payment_transaction_status"("p_transaction_id" "uuid", "p_provider_reference" "text", "p_status" "text", "p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mark_payment_transaction_status"("p_transaction_id" "uuid", "p_provider_reference" "text", "p_status" "text", "p_payload" "jsonb") IS 'Aplica resultado de pago y sincroniza estado de orden.';



