CREATE OR REPLACE FUNCTION "public"."mark_restock_request_in_transit"("p_request_id" "uuid") RETURNS "public"."restock_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_employee_id uuid := auth.uid();
  v_employee record;
  v_request public.restock_requests%rowtype;
  v_latest_log record;
  v_operational_role text;
  v_context_site_id uuid;
  v_allowed boolean := false;
begin
  if v_employee_id is null then
    raise exception 'not authenticated';
  end if;

  select e.id, e.role, e.is_active
    into v_employee
  from public.employees e
  where e.id = v_employee_id
    and e.is_active = true;

  if v_employee.id is null then
    raise exception 'employee not active';
  end if;

  select *
    into v_request
  from public.restock_requests r
  where r.id = p_request_id
  for update;

  if v_request.id is null then
    raise exception 'restock_request not found: %', p_request_id;
  end if;

  if v_request.from_site_id is null then
    raise exception 'from_site_id requerido para marcar en transito';
  end if;

  if v_request.cancelled_at is not null or v_request.closed_at is not null or v_request.received_at is not null then
    raise exception 'remision no se puede marcar en transito por su estado actual';
  end if;

  if v_request.in_transit_at is not null then
    return v_request;
  end if;

  -- Permiso por rol base del empleado.
  v_allowed := public.has_permission(
    'nexo.inventory.remissions.transit',
    v_request.from_site_id,
    null
  );

  -- Permiso por rol operativo activo del turno/check-in.
  if not v_allowed then
    select
      al.action,
      al.site_id as log_site_id,
      al.device_info,
      al.shift_id,
      s.site_id as shift_site_id,
      s.operational_role
    into v_latest_log
    from public.attendance_logs al
    left join public.employee_shifts s on s.id = al.shift_id
    where al.employee_id = v_employee_id
    order by al.occurred_at desc, al.created_at desc
    limit 1;

    if v_latest_log.action = 'check_in' then
      v_operational_role := coalesce(
        nullif(v_latest_log.device_info #>> '{operationalContext,operationalRole}', ''),
        nullif(v_latest_log.device_info #>> '{operationalContext,operational_role}', ''),
        nullif(v_latest_log.operational_role, '')
      );

      v_context_site_id := coalesce(
        nullif(v_latest_log.device_info #>> '{operationalContext,siteId}', '')::uuid,
        nullif(v_latest_log.device_info #>> '{operationalContext,site_id}', '')::uuid,
        v_latest_log.shift_site_id,
        v_latest_log.log_site_id
      );

      if v_context_site_id = v_request.from_site_id then
        v_allowed := public.has_role_permission(
          v_operational_role,
          'nexo.inventory.remissions.transit',
          v_request.from_site_id,
          null
        );
      end if;
    end if;
  end if;

  if not v_allowed then
    raise exception 'permission denied: remissions.transit';
  end if;

  update public.restock_requests r
  set
    in_transit_at = now(),
    in_transit_by = v_employee_id,
    status = 'in_transit',
    status_updated_at = now()
  where r.id = p_request_id
  returning * into v_request;

  return v_request;
end;
$$;


ALTER FUNCTION "public"."mark_restock_request_in_transit"("p_request_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mark_restock_request_in_transit"("p_request_id" "uuid") IS 'Permite a conductor marcar una remision como en transito desde NEXO, validando rol base u operativo activo.';



CREATE OR REPLACE FUNCTION "public"."nexo_kiosk_withdraw_workers"("p_source_location_id" "uuid") RETURNS TABLE("employee_id" "uuid", "label" "text", "role" "text", "destination_label" "text", "has_destination" boolean)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with source as (
    select il.id, il.site_id
    from public.inventory_locations il
    where il.id = p_source_location_id
      and il.is_active = true
    limit 1
  ),
  allowed as (
    select s.site_id
    from source s
    where public.has_permission('nexo.inventory.withdraw', s.site_id)
       or public.has_permission('nexo.inventory.transfers', s.site_id)
  ),
  site_workers as (
    select e.id, e.full_name, e.alias, e.role
    from allowed a
    join public.employee_sites es
      on es.site_id = a.site_id
     and es.is_active = true
    join public.employees e
      on e.id = es.employee_id
     and coalesce(e.is_active, true) = true

    union

    select e.id, e.full_name, e.alias, e.role
    from allowed a
    join public.employees e
      on e.site_id = a.site_id
     and coalesce(e.is_active, true) = true
  ),
  assignments as (
    select distinct on (a.employee_id)
      a.employee_id,
      a.location_id,
      coalesce(nullif(il.description, ''), nullif(il.zone, ''), nullif(il.code, ''), il.id::text) as destination_label
    from allowed src
    join public.employee_inventory_location_assignments a
      on a.site_id = src.site_id
     and a.purpose = 'kiosk_withdraw'
     and a.is_active = true
    join public.inventory_locations il
      on il.id = a.location_id
     and il.is_active = true
    where a.location_id <> p_source_location_id
    order by a.employee_id, a.updated_at desc
  )
  select
    sw.id as employee_id,
    coalesce(nullif(sw.alias, ''), nullif(sw.full_name, ''), sw.id::text) as label,
    sw.role,
    coalesce(a.destination_label, 'Sin destino (descuento)') as destination_label,
    (a.location_id is not null) as has_destination
  from site_workers sw
  left join assignments a on a.employee_id = sw.id
  where sw.id <> auth.uid()
  order by coalesce(nullif(sw.alias, ''), nullif(sw.full_name, ''), sw.id::text);
$$;


ALTER FUNCTION "public"."nexo_kiosk_withdraw_workers"("p_source_location_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."nexo_kiosk_withdraw_workers"("p_source_location_id" "uuid") IS 'Returns active workers for a kiosk source LOC site, including their kiosk withdrawal destination when configured.';



CREATE OR REPLACE FUNCTION "public"."normalize_procurement_receipt_costs"("p_input_unit_cost" numeric, "p_tax_included" boolean DEFAULT false, "p_tax_rate" numeric DEFAULT 0, "p_conversion_factor_to_stock" numeric DEFAULT 1, "p_input_qty" numeric DEFAULT 1) RETURNS TABLE("cost_input_mode" "text", "net_unit_cost" numeric, "gross_unit_cost" numeric, "tax_unit_amount" numeric, "stock_unit_cost" numeric, "net_total_cost" numeric, "gross_total_cost" numeric, "tax_amount" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  with safe as (
    select
      greatest(coalesce(p_input_unit_cost, 0), 0)::numeric as input_cost,
      coalesce(p_tax_included, false) as tax_included,
      greatest(coalesce(p_tax_rate, 0), 0)::numeric as tax_rate,
      greatest(coalesce(p_conversion_factor_to_stock, 1), 0.000001)::numeric as factor,
      greatest(coalesce(p_input_qty, 0), 0)::numeric as qty
  ),
  normalized as (
    select
      case when tax_included then 'gross' else 'net' end as cost_input_mode,
      case
        when tax_included and tax_rate > 0 then input_cost / (1 + (tax_rate / 100))
        else input_cost
      end as net_unit_cost,
      case
        when tax_included then input_cost
        else input_cost * (1 + (tax_rate / 100))
      end as gross_unit_cost,
      factor,
      qty
    from safe
  )
  select
    cost_input_mode,
    round(net_unit_cost, 6) as net_unit_cost,
    round(gross_unit_cost, 6) as gross_unit_cost,
    round(gross_unit_cost - net_unit_cost, 6) as tax_unit_amount,
    round(net_unit_cost / factor, 6) as stock_unit_cost,
    round(net_unit_cost * qty, 6) as net_total_cost,
    round(gross_unit_cost * qty, 6) as gross_total_cost,
    round((gross_unit_cost - net_unit_cost) * qty, 6) as tax_amount
  from normalized;
$$;


ALTER FUNCTION "public"."normalize_procurement_receipt_costs"("p_input_unit_cost" numeric, "p_tax_included" boolean, "p_tax_rate" numeric, "p_conversion_factor_to_stock" numeric, "p_input_qty" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."normalize_procurement_receipt_costs"("p_input_unit_cost" numeric, "p_tax_included" boolean, "p_tax_rate" numeric, "p_conversion_factor_to_stock" numeric, "p_input_qty" numeric) IS 'Normalizes receipt line cost into net/gross/tax/stock-unit values for ORIGO purchases.';



CREATE OR REPLACE FUNCTION "public"."notify_shift_published"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  fn_url text;
  secret text;
  payload jsonb;
begin
  -- Solo notificar en el momento de publicar:
  -- INSERT con published_at ya puesto, o UPDATE donde published_at pasaba de null a no null.
  if new.published_at is null then
    return new;
  end if;
  if tg_op = 'UPDATE' and old.published_at is not null then
    return new;  -- ya estaba publicado; no notificar por ediciones posteriores
  end if;

  select coalesce(value #>> '{}', '') into fn_url from public.app_config where key = 'shift_notify_function_url' limit 1;
  if trim(fn_url) = '' then
    return new;
  end if;

  select coalesce(value #>> '{}', '') into secret from public.app_config where key = 'shift_notify_internal_secret' limit 1;
  if trim(secret) = '' then
    return new;
  end if;

  payload := jsonb_build_object(
    'employee_id', new.employee_id,
    'shift_id', new.id,
    'shift_date', new.shift_date,
    'start_time', coalesce(nullif(trim(new.start_time), ''), '08:00'),
    'end_time', coalesce(nullif(trim(new.end_time), ''), '14:00'),
    'type', 'published'
  );

  perform net.http_post(
    trim(fn_url),
    payload,
    '{}'::jsonb,
    jsonb_build_object(
      'Content-Type', 'application/json',
      'x-internal-secret', trim(secret)
    )
  );

  return new;
exception
  when others then
    return new;
end;
$$;


ALTER FUNCTION "public"."notify_shift_published"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."notify_shift_published"() IS 'Notifica al empleado solo cuando se publica el turno (published_at pasa de null a valor). No en borrador ni al editar ya publicado.';



CREATE OR REPLACE FUNCTION "public"."notify_support_message_inserted"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  fn_url text;
  secret text;
begin
  select coalesce(value #>> '{}', '')
  into fn_url
  from public.app_config
  where key = 'support_message_notify_function_url'
  limit 1;

  select coalesce(value #>> '{}', '')
  into secret
  from public.app_config
  where key = 'shift_notify_internal_secret'
  limit 1;

  if trim(fn_url) = '' or trim(secret) = '' then
    return new;
  end if;

  perform net.http_post(
    trim(fn_url),
    jsonb_build_object(
      'ticket_id', new.ticket_id,
      'message_id', new.id,
      'author_id', new.author_id,
      'body', new.body
    ),
    '{}'::jsonb,
    jsonb_build_object(
      'Content-Type', 'application/json',
      'x-internal-secret', trim(secret)
    )
  );

  return new;
exception
  when others then
    return new;
end;
$$;


ALTER FUNCTION "public"."notify_support_message_inserted"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."notify_support_message_inserted"() IS 'Llama la Edge Function support-message-notify cuando se crea un mensaje de soporte.';



CREATE OR REPLACE FUNCTION "public"."numera_current_period_summary"() RETURNS TABLE("period_id" "uuid", "period_month" "date", "period_label" "text", "cost_centers" bigint, "budget_amount" numeric, "expected_revenue" numeric, "actual_expenses" numeric, "fixed_expenses" numeric, "variable_expenses" numeric, "one_time_expenses" numeric, "break_even_revenue" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'auth', 'storage', 'extensions'
    AS $$
  with current_period as (
    select id
    from public.numera_periods
    where period_month = date_trunc('month', current_date)::date
    order by period_month desc
    limit 1
  )
  select
    s.period_id,
    s.period_month,
    s.period_label,
    count(s.cost_center_id) as cost_centers,
    coalesce(sum(s.budget_amount), 0) as budget_amount,
    coalesce(sum(s.expected_revenue), 0) as expected_revenue,
    coalesce(sum(s.actual_expenses), 0) as actual_expenses,
    coalesce(sum(s.fixed_expenses), 0) as fixed_expenses,
    coalesce(sum(s.variable_expenses), 0) as variable_expenses,
    coalesce(sum(s.one_time_expenses), 0) as one_time_expenses,
    coalesce(sum(s.break_even_revenue), 0) as break_even_revenue
  from public.numera_cost_center_monthly_summary s
  join current_period cp on cp.id = s.period_id
  group by s.period_id, s.period_month, s.period_label;
$$;


ALTER FUNCTION "public"."numera_current_period_summary"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."origo_mark_inventory_entry_corrected"("p_original_entry_id" "uuid", "p_replacement_entry_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_original public.inventory_entries%rowtype;
  v_replacement public.inventory_entries%rowtype;
  v_updated_count integer := 0;
begin
  if v_user_id is null then
    raise exception 'Usuario no autenticado.';
  end if;

  if p_original_entry_id is null or p_replacement_entry_id is null then
    raise exception 'Recepción original y recepción corregida son obligatorias.';
  end if;

  if p_original_entry_id = p_replacement_entry_id then
    raise exception 'La recepción original y la recepción corregida no pueden ser la misma.';
  end if;

  select *
  into v_original
  from public.inventory_entries
  where id = p_original_entry_id
  for update;

  if not found then
    raise exception 'Recepción original no encontrada.';
  end if;

  select *
  into v_replacement
  from public.inventory_entries
  where id = p_replacement_entry_id
  for update;

  if not found then
    raise exception 'Recepción corregida no encontrada.';
  end if;

  if v_original.site_id is distinct from v_replacement.site_id then
    raise exception 'La recepción corregida no pertenece a la misma sede.';
  end if;

  if coalesce(v_original.status, '') <> 'reversed' then
    raise exception 'La recepción original debe estar reversada antes de marcarla como corregida.';
  end if;

  if coalesce(v_replacement.status, '') <> 'received' then
    raise exception 'La recepción corregida debe quedar en estado Recibida.';
  end if;

  if not public.has_permission('origo.procurement.receipts'::text, v_original.site_id, null) then
    raise exception 'No tienes permiso para cerrar esta corrección.';
  end if;

  update public.inventory_entries
  set status = 'corrected',
      updated_at = now()
  where id = p_original_entry_id;

  update public.inventory_entry_corrections
  set correction_type = 'edit',
      replacement_entry_id = p_replacement_entry_id
  where entry_id = p_original_entry_id
    and replacement_entry_id is null;

  get diagnostics v_updated_count = row_count;

  if v_updated_count <= 0 then
    raise exception 'No se encontró la auditoría de reversión para enlazar la corrección.';
  end if;
end;
$$;


ALTER FUNCTION "public"."origo_mark_inventory_entry_corrected"("p_original_entry_id" "uuid", "p_replacement_entry_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."origo_reverse_inventory_entry"("p_entry_id" "uuid", "p_comment" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_comment text := btrim(coalesce(p_comment, ''));
  v_now timestamptz := now();
  v_entry public.inventory_entries%rowtype;
  v_before jsonb;
  v_after jsonb;
  v_item_count integer := 0;
  v_current_qty numeric := 0;
  v_all_received boolean := false;
  v_event record;
  v_row record;
begin
  if v_user_id is null then
    raise exception 'Usuario no autenticado.';
  end if;

  if v_comment = '' then
    raise exception 'El motivo de reversión es obligatorio.';
  end if;

  select *
  into v_entry
  from public.inventory_entries
  where id = p_entry_id
  for update;

  if not found then
    raise exception 'Recepción no encontrada.';
  end if;

  if not has_permission('origo.procurement.receipts'::text, v_entry.site_id, null) then
    raise exception 'No tienes permiso para reversar esta recepción.';
  end if;

  if coalesce(v_entry.status, '') <> 'received' then
    raise exception 'Solo se pueden reversar recepciones en estado recibida.';
  end if;

  select count(*)
  into v_item_count
  from public.inventory_entry_items
  where entry_id = p_entry_id;

  if v_item_count <= 0 then
    raise exception 'La recepción no tiene ítems para reversar.';
  end if;

  select jsonb_build_object(
    'entry', to_jsonb(v_entry),
    'items', coalesce((
      select jsonb_agg(to_jsonb(ii) order by ii.created_at, ii.id)
      from public.inventory_entry_items ii
      where ii.entry_id = p_entry_id
    ), '[]'::jsonb),
    'cost_events', coalesce((
      select jsonb_agg(to_jsonb(ce) order by ce.created_at, ce.id)
      from public.product_cost_events ce
      where ce.source_entry_id = p_entry_id
    ), '[]'::jsonb)
  )
  into v_before;

  for v_row in
    select product_id, sum(quantity_received) as qty
    from public.inventory_entry_items
    where entry_id = p_entry_id
    group by product_id
  loop
    select current_qty
    into v_current_qty
    from public.inventory_stock_by_site
    where site_id = v_entry.site_id
      and product_id = v_row.product_id
    for update;

    if coalesce(v_current_qty, 0) < coalesce(v_row.qty, 0) then
      raise exception 'No se puede reversar: el stock de sede del producto % es menor que la cantidad recibida.', v_row.product_id;
    end if;
  end loop;

  for v_row in
    select location_id, product_id, sum(quantity_received) as qty
    from public.inventory_entry_items
    where entry_id = p_entry_id
      and location_id is not null
    group by location_id, product_id
  loop
    select current_qty
    into v_current_qty
    from public.inventory_stock_by_location
    where location_id = v_row.location_id
      and product_id = v_row.product_id
    for update;

    if coalesce(v_current_qty, 0) < coalesce(v_row.qty, 0) then
      raise exception 'No se puede reversar: el stock del LOC para el producto % es menor que la cantidad recibida.', v_row.product_id;
    end if;
  end loop;

  for v_event in
    select *
    from public.product_cost_events
    where source_entry_id = p_entry_id
    for update
  loop
    if exists (
      select 1
      from public.product_cost_events later
      where later.product_id = v_event.product_id
        and later.created_at > v_event.created_at
    ) then
      raise exception 'No se puede reversar automáticamente: hay eventos de costo posteriores para el producto %. Requiere recálculo de costos.', v_event.product_id;
    end if;
  end loop;

  insert into public.inventory_movements (
    site_id,
    product_id,
    location_id,
    location_position_id,
    movement_type,
    quantity,
    note,
    unit_cost,
    created_by,
    input_qty,
    input_unit_code,
    conversion_factor_to_stock,
    stock_unit_code,
    stock_unit_cost,
    line_total_cost,
    input_uom_profile_id
  )
  select
    v_entry.site_id,
    ii.product_id,
    ii.location_id,
    ii.location_position_id,
    'receipt_reversal',
    -ii.quantity_received,
    'Reversión recepción ORIGO ' || p_entry_id::text || ': ' || v_comment,
    ii.stock_unit_cost,
    v_user_id,
    -coalesce(ii.input_qty, ii.quantity_received),
    ii.input_unit_code,
    ii.conversion_factor_to_stock,
    ii.stock_unit_code,
    ii.stock_unit_cost,
    -coalesce(ii.line_total_cost, 0),
    ii.input_uom_profile_id
  from public.inventory_entry_items ii
  where ii.entry_id = p_entry_id;

  for v_row in
    select product_id, sum(quantity_received) as qty
    from public.inventory_entry_items
    where entry_id = p_entry_id
    group by product_id
  loop
    update public.inventory_stock_by_site
    set current_qty = round(current_qty - v_row.qty, 6),
        updated_at = v_now
    where site_id = v_entry.site_id
      and product_id = v_row.product_id;
  end loop;

  for v_row in
    select location_id, product_id, sum(quantity_received) as qty
    from public.inventory_entry_items
    where entry_id = p_entry_id
      and location_id is not null
    group by location_id, product_id
  loop
    perform public.upsert_inventory_stock_by_location(
      p_location_id := v_row.location_id,
      p_product_id := v_row.product_id,
      p_delta := -v_row.qty
    );
  end loop;

  for v_row in
    select purchase_order_item_id, sum(coalesce(input_qty, quantity_received)) as qty
    from public.inventory_entry_items
    where entry_id = p_entry_id
      and purchase_order_item_id is not null
    group by purchase_order_item_id
  loop
    update public.purchase_order_items
    set quantity_received = greatest(0, coalesce(quantity_received, 0) - v_row.qty)
    where id = v_row.purchase_order_item_id;
  end loop;

  if v_entry.purchase_order_id is not null then
    select coalesce(
      bool_and(quantity_ordered > 0 and coalesce(quantity_received, 0) >= quantity_ordered),
      false
    )
    into v_all_received
    from public.purchase_order_items
    where purchase_order_id = v_entry.purchase_order_id;

    update public.purchase_orders
    set status = case when v_all_received then 'received' else 'sent' end,
        received_at = case when v_all_received then received_at else null end
    where id = v_entry.purchase_order_id;
  end if;

  for v_event in
    select *
    from public.product_cost_events
    where source_entry_id = p_entry_id
    order by created_at, id
  loop
    update public.products
    set cost = v_event.cost_before,
        updated_at = v_now
    where id = v_event.product_id;

    insert into public.product_cost_events (
      product_id,
      site_id,
      source,
      source_entry_id,
      qty_before,
      qty_in,
      cost_before,
      cost_in,
      cost_after,
      basis,
      created_by
    )
    values (
      v_event.product_id,
      v_event.site_id,
      'entry_reversal',
      p_entry_id,
      coalesce(v_event.qty_before, 0) + coalesce(v_event.qty_in, 0),
      -coalesce(v_event.qty_in, 0),
      v_event.cost_after,
      v_event.cost_in,
      v_event.cost_before,
      v_event.basis,
      v_user_id
    );
  end loop;

  update public.inventory_entries
  set status = 'reversed',
      notes = btrim(concat_ws(E'\n', notes, 'Reversión ' || to_char(v_now, 'YYYY-MM-DD HH24:MI:SS TZ') || ': ' || v_comment)),
      updated_at = v_now
  where id = p_entry_id;

  select jsonb_build_object(
    'entry', to_jsonb(e),
    'items', coalesce((
      select jsonb_agg(to_jsonb(ii) order by ii.created_at, ii.id)
      from public.inventory_entry_items ii
      where ii.entry_id = p_entry_id
    ), '[]'::jsonb),
    'reversal_movements', coalesce((
      select jsonb_agg(to_jsonb(m) order by m.created_at, m.id)
      from public.inventory_movements m
      where m.note = 'Reversión recepción ORIGO ' || p_entry_id::text || ': ' || v_comment
    ), '[]'::jsonb)
  )
  into v_after
  from public.inventory_entries e
  where e.id = p_entry_id;

  insert into public.inventory_entry_corrections (
    entry_id,
    correction_type,
    comment,
    before_snapshot,
    after_snapshot,
    created_by
  )
  values (
    p_entry_id,
    'reverse',
    v_comment,
    v_before,
    v_after,
    v_user_id
  );
end;
$$;


ALTER FUNCTION "public"."origo_reverse_inventory_entry"("p_entry_id" "uuid", "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."override_order_delivery_confirmation"("p_order_id" "uuid", "p_site_id" "uuid", "p_reason" "text", "p_comment" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_order public.orders%rowtype;
  v_session public.order_delivery_sessions%rowtype;
  v_reason text := lower(trim(coalesce(p_reason, '')));
  v_comment text := trim(coalesce(p_comment, ''));
  v_now timestamptz := now();
  v_event_id uuid;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  if not public.has_permission('pulso.delivery.override', p_site_id, null) then
    raise exception 'permission_denied';
  end if;
  if v_reason not in ('client_without_pin','authorized_third_party','technical_failure','other') then
    raise exception 'invalid_override_reason';
  end if;
  if length(v_comment) < 8 then
    raise exception 'override_comment_required';
  end if;

  select * into v_order
  from public.orders
  where id = p_order_id and site_id = p_site_id
  for update;

  if v_order.id is null then raise exception 'order_not_found'; end if;
  if v_order.fulfillment_type <> 'delivery' then raise exception 'delivery_required'; end if;
  if v_order.status in ('delivered','cancelled') then raise exception 'order_closed'; end if;
  if v_order.status not in ('on_the_way','in_transit','ready_for_dispatch') then
    raise exception 'invalid_order_state';
  end if;

  select * into v_session
  from public.order_delivery_sessions
  where order_id = v_order.id
  for update;

  if v_session.id is null then
    raise exception 'delivery_session_not_found';
  end if;

  update public.order_delivery_sessions
  set status = 'confirmed',
      confirmed_at = v_now,
      confirmed_by = 'staff_override',
      issue_code = coalesce(issue_code, 'manual_override'),
      issue_notes = concat_ws(' | ', nullif(issue_notes, ''), v_reason || ': ' || v_comment),
      updated_at = v_now,
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'override_by', v_uid,
        'override_reason', v_reason,
        'override_comment', v_comment,
        'override_at', v_now
      ) || coalesce(p_metadata, '{}'::jsonb)
  where id = v_session.id;

  update public.orders
  set status = 'delivered',
      dispatch_status = 'delivered',
      delivered_at = coalesce(delivered_at, v_now),
      updated_at = v_now
  where id = v_order.id;

  insert into public.order_status_events (
    order_id, site_id, changed_by, actor_type, operation,
    from_status, to_status, from_dispatch_status, to_dispatch_status,
    dispatch_partner, dispatch_reference, metadata
  ) values (
    v_order.id, v_order.site_id, v_uid, 'staff', 'override_delivery_confirmation',
    v_order.status, 'delivered', v_order.dispatch_status, 'delivered',
    v_order.dispatch_partner, v_order.dispatch_reference,
    jsonb_build_object(
      'delivery_session_id', v_session.id,
      'override_reason', v_reason,
      'override_comment', v_comment,
      'confirmation_method', 'staff_override'
    ) || coalesce(p_metadata, '{}'::jsonb)
  ) returning id into v_event_id;

  return jsonb_build_object(
    'ok', true,
    'order_id', v_order.id,
    'status', 'delivered',
    'dispatch_status', 'delivered',
    'event_id', v_event_id,
    'confirmed_at', v_now
  );
end;
$$;


ALTER FUNCTION "public"."override_order_delivery_confirmation"("p_order_id" "uuid", "p_site_id" "uuid", "p_reason" "text", "p_comment" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."permission_scope_matches"("p_scope_type" "public"."permission_scope_type", "p_context_site_id" "uuid", "p_context_area_id" "uuid", "p_scope_site_id" "uuid", "p_scope_area_id" "uuid", "p_scope_site_type" "public"."site_type", "p_scope_area_kind" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_site_type public.site_type;
  v_area_kind text;
begin
  if p_scope_type = 'global' then
    return true;
  end if;

  if p_scope_type = 'site' then
    if p_context_site_id is null then
      return false;
    end if;
    if p_scope_site_id is not null and p_scope_site_id <> p_context_site_id then
      return false;
    end if;
    return public.can_access_site(p_context_site_id);
  end if;

  if p_scope_type = 'site_type' then
    if p_context_site_id is null then
      return false;
    end if;
    if not public.can_access_site(p_context_site_id) then
      return false;
    end if;
    select site_type into v_site_type from public.sites where id = p_context_site_id;
    return v_site_type = p_scope_site_type;
  end if;

  if p_scope_type = 'area' then
    if p_context_area_id is null then
      return false;
    end if;
    if p_scope_area_id is not null and p_scope_area_id <> p_context_area_id then
      return false;
    end if;
    return public.can_access_area(p_context_area_id);
  end if;

  if p_scope_type = 'area_kind' then
    if p_context_area_id is null then
      return false;
    end if;
    if not public.can_access_area(p_context_area_id) then
      return false;
    end if;
    select kind into v_area_kind from public.areas where id = p_context_area_id;
    return v_area_kind = p_scope_area_kind;
  end if;

  return false;
end;
$$;


ALTER FUNCTION "public"."permission_scope_matches"("p_scope_type" "public"."permission_scope_type", "p_context_site_id" "uuid", "p_context_area_id" "uuid", "p_scope_site_id" "uuid", "p_scope_area_id" "uuid", "p_scope_site_type" "public"."site_type", "p_scope_area_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_hidden_site_employee_assignment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_site_name text;
  v_visibility text;
begin
  select name, coalesce(operational_visibility, 'operational')
    into v_site_name, v_visibility
  from public.sites
  where id = new.site_id;

  if v_visibility <> 'operational' then
    raise exception 'No se puede asignar el site tecnico/oculto % (%) a employee_sites',
      coalesce(v_site_name, new.site_id::text),
      new.site_id;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."prevent_hidden_site_employee_assignment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_used_request_policy_semantic_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'storage', 'extensions'
    AS $$
begin
  if exists (
    select 1
    from public.restock_request_items item
    where item.request_policy_id = old.id
    limit 1
  ) and (
    new.product_id is distinct from old.product_id
    or new.request_unit_code is distinct from old.request_unit_code
    or new.base_unit_code is distinct from old.base_unit_code
    or new.base_qty_per_request_unit is distinct from old.base_qty_per_request_unit
    or new.constraint_mode is distinct from old.constraint_mode
    or new.minimum_request_qty is distinct from old.minimum_request_qty
    or new.request_step_qty is distinct from old.request_step_qty
    or new.allow_fraction is distinct from old.allow_fraction
    or new.policy_kind is distinct from old.policy_kind
    or new.physical_uom_profile_id is distinct from old.physical_uom_profile_id
  ) then
    raise exception using
      errcode = '23514',
      message = 'REQUEST_POLICY_VERSION_REQUIRED',
      detail = 'La política ya fue utilizada. Desactívala y crea una nueva versión para cambiar su significado.';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."prevent_used_request_policy_semantic_update"() OWNER TO "postgres";


