CREATE OR REPLACE FUNCTION "public"."process_order_payment"("p_order_id" "uuid", "p_site_id" "uuid", "p_payment_method" "text", "p_payment_reference" "text" DEFAULT NULL::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pos'
    AS $$
declare
  v_order record;
  v_loyalty_points int := 0;
begin
  select * into v_order
  from public.orders
  where id = p_order_id;

  if not found then
    return json_build_object('success', false, 'error', 'Orden no encontrada');
  end if;

  v_loyalty_points := floor(v_order.total_amount / 1000);

  update public.orders
  set status = 'completed',
      payment_status = 'paid',
      loyalty_processed = true,
      loyalty_points_awarded = v_loyalty_points,
      updated_at = now()
  where id = p_order_id;

  insert into pos.pos_payments (
    order_id,
    payment_method,
    amount,
    reference,
    created_at
  ) values (
    p_order_id,
    p_payment_method,
    v_order.total_amount,
    p_payment_reference,
    now()
  );

  if v_order.client_id is not null and v_loyalty_points > 0 then
    update public.users
    set loyalty_points = coalesce(loyalty_points, 0) + v_loyalty_points,
        updated_at = now()
    where id = v_order.client_id;

    insert into public.loyalty_transactions (
      user_id,
      order_id,
      kind,
      points_delta,
      description,
      created_at
    ) values (
      v_order.client_id,
      p_order_id,
      'earn',
      v_loyalty_points,
      'Order paid: loyalty earning',
      now()
    );
  end if;

  return json_build_object(
    'success', true,
    'order_id', p_order_id,
    'loyalty_points_awarded', v_loyalty_points
  );
end;
$$;


ALTER FUNCTION "public"."process_order_payment"("p_order_id" "uuid", "p_site_id" "uuid", "p_payment_method" "text", "p_payment_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."promote_app_screen_to_navigation"("p_registry_id" "uuid", "p_group_key" "text", "p_group_label" "text", "p_group_order" integer, "p_sort_order" integer DEFAULT 100, "p_is_active" boolean DEFAULT true) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_screen record;
  v_item_id uuid;
  v_group_key text := nullif(btrim(coalesce(p_group_key, '')), '');
  v_group_label text := nullif(btrim(coalesce(p_group_label, '')), '');
begin
  if not (
    has_permission('viso.staff.permissions.manage')
    or has_permission('viso.app_navigation.manage')
    or has_permission('staff.permissions.manage')
    or is_owner()
    or is_global_manager()
    or current_user = 'service_role'
    or current_setting('request.jwt.claim.role', true) = 'service_role'
  ) then
    raise exception 'permission_denied_app_navigation_manage';
  end if;

  select *
  into v_screen
  from public.app_screen_registry
  where id = p_registry_id
    and is_available = true
    and is_ignored = false;

  if not found then
    raise exception 'screen_not_found_or_not_available';
  end if;

  if v_group_key is null then
    v_group_key := coalesce(v_screen.suggested_group_key, 'configuration');
  end if;

  if v_group_label is null then
    v_group_label := coalesce(v_screen.suggested_group_label, 'Configuracion');
  end if;

  insert into public.app_navigation_items (
    app_code,
    group_key,
    group_label,
    group_order,
    item_key,
    label,
    description,
    href,
    icon,
    required_permission_code,
    sort_order,
    is_active
  )
  values (
    v_screen.app_code,
    v_group_key,
    v_group_label,
    p_group_order,
    v_screen.item_key,
    v_screen.label,
    v_screen.description,
    v_screen.href,
    coalesce(v_screen.icon, 'settings'),
    v_screen.required_permission_code,
    p_sort_order,
    p_is_active
  )
  on conflict (app_code, href)
  do update set
    group_key = excluded.group_key,
    group_label = excluded.group_label,
    group_order = excluded.group_order,
    item_key = excluded.item_key,
    label = excluded.label,
    description = excluded.description,
    icon = excluded.icon,
    required_permission_code = excluded.required_permission_code,
    sort_order = excluded.sort_order,
    is_active = excluded.is_active
  returning id into v_item_id;

  return v_item_id;
end;
$$;


ALTER FUNCTION "public"."promote_app_screen_to_navigation"("p_registry_id" "uuid", "p_group_key" "text", "p_group_label" "text", "p_group_order" integer, "p_sort_order" integer, "p_is_active" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."promote_app_screen_to_navigation"("p_registry_id" "uuid", "p_group_key" "text", "p_group_label" "text", "p_group_order" integer, "p_sort_order" integer, "p_is_active" boolean) IS 'Promotes a detected screen from app_screen_registry into app_navigation_items using selected group/order/visibility.';



CREATE OR REPLACE FUNCTION "public"."pulso_post_daily_sales_import"("p_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pass', 'pg_temp'
    AS $$
declare
  v_batch record;
  v_errors jsonb := '[]'::jsonb;
  v_posted_lines integer := 0;
  v_skipped_lines integer := 0;
  v_now timestamptz := now();
  v_line record;
  v_component record;
  v_movement_id uuid;
begin
  select *
    into v_batch
  from public.pulso_daily_sales_import_batches
  where id = p_batch_id
  for update;

  if v_batch.id is null then
    raise exception 'pulso_daily_sales_import_batch not found: %', p_batch_id;
  end if;

  if not public.has_permission('pulso.pos.main', v_batch.site_id) then
    raise exception 'permission denied';
  end if;

  if v_batch.status = 'posted' then
    return jsonb_build_object('status', 'posted', 'postedLines', 0, 'skippedLines', 0, 'errors', v_errors);
  end if;

  if v_batch.status not in ('validated') then
    raise exception 'Solo se pueden publicar lotes validados. Estado actual: %', v_batch.status;
  end if;

  for v_line in
    select
      row.id as row_id,
      row.site_id,
      row.sales_date,
      row.source_row_number,
      row.external_item_name,
      row.external_category,
      row.quantity as sold_qty,
      row.catalog_item_id,
      row.product_id as row_product_id,
      item.category_label,
      rule.id as rule_id,
      rule.area_id,
      rule.source_loc_id,
      rule.consumption_mode,
      rule.finished_product_id,
      rule.recipe_product_id,
      rule.ingredient_product_id,
      rule.ingredient_qty,
      rule.ingredient_unit
    from public.pulso_daily_sales_import_rows row
    left join pass.catalog_items item on item.id = row.catalog_item_id
    left join lateral (
      select r.*
      from public.pulso_sales_consumption_rules r
      where r.site_id = row.site_id
        and r.is_active = true
        and (
          r.catalog_item_id = row.catalog_item_id
          or (r.catalog_item_id is null and r.product_id = row.product_id)
          or (
            r.catalog_item_id is null
            and r.product_id is null
            and r.category_label is not null
            and lower(btrim(r.category_label)) = lower(btrim(coalesce(item.category_label, row.external_category)))
          )
        )
      order by
        case
          when r.catalog_item_id = row.catalog_item_id then 1
          when r.product_id = row.product_id then 2
          else 3
        end,
        r.priority,
        r.created_at
      limit 1
    ) rule on true
    where row.batch_id = p_batch_id
      and row.row_status = 'validated'
    order by row.source_row_number
  loop
    if v_line.catalog_item_id is null then
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'rowId', v_line.row_id,
        'rowNumber', v_line.source_row_number,
        'item', v_line.external_item_name,
        'issue', 'missing_catalog_item'
      ));
      continue;
    end if;

    if v_line.rule_id is null then
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'rowId', v_line.row_id,
        'rowNumber', v_line.source_row_number,
        'item', v_line.external_item_name,
        'category', coalesce(v_line.category_label, v_line.external_category),
        'issue', 'missing_consumption_rule'
      ));
      continue;
    end if;

    if v_line.consumption_mode = 'no_inventory' then
      update public.pulso_daily_sales_import_rows
      set row_status = 'posted',
          metadata = metadata || jsonb_build_object('inventoryPosting', 'no_inventory')
      where id = v_line.row_id;
      v_skipped_lines := v_skipped_lines + 1;
      continue;
    end if;

    for v_component in
      select
        v_line.consumption_mode as posting_kind,
        v_line.finished_product_id as product_id,
        v_line.sold_qty as qty,
        null::text as unit_code
      where v_line.consumption_mode = 'stored_finished_good'
      union all
      select
        v_line.consumption_mode,
        v_line.ingredient_product_id,
        v_line.sold_qty * v_line.ingredient_qty,
        v_line.ingredient_unit
      where v_line.consumption_mode = 'direct_ingredient'
      union all
      select
        v_line.consumption_mode,
        recipe.ingredient_product_id,
        (v_line.sold_qty / recipe_card.yield_qty) * recipe.quantity,
        null::text
      from public.recipes recipe
      join public.recipe_cards recipe_card
        on recipe_card.product_id = recipe.product_id
       and recipe_card.is_active = true
       and recipe_card.yield_qty > 0
      where v_line.consumption_mode = 'made_to_order_recipe'
        and recipe.product_id = v_line.recipe_product_id
        and recipe.is_active = true
        and recipe.ingredient_product_id is not null
        and recipe.quantity > 0
    loop
      if v_component.product_id is null or coalesce(v_component.qty, 0) <= 0 then
        v_errors := v_errors || jsonb_build_array(jsonb_build_object(
          'rowId', v_line.row_id,
          'rowNumber', v_line.source_row_number,
          'item', v_line.external_item_name,
          'issue', 'invalid_consumption_component'
        ));
        continue;
      end if;

      if coalesce((
        select stock.current_qty
        from public.inventory_stock_by_location stock
        where stock.location_id = v_line.source_loc_id
          and stock.product_id = v_component.product_id
      ), 0) < v_component.qty then
        v_errors := v_errors || jsonb_build_array(jsonb_build_object(
          'rowId', v_line.row_id,
          'rowNumber', v_line.source_row_number,
          'item', v_line.external_item_name,
          'productId', v_component.product_id,
          'sourceLocId', v_line.source_loc_id,
          'requiredQty', v_component.qty,
          'issue', 'insufficient_stock'
        ));
        continue;
      end if;

      if exists (
        select 1
        from public.pulso_sales_inventory_postings existing
        where existing.row_id = v_line.row_id
          and existing.product_id = v_component.product_id
          and existing.source_loc_id = v_line.source_loc_id
          and existing.posting_kind = v_component.posting_kind
      ) then
        continue;
      end if;

      insert into public.inventory_movements (
        site_id,
        product_id,
        movement_type,
        quantity,
        note,
        created_by,
        input_qty,
        input_unit_code,
        conversion_factor_to_stock,
        stock_unit_code
      )
      select
        v_line.site_id,
        v_component.product_id,
        'sale_out',
        v_component.qty,
        format('Pulso venta importada %s fila %s - %s', v_batch.sales_date, v_line.source_row_number, v_line.external_item_name),
        auth.uid(),
        v_component.qty,
        coalesce(nullif(v_component.unit_code, ''), p.stock_unit_code, p.unit, 'un'),
        1,
        coalesce(p.stock_unit_code, p.unit, 'un')
      from public.products p
      where p.id = v_component.product_id
      returning id into v_movement_id;

      insert into public.inventory_stock_by_site (site_id, product_id, current_qty, updated_at)
      values (v_line.site_id, v_component.product_id, -v_component.qty, v_now)
      on conflict (site_id, product_id) do update
        set current_qty = public.inventory_stock_by_site.current_qty + excluded.current_qty,
            updated_at = excluded.updated_at;

      insert into public.inventory_stock_by_location (location_id, product_id, current_qty, updated_at)
      values (v_line.source_loc_id, v_component.product_id, -v_component.qty, v_now)
      on conflict (location_id, product_id) do update
        set current_qty = public.inventory_stock_by_location.current_qty + excluded.current_qty,
            updated_at = excluded.updated_at;

      insert into public.pulso_sales_inventory_postings (
        batch_id,
        row_id,
        rule_id,
        site_id,
        sales_date,
        catalog_item_id,
        source_loc_id,
        area_id,
        product_id,
        quantity,
        movement_id,
        posting_kind,
        metadata
      )
      values (
        p_batch_id,
        v_line.row_id,
        v_line.rule_id,
        v_line.site_id,
        v_line.sales_date,
        v_line.catalog_item_id,
        v_line.source_loc_id,
        v_line.area_id,
        v_component.product_id,
        v_component.qty,
        v_movement_id,
        v_component.posting_kind,
        jsonb_build_object('source', 'pulso_post_daily_sales_import')
      );

      v_posted_lines := v_posted_lines + 1;
    end loop;

    if v_line.consumption_mode = 'made_to_order_recipe' and not exists (
      select 1
      from public.recipes recipe
      join public.recipe_cards recipe_card
        on recipe_card.product_id = recipe.product_id
       and recipe_card.is_active = true
       and recipe_card.yield_qty > 0
      where recipe.product_id = v_line.recipe_product_id
        and recipe.is_active = true
        and recipe.ingredient_product_id is not null
        and recipe.quantity > 0
    ) then
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'rowId', v_line.row_id,
        'rowNumber', v_line.source_row_number,
        'item', v_line.external_item_name,
        'issue', 'missing_recipe_components'
      ));
    end if;

    if jsonb_array_length(v_errors) = 0 then
      update public.pulso_daily_sales_import_rows
      set row_status = 'posted'
      where id = v_line.row_id;
    end if;
  end loop;

  if jsonb_array_length(v_errors) > 0 then
    raise exception 'No se puede publicar el lote: %', v_errors;
  end if;

  update public.pulso_daily_sales_import_batches
  set status = 'posted',
      posted_at = v_now,
      metadata = metadata || jsonb_build_object(
        'inventoryPostedAt', v_now,
        'inventoryPostedBy', auth.uid(),
        'inventoryPostedLines', v_posted_lines,
        'inventorySkippedLines', v_skipped_lines
      )
  where id = p_batch_id;

  return jsonb_build_object(
    'status', 'posted',
    'postedLines', v_posted_lines,
    'skippedLines', v_skipped_lines,
    'errors', v_errors
  );
end;
$$;


ALTER FUNCTION "public"."pulso_post_daily_sales_import"("p_batch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pulso_sync_external_sales_item_mapping_product_id"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pass'
    AS $$
begin
  select ci.product_id
    into new.product_id
  from pass.catalog_items ci
  where ci.id = new.catalog_item_id
    and ci.site_id = new.site_id;

  if not found then
    raise exception 'catalog_item_id no pertenece a la sede indicada';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."pulso_sync_external_sales_item_mapping_product_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pulso_validate_sales_consumption_rule"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pass'
    AS $$
declare
  v_loc record;
  v_catalog record;
begin
  select site_id, area_id, is_active
    into v_loc
  from public.inventory_locations
  where id = new.source_loc_id;

  if v_loc.site_id is null then
    raise exception 'source_loc_id no existe';
  end if;
  if v_loc.site_id <> new.site_id then
    raise exception 'source_loc_id no pertenece a la sede indicada';
  end if;
  if v_loc.area_id <> new.area_id then
    raise exception 'source_loc_id no pertenece al area indicada';
  end if;
  if coalesce(v_loc.is_active, false) is false then
    raise exception 'source_loc_id no esta activo';
  end if;

  if new.catalog_item_id is not null then
    select site_id, product_id, category_label
      into v_catalog
    from pass.catalog_items
    where id = new.catalog_item_id;

    if v_catalog.site_id is null then
      raise exception 'catalog_item_id no existe';
    end if;
    if v_catalog.site_id <> new.site_id then
      raise exception 'catalog_item_id no pertenece a la sede indicada';
    end if;

    new.product_id := coalesce(new.product_id, v_catalog.product_id);
    new.category_label := coalesce(nullif(btrim(new.category_label), ''), v_catalog.category_label);
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."pulso_validate_sales_consumption_rule"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rebuild_procurement_supplier_product_costs"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_item record;
  v_synced integer := 0;
  v_skipped integer := 0;
begin
  truncate table public.procurement_supplier_product_costs restart identity cascade;

  update public.inventory_entry_items
  set supplier_product_cost_id = null;

  for v_item in
    select i.id
    from public.inventory_entry_items i
    join public.inventory_entries e
      on e.id = i.entry_id
    where e.supplier_id is not null
      and coalesce(i.quantity_received, 0) > 0
    order by coalesce(e.received_at, e.created_at), i.created_at, i.id
  loop
    begin
      perform public.sync_procurement_supplier_product_cost_from_entry_item(v_item.id);
      v_synced := v_synced + 1;
    exception when others then
      v_skipped := v_skipped + 1;
    end;
  end loop;

  return jsonb_build_object(
    'synced_items', v_synced,
    'skipped_items', v_skipped,
    'cost_rows', (select count(*) from public.procurement_supplier_product_costs)
  );
end;
$$;


ALTER FUNCTION "public"."rebuild_procurement_supplier_product_costs"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rebuild_procurement_supplier_product_costs"() IS 'Rebuilds ORIGO supplier/product/presentation cost memory from historical inventory entries.';



CREATE OR REPLACE FUNCTION "public"."receive_purchase_order"("p_purchase_order_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'storage', 'extensions'
    AS $$
DECLARE
  v_po record;
  v_item record;

  v_purchase_unit_size numeric;
  v_received_base_qty numeric;

  v_prev_total_qty numeric;          -- stock TOTAL antes de recibir
  v_existing_cost numeric;
  v_received_unit_cost_base numeric;
  v_new_cost numeric;

  v_line_total numeric;
  v_total_amount numeric := 0;
BEGIN
  -- Lock PO
  SELECT *
  INTO v_po
  FROM public.purchase_orders
  WHERE id = p_purchase_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Purchase order % no existe', p_purchase_order_id;
  END IF;

  IF v_po.status IN ('received', 'completed') THEN
    RAISE EXCEPTION 'Purchase order % ya está recibida (status=%)', p_purchase_order_id, v_po.status;
  END IF;

  -- Procesar items recibidos
  FOR v_item IN
    SELECT *
    FROM public.purchase_order_items
    WHERE purchase_order_id = p_purchase_order_id
    ORDER BY created_at ASC
  LOOP
    IF v_item.quantity_received IS NULL OR v_item.quantity_received <= 0 THEN
      CONTINUE;
    END IF;

    -- purchase_unit_size por proveedor+producto
    SELECT ps.purchase_unit_size
    INTO v_purchase_unit_size
    FROM public.product_suppliers ps
    WHERE ps.supplier_id = v_po.supplier_id
      AND ps.product_id = v_item.product_id
    LIMIT 1;

    IF v_purchase_unit_size IS NULL OR v_purchase_unit_size <= 0 THEN
      RAISE EXCEPTION
        'Falta purchase_unit_size en product_suppliers para supplier_id=% product_id=% (PO=%)',
        v_po.supplier_id, v_item.product_id, p_purchase_order_id;
    END IF;

    -- Convertir a unidad base
    v_received_base_qty := v_item.quantity_received * v_purchase_unit_size;

    -- 1) Capturar stock total PREVIO (antes de sumar lo recibido)
    SELECT COALESCE(SUM(current_qty), 0)
    INTO v_prev_total_qty
    FROM public.inventory_stock_by_site
    WHERE product_id = v_item.product_id;

    -- 2) Costo actual (promedio anterior)
    SELECT COALESCE(cost, 0)
    INTO v_existing_cost
    FROM public.products
    WHERE id = v_item.product_id;

    -- 3) Costo recibido en unidad base
    v_received_unit_cost_base := v_item.unit_cost / v_purchase_unit_size;

    -- 4) Nuevo costo promedio ponderado (usando stock previo real)
    IF (v_prev_total_qty + v_received_base_qty) > 0 THEN
      v_new_cost :=
        (
          (v_existing_cost * v_prev_total_qty) +
          (v_received_unit_cost_base * v_received_base_qty)
        )
        / (v_prev_total_qty + v_received_base_qty);
    ELSE
      v_new_cost := v_received_unit_cost_base;
    END IF;

    -- Kardex
    INSERT INTO public.inventory_movements (
      site_id,
      product_id,
      movement_type,
      quantity,
      note,
      related_purchase_order_id,
      related_order_id
    )
    VALUES (
      v_po.site_id,
      v_item.product_id,
      'purchase_in',
      v_received_base_qty,
      'Recepción OC ' || p_purchase_order_id::text,
      p_purchase_order_id,
      NULL
    );

    -- Stock por sede
    INSERT INTO public.inventory_stock_by_site (site_id, product_id, current_qty, updated_at)
    VALUES (v_po.site_id, v_item.product_id, v_received_base_qty, now())
    ON CONFLICT (site_id, product_id)
    DO UPDATE SET
      current_qty = public.inventory_stock_by_site.current_qty + EXCLUDED.current_qty,
      updated_at = now();

    -- Actualizar costo del producto
    UPDATE public.products
    SET cost = v_new_cost,
        updated_at = now()
    WHERE id = v_item.product_id;

    -- Totales PO
    v_line_total := v_item.unit_cost * v_item.quantity_received;
    v_total_amount := v_total_amount + COALESCE(v_line_total, 0);

    UPDATE public.purchase_order_items
    SET line_total = v_line_total
    WHERE id = v_item.id;
  END LOOP;

  UPDATE public.purchase_orders
  SET status = 'received',
      received_at = now(),
      total_amount = v_total_amount
  WHERE id = p_purchase_order_id;

END;
$$;


ALTER FUNCTION "public"."receive_purchase_order"("p_purchase_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_expired_payment_checkouts"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'payments'
    AS $$
declare
  v_transaction_count integer := 0;
  v_order_count integer := 0;
begin
  with expired as (
    select
      tx.id as transaction_id,
      tx.order_id
    from payments.transactions tx
    join public.orders o
      on o.id = tx.order_id
    where tx.provider = 'wompi'
      and tx.status in ('pending', 'requires_action')
      and o.source = 'vento_pass'
      and o.fulfillment_type = 'delivery'
      and o.payment_status = 'pending_payment'
      and o.status = 'pending'
      and o.checkout_expires_at is not null
      and o.checkout_expires_at < now()
    for update of tx, o
  ),
  updated_transactions as (
    update payments.transactions tx
    set
      status = 'cancelled',
      raw_response = coalesce(tx.raw_response, '{}'::jsonb) || jsonb_build_object(
        'reason', 'checkout_expired_without_payment',
        'source', 'auto_reconciliation',
        'provider_charge_created', false,
        'reconciled_at', now()
      ),
      rejected_at = coalesce(tx.rejected_at, now()),
      updated_at = now()
    from expired e
    where tx.id = e.transaction_id
    returning tx.id
  ),
  updated_orders as (
    update public.orders o
    set
      status = 'cancelled',
      payment_status = 'failed',
      cancelled_at = coalesce(o.cancelled_at, now()),
      updated_at = now()
    from expired e
    where o.id = e.order_id
      and o.status = 'pending'
      and o.payment_status = 'pending_payment'
    returning o.id
  )
  select
    (select count(*) from updated_transactions),
    (select count(*) from updated_orders)
  into v_transaction_count, v_order_count;

  return jsonb_build_object(
    'ok', true,
    'cancelled_transactions', v_transaction_count,
    'cancelled_orders', v_order_count,
    'ran_at', now()
  );
end;
$$;


ALTER FUNCTION "public"."reconcile_expired_payment_checkouts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_inventory_stock_positions_for_count"("p_location_id" "uuid", "p_lines" "jsonb", "p_created_by" "uuid" DEFAULT "auth"."uid"(), "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_location record;
  v_product_id uuid;
  v_total_lines integer := 0;
  v_positioned_lines integer := 0;
  v_positioned_qty numeric := 0;
  v_bad_product_id uuid;
  v_bad_positioned_qty numeric;
  v_bad_location_qty numeric;
begin
  if p_location_id is null then
    raise exception 'location is required';
  end if;

  if jsonb_typeof(coalesce(p_lines, '[]'::jsonb)) <> 'array' then
    raise exception 'p_lines debe ser un arreglo JSON';
  end if;

  select loc.id, loc.site_id, loc.code
    into v_location
  from public.inventory_locations loc
  where loc.id = p_location_id
    and coalesce(loc.is_active, true) = true;

  if not found then
    raise exception 'active LOC not found';
  end if;

  if not public.has_permission('nexo.inventory.stock', v_location.site_id) then
    raise exception 'permission denied';
  end if;

  create temporary table tmp_position_count_lines (
    product_id uuid not null,
    position_id uuid null,
    quantity numeric not null
  ) on commit drop;

  insert into tmp_position_count_lines (product_id, position_id, quantity)
  select
    (entry ->> 'product_id')::uuid,
    nullif(trim(coalesce(entry ->> 'position_id', '')), '')::uuid,
    (entry ->> 'quantity')::numeric
  from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) entry
  where nullif(trim(coalesce(entry ->> 'product_id', '')), '') is not null
    and coalesce((entry ->> 'quantity')::numeric, 0) > 0;

  select count(*) into v_total_lines
  from tmp_position_count_lines;

  if v_total_lines = 0 then
    raise exception 'Al menos una linea con cantidad > 0';
  end if;

  if exists (
    select 1
    from tmp_position_count_lines line
    where line.position_id is not null
      and not exists (
        select 1
        from public.inventory_location_positions pos
        where pos.id = line.position_id
          and pos.location_id = p_location_id
          and pos.site_id = v_location.site_id
          and coalesce(pos.is_active, true) = true
      )
  ) then
    raise exception 'Una o mas posiciones internas no pertenecen al LOC del conteo';
  end if;

  create temporary table tmp_position_count_agg (
    product_id uuid not null,
    position_id uuid not null,
    quantity numeric not null,
    primary key (product_id, position_id)
  ) on commit drop;

  insert into tmp_position_count_agg (product_id, position_id, quantity)
  select
    line.product_id,
    line.position_id,
    sum(line.quantity)
  from tmp_position_count_lines line
  where line.position_id is not null
  group by line.product_id, line.position_id
  having sum(line.quantity) > 0;

  for v_product_id in
    select distinct line.product_id
    from tmp_position_count_lines line
  loop
    perform pg_advisory_xact_lock(hashtextextended(p_location_id::text || ':' || v_product_id::text, 0));
  end loop;

  select
    agg.product_id,
    agg.positioned_qty,
    coalesce(stock.current_qty, 0)
  into
    v_bad_product_id,
    v_bad_positioned_qty,
    v_bad_location_qty
  from (
    select
      product_id,
      sum(quantity) as positioned_qty
    from tmp_position_count_agg
    group by product_id
  ) agg
  left join public.inventory_stock_by_location stock
    on stock.location_id = p_location_id
   and stock.product_id = agg.product_id
  where agg.positioned_qty > coalesce(stock.current_qty, 0) + 0.000001
  limit 1;

  if v_bad_product_id is not null then
    raise exception
      'positioned quantity % exceeds LOC stock % for product %',
      v_bad_positioned_qty,
      v_bad_location_qty,
      v_bad_product_id;
  end if;

  delete from public.inventory_stock_by_position stock_pos
  using public.inventory_location_positions pos
  where pos.id = stock_pos.position_id
    and pos.location_id = p_location_id
    and stock_pos.product_id in (
      select distinct line.product_id
      from tmp_position_count_lines line
    );

  insert into public.inventory_stock_by_position (
    position_id,
    product_id,
    current_qty,
    updated_at
  )
  select
    agg.position_id,
    agg.product_id,
    agg.quantity,
    now()
  from tmp_position_count_agg agg
  on conflict (position_id, product_id) do update
    set current_qty = excluded.current_qty,
        updated_at = now();

  insert into public.inventory_movements (
    site_id,
    product_id,
    movement_type,
    quantity,
    input_qty,
    input_unit_code,
    conversion_factor_to_stock,
    stock_unit_code,
    note,
    created_by
  )
  select
    v_location.site_id,
    agg.product_id,
    'stock_reconcile_position_count',
    agg.quantity,
    agg.quantity,
    coalesce(nullif(product.stock_unit_code, ''), nullif(product.unit, ''), 'un'),
    1,
    coalesce(nullif(product.stock_unit_code, ''), nullif(product.unit, ''), 'un'),
    coalesce(
      nullif(trim(p_note), ''),
      format('Reconciliacion interna por conteo LOC %s', v_location.code)
    ),
    p_created_by
  from tmp_position_count_agg agg
  left join public.products product
    on product.id = agg.product_id;

  select
    count(*),
    coalesce(sum(quantity), 0)
  into
    v_positioned_lines,
    v_positioned_qty
  from tmp_position_count_agg;

  return jsonb_build_object(
    'locationId', p_location_id,
    'totalLines', v_total_lines,
    'positionedLines', v_positioned_lines,
    'positionedQty', v_positioned_qty
  );
end;
$$;


ALTER FUNCTION "public"."reconcile_inventory_stock_positions_for_count"("p_location_id" "uuid", "p_lines" "jsonb", "p_created_by" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_staff_invitations"() RETURNS TABLE("accepted_count" integer, "expired_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_actor_role text;
  v_actor_site_id uuid;
  v_is_global_manager boolean;
begin
  select e.role, e.site_id
    into v_actor_role, v_actor_site_id
  from public.employees e
  where e.id = auth.uid()
    and e.is_active is distinct from false;

  if v_actor_role is null
     or not (v_actor_role = any (array['propietario', 'gerente_general', 'gerente'])) then
    raise exception 'Forbidden' using errcode = '42501';
  end if;

  v_is_global_manager := v_actor_role = any (array['propietario', 'gerente_general']);

  with expired_rows as (
    update public.staff_invitations si
       set status = 'expired',
           expired_at = coalesce(si.expired_at, si.expires_at, now()),
           updated_at = now(),
           metadata = coalesce(si.metadata, '{}'::jsonb)
             || jsonb_build_object(
               'reconciled_by', auth.uid(),
               'reconciled_reason', 'invite_expired'
             )
     where si.status = 'sent'
       and coalesce(si.expires_at, si.expired_at) is not null
       and coalesce(si.expires_at, si.expired_at) < now()
       and (
         v_is_global_manager
         or coalesce(si.site_id, si.staff_site_id) = v_actor_site_id
       )
     returning si.id
  ),
  matched_active_employee as (
    select distinct on (si.id)
      si.id as invitation_id,
      e.id as employee_id
    from public.staff_invitations si
    join public.employees e
      on e.is_active is distinct from false
     and (
       si.auth_user_id = e.id
       or si.employee_id = e.id
       or exists (
         select 1
         from public.users u
         where u.id = e.id
           and si.email is not null
           and lower(u.email) = lower(si.email)
       )
     )
    where si.status in ('sent', 'expired')
      and (
        v_is_global_manager
        or coalesce(si.site_id, si.staff_site_id) = v_actor_site_id
      )
    order by si.id, e.updated_at desc nulls last, e.joined_at desc nulls last
  ),
  accepted_rows as (
    update public.staff_invitations si
       set status = 'accepted',
           accepted_at = coalesce(si.accepted_at, now()),
           auth_user_id = coalesce(si.auth_user_id, m.employee_id),
           employee_id = coalesce(si.employee_id, m.employee_id),
           updated_at = now(),
           metadata = coalesce(si.metadata, '{}'::jsonb)
             || jsonb_build_object(
               'reconciled_by', auth.uid(),
               'reconciled_reason', 'active_employee_exists'
             )
      from matched_active_employee m
     where si.id = m.invitation_id
     returning si.id
  )
  select
    (select count(*)::integer from accepted_rows),
    (select count(*)::integer from expired_rows)
  into accepted_count, expired_count;

  return next;
end;
$$;


ALTER FUNCTION "public"."reconcile_staff_invitations"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_zero_internal_positions_for_location_product"("p_location_id" "uuid", "p_product_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_location_qty numeric := 0;
  v_updated integer := 0;
begin
  if p_location_id is null or p_product_id is null then
    return 0;
  end if;

  select coalesce(stock.current_qty, 0)
    into v_location_qty
  from public.inventory_stock_by_location stock
  where stock.location_id = p_location_id
    and stock.product_id = p_product_id;

  v_location_qty := coalesce(v_location_qty, 0);

  if abs(v_location_qty) > 0.000001 then
    return 0;
  end if;

  update public.inventory_stock_by_position stock_pos
  set
    current_qty = 0,
    updated_at = now()
  from public.inventory_location_positions pos
  where pos.id = stock_pos.position_id
    and pos.location_id = p_location_id
    and stock_pos.product_id = p_product_id
    and abs(coalesce(stock_pos.current_qty, 0)) > 0.000001;

  get diagnostics v_updated = row_count;
  return v_updated;
end;
$$;


ALTER FUNCTION "public"."reconcile_zero_internal_positions_for_location_product"("p_location_id" "uuid", "p_product_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reconcile_zero_internal_positions_for_location_product"("p_location_id" "uuid", "p_product_id" "uuid") IS 'Mantiene la jerarquia de stock: si un LOC queda en 0 para un producto, ninguna posicion interna del LOC puede conservar saldo.';



CREATE OR REPLACE FUNCTION "public"."register_shift_departure_event"("p_site_id" "uuid", "p_distance_meters" integer, "p_accuracy_meters" integer DEFAULT NULL::integer, "p_source" "text" DEFAULT 'mobile'::"text", "p_notes" "text" DEFAULT NULL::"text", "p_occurred_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_employee_id uuid := auth.uid();
  v_employee public.employees%rowtype;
  v_shift_site_id uuid;
  v_shift_start_at timestamptz;
  v_event_id uuid;
  v_distance integer := greatest(coalesce(p_distance_meters, 0), 0);
  v_accuracy integer := case
    when p_accuracy_meters is null then null
    else greatest(p_accuracy_meters, 0)
  end;
  v_event_time timestamptz := coalesce(p_occurred_at, now());
begin
  if v_employee_id is null then
    raise exception 'No autenticado';
  end if;

  select *
    into v_employee
  from public.employees
  where id = v_employee_id;

  if not found then
    raise exception 'Empleado no encontrado';
  end if;

  if coalesce(v_employee.is_active, false) is false then
    raise exception 'Empleado inactivo';
  end if;

  select al.site_id, al.occurred_at
    into v_shift_site_id, v_shift_start_at
  from public.attendance_logs al
  where al.employee_id = v_employee_id
    and al.action = 'check_in'
    and not exists (
      select 1
      from public.attendance_logs ao
      where ao.employee_id = al.employee_id
        and ao.action = 'check_out'
        and ao.occurred_at > al.occurred_at
    )
  order by al.occurred_at desc, al.created_at desc
  limit 1;

  if v_shift_start_at is null then
    return jsonb_build_object('inserted', false, 'reason', 'no_open_shift');
  end if;

  if p_site_id is not null and p_site_id is distinct from v_shift_site_id then
    return jsonb_build_object('inserted', false, 'reason', 'site_mismatch');
  end if;

  if exists (
    select 1
    from public.attendance_breaks b
    where b.employee_id = v_employee_id
      and b.ended_at is null
  ) then
    return jsonb_build_object('inserted', false, 'reason', 'on_break');
  end if;

  insert into public.attendance_shift_events (
    employee_id,
    site_id,
    shift_start_at,
    event_type,
    occurred_at,
    distance_meters,
    accuracy_meters,
    source,
    notes
  )
  values (
    v_employee_id,
    coalesce(p_site_id, v_shift_site_id),
    v_shift_start_at,
    'left_site_open_shift',
    v_event_time,
    v_distance,
    v_accuracy,
    coalesce(p_source, 'mobile'),
    p_notes
  )
  on conflict (employee_id, shift_start_at, event_type) do nothing
  returning id
    into v_event_id;

  if v_event_id is null then
    return jsonb_build_object('inserted', false, 'reason', 'already_recorded');
  end if;

  return jsonb_build_object(
    'inserted', true,
    'event_id', v_event_id,
    'shift_start_at', v_shift_start_at
  );
end;
$$;


ALTER FUNCTION "public"."register_shift_departure_event"("p_site_id" "uuid", "p_distance_meters" integer, "p_accuracy_meters" integer, "p_source" "text", "p_notes" "text", "p_occurred_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_shift_departure_event_autoclose"("p_site_id" "uuid", "p_distance_meters" integer, "p_accuracy_meters" integer DEFAULT NULL::integer, "p_source" "text" DEFAULT 'mobile'::"text", "p_notes" "text" DEFAULT NULL::"text", "p_occurred_at" timestamp with time zone DEFAULT "now"(), "p_auto_checkout_threshold_meters" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_employee_id uuid := auth.uid();
  v_employee public.employees%rowtype;
  v_shift_site_id uuid;
  v_shift_start_at timestamptz;
  v_event_id uuid;
  v_distance integer := greatest(coalesce(p_distance_meters, 0), 0);
  v_accuracy integer := case
    when p_accuracy_meters is null then null
    else greatest(p_accuracy_meters, 0)
  end;
  v_event_time timestamptz := coalesce(p_occurred_at, now());
  v_threshold integer := greatest(coalesce(p_auto_checkout_threshold_meters, 500), 100);
  v_is_outside boolean;
  v_auto_checkout_applied boolean := false;
  v_auto_checkout_reason text := null;
  v_timezone text := 'America/Bogota';
begin
  if v_employee_id is null then
    raise exception 'No autenticado';
  end if;

  select *
    into v_employee
  from public.employees
  where id = v_employee_id;

  if not found then
    raise exception 'Empleado no encontrado';
  end if;

  if coalesce(v_employee.is_active, false) is false then
    raise exception 'Empleado inactivo';
  end if;

  select al.site_id, al.occurred_at
    into v_shift_site_id, v_shift_start_at
  from public.attendance_logs al
  where al.employee_id = v_employee_id
    and al.action = 'check_in'
    and not exists (
      select 1
      from public.attendance_logs ao
      where ao.employee_id = al.employee_id
        and ao.action = 'check_out'
        and ao.occurred_at > al.occurred_at
    )
  order by al.occurred_at desc, al.created_at desc
  limit 1;

  if v_shift_start_at is null then
    return jsonb_build_object('inserted', false, 'reason', 'no_open_shift');
  end if;

  if (v_shift_start_at at time zone v_timezone)::date <> (v_event_time at time zone v_timezone)::date then
    return jsonb_build_object(
      'inserted', false,
      'reason', 'open_shift_not_today',
      'auto_checkout_applied', false,
      'auto_checkout_reason', 'open_shift_not_today',
      'shift_start_at', v_shift_start_at
    );
  end if;

  if p_site_id is not null and p_site_id is distinct from v_shift_site_id then
    return jsonb_build_object('inserted', false, 'reason', 'site_mismatch');
  end if;

  if exists (
    select 1
    from public.attendance_breaks b
    where b.employee_id = v_employee_id
      and b.ended_at is null
  ) then
    return jsonb_build_object(
      'inserted', false,
      'reason', 'on_break',
      'auto_checkout_applied', false,
      'auto_checkout_reason', 'on_break'
    );
  end if;

  insert into public.attendance_shift_events (
    employee_id,
    site_id,
    shift_start_at,
    event_type,
    occurred_at,
    distance_meters,
    accuracy_meters,
    source,
    notes
  )
  values (
    v_employee_id,
    coalesce(p_site_id, v_shift_site_id),
    v_shift_start_at,
    'left_site_open_shift',
    v_event_time,
    v_distance,
    v_accuracy,
    coalesce(p_source, 'mobile'),
    p_notes
  )
  on conflict (employee_id, shift_start_at, event_type) do nothing
  returning id
    into v_event_id;

  v_is_outside := (v_distance + coalesce(v_accuracy, 0)) >= v_threshold;

  if v_is_outside then
    begin
      update public.attendance_breaks
      set
        ended_at = coalesce(ended_at, v_event_time),
        end_source = 'system',
        end_notes = coalesce(end_notes, 'Cierre automático por salida de sede')
      where employee_id = v_employee_id
        and ended_at is null;

      insert into public.attendance_logs (
        employee_id,
        site_id,
        action,
        source,
        latitude,
        longitude,
        accuracy_meters,
        device_info,
        notes,
        occurred_at
      )
      values (
        v_employee_id,
        coalesce(p_site_id, v_shift_site_id),
        'check_out',
        'system',
        null,
        null,
        coalesce(v_accuracy, 0),
        jsonb_build_object(
          'autoCheckout', true,
          'origin', 'departure_monitor',
          'distanceMeters', v_distance,
          'accuracyMeters', v_accuracy,
          'thresholdMeters', v_threshold
        ),
        'Auto check-out por salida de sede',
        v_event_time
      );

      v_auto_checkout_applied := true;
      v_auto_checkout_reason := 'auto_checkout_applied';
    exception
      when others then
        v_auto_checkout_applied := false;
        v_auto_checkout_reason := sqlerrm;
    end;
  else
    v_auto_checkout_reason := 'below_threshold';
  end if;

  return jsonb_build_object(
    'inserted', v_event_id is not null,
    'reason', case when v_event_id is null then 'already_recorded' else null end,
    'event_id', v_event_id,
    'shift_start_at', v_shift_start_at,
    'auto_checkout_applied', v_auto_checkout_applied,
    'auto_checkout_reason', v_auto_checkout_reason,
    'threshold_meters', v_threshold
  );
end;
$$;


ALTER FUNCTION "public"."register_shift_departure_event_autoclose"("p_site_id" "uuid", "p_distance_meters" integer, "p_accuracy_meters" integer, "p_source" "text", "p_notes" "text", "p_occurred_at" timestamp with time zone, "p_auto_checkout_threshold_meters" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_attendance_shift_before_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_original_site_id uuid := new.site_id;
  v_shift record;
begin
  if new.shift_id is null then
    new.shift_id := public.resolve_attendance_shift_id(
      new.employee_id,
      new.site_id,
      new.geofence_site_id,
      new.action,
      new.occurred_at
    );
  end if;

  if new.shift_id is not null then
    select id, site_id, checkin_site_id, checkout_site_id
      into v_shift
    from public.employee_shifts
    where id = new.shift_id;

    if found then
      -- If the client sent only the physical marking site in site_id,
      -- preserve it as geofence_site_id before normalizing site_id to operational site.
      if new.geofence_site_id is null
        and v_original_site_id is distinct from v_shift.site_id
      then
        new.geofence_site_id := v_original_site_id;
      end if;

      -- attendance_logs.site_id must represent the operational site.
      new.site_id := v_shift.site_id;
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."resolve_attendance_shift_before_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_attendance_shift_id"("p_employee_id" "uuid", "p_site_id" "uuid", "p_geofence_site_id" "uuid", "p_action" "text", "p_occurred_at" timestamp with time zone) RETURNS "uuid"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  with policy as (
    select
      coalesce(shift_match_early_checkin_minutes, 120) as early_checkin,
      coalesce(shift_match_late_checkin_minutes, 60) as late_checkin,
      coalesce(shift_match_early_checkout_minutes, 60) as early_checkout,
      coalesce(shift_match_late_checkout_minutes, 240) as late_checkout
    from public.attendance_policy
    order by created_at asc
    limit 1
  ),
  candidates as (
    select
      s.id,
      case
        when p_action = 'check_in'
          then abs(extract(epoch from (p_occurred_at - public._shift_start_at_bogota(s.shift_date, s.start_time))))
        else abs(extract(epoch from (p_occurred_at - public._shift_end_at_bogota(s.shift_date, s.end_time))))
      end as distance_seconds
    from public.employee_shifts s
    cross join policy p
    where s.employee_id = p_employee_id
      and s.published_at is not null
      and coalesce(s.status, 'scheduled') <> 'cancelled'
      and coalesce(s.shift_kind, 'laboral') <> 'descanso'
      and (
        s.site_id = p_site_id
        or s.checkin_site_id = p_site_id
        or s.checkout_site_id = p_site_id
        or (p_geofence_site_id is not null and s.site_id = p_geofence_site_id)
        or (p_geofence_site_id is not null and s.checkin_site_id = p_geofence_site_id)
        or (p_geofence_site_id is not null and s.checkout_site_id = p_geofence_site_id)
      )
      and (
        (
          p_action = 'check_in'
          and p_occurred_at >= public._shift_start_at_bogota(s.shift_date, s.start_time) - make_interval(mins => p.early_checkin)
          and p_occurred_at <= public._shift_start_at_bogota(s.shift_date, s.start_time) + make_interval(mins => p.late_checkin)
        )
        or
        (
          p_action = 'check_out'
          and p_occurred_at >= public._shift_end_at_bogota(s.shift_date, s.end_time) - make_interval(mins => p.early_checkout)
          and p_occurred_at <= public._shift_end_at_bogota(s.shift_date, s.end_time) + make_interval(mins => p.late_checkout)
        )
      )
    order by distance_seconds asc, s.shift_date asc, s.start_time asc
    limit 1
  )
  select id from candidates;
$$;


ALTER FUNCTION "public"."resolve_attendance_shift_id"("p_employee_id" "uuid", "p_site_id" "uuid", "p_geofence_site_id" "uuid", "p_action" "text", "p_occurred_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_internal_transfer_price"("p_product_id" "uuid", "p_seller_cost_center_id" "uuid", "p_buyer_cost_center_id" "uuid", "p_buyer_site_id" "uuid", "p_unit_code" "text" DEFAULT NULL::"text", "p_at" timestamp with time zone DEFAULT "now"()) RETURNS TABLE("price_list_id" "uuid", "price_list_item_id" "uuid", "unit_price" numeric, "unit_code" "text", "currency" "text", "priority" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    resolved.price_list_id,
    resolved.price_list_item_id,
    resolved.unit_price,
    resolved.unit_code,
    resolved.currency,
    resolved.priority
  from public.resolve_internal_transfer_price_for_profile(
    p_product_id,
    p_seller_cost_center_id,
    p_buyer_cost_center_id,
    p_buyer_site_id,
    null,
    p_unit_code,
    p_at
  ) resolved
  limit 1;
$$;


ALTER FUNCTION "public"."resolve_internal_transfer_price"("p_product_id" "uuid", "p_seller_cost_center_id" "uuid", "p_buyer_cost_center_id" "uuid", "p_buyer_site_id" "uuid", "p_unit_code" "text", "p_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_internal_transfer_price"("p_product_id" "uuid", "p_seller_cost_center_id" "uuid", "p_buyer_cost_center_id" "uuid", "p_buyer_site_id" "uuid", "p_unit_code" "text", "p_at" timestamp with time zone) IS 'Returns the best active internal price for product/seller/buyer/unit/date. Priority: buyer cost center, buyer site, general seller price.';



CREATE OR REPLACE FUNCTION "public"."resolve_internal_transfer_price_for_profile"("p_product_id" "uuid", "p_seller_cost_center_id" "uuid", "p_buyer_cost_center_id" "uuid", "p_buyer_site_id" "uuid", "p_uom_profile_id" "uuid" DEFAULT NULL::"uuid", "p_unit_code" "text" DEFAULT NULL::"text", "p_at" timestamp with time zone DEFAULT "now"()) RETURNS TABLE("price_list_id" "uuid", "price_list_item_id" "uuid", "unit_price" numeric, "unit_code" "text", "currency" "text", "priority" integer, "uom_profile_id" "uuid", "pricing_label" "text", "pricing_input_unit_code" "text", "pricing_qty_in_input_unit" numeric, "pricing_qty_in_stock_unit" numeric, "pricing_factor_to_stock" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    pl.id as price_list_id,
    pli.id as price_list_item_id,
    pli.unit_price,
    pli.unit_code,
    'COP'::text as currency,
    case
      when pl.buyer_cost_center_id = p_buyer_cost_center_id then 1
      when pl.buyer_site_id = p_buyer_site_id then 2
      when pl.buyer_cost_center_id is null and pl.buyer_site_id is null then 3
      else 9
    end as priority,
    pli.uom_profile_id,
    pli.pricing_label,
    pli.pricing_input_unit_code,
    pli.pricing_qty_in_input_unit,
    pli.pricing_qty_in_stock_unit,
    case
      when coalesce(pli.pricing_qty_in_input_unit, 0) > 0
        then pli.pricing_qty_in_stock_unit / pli.pricing_qty_in_input_unit
      else 1
    end as pricing_factor_to_stock
  from public.internal_price_list_items pli
  join public.internal_price_lists pl
    on pl.id = pli.price_list_id
  where pli.product_id = p_product_id
    and pli.is_active = true
    and pl.is_active = true
    and pl.seller_cost_center_id = p_seller_cost_center_id
    and p_at >= pl.valid_from
    and (pl.valid_to is null or p_at < pl.valid_to)
    and (
      pl.buyer_cost_center_id = p_buyer_cost_center_id
      or pl.buyer_site_id = p_buyer_site_id
      or (pl.buyer_cost_center_id is null and pl.buyer_site_id is null)
    )
    and (
      (
        p_uom_profile_id is not null
        and pli.uom_profile_id = p_uom_profile_id
      )
      or (
        pli.uom_profile_id is null
        and (
          p_unit_code is null
          or btrim(p_unit_code) = ''
          or lower(btrim(pli.unit_code)) = lower(btrim(p_unit_code))
        )
      )
      or (
        p_uom_profile_id is null
        and pli.uom_profile_id is not null
        and (
          p_unit_code is null
          or btrim(p_unit_code) = ''
          or lower(btrim(pli.unit_code)) = lower(btrim(p_unit_code))
        )
      )
    )
  order by
    case
      when p_uom_profile_id is not null and pli.uom_profile_id = p_uom_profile_id then 0
      when pli.uom_profile_id is null then 1
      else 2
    end,
    case
      when pl.buyer_cost_center_id = p_buyer_cost_center_id then 1
      when pl.buyer_site_id = p_buyer_site_id then 2
      when pl.buyer_cost_center_id is null and pl.buyer_site_id is null then 3
      else 9
    end,
    pl.valid_from desc,
    pli.created_at desc
  limit 1;
$$;


ALTER FUNCTION "public"."resolve_internal_transfer_price_for_profile"("p_product_id" "uuid", "p_seller_cost_center_id" "uuid", "p_buyer_cost_center_id" "uuid", "p_buyer_site_id" "uuid", "p_uom_profile_id" "uuid", "p_unit_code" "text", "p_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_internal_transfer_price_for_profile"("p_product_id" "uuid", "p_seller_cost_center_id" "uuid", "p_buyer_cost_center_id" "uuid", "p_buyer_site_id" "uuid", "p_uom_profile_id" "uuid", "p_unit_code" "text", "p_at" timestamp with time zone) IS 'Returns the best active internal price for product/seller/buyer/date, preferring an exact UOM profile/presentation match and falling back to legacy unit_code.';



CREATE OR REPLACE FUNCTION "public"."resolve_product_sku_brand_code"("p_site_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'auth', 'storage', 'extensions'
    AS $$
declare
  v_site_type text;
  v_site_code text;
begin
  select s.type, s.code
    into v_site_type, v_site_code
  from public.sites s
  where s.id = p_site_id;

  if v_site_type is not null then
    case lower(v_site_type)
      when 'vento_group' then return 'VGR';
      when 'vento_cafe' then return 'VCF';
      when 'saudo' then return 'SAU';
      when 'vaila_vainilla' then return 'VAI';
      when 'catering' then return 'CAT';
    end case;
  end if;

  if v_site_code is null then
    return null;
  end if;

  return upper(regexp_replace(v_site_code, '[^A-Za-z0-9]', '', 'g'));
end;
$$;


ALTER FUNCTION "public"."resolve_product_sku_brand_code"("p_site_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_product_sku_type_code"("p_product_type" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'auth', 'storage', 'extensions'
    AS $$
declare
  v_raw text;
  v_clean text;
begin
  v_raw := coalesce(p_product_type, '');
  v_clean := lower(v_raw);

  if v_clean like '%venta%' then
    return 'VEN';
  elsif v_clean like '%insum%' then
    return 'INS';
  elsif v_clean like '%prepar%' then
    return 'PRE';
  elsif v_clean like '%empa%' then
    return 'EMP';
  elsif v_clean like '%limp%' then
    return 'LIM';
  elsif v_clean like '%mant%' then
    return 'MAN';
  elsif v_clean like '%acti%' then
    return 'ACT';
  end if;

  v_clean := regexp_replace(v_clean, '[^a-z0-9]', '', 'g');
  if v_clean = '' then
    return 'GEN';
  end if;

  return upper(substr(v_clean, 1, 3));
end;
$$;


ALTER FUNCTION "public"."resolve_product_sku_type_code"("p_product_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reverse_restock_request"("p_request_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_request public.restock_requests%rowtype;
  v_now timestamptz := timezone('utc', now());
  v_actor uuid := auth.uid();
  v_marker text;
begin
  select *
  into v_request
  from public.restock_requests
  where id = p_request_id;

  if not found then
    raise exception 'request_not_found';
  end if;

  if v_actor is null then
    raise exception 'permission_denied_reverse';
  end if;

  if not public.has_permission('nexo.inventory.remissions.cancel') then
    raise exception 'permission_denied_reverse';
  end if;

  v_marker := '[REVERSA_APLICADA ' || to_char(v_now, 'YYYY-MM-DD"T"HH24:MI:SS"Z"') || ']';

  if coalesce(v_request.notes, '') like '%[REVERSA_APLICADA %' then
    raise exception 'already_reversed';
  end if;

  with movement_net as (
    select
      m.site_id,
      m.product_id,
      sum(
        case
          when m.movement_type = 'transfer_out' then greatest(coalesce(m.quantity, 0), 0)
          when m.movement_type = 'transfer_in' then -greatest(coalesce(m.quantity, 0), 0)
          else 0
        end
      ) as net_qty
    from public.inventory_movements m
    where m.related_restock_request_id = p_request_id
      and m.site_id is not null
      and m.product_id is not null
      and m.movement_type in ('transfer_out', 'transfer_in')
    group by m.site_id, m.product_id
  ),
  reversible_site as (
    select site_id, product_id, net_qty
    from movement_net
    where net_qty > 0
  )
  insert into public.inventory_movements (
    site_id,
    product_id,
    movement_type,
    quantity,
    note,
    related_restock_request_id,
    created_by,
    created_at
  )
  select
    rs.site_id,
    rs.product_id,
    'adjustment_in',
    rs.net_qty,
    'reverse_restock_request',
    p_request_id,
    v_actor,
    v_now
  from reversible_site rs;

  update public.restock_requests
  set
    status = 'cancelled',
    cancelled_at = coalesce(cancelled_at, v_now),
    status_updated_at = v_now,
    notes = trim(
      both E'\n'
      from concat_ws(E'\n', nullif(notes, ''), v_marker)
    )
  where id = p_request_id;
end;
$$;


ALTER FUNCTION "public"."reverse_restock_request"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."run_shift_runtime_processor"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  fn_url text;
  cron_secret text;
begin
  select coalesce(value #>> '{}', '')
  into fn_url
  from public.app_config
  where key = 'shift_runtime_processor_url'
  limit 1;

  if trim(fn_url) = '' then
    return;
  end if;

  select coalesce(secret_value, '')
  into cron_secret
  from public.internal_job_secrets
  where key = 'shift_runtime_processor_cron'
  limit 1;

  perform net.http_post(
    trim(fn_url),
    '{}'::jsonb,
    '{}'::jsonb,
    jsonb_build_object(
      'Content-Type', 'application/json',
      'x-cron-key', trim(coalesce(cron_secret, ''))
    )
  );
end;
$$;


ALTER FUNCTION "public"."run_shift_runtime_processor"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."run_shift_runtime_processor"() IS 'Dispara la Edge Function shift-runtime-processor con secreto interno para recordatorios y autocierres programados.';



CREATE OR REPLACE FUNCTION "public"."save_or_touch_gift_recipient"("p_name" "text", "p_phone" "text", "p_relationship" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid;
  v_name text := nullif(trim(coalesce(p_name, '')), '');
  v_phone text := nullif(trim(coalesce(p_phone, '')), '');
  v_relationship text := nullif(trim(coalesce(p_relationship, '')), '');
begin
  if auth.uid() is null then
    raise exception 'authentication_required';
  end if;
  if v_name is null then raise exception 'recipient_name_required'; end if;
  if v_phone is null then raise exception 'recipient_phone_required'; end if;

  insert into public.gift_recipients(owner_id, name, phone, relationship, last_used_at)
  values (auth.uid(), v_name, v_phone, v_relationship, now())
  on conflict (owner_id, phone)
  do update set
    name = excluded.name,
    relationship = excluded.relationship,
    last_used_at = now(),
    updated_at = now()
  returning id into v_id;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."save_or_touch_gift_recipient"("p_name" "text", "p_phone" "text", "p_relationship" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."scheduled_auto_close_shift"("p_shift_id" "uuid", "p_triggered_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_shift public.employee_shifts%rowtype;
  v_shift_start_at timestamptz;
  v_check_in public.attendance_logs%rowtype;
  v_existing_check_out public.attendance_logs%rowtype;
  v_closed_breaks int := 0;
begin
  if p_shift_id is null then
    raise exception 'shift_id_required';
  end if;

  select *
  into v_shift
  from public.employee_shifts
  where id = p_shift_id
  for update;

  if not found then
    return jsonb_build_object(
      'applied', false,
      'reason', 'shift_not_found'
    );
  end if;

  if v_shift.published_at is null then
    return jsonb_build_object(
      'applied', false,
      'reason', 'shift_not_published'
    );
  end if;

  if coalesce(v_shift.status, '') = 'cancelled' then
    return jsonb_build_object(
      'applied', false,
      'reason', 'shift_cancelled'
    );
  end if;

  v_shift_start_at := make_timestamptz(
    extract(year from v_shift.shift_date)::int,
    extract(month from v_shift.shift_date)::int,
    extract(day from v_shift.shift_date)::int,
    extract(hour from v_shift.start_time)::int,
    extract(minute from v_shift.start_time)::int,
    extract(second from v_shift.start_time),
    'America/Bogota'
  );

  select *
  into v_check_in
  from public.attendance_logs
  where employee_id = v_shift.employee_id
    and site_id = v_shift.site_id
    and action = 'check_in'
    and occurred_at >= v_shift_start_at - interval '6 hours'
    and occurred_at <= p_triggered_at
    and (shift_id = p_shift_id or shift_id is null)
  order by
    case when shift_id = p_shift_id then 0 else 1 end,
    occurred_at desc
  limit 1;

  if not found then
    return jsonb_build_object(
      'applied', false,
      'reason', 'no_check_in'
    );
  end if;

  select *
  into v_existing_check_out
  from public.attendance_logs
  where employee_id = v_shift.employee_id
    and site_id = v_shift.site_id
    and action = 'check_out'
    and occurred_at >= v_check_in.occurred_at
    and occurred_at <= p_triggered_at
    and (shift_id = p_shift_id or shift_id is null)
  order by occurred_at asc
  limit 1;

  if found then
    return jsonb_build_object(
      'applied', false,
      'reason', 'already_closed',
      'check_out_at', v_existing_check_out.occurred_at
    );
  end if;

  update public.attendance_breaks
  set ended_at = p_triggered_at
  where employee_id = v_shift.employee_id
    and ended_at is null
    and started_at >= v_check_in.occurred_at;

  get diagnostics v_closed_breaks = row_count;

  insert into public.attendance_logs (
    employee_id,
    site_id,
    action,
    occurred_at,
    source,
    latitude,
    longitude,
    accuracy_meters,
    notes,
    device_info,
    client_event_id,
    shift_id
  )
  values (
    v_shift.employee_id,
    v_shift.site_id,
    'check_out',
    p_triggered_at,
    'system',
    null,
    null,
    null,
    'Auto check-out por fin programado del turno',
    jsonb_build_object(
      'scheduledAutoCheckout', true,
      'closedOpenBreaks', v_closed_breaks
    ),
    null,
    p_shift_id
  );

  return jsonb_build_object(
    'applied', true,
    'reason', 'auto_closed',
    'check_in_at', v_check_in.occurred_at,
    'check_out_at', p_triggered_at,
    'closed_breaks', v_closed_breaks
  );
end;
$$;


ALTER FUNCTION "public"."scheduled_auto_close_shift"("p_shift_id" "uuid", "p_triggered_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."scheduled_auto_close_shift"("p_shift_id" "uuid", "p_triggered_at" timestamp with time zone) IS 'Autocierra un turno programado abierto usando la hora de ejecución como check-out del sistema.';



