CREATE OR REPLACE FUNCTION "public"."shared_device_actor_is_allowed_v1"("p_device_id" "uuid", "p_actor_employee_id" "uuid", "p_site_id" "uuid" DEFAULT NULL::"uuid", "p_area_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
  with actor as (
    select
      e.id,
      e.role,
      e.site_id as default_site_id,
      e.is_active
    from public.employees e
    where e.id = p_actor_employee_id
  ),
  last_attendance as (
    select
      al.employee_id,
      al.action,
      al.site_id,
      al.shift_id,
      al.device_info
    from public.attendance_logs al
    where al.employee_id = p_actor_employee_id
      and al.action in ('check_in', 'check_out')
    order by al.occurred_at desc, al.created_at desc
    limit 1
  ),
  active_context as (
    select
      la.employee_id,
      coalesce(
        nullif(la.device_info #>> '{operationalContext,siteId}', '')::uuid,
        la.site_id
      ) as active_site_id,
      nullif(la.device_info #>> '{operationalContext,areaId}', '')::uuid as active_area_id,
      coalesce(
        nullif(la.device_info #>> '{operationalContext,operationalRole}', ''),
        a.role
      ) as active_role
    from last_attendance la
    join actor a on a.id = la.employee_id
    where la.action = 'check_in'
  )
  select exists (
    select 1
    from public.shared_operational_device_actor_policies p
    join actor a on a.is_active
    left join active_context ac on true
    where p.device_id = p_device_id
      and p.is_active
      and ac.employee_id is not null
      and (
        (p.policy_type = 'any_active_worker')
        or (
          p.policy_type = 'same_site_active_worker'
          and ac.active_site_id = p.site_id
        )
        or (
          p.policy_type = 'same_area_active_worker'
          and ac.active_site_id = p.site_id
          and ac.active_area_id = p.area_id
        )
        or (
          p.policy_type = 'role_in_site'
          and ac.active_site_id = p.site_id
          and ac.active_role = p.role_code
        )
        or (
          p.policy_type = 'role_in_area'
          and ac.active_site_id = p.site_id
          and ac.active_area_id = p.area_id
          and ac.active_role = p.role_code
        )
        or (
          p.policy_type = 'specific_employee'
          and a.id = p.employee_id
        )
      )
      and (p_site_id is null or ac.active_site_id = p_site_id)
      and (p_area_id is null or ac.active_area_id = p_area_id)
  );
$$;


ALTER FUNCTION "public"."shared_device_actor_is_allowed_v1"("p_device_id" "uuid", "p_actor_employee_id" "uuid", "p_site_id" "uuid", "p_area_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."shared_device_actor_is_allowed_v1"("p_device_id" "uuid", "p_actor_employee_id" "uuid", "p_site_id" "uuid", "p_area_id" "uuid") IS 'Valida si un actor humano activo con jornada abierta puede operar un dispositivo compartido según sus políticas.';



CREATE OR REPLACE FUNCTION "public"."sign_shared_device_action"("p_actor_employee_id" "uuid", "p_actor_pin" "text" DEFAULT NULL::"text", "p_app_code" "text" DEFAULT 'nexo'::"text", "p_action_code" "text" DEFAULT NULL::"text", "p_target_table" "text" DEFAULT NULL::"text", "p_target_id" "uuid" DEFAULT NULL::"uuid", "p_signature_method" "text" DEFAULT 'pin'::"text", "p_ttl_seconds" integer DEFAULT 300, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS TABLE("signature_id" "uuid", "actor_employee_id" "uuid", "actor_shift_id" "uuid", "expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_device public.shared_operational_devices%rowtype;
  v_actor public.employees%rowtype;
  v_shift_id uuid;
  v_actor_site_id uuid;
  v_actor_area_id uuid;
  v_action_code text := nullif(btrim(coalesce(p_action_code, '')), '');
  v_app_code text := nullif(btrim(coalesce(p_app_code, '')), '');
  v_method text := lower(nullif(btrim(coalesce(p_signature_method, '')), ''));
  v_expires_at timestamptz;
  v_signature_id uuid;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;

  if v_action_code is null then
    raise exception 'ACTION_CODE_REQUIRED' using errcode = '22023';
  end if;

  if v_app_code is null then
    raise exception 'APP_CODE_REQUIRED' using errcode = '22023';
  end if;

  if v_method is null then
    v_method := 'pin';
  end if;

  if v_method not in ('pin', 'qr', 'nfc', 'manual_override', 'session_reuse') then
    raise exception 'INVALID_SIGNATURE_METHOD' using errcode = '22023';
  end if;

  select * into v_device
  from public.shared_operational_devices d
  where d.auth_user_id = auth.uid()
    and d.is_active
    and d.activation_status = 'active'
  limit 1;

  if v_device.id is null then
    raise exception 'ACTIVE_SHARED_DEVICE_REQUIRED' using errcode = '28000';
  end if;

  if not exists (
    select 1
    from public.shared_operational_device_apps da
    where da.device_id = v_device.id
      and da.app_code = v_app_code
      and da.is_active
  ) then
    raise exception 'APP_NOT_ALLOWED_FOR_DEVICE' using errcode = '42501';
  end if;

  if p_actor_employee_id is null then
    if nullif(btrim(coalesce(p_actor_pin, '')), '') is null then
      raise exception 'ACTOR_PIN_REQUIRED' using errcode = '22023';
    end if;

    with candidates as (
      select e.*
      from public.employees e
      where e.is_active is true
        and coalesce(e.pin_code, '') = btrim(p_actor_pin)
        and public.shared_device_actor_is_allowed_v1(
          v_device.id,
          e.id,
          case when v_device.requires_active_actor_shift then v_device.site_id else null end,
          null
        )
    )
    select * into v_actor
    from candidates
    limit 1;

    if v_actor.id is null then
      raise exception 'ACTIVE_ACTOR_REQUIRED' using errcode = '28000';
    end if;

    if (
      select count(*)
      from public.employees e
      where e.is_active is true
        and coalesce(e.pin_code, '') = btrim(p_actor_pin)
        and public.shared_device_actor_is_allowed_v1(
          v_device.id,
          e.id,
          case when v_device.requires_active_actor_shift then v_device.site_id else null end,
          null
        )
    ) > 1 then
      raise exception 'AMBIGUOUS_ACTOR_PIN' using errcode = '21000';
    end if;
  else
    select * into v_actor
    from public.employees e
    where e.id = p_actor_employee_id
      and e.is_active is true
    limit 1;

    if v_actor.id is null then
      raise exception 'ACTIVE_ACTOR_REQUIRED' using errcode = '28000';
    end if;
  end if;

  if v_device.requires_actor_pin and not v_device.allow_actor_without_pin then
    if v_method <> 'pin' then
      raise exception 'PIN_SIGNATURE_REQUIRED' using errcode = '42501';
    end if;

    if nullif(btrim(coalesce(p_actor_pin, '')), '') is null then
      raise exception 'ACTOR_PIN_REQUIRED' using errcode = '22023';
    end if;

    if coalesce(v_actor.pin_code, '') <> btrim(p_actor_pin) then
      raise exception 'INVALID_ACTOR_PIN' using errcode = '28000';
    end if;
  end if;

  select s.actor_shift_id, s.active_site_id, s.active_area_id
  into v_shift_id, v_actor_site_id, v_actor_area_id
  from public.current_actor_shift_for_shared_device_v1(
    p_actor_employee_id,
    case when v_device.requires_active_actor_shift then v_device.site_id else null end,
    null
  ) s
  limit 1;

  if v_device.requires_active_actor_shift and v_shift_id is null then
    raise exception 'ACTIVE_ACTOR_SHIFT_REQUIRED' using errcode = '42501';
  end if;

  if not public.shared_device_actor_is_allowed_v1(
    v_device.id,
    p_actor_employee_id,
    case when v_device.requires_active_actor_shift then v_device.site_id else null end,
    null
  ) then
    raise exception 'ACTOR_NOT_ALLOWED_FOR_DEVICE' using errcode = '42501';
  end if;

  if p_ttl_seconds is null or p_ttl_seconds <= 0 then
    v_expires_at := now();
  else
    v_expires_at := now() + make_interval(secs => least(p_ttl_seconds, 3600));
  end if;

  insert into public.shared_device_actor_signatures (
    shared_device_id,
    auth_user_id,
    actor_employee_id,
    actor_shift_id,
    site_id,
    area_id,
    app_code,
    action_code,
    target_table,
    target_id,
    signature_method,
    signed_at,
    expires_at,
    metadata
  ) values (
    v_device.id,
    auth.uid(),
    v_actor.id,
    v_shift_id,
    coalesce(v_actor_site_id, v_device.site_id),
    coalesce(v_actor_area_id, v_device.area_id),
    v_app_code,
    v_action_code,
    nullif(btrim(coalesce(p_target_table, '')), ''),
    p_target_id,
    v_method,
    now(),
    v_expires_at,
    coalesce(p_metadata, '{}'::jsonb) || jsonb_build_object(
      'device_code', v_device.code,
      'device_label', v_device.label,
      'actor_role', v_actor.role
    )
  )
  returning id into v_signature_id;

  insert into public.shared_operational_device_events (
    device_id,
    session_user_id,
    actor_employee_id,
    actor_shift_id,
    app_code,
    site_id,
    area_id,
    event_type,
    event_payload,
    source
  ) values (
    v_device.id,
    auth.uid(),
    v_actor.id,
    v_shift_id,
    v_app_code,
    coalesce(v_actor_site_id, v_device.site_id),
    coalesce(v_actor_area_id, v_device.area_id),
    'actor_signature_created',
    jsonb_build_object(
      'signature_id', v_signature_id,
      'action_code', v_action_code,
      'target_table', p_target_table,
      'target_id', p_target_id,
      'signature_method', v_method,
      'expires_at', v_expires_at
    ),
    'shared_device'
  );

  return query select v_signature_id, v_actor.id, v_shift_id, v_expires_at;
end;
$$;


ALTER FUNCTION "public"."sign_shared_device_action"("p_actor_employee_id" "uuid", "p_actor_pin" "text", "p_app_code" "text", "p_action_code" "text", "p_target_table" "text", "p_target_id" "uuid", "p_signature_method" "text", "p_ttl_seconds" integer, "p_metadata" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sign_shared_device_action"("p_actor_employee_id" "uuid", "p_actor_pin" "text", "p_app_code" "text", "p_action_code" "text", "p_target_table" "text", "p_target_id" "uuid", "p_signature_method" "text", "p_ttl_seconds" integer, "p_metadata" "jsonb") IS 'Firma una accion operativa desde un dispositivo compartido activo, validando actor humano, PIN, jornada y politica de uso.';



CREATE OR REPLACE FUNCTION "public"."split_restock_request_item"("p_item_id" "uuid", "p_split_quantity" numeric) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_item public.restock_request_items%rowtype;
  v_request public.restock_requests%rowtype;
  v_original_quantity numeric;
  v_split_quantity numeric;
  v_split_ratio numeric;
  v_split_input_qty numeric;
  v_remaining_input_qty numeric;
  v_split_transfer_total numeric;
  v_remaining_transfer_total numeric;
  v_new_item_id uuid;
begin
  v_split_quantity := coalesce(p_split_quantity, 0);

  select *
  into v_item
  from public.restock_request_items
  where id = p_item_id;

  if v_item.id is null then
    raise exception 'Linea de remision no encontrada.';
  end if;

  select *
  into v_request
  from public.restock_requests
  where id = v_item.request_id;

  if v_request.id is null then
    raise exception 'Remision no encontrada para la linea indicada.';
  end if;

  if v_request.from_site_id is null then
    raise exception 'La remision no tiene sede origen.';
  end if;

  if v_request.status not in ('pending', 'preparing') then
    raise exception 'Solo puedes partir lineas en remisiones pendientes o preparando.';
  end if;

  if not public.has_permission('nexo.inventory.remissions.prepare', v_request.from_site_id) then
    raise exception 'No tienes permiso para partir lineas en esta remision.';
  end if;

  v_original_quantity := coalesce(v_item.quantity, 0);

  if v_original_quantity <= 0 then
    raise exception 'La linea no tiene cantidad valida para partir.';
  end if;

  if v_split_quantity <= 0 then
    raise exception 'La cantidad a partir debe ser mayor que cero.';
  end if;

  if v_split_quantity >= v_original_quantity then
    raise exception 'La cantidad a partir debe ser menor que la cantidad actual.';
  end if;

  if coalesce(v_item.prepared_quantity, 0) <> 0
     or coalesce(v_item.shipped_quantity, 0) <> 0
     or coalesce(v_item.received_quantity, 0) <> 0
     or coalesce(v_item.shortage_quantity, 0) <> 0 then
    raise exception 'Solo puedes partir lineas que todavia no tengan preparacion, envio, recepcion ni faltantes.';
  end if;

  v_split_ratio := v_split_quantity / v_original_quantity;
  v_split_input_qty := case
    when v_item.input_qty is null then null
    else v_item.input_qty * v_split_ratio
  end;
  v_remaining_input_qty := case
    when v_item.input_qty is null then null
    else v_item.input_qty - v_split_input_qty
  end;
  v_split_transfer_total := case
    when v_item.transfer_total is null then null
    else v_item.transfer_total * v_split_ratio
  end;
  v_remaining_transfer_total := case
    when v_item.transfer_total is null then null
    else v_item.transfer_total - v_split_transfer_total
  end;

  insert into public.restock_request_items (
    request_id,
    product_id,
    quantity,
    unit,
    transfer_unit_price,
    transfer_currency,
    transfer_total,
    input_qty,
    input_unit_code,
    conversion_factor_to_stock,
    stock_unit_code,
    production_area_kind,
    source_location_id,
    prepared_quantity,
    shipped_quantity,
    received_quantity,
    shortage_quantity,
    item_status,
    notes
  )
  values (
    v_item.request_id,
    v_item.product_id,
    v_split_quantity,
    v_item.unit,
    v_item.transfer_unit_price,
    v_item.transfer_currency,
    v_split_transfer_total,
    v_split_input_qty,
    v_item.input_unit_code,
    v_item.conversion_factor_to_stock,
    v_item.stock_unit_code,
    v_item.production_area_kind,
    null,
    0,
    0,
    0,
    0,
    coalesce(v_item.item_status, 'pending'),
    v_item.notes
  )
  returning id into v_new_item_id;

  update public.restock_request_items
  set
    quantity = v_original_quantity - v_split_quantity,
    input_qty = v_remaining_input_qty,
    transfer_total = v_remaining_transfer_total
  where id = v_item.id;

  return v_new_item_id;
end;
$$;


ALTER FUNCTION "public"."split_restock_request_item"("p_item_id" "uuid", "p_split_quantity" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_attendance_break"("p_site_id" "uuid", "p_source" "text" DEFAULT 'mobile'::"text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "public"."attendance_breaks"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_employee public.employees%rowtype;
  v_last_action text;
  v_last_site_id uuid;
  v_result public.attendance_breaks%rowtype;
begin
  if auth.uid() is null then
    raise exception 'No autenticado';
  end if;

  select *
    into v_employee
  from public.employees
  where id = auth.uid();

  if not found then
    raise exception 'Empleado no encontrado';
  end if;

  if coalesce(v_employee.is_active, false) is false then
    raise exception 'Empleado inactivo';
  end if;

  select action, site_id
    into v_last_action, v_last_site_id
  from public.attendance_logs
  where employee_id = v_employee.id
  order by occurred_at desc, created_at desc
  limit 1;

  if v_last_action is distinct from 'check_in' then
    raise exception 'No hay un turno activo para iniciar descanso';
  end if;

  if p_site_id is not null and p_site_id is distinct from v_last_site_id then
    raise exception 'La sede del descanso no coincide con el turno activo';
  end if;

  if exists (
    select 1
    from public.attendance_breaks b
    where b.employee_id = v_employee.id
      and b.ended_at is null
  ) then
    raise exception 'Ya tienes un descanso activo';
  end if;

  insert into public.attendance_breaks (
    employee_id,
    site_id,
    started_at,
    start_source,
    start_notes
  )
  values (
    v_employee.id,
    coalesce(p_site_id, v_last_site_id),
    now(),
    coalesce(p_source, 'mobile'),
    p_notes
  )
  returning *
    into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."start_attendance_break"("p_site_id" "uuid", "p_source" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_context_simulation_v1"("p_site_id" "uuid", "p_area_id" "uuid" DEFAULT NULL::"uuid", "p_operational_role" "text" DEFAULT NULL::"text", "p_administrative_role" "text" DEFAULT NULL::"text", "p_duration_minutes" integer DEFAULT 240, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_session_id uuid;
  v_duration integer := greatest(15, least(coalesce(p_duration_minutes, 240), 720));
begin
  if v_user_id is null then
    raise exception 'Sesión no autenticada.';
  end if;
  if not public.can_manage_context_simulation_v1(v_user_id) then
    raise exception 'No tienes permiso para activar simulaciones de contexto.';
  end if;
  if p_site_id is null or not exists (
    select 1 from public.sites s where s.id = p_site_id
  ) then
    raise exception 'La sede simulada no existe.';
  end if;
  if nullif(btrim(coalesce(p_operational_role, '')), '') is null
     and nullif(btrim(coalesce(p_administrative_role, '')), '') is null then
    raise exception 'Debes seleccionar un rol operativo o administrativo.';
  end if;

  update public.context_simulation_sessions
  set is_active = false, ended_at = coalesce(ended_at, now()), updated_at = now()
  where user_id = v_user_id and is_active and ended_at is null;

  insert into public.context_simulation_sessions (
    user_id, site_id, area_id, operational_role, administrative_role,
    expires_at, created_by, metadata
  ) values (
    v_user_id,
    p_site_id,
    p_area_id,
    nullif(btrim(coalesce(p_operational_role, '')), ''),
    nullif(btrim(coalesce(p_administrative_role, '')), ''),
    now() + make_interval(mins => v_duration),
    v_user_id,
    coalesce(p_metadata, '{}'::jsonb)
  ) returning id into v_session_id;

  return v_session_id;
end;
$$;


ALTER FUNCTION "public"."start_context_simulation_v1"("p_site_id" "uuid", "p_area_id" "uuid", "p_operational_role" "text", "p_administrative_role" "text", "p_duration_minutes" integer, "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."stop_context_simulation_v1"() RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_count integer;
begin
  if auth.uid() is null then return false; end if;
  update public.context_simulation_sessions
  set is_active = false, ended_at = coalesce(ended_at, now()), updated_at = now()
  where user_id = auth.uid() and is_active and ended_at is null;
  get diagnostics v_count = row_count;
  return v_count > 0;
end;
$$;


ALTER FUNCTION "public"."stop_context_simulation_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."support_ticket_is_visible_to_current_employee"("p_ticket_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.support_tickets t
    where t.id = p_ticket_id
      and (
        t.created_by = auth.uid()
        or t.assigned_to = auth.uid()
        or t.target_employee_id = auth.uid()
        or public.is_owner()
        or public.is_global_manager()
        or exists (
          select 1
          from public.employees e
          join public.employee_sites es on es.employee_id = e.id
          where e.id = auth.uid()
            and e.role = 'gerente'
            and es.site_id = t.site_id
            and es.is_active = true
        )
      )
  );
$$;


