CREATE OR REPLACE FUNCTION "public"."sync_attendance_events"("p_events" "jsonb") RETURNS TABLE("event_id" "text", "result" "text", "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_employee_id uuid := auth.uid();
  v_item jsonb;
  v_event_id text;
  v_action text;
  v_site_id uuid;
  v_geofence_site_id uuid;
  v_geofence_distance_meters numeric;
  v_occurred_at timestamptz;
  v_lat numeric;
  v_lng numeric;
  v_accuracy numeric;
  v_source text;
  v_notes text;
  v_device_info jsonb;
  v_shift_id uuid;
begin
  if v_employee_id is null then
    raise exception 'auth.uid() is null';
  end if;

  if not public.anima_is_active_employee() then
    raise exception 'Empleado inactivo o no encontrado';
  end if;

  if p_events is null or jsonb_typeof(p_events) <> 'array' then
    raise exception 'p_events must be a json array';
  end if;

  for v_item in select value from jsonb_array_elements(p_events)
  loop
    v_event_id := nullif(trim(coalesce(v_item ->> 'eventId', v_item ->> 'event_id', '')), '');
    v_action := lower(trim(coalesce(v_item ->> 'eventType', v_item ->> 'event_type', v_item ->> 'action', '')));
    v_source := coalesce(nullif(trim(coalesce(v_item ->> 'source', '')), ''), 'mobile');
    v_notes := nullif(trim(coalesce(v_item ->> 'notes', '')), '');
    v_occurred_at := coalesce(
      nullif(v_item ->> 'occurredAt', '')::timestamptz,
      nullif(v_item ->> 'occurred_at', '')::timestamptz,
      now()
    );
    v_site_id := nullif(coalesce(v_item ->> 'siteId', v_item ->> 'site_id', ''), '')::uuid;
    v_geofence_site_id := nullif(coalesce(v_item ->> 'geofenceSiteId', v_item ->> 'geofence_site_id', ''), '')::uuid;
    v_geofence_distance_meters := nullif(
      coalesce(v_item ->> 'geofenceDistanceMeters', v_item ->> 'geofence_distance_meters', ''),
      ''
    )::numeric;
    v_lat := nullif(coalesce(v_item #>> '{geoSnapshot,lat}', v_item ->> 'latitude', ''), '')::numeric;
    v_lng := nullif(coalesce(v_item #>> '{geoSnapshot,lng}', v_item ->> 'longitude', ''), '')::numeric;
    v_accuracy := nullif(
      coalesce(v_item #>> '{geoSnapshot,accuracy}', v_item ->> 'accuracy_meters', ''),
      ''
    )::numeric;
    v_device_info := coalesce(v_item -> 'deviceInfo', v_item -> 'device_info', '{}'::jsonb);
    v_shift_id := nullif(coalesce(v_item ->> 'shiftId', v_item ->> 'shift_id', ''), '')::uuid;

    if v_event_id is null then
      return query select null::text, 'error'::text, 'event_id missing'::text;
      continue;
    end if;

    if v_action not in ('check_in', 'check_out') then
      return query select v_event_id, 'error'::text, 'event_type not supported'::text;
      continue;
    end if;

    if v_source not in ('mobile', 'web', 'kiosk') then
      return query select v_event_id, 'error'::text, 'source not allowed'::text;
      continue;
    end if;

    if v_site_id is null then
      return query select v_event_id, 'error'::text, 'site_id missing'::text;
      continue;
    end if;

    if not public.can_access_site(v_site_id) then
      return query select v_event_id, 'error'::text, 'No autorizado para esta sede'::text;
      continue;
    end if;

    begin
      insert into public.attendance_logs (
        employee_id,
        site_id,
        action,
        occurred_at,
        source,
        latitude,
        longitude,
        accuracy_meters,
        notes,
        device_info,
        client_event_id,
        shift_id,
        geofence_site_id,
        geofence_distance_meters
      )
      values (
        v_employee_id,
        v_site_id,
        v_action,
        v_occurred_at,
        v_source,
        v_lat,
        v_lng,
        v_accuracy,
        v_notes,
        jsonb_set(coalesce(v_device_info, '{}'::jsonb), '{clientEventId}', to_jsonb(v_event_id), true),
        v_event_id,
        v_shift_id,
        v_geofence_site_id,
        v_geofence_distance_meters
      );

      return query select v_event_id, 'applied'::text, null::text;
    exception
      when unique_violation then
        return query select v_event_id, 'duplicate'::text, 'Evento ya aplicado previamente.'::text;
      when others then
        insert into public.attendance_sync_conflicts (
          employee_id,
          event_id,
          event_type,
          site_id,
          occurred_at,
          reason,
          payload
        )
        values (
          v_employee_id,
          v_event_id,
          v_action,
          v_site_id::text,
          v_occurred_at,
          sqlerrm,
          v_item
        );

        if sqlstate = 'P0001' then
          return query select v_event_id, 'conflict'::text, sqlerrm;
        else
          return query select v_event_id, 'error'::text, sqlerrm;
        end if;
    end;
  end loop;
end;
$$;


ALTER FUNCTION "public"."sync_attendance_events"("p_events" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_employee_primary_site_assignment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_employee_id uuid;
  v_requested_primary_site_id uuid;
  v_current_employee_site_id uuid;
  v_next_site_id uuid;
begin
  if pg_trigger_depth() > 1 then
    return coalesce(new, old);
  end if;

  v_employee_id := coalesce(new.employee_id, old.employee_id);

  if v_employee_id is null then
    return coalesce(new, old);
  end if;

  if tg_op <> 'DELETE'
    and coalesce(new.is_active, true) is true
    and coalesce(new.is_primary, false) is true then
    v_requested_primary_site_id := new.site_id;
  else
    v_requested_primary_site_id := null;
  end if;

  select e.site_id
    into v_current_employee_site_id
  from public.employees e
  where e.id = v_employee_id;

  select es.site_id
    into v_next_site_id
  from public.employee_sites es
  where es.employee_id = v_employee_id
    and coalesce(es.is_active, true) is true
  order by
    case
      when v_requested_primary_site_id is not null and es.site_id = v_requested_primary_site_id then 0
      else 1
    end,
    case
      when v_current_employee_site_id is not null and es.site_id = v_current_employee_site_id then 0
      else 1
    end,
    case when coalesce(es.is_primary, false) then 0 else 1 end,
    es.site_id
  limit 1;

  update public.employee_sites es
  set is_primary = false
  where es.employee_id = v_employee_id
    and coalesce(es.is_primary, false) is true
    and (v_next_site_id is null or es.site_id <> v_next_site_id);

  if v_next_site_id is not null then
    update public.employee_sites es
    set is_primary = true
    where es.employee_id = v_employee_id
      and es.site_id = v_next_site_id
      and coalesce(es.is_primary, false) is false;
  end if;

  update public.employees
  set
    site_id = v_next_site_id,
    updated_at = now()
  where id = v_employee_id
    and site_id is distinct from v_next_site_id;

  insert into public.employee_settings (employee_id, selected_site_id, updated_at)
  values (v_employee_id, v_next_site_id, now())
  on conflict (employee_id)
  do update set
    selected_site_id = excluded.selected_site_id,
    updated_at = excluded.updated_at
  where public.employee_settings.selected_site_id is distinct from excluded.selected_site_id;

  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "public"."sync_employee_primary_site_assignment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_employee_site_assignment_from_employee"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if pg_trigger_depth() > 1 then
    return new;
  end if;

  if new.site_id is not null and (tg_op = 'INSERT' or new.site_id is distinct from old.site_id) then
    update public.employee_sites
    set is_primary = false
    where employee_id = new.id
      and site_id <> new.site_id
      and coalesce(is_primary, false) is true;

    insert into public.employee_sites (employee_id, site_id, is_primary, is_active)
    values (new.id, new.site_id, true, true)
    on conflict (employee_id, site_id)
    do update set
      is_primary = true,
      is_active = true;
  end if;

  if tg_op = 'INSERT' or new.site_id is distinct from old.site_id then
    insert into public.employee_settings (employee_id, selected_site_id, updated_at)
    values (new.id, new.site_id, now())
    on conflict (employee_id)
    do update set
      selected_site_id = excluded.selected_site_id,
      updated_at = excluded.updated_at
    where public.employee_settings.selected_site_id is distinct from excluded.selected_site_id;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_employee_site_assignment_from_employee"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_order_billing_request_status"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if new.status = 'cancelled' or new.payment_status in ('failed', 'cancelled') then
    update public.order_billing_requests
    set
      status = 'cancelled',
      error_message = case
        when new.status = 'cancelled' then 'order_cancelled'
        else 'payment_' || new.payment_status
      end,
      updated_at = now()
    where order_id = new.id
      and status not in ('issued', 'submitted');
  elsif new.payment_status = 'paid'
     or (new.fulfillment_type in ('pickup', 'on_premise') and new.status = 'delivered') then
    update public.order_billing_requests
    set
      status = 'ready_to_issue',
      error_message = null,
      updated_at = now()
    where order_id = new.id
      and status in ('requested', 'failed', 'cancelled');
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_order_billing_request_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_order_delivery_session"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'app_private', 'extensions'
    AS $$
declare
  v_session_id uuid;
  v_pin text;
begin
  if new.fulfillment_type <> 'delivery' then
    return new;
  end if;

  if new.status = 'on_the_way'
     and (tg_op = 'INSERT' or old.status is distinct from new.status) then
    select id into v_session_id
    from public.order_delivery_sessions
    where order_id = new.id;

    if v_session_id is null then
      v_session_id := gen_random_uuid();
      v_pin := app_private.delivery_pin_for_session(v_session_id);

      insert into public.order_delivery_sessions (
        id,
        order_id,
        site_id,
        status,
        confirmation_pin_hash,
        expires_at,
        metadata
      ) values (
        v_session_id,
        new.id,
        new.site_id,
        'in_transit',
        encode(extensions.digest(v_pin, 'sha256'::text), 'hex'),
        now() + interval '12 hours',
        jsonb_build_object('source', 'orders_status_trigger')
      );
    else
      update public.order_delivery_sessions
      set status = case when status = 'confirmed' then status else 'in_transit' end,
          expires_at = case when status = 'confirmed' then expires_at else now() + interval '12 hours' end,
          updated_at = now()
      where id = v_session_id;
    end if;
  elsif new.status = 'cancelled' and old.status is distinct from new.status then
    update public.order_delivery_sessions
    set status = case when status = 'confirmed' then status else 'cancelled' end,
        updated_at = now()
    where order_id = new.id;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_order_delivery_session"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_order_fulfillment_state"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if new.fulfillment_type = 'delivery' then
    if coalesce(new.dispatch_status, '') = '' or new.dispatch_status = 'not_required' then
      new.dispatch_status := 'pending';
    end if;
  else
    new.dispatch_status := 'not_required';
  end if;

  if new.status = 'confirmed' and new.confirmed_at is null then
    new.confirmed_at := now();
  end if;

  if new.status = 'ready_for_dispatch' and new.ready_for_dispatch_at is null then
    new.ready_for_dispatch_at := now();
  end if;

  if new.status = 'on_the_way' and new.on_the_way_at is null then
    new.on_the_way_at := now();
    if new.fulfillment_type = 'delivery' then
      new.dispatch_status := 'on_the_way';
    end if;
  end if;

  if new.status = 'delivered' and new.delivered_at is null then
    new.delivered_at := now();
    if new.fulfillment_type = 'delivery' then
      new.dispatch_status := 'delivered';
    end if;
  end if;

  if new.status = 'cancelled' and new.cancelled_at is null then
    new.cancelled_at := now();
    if new.fulfillment_type = 'delivery' then
      new.dispatch_status := 'cancelled';
    end if;
  end if;

  return new;
end
$$;


ALTER FUNCTION "public"."sync_order_fulfillment_state"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_procurement_supplier_product_cost_from_entry_item"("p_entry_item_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row record;
  v_norm record;

  v_existing_id uuid;
  v_cost_id uuid;

  v_input_qty numeric;
  v_stock_qty numeric;
  v_factor numeric;

  v_total_input_qty numeric;
  v_total_stock_qty numeric;
  v_total_net_cost numeric;
  v_total_gross_cost numeric;
  v_samples_count integer;
begin
  select
    i.id as entry_item_id,
    i.entry_id,
    i.product_id,
    i.input_uom_profile_id,
    i.input_qty,
    i.quantity_received,
    i.input_unit_code,
    i.unit,
    i.conversion_factor_to_stock,
    i.stock_unit_code,
    i.input_unit_cost,
    i.tax_included,
    i.tax_rate,
    i.net_unit_cost as existing_net_unit_cost,
    i.gross_unit_cost as existing_gross_unit_cost,
    i.stock_unit_cost as existing_stock_unit_cost,
    i.net_total_cost as existing_net_total_cost,
    i.gross_total_cost as existing_gross_total_cost,
    i.currency,
    e.supplier_id,
    e.received_at,
    e.created_at as entry_created_at
  into v_row
  from public.inventory_entry_items i
  join public.inventory_entries e
    on e.id = i.entry_id
  where i.id = p_entry_item_id;

  if not found then
    raise exception 'inventory_entry_item_not_found: %', p_entry_item_id;
  end if;

  if v_row.supplier_id is null then
    return null;
  end if;

  v_factor := greatest(coalesce(v_row.conversion_factor_to_stock, 1), 0.000001);
  v_stock_qty := greatest(coalesce(v_row.quantity_received, 0), 0);

  v_input_qty :=
    case
      when coalesce(v_row.input_qty, 0) > 0 then v_row.input_qty
      when v_stock_qty > 0 and v_factor > 0 then v_stock_qty / v_factor
      else 0
    end;

  if v_input_qty <= 0 or v_stock_qty <= 0 then
    return null;
  end if;

  select *
  into v_norm
  from public.normalize_procurement_receipt_costs(
    coalesce(
      nullif(v_row.input_unit_cost, 0),
      nullif(v_row.existing_gross_unit_cost, 0),
      nullif(v_row.existing_net_unit_cost, 0),
      0
    ),
    coalesce(v_row.tax_included, false),
    coalesce(v_row.tax_rate, 0),
    v_factor,
    v_input_qty
  );

  -- Prefer explicitly stored normalized values when they already exist.
  v_norm.net_unit_cost :=
    case
      when coalesce(v_row.existing_net_unit_cost, 0) > 0 then v_row.existing_net_unit_cost
      else v_norm.net_unit_cost
    end;

  v_norm.gross_unit_cost :=
    case
      when coalesce(v_row.existing_gross_unit_cost, 0) > 0 then v_row.existing_gross_unit_cost
      else v_norm.gross_unit_cost
    end;

  v_norm.stock_unit_cost :=
    case
      when coalesce(v_row.existing_stock_unit_cost, 0) > 0 then v_row.existing_stock_unit_cost
      else v_norm.stock_unit_cost
    end;

  v_norm.net_total_cost :=
    case
      when coalesce(v_row.existing_net_total_cost, 0) > 0 then v_row.existing_net_total_cost
      else round(v_norm.net_unit_cost * v_input_qty, 6)
    end;

  v_norm.gross_total_cost :=
    case
      when coalesce(v_row.existing_gross_total_cost, 0) > 0 then v_row.existing_gross_total_cost
      else round(v_norm.gross_unit_cost * v_input_qty, 6)
    end;

  select c.id
  into v_existing_id
  from public.procurement_supplier_product_costs c
  where c.is_active = true
    and c.supplier_id = v_row.supplier_id
    and c.product_id = v_row.product_id
    and c.input_uom_profile_id is not distinct from v_row.input_uom_profile_id
    and lower(c.input_unit_code) = lower(coalesce(nullif(v_row.input_unit_code, ''), nullif(v_row.unit, ''), 'un'))
    and c.conversion_factor_to_stock = v_factor
    and lower(c.stock_unit_code) = lower(coalesce(nullif(v_row.stock_unit_code, ''), nullif(v_row.input_unit_code, ''), 'un'))
    and c.currency = coalesce(nullif(v_row.currency, ''), 'COP')
  limit 1;

  if v_existing_id is null then
    insert into public.procurement_supplier_product_costs (
      supplier_id,
      product_id,
      input_uom_profile_id,
      input_unit_code,
      input_unit_label,
      conversion_factor_to_stock,
      stock_unit_code,
      currency,

      last_net_unit_cost,
      last_gross_unit_cost,
      last_stock_unit_cost,

      avg_net_unit_cost,
      avg_gross_unit_cost,
      avg_stock_unit_cost,

      total_input_qty,
      total_stock_qty,
      total_net_cost,
      total_gross_cost,
      samples_count,

      last_entry_id,
      last_entry_item_id,
      last_received_at
    )
    values (
      v_row.supplier_id,
      v_row.product_id,
      v_row.input_uom_profile_id,
      lower(coalesce(nullif(v_row.input_unit_code, ''), nullif(v_row.unit, ''), 'un')),
      coalesce(nullif(v_row.unit, ''), nullif(v_row.input_unit_code, ''), 'un'),
      v_factor,
      lower(coalesce(nullif(v_row.stock_unit_code, ''), nullif(v_row.input_unit_code, ''), 'un')),
      coalesce(nullif(v_row.currency, ''), 'COP'),

      round(v_norm.net_unit_cost, 6),
      round(v_norm.gross_unit_cost, 6),
      round(v_norm.stock_unit_cost, 6),

      round(v_norm.net_total_cost / nullif(v_input_qty, 0), 6),
      round(v_norm.gross_total_cost / nullif(v_input_qty, 0), 6),
      round(v_norm.net_total_cost / nullif(v_stock_qty, 0), 6),

      round(v_input_qty, 6),
      round(v_stock_qty, 6),
      round(v_norm.net_total_cost, 6),
      round(v_norm.gross_total_cost, 6),
      1,

      v_row.entry_id,
      v_row.entry_item_id,
      coalesce(v_row.received_at, v_row.entry_created_at, now())
    )
    returning id into v_cost_id;
  else
    select
      c.total_input_qty + v_input_qty,
      c.total_stock_qty + v_stock_qty,
      c.total_net_cost + v_norm.net_total_cost,
      c.total_gross_cost + v_norm.gross_total_cost,
      c.samples_count + 1
    into
      v_total_input_qty,
      v_total_stock_qty,
      v_total_net_cost,
      v_total_gross_cost,
      v_samples_count
    from public.procurement_supplier_product_costs c
    where c.id = v_existing_id;

    update public.procurement_supplier_product_costs
    set
      input_unit_label = coalesce(nullif(v_row.unit, ''), nullif(v_row.input_unit_code, ''), input_unit_label),

      last_net_unit_cost = round(v_norm.net_unit_cost, 6),
      last_gross_unit_cost = round(v_norm.gross_unit_cost, 6),
      last_stock_unit_cost = round(v_norm.stock_unit_cost, 6),

      avg_net_unit_cost = round(v_total_net_cost / nullif(v_total_input_qty, 0), 6),
      avg_gross_unit_cost = round(v_total_gross_cost / nullif(v_total_input_qty, 0), 6),
      avg_stock_unit_cost = round(v_total_net_cost / nullif(v_total_stock_qty, 0), 6),

      total_input_qty = round(v_total_input_qty, 6),
      total_stock_qty = round(v_total_stock_qty, 6),
      total_net_cost = round(v_total_net_cost, 6),
      total_gross_cost = round(v_total_gross_cost, 6),
      samples_count = v_samples_count,

      last_entry_id = v_row.entry_id,
      last_entry_item_id = v_row.entry_item_id,
      last_received_at = coalesce(v_row.received_at, v_row.entry_created_at, now()),
      updated_at = now()
    where id = v_existing_id
    returning id into v_cost_id;
  end if;

  update public.inventory_entry_items
  set
    supplier_product_cost_id = v_cost_id,
    cost_input_mode = coalesce(cost_input_mode, v_norm.cost_input_mode),
    net_unit_cost = coalesce(nullif(net_unit_cost, 0), round(v_norm.net_unit_cost, 6)),
    gross_unit_cost = coalesce(nullif(gross_unit_cost, 0), round(v_norm.gross_unit_cost, 6)),
    stock_unit_cost = coalesce(nullif(stock_unit_cost, 0), round(v_norm.stock_unit_cost, 6)),
    net_total_cost = coalesce(nullif(net_total_cost, 0), round(v_norm.net_total_cost, 6)),
    gross_total_cost = coalesce(nullif(gross_total_cost, 0), round(v_norm.gross_total_cost, 6)),
    tax_amount = coalesce(nullif(tax_amount, 0), round(v_norm.gross_total_cost - v_norm.net_total_cost, 6))
  where id = v_row.entry_item_id;

  return v_cost_id;
end;
$$;


