CREATE OR REPLACE FUNCTION "public"."sync_restock_request_item_measurement_counts"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'storage', 'extensions'
    AS $$
declare
  v_mode text;
  v_aux_unit text;
begin
  select
    coalesce(measurement_mode, 'fixed_presentation'),
    nullif(btrim(aux_count_unit_code), '')
  into v_mode, v_aux_unit
  from public.product_inventory_profiles
  where product_id = new.product_id;

  if coalesce(v_mode, 'fixed_presentation') = 'count_with_weight' then
    new.aux_count_unit_code := coalesce(v_aux_unit, new.aux_count_unit_code, 'empaques');

    if tg_op = 'INSERT' then
      new.input_aux_count := coalesce(new.input_aux_count, new.requested_policy_qty);
      new.prepared_aux_count := coalesce(new.prepared_aux_count, new.input_aux_count);
      new.shipped_aux_count := coalesce(new.shipped_aux_count, new.prepared_aux_count, new.input_aux_count);
    else
      if new.input_aux_count is null then
        new.input_aux_count := coalesce(old.input_aux_count, new.requested_policy_qty);
      end if;

      if new.prepared_quantity is distinct from old.prepared_quantity
         and coalesce(new.prepared_quantity, 0) > 0
         and new.prepared_aux_count is null then
        new.prepared_aux_count := coalesce(old.prepared_aux_count, new.input_aux_count, new.requested_policy_qty);
      end if;

      if new.shipped_quantity is distinct from old.shipped_quantity
         and coalesce(new.shipped_quantity, 0) > 0
         and new.shipped_aux_count is null then
        new.shipped_aux_count := coalesce(old.shipped_aux_count, new.prepared_aux_count, new.input_aux_count, new.requested_policy_qty);
      end if;

      if new.received_quantity is distinct from old.received_quantity
         and coalesce(new.received_quantity, 0) > 0
         and new.received_aux_count is null then
        new.received_aux_count := coalesce(old.received_aux_count, new.shipped_aux_count, new.prepared_aux_count, new.input_aux_count);
      end if;
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_restock_request_item_measurement_counts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_restock_request_status_from_items"("p_request_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_request public.restock_requests%rowtype;
  v_has_items boolean := false;
  v_any_prepared boolean := false;
  v_any_shipped boolean := false;
  v_any_accounted boolean := false;
  v_all_shipped_fully_received boolean := true;
  v_next_status text := 'pending';
begin
  select *
  into v_request
  from public.restock_requests
  where id = p_request_id;

  if v_request.id is null then
    return null;
  end if;

  if v_request.status in ('cancelled', 'closed') then
    return v_request.status;
  end if;

  select
    count(*) > 0,
    bool_or(coalesce(prepared_quantity, 0) > 0),
    bool_or(coalesce(shipped_quantity, 0) > 0),
    bool_or(coalesce(received_quantity, 0) + coalesce(shortage_quantity, 0) > 0),
    bool_and(
      case
        when coalesce(shipped_quantity, 0) > 0
          then coalesce(received_quantity, 0) = coalesce(shipped_quantity, 0)
        else true
      end
    )
  into
    v_has_items,
    v_any_prepared,
    v_any_shipped,
    v_any_accounted,
    v_all_shipped_fully_received
  from public.restock_request_items
  where request_id = p_request_id;

  if not v_has_items then
    v_next_status := 'pending';
  elsif v_any_shipped then
    if coalesce(v_all_shipped_fully_received, false) then
      v_next_status := 'received';
    elsif v_any_accounted then
      v_next_status := 'partial';
    else
      v_next_status := 'in_transit';
    end if;
  elsif v_any_prepared then
    v_next_status := 'preparing';
  else
    v_next_status := 'pending';
  end if;

  update public.restock_requests
  set
    status = v_next_status,
    received_at = case
      when v_next_status in ('partial', 'received')
        then coalesce(received_at, now())
      else received_at
    end,
    status_updated_at = now()
  where id = p_request_id;

  return v_next_status;
end;
$$;


ALTER FUNCTION "public"."sync_restock_request_status_from_items"("p_request_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sync_restock_request_status_from_items"("p_request_id" "uuid") IS 'Recalcula el estado de una remisión con base en las cantidades preparadas, enviadas, recibidas y faltantes de sus líneas.';



