CREATE OR REPLACE FUNCTION "public"."update_order_gift_operational_state"("p_order_id" "uuid", "p_site_id" "uuid", "p_operation" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_permission boolean := false;
  v_operation text := lower(trim(coalesce(p_operation, '')));
  v_order public.orders%rowtype;
  v_gift public.order_gift_details%rowtype;
  v_now timestamptz := now();
  v_event_id uuid;
  v_snapshot jsonb;
begin
  if v_uid is null then
    raise exception 'authentication_required';
  end if;

  select public.has_permission('pulso.pos.main', p_site_id, null)
  into v_permission;

  if not coalesce(v_permission, false) then
    raise exception 'permission_denied';
  end if;

  select *
  into v_order
  from public.orders o
  where o.id = p_order_id
    and o.site_id = p_site_id
  for update;

  if v_order.id is null then
    raise exception 'order_not_found';
  end if;

  if not coalesce(v_order.is_gift, false) then
    raise exception 'order_is_not_gift';
  end if;

  select *
  into v_gift
  from public.order_gift_details g
  where g.order_id = p_order_id
  for update;

  if v_gift.id is null then
    raise exception 'gift_details_not_found';
  end if;

  if v_operation = 'mark_card_prepared' then
    if not v_gift.card_requested then
      raise exception 'gift_card_not_requested';
    end if;

    if v_gift.card_status = 'pending' then
      update public.order_gift_details
      set card_status = 'prepared',
          card_prepared_at = coalesce(card_prepared_at, v_now),
          card_prepared_by = coalesce(card_prepared_by, v_uid),
          updated_at = v_now
      where id = v_gift.id;
    end if;

  elsif v_operation = 'mark_card_included' then
    if not v_gift.card_requested then
      raise exception 'gift_card_not_requested';
    end if;

    if v_gift.card_status = 'pending' then
      raise exception 'gift_card_must_be_prepared_first';
    end if;

    if v_gift.card_status = 'prepared' then
      update public.order_gift_details
      set card_status = 'included',
          card_included_at = coalesce(card_included_at, v_now),
          card_included_by = coalesce(card_included_by, v_uid),
          updated_at = v_now
      where id = v_gift.id;
    end if;

  elsif v_operation = 'confirm_price_free_packaging' then
    if not v_gift.hide_prices then
      raise exception 'price_free_packaging_not_required';
    end if;

    if v_gift.price_free_packaging_confirmed_at is null then
      update public.order_gift_details
      set price_free_packaging_confirmed_at = v_now,
          price_free_packaging_confirmed_by = v_uid,
          updated_at = v_now
      where id = v_gift.id;
    end if;

  else
    raise exception 'invalid_gift_operation';
  end if;

  select *
  into v_gift
  from public.order_gift_details g
  where g.id = v_gift.id;

  v_snapshot := jsonb_strip_nulls(jsonb_build_object(
    'is_gift', true,
    'buyer_name', v_gift.buyer_name,
    'buyer_phone', v_gift.buyer_phone,
    'recipient_name', v_gift.recipient_name,
    'recipient_phone', v_gift.recipient_phone,
    'recipient_relationship', v_gift.recipient_relationship,
    'is_surprise', v_gift.is_surprise,
    'contact_policy', v_gift.contact_policy,
    'fallback_contact_policy', v_gift.fallback_contact_policy,
    'card_requested', v_gift.card_requested,
    'card_message', v_gift.card_message,
    'card_to', v_gift.card_to,
    'card_from', v_gift.card_from,
    'card_status', v_gift.card_status,
    'card_prepared_at', v_gift.card_prepared_at,
    'card_prepared_by', v_gift.card_prepared_by,
    'card_included_at', v_gift.card_included_at,
    'card_included_by', v_gift.card_included_by,
    'hide_prices', v_gift.hide_prices,
    'price_free_packaging_confirmed_at', v_gift.price_free_packaging_confirmed_at,
    'price_free_packaging_confirmed_by', v_gift.price_free_packaging_confirmed_by
  ));

  update public.orders
  set guest_info = coalesce(guest_info, '{}'::jsonb)
        || jsonb_build_object('gift', v_snapshot),
      updated_at = v_now
  where id = v_order.id;

  insert into public.order_status_events (
    order_id,
    site_id,
    changed_by,
    actor_type,
    operation,
    from_status,
    to_status,
    from_dispatch_status,
    to_dispatch_status,
    dispatch_partner,
    dispatch_reference,
    metadata
  )
  values (
    v_order.id,
    v_order.site_id,
    v_uid,
    'staff',
    v_operation,
    v_order.status,
    v_order.status,
    v_order.dispatch_status,
    v_order.dispatch_status,
    v_order.dispatch_partner,
    v_order.dispatch_reference,
    coalesce(p_metadata, '{}'::jsonb)
      || jsonb_build_object('gift_card_status', v_gift.card_status)
  )
  returning id into v_event_id;

  return jsonb_build_object(
    'ok', true,
    'event_id', v_event_id,
    'order_id', v_order.id,
    'operation', v_operation,
    'card_status', v_gift.card_status,
    'card_prepared_at', v_gift.card_prepared_at,
    'card_included_at', v_gift.card_included_at,
    'price_free_packaging_confirmed_at', v_gift.price_free_packaging_confirmed_at
  );
end;
$$;


ALTER FUNCTION "public"."update_order_gift_operational_state"("p_order_id" "uuid", "p_site_id" "uuid", "p_operation" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_order_operational_state"("p_order_id" "uuid", "p_site_id" "uuid", "p_operation" "text", "p_dispatch_partner" "text" DEFAULT NULL::"text", "p_dispatch_reference" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_order public.orders%rowtype;
  v_permission boolean := false;
  v_operation text := lower(trim(coalesce(p_operation, '')));
  v_from_status text;
  v_to_status text;
  v_from_dispatch text;
  v_to_dispatch text;
  v_partner text;
  v_reference text;
  v_event_id uuid;
  v_gift public.order_gift_details%rowtype;
  v_delivery_session public.order_delivery_sessions%rowtype;
begin
  if v_uid is null then
    raise exception 'authentication_required';
  end if;

  select public.has_permission('pulso.pos.main', p_site_id, null)
  into v_permission;

  if not coalesce(v_permission, false) then
    raise exception 'permission_denied';
  end if;

  select *
  into v_order
  from public.orders o
  where o.id = p_order_id
    and o.site_id = p_site_id
  for update;

  if v_order.id is null then
    raise exception 'order_not_found';
  end if;

  if v_operation <> 'mark_cancelled'
    and v_order.fulfillment_type = 'delivery'
    and coalesce(v_order.payment_status, 'unpaid') <> 'paid' then
    raise exception 'payment_not_approved';
  end if;

  if v_operation <> 'mark_cancelled'
    and coalesce(v_order.fulfillment_type, '') <> 'delivery'
    and coalesce(v_order.payment_status, 'unpaid') not in ('paid', 'not_required') then
    raise exception 'payment_not_allowed_for_operation';
  end if;

  if v_operation = 'mark_ready' and coalesce(v_order.is_gift, false) then
    select * into v_gift
    from public.order_gift_details g
    where g.order_id = v_order.id;

    if v_gift.id is null then raise exception 'gift_details_not_found'; end if;
    if v_gift.card_requested and v_gift.card_status <> 'included' then
      raise exception 'gift_card_checklist_incomplete';
    end if;
    if v_gift.hide_prices and v_gift.price_free_packaging_confirmed_at is null then
      raise exception 'gift_packaging_checklist_incomplete';
    end if;
  end if;

  v_from_status := coalesce(v_order.status, 'pending');
  v_from_dispatch := coalesce(v_order.dispatch_status, 'not_required');
  v_to_status := v_from_status;
  v_to_dispatch := v_from_dispatch;
  v_partner := v_order.dispatch_partner;
  v_reference := v_order.dispatch_reference;

  if v_operation = 'mark_preparing' then
    if v_from_status not in ('pending', 'confirmed') then raise exception 'invalid_transition:mark_preparing'; end if;
    v_to_status := 'preparing';

  elsif v_operation = 'mark_ready' then
    if v_from_status not in ('pending', 'confirmed', 'preparing') then raise exception 'invalid_transition:mark_ready'; end if;
    v_to_status := 'ready_for_dispatch';
    if v_order.fulfillment_type = 'delivery' and v_to_dispatch in ('not_required', 'pending', 'scheduled') then
      v_to_dispatch := 'pending';
    end if;

  elsif v_operation = 'mark_in_transit' then
    if v_order.fulfillment_type <> 'delivery' then raise exception 'invalid_fulfillment_for_in_transit'; end if;
    if v_from_status not in ('ready_for_dispatch', 'on_the_way', 'in_transit') then raise exception 'invalid_transition:mark_in_transit'; end if;
    v_to_status := 'on_the_way';
    v_to_dispatch := 'on_the_way';

  elsif v_operation = 'mark_delivered' then
    if v_from_status = 'cancelled' then raise exception 'invalid_transition:mark_delivered'; end if;

    if v_order.fulfillment_type = 'delivery' then
      select * into v_delivery_session
      from public.order_delivery_sessions
      where order_id = v_order.id;

      if v_delivery_session.id is null or v_delivery_session.status <> 'confirmed' then
        raise exception 'delivery_confirmation_required';
      end if;

      v_to_status := 'delivered';
      v_to_dispatch := 'delivered';
    else
      v_to_status := 'delivered';
      v_to_dispatch := 'not_required';
    end if;

  elsif v_operation = 'mark_cancelled' then
    if v_from_status = 'delivered' then raise exception 'invalid_transition:mark_cancelled'; end if;
    v_to_status := 'cancelled';
    v_to_dispatch := case when v_order.fulfillment_type = 'delivery' then 'cancelled' else 'not_required' end;

  elsif v_operation = 'assign_dispatch' then
    if v_order.fulfillment_type <> 'delivery' then raise exception 'invalid_fulfillment_for_assign_dispatch'; end if;
    if v_from_status in ('delivered', 'cancelled') then raise exception 'invalid_transition:assign_dispatch'; end if;
    if nullif(trim(coalesce(p_dispatch_partner, '')), '') is null
       and nullif(trim(coalesce(p_dispatch_reference, '')), '') is null then
      raise exception 'dispatch_partner_or_reference_required';
    end if;
    if nullif(trim(coalesce(p_dispatch_partner, '')), '') is not null then v_partner := trim(p_dispatch_partner); end if;
    if nullif(trim(coalesce(p_dispatch_reference, '')), '') is not null then v_reference := trim(p_dispatch_reference); end if;
    if v_to_dispatch in ('not_required', 'pending', 'scheduled') then v_to_dispatch := 'assigned'; end if;

  else
    raise exception 'invalid_operation';
  end if;

  update public.orders
  set status = v_to_status,
      dispatch_status = v_to_dispatch,
      dispatch_partner = v_partner,
      dispatch_reference = v_reference,
      delivered_at = case when v_to_status = 'delivered' then coalesce(delivered_at, now()) else delivered_at end,
      updated_at = now()
  where id = v_order.id;

  insert into public.order_status_events (
    order_id, site_id, changed_by, actor_type, operation,
    from_status, to_status, from_dispatch_status, to_dispatch_status,
    dispatch_partner, dispatch_reference, metadata
  ) values (
    v_order.id, v_order.site_id, v_uid, 'staff', v_operation,
    v_from_status, v_to_status, v_from_dispatch, v_to_dispatch,
    v_partner, v_reference, coalesce(p_metadata, '{}'::jsonb)
  ) returning id into v_event_id;

  return jsonb_build_object(
    'ok', true,
    'event_id', v_event_id,
    'order_id', v_order.id,
    'site_id', v_order.site_id,
    'operation', v_operation,
    'status', v_to_status,
    'dispatch_status', v_to_dispatch,
    'dispatch_partner', v_partner,
    'dispatch_reference', v_reference
  );
end;
$$;


ALTER FUNCTION "public"."update_order_operational_state"("p_order_id" "uuid", "p_site_id" "uuid", "p_operation" "text", "p_dispatch_partner" "text", "p_dispatch_reference" "text", "p_metadata" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_order_operational_state"("p_order_id" "uuid", "p_site_id" "uuid", "p_operation" "text", "p_dispatch_partner" "text", "p_dispatch_reference" "text", "p_metadata" "jsonb") IS 'Actualiza estado operativo de pedidos. Domicilio exige pago aprobado; recoger y en sitio permiten pago no requerido.';



CREATE OR REPLACE FUNCTION "public"."update_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'storage', 'extensions'
    AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_updated_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_app_screen_registry"("p_app_code" "text", "p_href" "text", "p_label" "text", "p_description" "text" DEFAULT NULL::"text", "p_icon" "text" DEFAULT NULL::"text", "p_suggested_group_key" "text" DEFAULT NULL::"text", "p_suggested_group_label" "text" DEFAULT NULL::"text", "p_suggested_group_order" integer DEFAULT NULL::integer, "p_suggested_sort_order" integer DEFAULT NULL::integer, "p_required_permission_code" "text" DEFAULT NULL::"text", "p_permission_name" "text" DEFAULT NULL::"text", "p_permission_description" "text" DEFAULT NULL::"text", "p_source_path" "text" DEFAULT NULL::"text", "p_sync_source" "text" DEFAULT 'scanner'::"text", "p_sync_hash" "text" DEFAULT NULL::"text", "p_navigation_kind" "text" DEFAULT 'menu'::"text", "p_is_menu_candidate" boolean DEFAULT true, "p_parent_href" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_app_code text := lower(btrim(p_app_code));
  v_href text := case
    when left(btrim(p_href), 1) = '/' then btrim(p_href)
    else '/' || btrim(p_href)
  end;
  v_item_key text;
  v_registry_id uuid;

  v_app_id uuid;
  v_permission_code_full text := null;
  v_permission_code_local text := null;
  v_navigation_kind text := coalesce(nullif(btrim(p_navigation_kind), ''), 'menu');
begin
  if v_app_code = '' then
    raise exception 'app_code_required';
  end if;

  if v_href = '/' then
    raise exception 'href_must_not_be_root';
  end if;

  if btrim(coalesce(p_label, '')) = '' then
    raise exception 'label_required';
  end if;

  if v_navigation_kind not in ('menu', 'submenu', 'detail', 'action', 'internal', 'auth', 'hidden') then
    v_navigation_kind := 'internal';
  end if;

  v_item_key := public._navigation_slugify(v_href);
  v_permission_code_full := nullif(btrim(coalesce(p_required_permission_code, '')), '');

  insert into public.app_screen_registry (
    app_code,
    item_key,
    label,
    description,
    href,
    icon,
    suggested_group_key,
    suggested_group_label,
    suggested_group_order,
    suggested_sort_order,
    required_permission_code,
    permission_name,
    permission_description,
    source_path,
    sync_source,
    sync_hash,
    navigation_kind,
    is_menu_candidate,
    parent_href,
    is_available,
    is_ignored,
    last_seen_at
  )
  values (
    v_app_code,
    v_item_key,
    btrim(p_label),
    nullif(btrim(coalesce(p_description, '')), ''),
    v_href,
    nullif(btrim(coalesce(p_icon, '')), ''),
    nullif(btrim(coalesce(p_suggested_group_key, '')), ''),
    nullif(btrim(coalesce(p_suggested_group_label, '')), ''),
    p_suggested_group_order,
    p_suggested_sort_order,
    v_permission_code_full,
    nullif(btrim(coalesce(p_permission_name, '')), ''),
    nullif(btrim(coalesce(p_permission_description, '')), ''),
    nullif(btrim(coalesce(p_source_path, '')), ''),
    nullif(btrim(coalesce(p_sync_source, '')), ''),
    nullif(btrim(coalesce(p_sync_hash, '')), ''),
    v_navigation_kind,
    coalesce(p_is_menu_candidate, true),
    nullif(btrim(coalesce(p_parent_href, '')), ''),
    true,
    false,
    now()
  )
  on conflict (app_code, href)
  do update set
    item_key = excluded.item_key,
    label = excluded.label,
    description = excluded.description,
    icon = excluded.icon,
    suggested_group_key = excluded.suggested_group_key,
    suggested_group_label = excluded.suggested_group_label,
    suggested_group_order = excluded.suggested_group_order,
    suggested_sort_order = excluded.suggested_sort_order,
    required_permission_code = excluded.required_permission_code,
    permission_name = excluded.permission_name,
    permission_description = excluded.permission_description,
    source_path = excluded.source_path,
    sync_source = excluded.sync_source,
    sync_hash = excluded.sync_hash,
    navigation_kind = excluded.navigation_kind,
    is_menu_candidate = excluded.is_menu_candidate,
    parent_href = excluded.parent_href,
    is_available = true,
    last_seen_at = now(),
    updated_at = now()
  returning id into v_registry_id;

  if v_permission_code_full is not null then
    select id
    into v_app_id
    from public.apps
    where code = v_app_code
    limit 1;

    if v_app_id is not null then
      if v_permission_code_full like v_app_code || '.%' then
        v_permission_code_local := substr(v_permission_code_full, length(v_app_code) + 2);
      else
        v_permission_code_local := v_permission_code_full;
      end if;

      insert into public.app_permissions (
        app_id,
        code,
        name,
        description,
        is_active
      )
      values (
        v_app_id,
        v_permission_code_local,
        coalesce(nullif(btrim(coalesce(p_permission_name, '')), ''), btrim(p_label)),
        coalesce(
          nullif(btrim(coalesce(p_permission_description, '')), ''),
          'Permite acceder a ' || btrim(p_label) || '.'
        ),
        true
      )
      on conflict (app_id, code)
      do update set
        name = coalesce(excluded.name, public.app_permissions.name),
        description = coalesce(excluded.description, public.app_permissions.description),
        is_active = true,
        updated_at = now();
    end if;
  end if;

  return v_registry_id;
end;
$$;


ALTER FUNCTION "public"."upsert_app_screen_registry"("p_app_code" "text", "p_href" "text", "p_label" "text", "p_description" "text", "p_icon" "text", "p_suggested_group_key" "text", "p_suggested_group_label" "text", "p_suggested_group_order" integer, "p_suggested_sort_order" integer, "p_required_permission_code" "text", "p_permission_name" "text", "p_permission_description" "text", "p_source_path" "text", "p_sync_source" "text", "p_sync_hash" "text", "p_navigation_kind" "text", "p_is_menu_candidate" boolean, "p_parent_href" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."upsert_app_screen_registry"("p_app_code" "text", "p_href" "text", "p_label" "text", "p_description" "text", "p_icon" "text", "p_suggested_group_key" "text", "p_suggested_group_label" "text", "p_suggested_group_order" integer, "p_suggested_sort_order" integer, "p_required_permission_code" "text", "p_permission_name" "text", "p_permission_description" "text", "p_source_path" "text", "p_sync_source" "text", "p_sync_hash" "text", "p_navigation_kind" "text", "p_is_menu_candidate" boolean, "p_parent_href" "text") IS 'Upserts a detected app screen into the global registry with navigation classification and creates its permission definition when possible.';



CREATE OR REPLACE FUNCTION "public"."upsert_driver_checkin_point"("p_code" "text", "p_name" "text", "p_latitude" numeric, "p_longitude" numeric, "p_radius_meters" integer DEFAULT 100, "p_address" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_site_id uuid;
begin
  if nullif(btrim(coalesce(p_code, '')), '') is null then
    raise exception 'p_code es requerido';
  end if;

  if nullif(btrim(coalesce(p_name, '')), '') is null then
    raise exception 'p_name es requerido';
  end if;

  if p_latitude is null or p_longitude is null then
    raise exception 'latitud y longitud son requeridas';
  end if;

  if coalesce(p_radius_meters, 0) <= 0 then
    raise exception 'p_radius_meters debe ser mayor a cero';
  end if;

  insert into public.sites (
    code,
    name,
    type,
    is_active,
    latitude,
    longitude,
    address,
    site_type,
    site_kind,
    checkin_radius_meters,
    is_public,
    operational_visibility
  ) values (
    lower(btrim(p_code)),
    btrim(p_name),
    'checkin_point',
    true,
    p_latitude,
    p_longitude,
    nullif(btrim(coalesce(p_address, '')), ''),
    'admin'::public.site_type,
    'vehicle_yard',
    p_radius_meters,
    false,
    'hidden'
  )
  on conflict (code) do update set
    name = excluded.name,
    type = excluded.type,
    is_active = true,
    latitude = excluded.latitude,
    longitude = excluded.longitude,
    address = excluded.address,
    site_type = excluded.site_type,
    site_kind = excluded.site_kind,
    checkin_radius_meters = excluded.checkin_radius_meters,
    is_public = false,
    operational_visibility = 'hidden'
  returning id into v_site_id;

  insert into public.site_attendance_policy (
    site_id,
    checkin_radius_meters,
    requires_geofence
  ) values (
    v_site_id,
    p_radius_meters,
    true
  )
  on conflict (site_id) do update set
    checkin_radius_meters = excluded.checkin_radius_meters,
    requires_geofence = true,
    updated_at = now();

  return v_site_id;
end;
$$;


ALTER FUNCTION "public"."upsert_driver_checkin_point"("p_code" "text", "p_name" "text", "p_latitude" numeric, "p_longitude" numeric, "p_radius_meters" integer, "p_address" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."upsert_driver_checkin_point"("p_code" "text", "p_name" "text", "p_latitude" numeric, "p_longitude" numeric, "p_radius_meters" integer, "p_address" "text") IS 'Crea/actualiza un site oculto para geocerca de recogida/devolucion de camioneta.';



CREATE OR REPLACE FUNCTION "public"."upsert_employee_site_operational_profile"("p_employee_id" "uuid", "p_site_id" "uuid", "p_default_operational_role" "text" DEFAULT NULL::"text", "p_default_checkin_site_id" "uuid" DEFAULT NULL::"uuid", "p_default_checkout_site_id" "uuid" DEFAULT NULL::"uuid", "p_is_active" boolean DEFAULT true, "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid;
  v_actor uuid;
begin
  if not (public.is_owner() or public.is_global_manager() or public.is_manager()) then
    raise exception 'Not authorized to manage employee operational profiles';
  end if;

  v_actor := auth.uid();

  insert into public.employee_site_operational_profiles (
    employee_id,
    site_id,
    default_operational_role,
    default_checkin_site_id,
    default_checkout_site_id,
    is_active,
    notes,
    created_by,
    updated_by
  )
  values (
    p_employee_id,
    p_site_id,
    nullif(btrim(coalesce(p_default_operational_role, '')), ''),
    p_default_checkin_site_id,
    p_default_checkout_site_id,
    coalesce(p_is_active, true),
    nullif(btrim(coalesce(p_notes, '')), ''),
    v_actor,
    v_actor
  )
  on conflict (employee_id, site_id)
  do update set
    default_operational_role = excluded.default_operational_role,
    default_checkin_site_id = excluded.default_checkin_site_id,
    default_checkout_site_id = excluded.default_checkout_site_id,
    is_active = excluded.is_active,
    notes = excluded.notes,
    updated_by = excluded.updated_by,
    updated_at = now()
  returning id into v_id;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."upsert_employee_site_operational_profile"("p_employee_id" "uuid", "p_site_id" "uuid", "p_default_operational_role" "text", "p_default_checkin_site_id" "uuid", "p_default_checkout_site_id" "uuid", "p_is_active" boolean, "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."upsert_employee_site_operational_profile"("p_employee_id" "uuid", "p_site_id" "uuid", "p_default_operational_role" "text", "p_default_checkin_site_id" "uuid", "p_default_checkout_site_id" "uuid", "p_is_active" boolean, "p_notes" "text") IS 'Creates or updates default operational role and geofence points for an employee at an operational site.';



CREATE OR REPLACE FUNCTION "public"."upsert_inventory_stock_by_location"("p_location_id" "uuid", "p_product_id" "uuid", "p_delta" numeric) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_site_id uuid;
  v_new_location_qty numeric := 0;
begin
  select site_id into v_site_id
  from public.inventory_locations
  where id = p_location_id;

  if v_site_id is null then
    raise exception 'location not found';
  end if;

  if not (
    public.has_permission('nexo.inventory.stock', v_site_id)
    or public.has_permission('nexo.inventory.remissions.prepare', v_site_id)
    or public.has_permission('nexo.inventory.remissions.receive', v_site_id)
    or public.has_permission('nexo.inventory.production_batches', v_site_id)
    or public.has_permission('nexo.inventory.entries', v_site_id)
    or public.has_permission('nexo.inventory.transfers', v_site_id)
  ) then
    raise exception 'permission denied';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_location_id::text || ':' || p_product_id::text, 0));

  insert into public.inventory_stock_by_location (location_id, product_id, current_qty, updated_at)
  values (p_location_id, p_product_id, p_delta, now())
  on conflict (location_id, product_id) do update
    set current_qty = public.inventory_stock_by_location.current_qty + excluded.current_qty,
        updated_at = now()
  returning current_qty into v_new_location_qty;

  if abs(coalesce(v_new_location_qty, 0)) <= 0.000001 then
    perform public.reconcile_zero_internal_positions_for_location_product(p_location_id, p_product_id);
  end if;
end;
$$;


ALTER FUNCTION "public"."upsert_inventory_stock_by_location"("p_location_id" "uuid", "p_product_id" "uuid", "p_delta" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_inventory_stock_by_uom_profile"("p_location_id" "uuid", "p_product_id" "uuid", "p_uom_profile_id" "uuid", "p_presentation_delta" numeric, "p_base_delta" numeric, "p_location_position_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_site_id uuid;
begin
  select checked.site_id
    into v_site_id
  from public.assert_inventory_uom_profile_stock_input(
    p_location_id,
    p_location_position_id,
    p_product_id,
    p_uom_profile_id,
    abs(coalesce(p_presentation_delta, 0)),
    abs(coalesce(p_base_delta, 0))
  ) checked;

  if not (
    public.has_permission('nexo.inventory.stock', v_site_id)
    or public.has_permission('nexo.inventory.entries', v_site_id)
    or public.has_permission('nexo.inventory.transfers', v_site_id)
    or public.has_permission('nexo.inventory.withdraw', v_site_id)
    or public.has_permission('nexo.inventory.remissions.prepare', v_site_id)
    or public.has_permission('nexo.inventory.remissions.receive', v_site_id)
  ) then
    raise exception 'permission denied';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_location_id::text || ':' || p_product_id::text || ':' || p_uom_profile_id::text || ':' || coalesce(p_location_position_id::text, ''), 0));

  if p_location_position_id is null then
    insert into public.inventory_stock_by_uom_profile (
      site_id,
      location_id,
      location_position_id,
      product_id,
      uom_profile_id,
      presentation_qty,
      base_qty,
      updated_at
    )
    values (
      v_site_id,
      p_location_id,
      null,
      p_product_id,
      p_uom_profile_id,
      coalesce(p_presentation_delta, 0),
      coalesce(p_base_delta, 0),
      now()
    )
    on conflict (location_id, product_id, uom_profile_id) where location_position_id is null do update
      set presentation_qty = public.inventory_stock_by_uom_profile.presentation_qty + excluded.presentation_qty,
          base_qty = public.inventory_stock_by_uom_profile.base_qty + excluded.base_qty,
          site_id = excluded.site_id,
          updated_at = now();
  else
    insert into public.inventory_stock_by_uom_profile (
      site_id,
      location_id,
      location_position_id,
      product_id,
      uom_profile_id,
      presentation_qty,
      base_qty,
      updated_at
    )
    values (
      v_site_id,
      p_location_id,
      p_location_position_id,
      p_product_id,
      p_uom_profile_id,
      coalesce(p_presentation_delta, 0),
      coalesce(p_base_delta, 0),
      now()
    )
    on conflict (location_id, location_position_id, product_id, uom_profile_id) where location_position_id is not null do update
      set presentation_qty = public.inventory_stock_by_uom_profile.presentation_qty + excluded.presentation_qty,
          base_qty = public.inventory_stock_by_uom_profile.base_qty + excluded.base_qty,
          site_id = excluded.site_id,
          updated_at = now();
  end if;

  if exists (
    select 1
    from public.inventory_stock_by_uom_profile stock
    where stock.location_id = p_location_id
      and stock.product_id = p_product_id
      and stock.uom_profile_id = p_uom_profile_id
      and (
        (p_location_position_id is null and stock.location_position_id is null)
        or stock.location_position_id = p_location_position_id
      )
      and (stock.presentation_qty < -0.000001 or stock.base_qty < -0.000001)
  ) then
    raise exception 'insufficient stock for uom profile';
  end if;
end;
$$;


ALTER FUNCTION "public"."upsert_inventory_stock_by_uom_profile"("p_location_id" "uuid", "p_product_id" "uuid", "p_uom_profile_id" "uuid", "p_presentation_delta" numeric, "p_base_delta" numeric, "p_location_position_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_operational_checkin_point"("p_code" "text", "p_name" "text", "p_latitude" numeric, "p_longitude" numeric, "p_radius_meters" integer DEFAULT 100, "p_address" "text" DEFAULT NULL::"text", "p_site_kind" "text" DEFAULT 'checkin_point'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid;
  v_site_kind text;
begin
  if not (public.is_owner() or public.is_global_manager() or public.is_manager()) then
    raise exception 'Not authorized to manage operational check-in points';
  end if;

  if nullif(btrim(coalesce(p_code, '')), '') is null then
    raise exception 'Point code is required';
  end if;

  if nullif(btrim(coalesce(p_name, '')), '') is null then
    raise exception 'Point name is required';
  end if;

  if p_latitude is null or p_longitude is null then
    raise exception 'Latitude and longitude are required';
  end if;

  v_site_kind := coalesce(nullif(btrim(p_site_kind), ''), 'checkin_point');

  insert into public.sites (
    code,
    name,
    type,
    site_type,
    site_kind,
    latitude,
    longitude,
    address,
    checkin_radius_meters,
    is_public,
    operational_visibility,
    is_active
  )
  values (
    btrim(p_code),
    btrim(p_name),
    'internal',
    'satellite',
    v_site_kind,
    p_latitude,
    p_longitude,
    nullif(btrim(coalesce(p_address, '')), ''),
    greatest(coalesce(p_radius_meters, 100), 1),
    false,
    'hidden',
    true
  )
  on conflict (code)
  do update set
    name = excluded.name,
    type = excluded.type,
    site_type = excluded.site_type,
    site_kind = excluded.site_kind,
    latitude = excluded.latitude,
    longitude = excluded.longitude,
    address = excluded.address,
    checkin_radius_meters = excluded.checkin_radius_meters,
    is_public = false,
    operational_visibility = 'hidden',
    is_active = true
  returning id into v_id;

  -- A technical geofence point must not be assigned as an operational site to employees.
  delete from public.employee_sites where site_id = v_id;

  update public.employee_settings
     set selected_site_id = null
   where selected_site_id = v_id;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."upsert_operational_checkin_point"("p_code" "text", "p_name" "text", "p_latitude" numeric, "p_longitude" numeric, "p_radius_meters" integer, "p_address" "text", "p_site_kind" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."upsert_operational_checkin_point"("p_code" "text", "p_name" "text", "p_latitude" numeric, "p_longitude" numeric, "p_radius_meters" integer, "p_address" "text", "p_site_kind" "text") IS 'Creates or updates a hidden physical geofence point for ANIMA check-in/check-out. It does not assign the point as an operational employee site.';



CREATE OR REPLACE FUNCTION "public"."upsert_site_operational_role"("p_site_id" "uuid", "p_area_id" "uuid", "p_role_code" "text", "p_is_default" boolean DEFAULT false, "p_is_active" boolean DEFAULT true) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid;
begin
  if p_site_id is null then
    raise exception 'site_id is required';
  end if;

  if nullif(trim(p_role_code), '') is null then
    raise exception 'role_code is required';
  end if;

  if not exists (
    select 1
    from public.operational_roles
    where code = p_role_code
      and is_active = true
  ) then
    raise exception 'Operational role % does not exist or is inactive', p_role_code;
  end if;

  if p_area_id is not null and not exists (
    select 1
    from public.areas
    where id = p_area_id
      and site_id = p_site_id
  ) then
    raise exception 'The selected area does not belong to the selected site';
  end if;

  if p_is_default then
    update public.site_operational_roles
    set
      is_default = false,
      updated_at = now()
    where site_id = p_site_id
      and (
        (area_id is null and p_area_id is null)
        or area_id = p_area_id
      );
  end if;

  select id
  into v_id
  from public.site_operational_roles
  where site_id = p_site_id
    and (
      (area_id is null and p_area_id is null)
      or area_id = p_area_id
    )
    and role_code = p_role_code
  limit 1;

  if v_id is null then
    insert into public.site_operational_roles (
      site_id,
      area_id,
      role_code,
      is_default,
      is_active
    )
    values (
      p_site_id,
      p_area_id,
      p_role_code,
      p_is_default,
      p_is_active
    )
    returning id into v_id;
  else
    update public.site_operational_roles
    set
      is_default = p_is_default,
      is_active = p_is_active,
      updated_at = now()
    where id = v_id;
  end if;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."upsert_site_operational_role"("p_site_id" "uuid", "p_area_id" "uuid", "p_role_code" "text", "p_is_default" boolean, "p_is_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."util_column_usage"("p_table" "regclass") RETURNS TABLE("column_name" "text", "non_null_count" bigint, "total_count" bigint, "pct_non_null" numeric)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'storage', 'extensions'
    AS $$
declare
  col record;
  total bigint;
begin
  execute format('select count(*) from %s', p_table) into total;

  for col in
    select a.attname as column_name
    from pg_attribute a
    where a.attrelid = p_table
      and a.attnum > 0
      and not a.attisdropped
  loop
    return query execute format(
      'select %L::text,
              count(%I)::bigint,
              %s::bigint,
              round((count(%I)::numeric / nullif(%s,0))*100, 2)
       from %s',
      col.column_name,
      col.column_name,
      total,
      col.column_name,
      total,
      p_table
    );
  end loop;
end $$;


ALTER FUNCTION "public"."util_column_usage"("p_table" "regclass") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_context_simulation_session_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if new.area_id is not null and not exists (
    select 1 from public.areas a
    where a.id = new.area_id and a.site_id = new.site_id and coalesce(a.is_active, true)
  ) then
    raise exception 'El área simulada no pertenece a la sede seleccionada.';
  end if;

  if nullif(btrim(coalesce(new.operational_role, '')), '') is not null and not exists (
    select 1 from public.site_operational_roles sor
    where sor.site_id = new.site_id
      and sor.role_code = btrim(new.operational_role)
      and coalesce(sor.is_active, true)
      and (sor.area_id is null or new.area_id is null or sor.area_id = new.area_id)
  ) then
    raise exception 'El rol operativo simulado no está habilitado para la sede/área seleccionada.';
  end if;

  new.updated_at := now();
  return new;
end;
$$;


ALTER FUNCTION "public"."validate_context_simulation_session_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_employee_site_operational_profile"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'storage', 'extensions'
    AS $$
declare
  v_site_visibility text;
  v_site_active boolean;
  v_checkin_active boolean;
  v_checkout_active boolean;
begin
  select s.operational_visibility, s.is_active
    into v_site_visibility, v_site_active
  from public.sites s
  where s.id = new.site_id;

  if coalesce(v_site_active, false) is distinct from true then
    raise exception 'Operational profile site must be an active site';
  end if;

  if coalesce(v_site_visibility, '') <> 'operational' then
    raise exception 'Operational profile site must have operational_visibility = operational';
  end if;

  if new.default_checkin_site_id is not null then
    select s.is_active into v_checkin_active
    from public.sites s
    where s.id = new.default_checkin_site_id;

    if coalesce(v_checkin_active, false) is distinct from true then
      raise exception 'Default check-in point must be an active site';
    end if;
  end if;

  if new.default_checkout_site_id is not null then
    select s.is_active into v_checkout_active
    from public.sites s
    where s.id = new.default_checkout_site_id;

    if coalesce(v_checkout_active, false) is distinct from true then
      raise exception 'Default check-out point must be an active site';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_employee_site_operational_profile"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_product_request_policy"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'storage', 'extensions'
    AS $$
declare
  v_stock_unit_code text;
  v_physical_profile record;
  v_request_family text;
  v_base_family text;
begin
  new.label := btrim(new.label);
  new.request_unit_code := lower(btrim(new.request_unit_code));
  new.base_unit_code := lower(btrim(new.base_unit_code));
  new.updated_at := now();

  select lower(coalesce(nullif(stock_unit_code, ''), nullif(unit, '')))
    into v_stock_unit_code
  from public.products
  where id = new.product_id;

  if v_stock_unit_code is null then
    raise exception 'El producto de la política no existe o no tiene unidad base.';
  end if;

  if new.base_unit_code <> v_stock_unit_code then
    raise exception 'La unidad base de la política (%) no coincide con la unidad base del producto (%).', new.base_unit_code, v_stock_unit_code;
  end if;

  if new.policy_kind = 'physical_presentation' then
    select id, product_id, input_unit_code, qty_in_input_unit, qty_in_stock_unit, is_active
      into v_physical_profile
    from public.product_uom_profiles
    where id = new.physical_uom_profile_id;

    if v_physical_profile.id is null
       or v_physical_profile.product_id <> new.product_id
       or v_physical_profile.is_active is false then
      raise exception 'La presentación física no existe, está inactiva o pertenece a otro producto.';
    end if;

    if v_physical_profile.qty_in_input_unit is null
       or v_physical_profile.qty_in_input_unit <= 0
       or v_physical_profile.qty_in_stock_unit is null
       or v_physical_profile.qty_in_stock_unit <= 0 then
      raise exception 'La presentación física tiene una equivalencia inválida.';
    end if;

    if round((v_physical_profile.qty_in_stock_unit / v_physical_profile.qty_in_input_unit)::numeric, 6)
       <> round(new.base_qty_per_request_unit, 6) then
      raise exception 'La equivalencia no coincide con la presentación física seleccionada.';
    end if;
  end if;

  if new.policy_kind = 'actual_quantity' then
    select family into v_request_family
    from public.inventory_units
    where code = new.request_unit_code and is_active = true;

    select family into v_base_family
    from public.inventory_units
    where code = new.base_unit_code and is_active = true;

    if v_request_family is null or v_base_family is null or v_request_family <> v_base_family then
      raise exception 'La política de cantidad real debe usar unidades activas de la misma familia.';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_product_request_policy"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_product_site_production_location"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_location_site_id uuid;
  v_location_type text;
  v_location_active boolean;
  v_area_kind text;
  v_area_active boolean;
  v_area_enabled_for_recipe boolean := false;
begin
  if new.production_location_id is null then
    return new;
  end if;

  select loc.site_id,
         loc.location_type,
         coalesce(loc.is_active, true),
         area.kind,
         coalesce(area.is_active, true)
    into v_location_site_id,
         v_location_type,
         v_location_active,
         v_area_kind,
         v_area_active
  from public.inventory_locations loc
  left join public.areas area on area.id = loc.area_id
  where loc.id = new.production_location_id;

  if v_location_site_id is null then
    raise exception 'production_location_id % does not exist', new.production_location_id;
  end if;

  if v_location_site_id <> new.site_id then
    raise exception 'production_location_id % does not belong to product site %', new.production_location_id, new.site_id;
  end if;

  if not coalesce(v_location_active, false) then
    raise exception 'production_location_id % must be active', new.production_location_id;
  end if;

  if v_area_kind is not null and coalesce(v_area_active, false) then
    select exists (
      select 1
      from public.site_area_purpose_rules rule
      where rule.site_id = new.site_id
        and rule.area_kind = v_area_kind
        and rule.purpose = 'production_recipe'
        and coalesce(rule.is_enabled, true) = true
    ) into v_area_enabled_for_recipe;
  end if;

  if coalesce(v_location_type, '') <> 'production'
     and not coalesce(v_area_enabled_for_recipe, false) then
    raise exception 'production_location_id % must be a production LOC or belong to an area enabled for production_recipe', new.production_location_id;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_product_site_production_location"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_product_site_production_route"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_input_site_id uuid;
  v_input_area_kind text;
  v_input_is_active boolean;
  v_output_site_id uuid;
  v_output_is_active boolean;
  v_position_site_id uuid;
  v_position_location_id uuid;
  v_position_is_active boolean;
begin
  select l.site_id, a.kind, coalesce(l.is_active, true)
    into v_input_site_id, v_input_area_kind, v_input_is_active
  from public.inventory_locations l
  left join public.areas a on a.id = l.area_id
  where l.id = new.input_location_id;

  if v_input_site_id is null then
    raise exception 'input_location_id no existe o no tiene sede: %', new.input_location_id;
  end if;

  if v_input_site_id <> new.site_id then
    raise exception 'input_location_id % no pertenece a site_id %', new.input_location_id, new.site_id;
  end if;

  if coalesce(v_input_is_active, false) = false then
    raise exception 'input_location_id % está inactivo', new.input_location_id;
  end if;

  if v_input_area_kind is distinct from new.area_kind then
    raise exception 'input_location_id % pertenece al área %, no al área %',
      new.input_location_id,
      coalesce(v_input_area_kind, '(sin área)'),
      new.area_kind;
  end if;

  if new.output_mode = 'order_fulfillment' then
    if new.output_location_id is not null or new.output_position_id is not null then
      raise exception 'order_fulfillment no debe tener output_location_id ni output_position_id';
    end if;
    return new;
  end if;

  if new.output_location_id is null then
    raise exception 'output_location_id es requerido cuando output_mode = %', new.output_mode;
  end if;

  select l.site_id, coalesce(l.is_active, true)
    into v_output_site_id, v_output_is_active
  from public.inventory_locations l
  where l.id = new.output_location_id;

  if v_output_site_id is null then
    raise exception 'output_location_id no existe o no tiene sede: %', new.output_location_id;
  end if;

  if v_output_site_id <> new.site_id then
    raise exception 'output_location_id % no pertenece a site_id %', new.output_location_id, new.site_id;
  end if;

  if coalesce(v_output_is_active, false) = false then
    raise exception 'output_location_id % está inactivo', new.output_location_id;
  end if;

  if new.output_position_id is not null then
    select p.site_id, p.location_id, p.is_active
      into v_position_site_id, v_position_location_id, v_position_is_active
    from public.inventory_location_positions p
    where p.id = new.output_position_id;

    if v_position_site_id is null then
      raise exception 'output_position_id no existe: %', new.output_position_id;
    end if;

    if v_position_site_id <> new.site_id then
      raise exception 'output_position_id % no pertenece a site_id %', new.output_position_id, new.site_id;
    end if;

    if v_position_location_id <> new.output_location_id then
      raise exception 'output_position_id % pertenece al LOC %, no al output_location_id %',
        new.output_position_id,
        v_position_location_id,
        new.output_location_id;
    end if;

    if coalesce(v_position_is_active, false) = false then
      raise exception 'output_position_id % está inactivo', new.output_position_id;
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_product_site_production_route"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_recipe_outputs"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_recipe record;
  v_pct_sum numeric;
  v_primary_count integer;
begin
  select id, product_id, site_id
    into v_recipe
  from public.recipe_cards
  where id = new.recipe_card_id;

  if v_recipe.id is null then
    raise exception 'recipe_card_id no existe';
  end if;

  if new.output_role = 'primary' and new.product_id is distinct from v_recipe.product_id then
    raise exception 'El output principal debe ser el producto principal de la receta.';
  end if;

  if new.output_role <> 'primary' and new.product_id = v_recipe.product_id then
    raise exception 'El producto principal no puede repetirse como coproducto.';
  end if;

  if new.cost_allocation_method = 'percentage' and new.cost_allocation_pct is null then
    raise exception 'Los outputs con costeo porcentual necesitan porcentaje.';
  end if;

  if new.destination_location_id is not null and not exists (
    select 1
    from public.inventory_locations loc
    where loc.id = new.destination_location_id
      and loc.site_id = v_recipe.site_id
      and coalesce(loc.is_active, true) = true
  ) then
    raise exception 'El LOC destino del output no pertenece a la sede de la receta.';
  end if;

  select count(*)
    into v_primary_count
  from public.recipe_outputs ro
  where ro.recipe_card_id = new.recipe_card_id
    and coalesce(ro.is_active, true)
    and ro.output_role = 'primary'
    and ro.id is distinct from new.id;

  if coalesce(new.is_active, true) and new.output_role = 'primary' then
    v_primary_count := v_primary_count + 1;
  end if;

  if v_primary_count > 1 then
    raise exception 'Solo puede haber un output principal activo por receta.';
  end if;

  select coalesce(sum(coalesce(ro.cost_allocation_pct, 0)), 0)
    into v_pct_sum
  from public.recipe_outputs ro
  where ro.recipe_card_id = new.recipe_card_id
    and ro.id is distinct from new.id
    and coalesce(ro.is_active, true)
    and ro.cost_allocation_method = 'percentage';

  if coalesce(new.is_active, true) and new.cost_allocation_method = 'percentage' then
    v_pct_sum := v_pct_sum + coalesce(new.cost_allocation_pct, 0);
  end if;

  if coalesce(new.is_active, true) and new.cost_allocation_method = 'percentage' and v_pct_sum > 100.000001 then
    raise exception 'La suma de porcentajes de outputs no puede superar 100%%.';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_recipe_outputs"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_recipe_site_use"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_recipe record;
  v_area_site_id uuid;
  v_source record;
  v_destination record;
begin
  select id, product_id
    into v_recipe
  from public.recipe_cards
  where id = new.recipe_card_id;

  if v_recipe.id is null then
    raise exception 'recipe_card_id no existe';
  end if;

  new.product_id := v_recipe.product_id;

  if new.usage_mode = 'no_inventory' then
    new.area_id := null;
    new.source_location_id := null;
    new.destination_location_id := null;
  end if;

  if new.usage_mode in ('sells_finished_good', 'stored_for_production', 'prepares_to_order') then
    new.destination_location_id := null;
  end if;

  if new.area_id is not null then
    select site_id into v_area_site_id
    from public.areas
    where id = new.area_id;

    if v_area_site_id is distinct from new.site_id then
      raise exception 'El area no pertenece a la sede del uso.';
    end if;
  end if;

  if new.source_location_id is not null then
    select site_id, area_id, is_active
      into v_source
    from public.inventory_locations
    where id = new.source_location_id;

    if v_source.site_id is null then
      raise exception 'El LOC origen seleccionado no existe.';
    end if;
    if v_source.site_id is distinct from new.site_id then
      raise exception 'El LOC origen no pertenece a la sede del uso.';
    end if;
    if coalesce(v_source.is_active, false) is false then
      raise exception 'El LOC origen no esta activo.';
    end if;

    if new.usage_mode in ('sells_finished_good', 'stored_for_production') then
      new.area_id := v_source.area_id;
    elsif new.area_id is not null and v_source.area_id is distinct from new.area_id then
      raise exception 'El LOC origen no pertenece al area del uso.';
    end if;
  end if;

  if new.destination_location_id is not null then
    select site_id, area_id, is_active
      into v_destination
    from public.inventory_locations
    where id = new.destination_location_id;

    if v_destination.site_id is null then
      raise exception 'El LOC destino seleccionado no existe.';
    end if;
    if v_destination.site_id is distinct from new.site_id then
      raise exception 'El LOC destino no pertenece a la sede del uso.';
    end if;
    if coalesce(v_destination.is_active, false) is false then
      raise exception 'El LOC destino no esta activo.';
    end if;
    if new.usage_mode = 'produces_here'
      and new.area_id is not null
      and v_destination.area_id is not null
      and v_destination.area_id is distinct from new.area_id then
      raise exception 'El LOC destino no pertenece al area del uso.';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_recipe_site_use"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_restock_request_item_pick"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_item record;
  v_request record;
  v_location record;
  v_position record;
  v_profile record;
begin
  select
    item.id,
    item.request_id,
    item.product_id,
    item.quantity
    into v_item
  from public.restock_request_items item
  where item.id = new.item_id;

  if not found then
    raise exception 'restock request item not found';
  end if;

  if new.request_id <> v_item.request_id then
    raise exception 'pick request_id does not match item request_id';
  end if;

  if new.product_id <> v_item.product_id then
    raise exception 'pick product_id does not match item product_id';
  end if;

  select req.id, req.from_site_id, req.status
    into v_request
  from public.restock_requests req
  where req.id = new.request_id;

  if not found then
    raise exception 'restock request not found';
  end if;

  if v_request.from_site_id is null then
    raise exception 'restock request has no origin site';
  end if;

  select loc.id, loc.site_id
    into v_location
  from public.inventory_locations loc
  where loc.id = new.source_location_id
    and coalesce(loc.is_active, true) = true;

  if not found then
    raise exception 'active source LOC not found';
  end if;

  if v_location.site_id <> v_request.from_site_id then
    raise exception 'source LOC does not belong to restock request origin site';
  end if;

  if new.source_location_position_id is not null then
    select pos.id, pos.location_id, pos.site_id
      into v_position
    from public.inventory_location_positions pos
    where pos.id = new.source_location_position_id
      and pos.location_id = new.source_location_id
      and coalesce(pos.is_active, true) = true;

    if not found then
      raise exception 'active internal position not found for source LOC';
    end if;
  end if;

  if new.uom_profile_id is not null then
    select profile.id, profile.product_id, profile.is_active
      into v_profile
    from public.product_uom_profiles profile
    where profile.id = new.uom_profile_id;

    if not found or v_profile.product_id <> new.product_id then
      raise exception 'uom profile does not belong to pick product';
    end if;

    if coalesce(v_profile.is_active, false) <> true then
      raise exception 'uom profile is inactive';
    end if;

    perform 1
    from public.assert_inventory_uom_profile_stock_input(
      new.source_location_id,
      new.source_location_position_id,
      new.product_id,
      new.uom_profile_id,
      new.presentation_qty,
      new.base_qty
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_restock_request_item_pick"() OWNER TO "postgres";


