CREATE OR REPLACE FUNCTION "public"."value_closed_restock_request"("p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_request record;
  v_item record;
  v_price record;

  v_now timestamptz := now();
  v_price_at timestamptz;
  v_effective_closed_at timestamptz;
  v_seller_cost_center_id uuid;
  v_buyer_cost_center_id uuid;

  v_billable_count integer := 0;
  v_missing_price_count integer := 0;
  v_variance_count integer := 0;

  v_received_qty numeric := 0;
  v_pricing_qty numeric := 0;
  v_total numeric := 0;
  v_line_total numeric := 0;
  v_unit_code text;

  v_is_service_role boolean := false;
  v_permission_ok boolean := false;
begin
  select r.*
  into v_request
  from public.restock_requests r
  where r.id = p_request_id
  for update;

  if not found then
    raise exception 'request_not_found';
  end if;

  v_is_service_role :=
    current_user = 'service_role'
    or current_setting('request.jwt.claim.role', true) = 'service_role';

  v_permission_ok :=
    v_is_service_role
    or public.has_permission('nexo.internal_invoices.generate')
    or public.has_permission('nexo.internal_invoices.issue')
    or public.has_permission('nexo.inventory.remissions.all_sites')
    or public.has_permission('nexo.inventory.remissions.prepare', v_request.from_site_id)
    or public.has_permission('nexo.inventory.remissions.receive', v_request.to_site_id)
    or is_owner()
    or is_global_manager();

  if not v_permission_ok then
    raise exception 'permission_denied_internal_billing';
  end if;

  if v_request.internal_pos_document_id is not null
     or v_request.pricing_status in ('invoiced', 'credited') then
    return jsonb_build_object(
      'request_id', p_request_id,
      'pricing_status', v_request.pricing_status,
      'message', 'already_invoiced_or_credited'
    );
  end if;

  v_seller_cost_center_id := coalesce(
    v_request.seller_cost_center_id,
    public.get_site_cost_center(v_request.from_site_id)
  );
  v_buyer_cost_center_id := coalesce(
    v_request.buyer_cost_center_id,
    public.get_site_cost_center(v_request.to_site_id)
  );

  v_effective_closed_at := coalesce(
    v_request.closed_at,
    case when v_request.status in ('received', 'closed') then v_request.received_at end,
    case when v_request.status in ('received', 'closed') then v_request.status_updated_at end,
    case when v_request.status in ('received', 'closed') then v_now end
  );
  v_price_at := coalesce(v_effective_closed_at, v_now);

  if v_request.status not in ('closed', 'received') then
    update public.restock_requests
    set
      pricing_mode = 'internal_transfer',
      pricing_status = 'pending_close',
      seller_cost_center_id = v_seller_cost_center_id,
      buyer_cost_center_id = v_buyer_cost_center_id,
      priced_at = null
    where id = p_request_id;

    return jsonb_build_object(
      'request_id', p_request_id,
      'pricing_status', 'pending_close',
      'message', 'request_is_not_received'
    );
  end if;

  if v_effective_closed_at is null then
    update public.restock_requests
    set
      pricing_mode = 'internal_transfer',
      pricing_status = 'pending_close',
      seller_cost_center_id = v_seller_cost_center_id,
      buyer_cost_center_id = v_buyer_cost_center_id,
      priced_at = null
    where id = p_request_id;

    return jsonb_build_object(
      'request_id', p_request_id,
      'pricing_status', 'pending_close',
      'message', 'missing_received_or_closed_at'
    );
  end if;

  if v_seller_cost_center_id is null or v_buyer_cost_center_id is null then
    update public.restock_requests
    set
      pricing_mode = 'internal_transfer',
      pricing_status = 'pending_price',
      seller_cost_center_id = v_seller_cost_center_id,
      buyer_cost_center_id = v_buyer_cost_center_id,
      closed_at = coalesce(closed_at, v_effective_closed_at),
      priced_at = null
    where id = p_request_id;

    return jsonb_build_object(
      'request_id', p_request_id,
      'pricing_status', 'pending_price',
      'message', 'missing_cost_center',
      'seller_cost_center_id', v_seller_cost_center_id,
      'buyer_cost_center_id', v_buyer_cost_center_id
    );
  end if;

  -- Crea diferencias cuando lo recibido no coincide con lo enviado.
  insert into public.internal_transfer_variances (
    remission_id,
    remission_item_id,
    product_id,
    expected_qty,
    dispatched_qty,
    received_qty,
    variance_qty,
    unit_code,
    variance_type,
    reason,
    financial_treatment,
    status,
    created_at,
    updated_at
  )
  select
    p_request_id,
    i.id,
    i.product_id,
    coalesce(i.quantity, 0),
    coalesce(i.shipped_quantity, 0),
    coalesce(i.received_quantity, 0),
    abs(coalesce(i.shipped_quantity, 0) - coalesce(i.received_quantity, 0)),
    coalesce(nullif(btrim(i.stock_unit_code), ''), nullif(btrim(i.unit), ''), nullif(btrim(i.input_unit_code), ''), 'un'),
    case
      when coalesce(i.received_quantity, 0) > coalesce(i.shipped_quantity, 0) then 'overage'
      else 'shortage'
    end,
    'Diferencia detectada automaticamente al valorizar la remision.',
    'pending',
    'pending',
    v_now,
    v_now
  from public.restock_request_items i
  where i.request_id = p_request_id
    and abs(coalesce(i.shipped_quantity, 0) - coalesce(i.received_quantity, 0)) > 0
    and not exists (
      select 1
      from public.internal_transfer_variances v
      where v.remission_item_id = i.id
        and v.status <> 'cancelled'
    );

  select count(*)
  into v_variance_count
  from public.internal_transfer_variances v
  where v.remission_id = p_request_id
    and v.status not in ('approved', 'cancelled');

  if v_variance_count > 0 then
    update public.restock_requests
    set
      pricing_mode = 'internal_transfer',
      pricing_status = 'pending_variance_resolution',
      seller_cost_center_id = v_seller_cost_center_id,
      buyer_cost_center_id = v_buyer_cost_center_id,
      closed_at = coalesce(closed_at, v_effective_closed_at),
      priced_at = null
    where id = p_request_id;

    return jsonb_build_object(
      'request_id', p_request_id,
      'pricing_status', 'pending_variance_resolution',
      'pending_variances', v_variance_count
    );
  end if;

  for v_item in
    select i.*
    from public.restock_request_items i
    where i.request_id = p_request_id
    order by i.created_at asc, i.id asc
  loop
    v_received_qty := coalesce(v_item.received_quantity, 0);
    v_unit_code := coalesce(
      nullif(btrim(v_item.input_unit_code), ''),
      nullif(btrim(v_item.stock_unit_code), ''),
      nullif(btrim(v_item.unit), ''),
      'un'
    );

    if v_received_qty <= 0 then
      update public.restock_request_items
      set
        transfer_unit_price = 0,
        transfer_currency = 'COP',
        transfer_total = 0,
        internal_price_list_id = null,
        internal_price_list_item_id = null,
        priced_at = v_now
      where id = v_item.id;

      continue;
    end if;

    v_billable_count := v_billable_count + 1;

    -- Si la línea fue solicitada con presentación física, se cobra en esa presentación.
    -- Ejemplo: cantidad base 4000 ml, input_qty 2 potes, recibido 2000 ml => pricing_qty 1 pote.
    if v_item.input_uom_profile_id is not null
       and coalesce(v_item.input_qty, 0) > 0
       and coalesce(v_item.quantity, 0) > 0 then
      v_pricing_qty := round((v_received_qty / v_item.quantity) * v_item.input_qty, 6);
    else
      v_pricing_qty := v_received_qty;
    end if;

    select *
    into v_price
    from public.resolve_internal_transfer_price_for_profile(
      v_item.product_id,
      v_seller_cost_center_id,
      v_buyer_cost_center_id,
      v_request.to_site_id,
      v_item.input_uom_profile_id,
      v_unit_code,
      v_price_at
    );

    if not found then
      v_missing_price_count := v_missing_price_count + 1;

      update public.restock_request_items
      set
        transfer_unit_price = null,
        transfer_currency = 'COP',
        transfer_total = null,
        internal_price_list_id = null,
        internal_price_list_item_id = null,
        priced_at = null
      where id = v_item.id;

      continue;
    end if;

    v_line_total := round(v_pricing_qty * v_price.unit_price, 2);
    v_total := v_total + v_line_total;

    update public.restock_request_items
    set
      transfer_unit_price = v_price.unit_price,
      transfer_currency = v_price.currency,
      transfer_total = v_line_total,
      internal_price_list_id = v_price.price_list_id,
      internal_price_list_item_id = v_price.price_list_item_id,
      priced_at = v_now
    where id = v_item.id;
  end loop;

  if v_missing_price_count > 0 then
    update public.restock_requests
    set
      pricing_mode = 'internal_transfer',
      pricing_status = 'pending_price',
      seller_cost_center_id = v_seller_cost_center_id,
      buyer_cost_center_id = v_buyer_cost_center_id,
      closed_at = coalesce(closed_at, v_effective_closed_at),
      priced_at = null
    where id = p_request_id;

    return jsonb_build_object(
      'request_id', p_request_id,
      'pricing_status', 'pending_price',
      'billable_lines', v_billable_count,
      'missing_price_lines', v_missing_price_count
    );
  end if;

  if v_billable_count = 0 then
    update public.restock_requests
    set
      pricing_mode = 'internal_transfer',
      pricing_status = 'not_applicable',
      seller_cost_center_id = v_seller_cost_center_id,
      buyer_cost_center_id = v_buyer_cost_center_id,
      closed_at = coalesce(closed_at, v_effective_closed_at),
      priced_at = v_now
    where id = p_request_id;

    return jsonb_build_object(
      'request_id', p_request_id,
      'pricing_status', 'not_applicable',
      'billable_lines', 0,
      'total', 0
    );
  end if;

  update public.restock_requests
  set
    pricing_mode = 'internal_transfer',
    pricing_status = 'ready_to_invoice',
    seller_cost_center_id = v_seller_cost_center_id,
    buyer_cost_center_id = v_buyer_cost_center_id,
    closed_at = coalesce(closed_at, v_effective_closed_at),
    priced_at = v_now
  where id = p_request_id;

  return jsonb_build_object(
    'request_id', p_request_id,
    'pricing_status', 'ready_to_invoice',
    'billable_lines', v_billable_count,
    'missing_price_lines', 0,
    'total', v_total
  );
end;
$$;


ALTER FUNCTION "public"."value_closed_restock_request"("p_request_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."value_closed_restock_request"("p_request_id" "uuid") IS 'Values a received/closed restock request for internal billing. Uses input_uom_profile_id to resolve internal price by presentation and stores transfer_* as financial snapshot.';



CREATE OR REPLACE FUNCTION "public"."value_closed_restock_requests_for_cutoff"("p_cutoff_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_request record;
  v_result jsonb;
  v_status text;

  v_processed integer := 0;
  v_ready integer := 0;
  v_pending_price integer := 0;
  v_pending_variance integer := 0;
  v_pending_close integer := 0;
  v_not_applicable integer := 0;
  v_other integer := 0;
begin
  for v_request in
    select r.id
    from public.restock_requests r
    where r.status in ('closed', 'received')
      and coalesce(r.closed_at, r.received_at) is not null
      and coalesce(r.closed_at, r.received_at) <= p_cutoff_at
      and r.internal_pos_document_id is null
      and r.pricing_status not in ('invoiced', 'credited')
    order by coalesce(r.closed_at, r.received_at) asc, r.id asc
  loop
    v_result := public.value_closed_restock_request(v_request.id);
    v_status := coalesce(v_result->>'pricing_status', 'unknown');
    v_processed := v_processed + 1;

    if v_status = 'ready_to_invoice' then
      v_ready := v_ready + 1;
    elsif v_status = 'pending_price' then
      v_pending_price := v_pending_price + 1;
    elsif v_status = 'pending_variance_resolution' then
      v_pending_variance := v_pending_variance + 1;
    elsif v_status = 'pending_close' then
      v_pending_close := v_pending_close + 1;
    elsif v_status = 'not_applicable' then
      v_not_applicable := v_not_applicable + 1;
    else
      v_other := v_other + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'cutoff_at', p_cutoff_at,
    'processed', v_processed,
    'ready_to_invoice', v_ready,
    'pending_price', v_pending_price,
    'pending_variance_resolution', v_pending_variance,
    'pending_close', v_pending_close,
    'not_applicable', v_not_applicable,
    'other', v_other
  );
end;
$$;


ALTER FUNCTION "public"."value_closed_restock_requests_for_cutoff"("p_cutoff_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."value_closed_restock_requests_for_cutoff"("p_cutoff_at" timestamp with time zone) IS 'Values all received/closed, non-invoiced restock requests up to a cutoff. Uses coalesce(closed_at, received_at) because v1 closes operationally on received.';



CREATE OR REPLACE FUNCTION "public"."verify_employee_kiosk_pin"("p_employee_id" "uuid", "p_pin" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  v_pin text := btrim(coalesce(p_pin, ''));
  v_hash text;
  v_legacy_pin text;
begin
  if p_employee_id is null or v_pin = '' then
    return false;
  end if;

  select pin_code_hash, pin_code
  into v_hash, v_legacy_pin
  from public.employees
  where id = p_employee_id
    and is_active is true;

  if v_hash is not null and v_hash = crypt(v_pin, v_hash) then
    return true;
  end if;

  if v_hash is null and v_legacy_pin is not null and v_legacy_pin = v_pin then
    update public.employees
    set pin_code_hash = crypt(v_pin, gen_salt('bf')),
        pin_code = null
    where id = p_employee_id;
    return true;
  end if;

  return false;
end;
$$;


ALTER FUNCTION "public"."verify_employee_kiosk_pin"("p_employee_id" "uuid", "p_pin" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."verify_shared_device_action_signature"("p_signature_id" "uuid", "p_app_code" "text", "p_action_code" "text", "p_target_table" "text" DEFAULT NULL::"text", "p_target_id" "uuid" DEFAULT NULL::"uuid", "p_consume" boolean DEFAULT false) RETURNS TABLE("signature_id" "uuid", "actor_employee_id" "uuid", "actor_shift_id" "uuid", "shared_device_id" "uuid", "site_id" "uuid", "area_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_sig public.shared_device_actor_signatures%rowtype;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;

  select * into v_sig
  from public.shared_device_actor_signatures s
  where s.id = p_signature_id
    and s.auth_user_id = auth.uid()
    and s.app_code = p_app_code
    and s.action_code = p_action_code
    and (s.expires_at is null or s.expires_at >= now())
    and (p_target_table is null or s.target_table is null or s.target_table = p_target_table)
    and (p_target_id is null or s.target_id is null or s.target_id = p_target_id)
  limit 1;

  if v_sig.id is null then
    raise exception 'INVALID_OR_EXPIRED_SHARED_DEVICE_SIGNATURE' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.shared_operational_devices d
    where d.id = v_sig.shared_device_id
      and d.auth_user_id = auth.uid()
      and d.is_active
      and d.activation_status = 'active'
  ) then
    raise exception 'ACTIVE_SHARED_DEVICE_REQUIRED' using errcode = '28000';
  end if;

  if p_consume then
    update public.shared_device_actor_signatures
    set expires_at = least(coalesce(expires_at, now()), now())
    where id = v_sig.id;
  end if;

  return query select
    v_sig.id,
    v_sig.actor_employee_id,
    v_sig.actor_shift_id,
    v_sig.shared_device_id,
    v_sig.site_id,
    v_sig.area_id;
end;
$$;


ALTER FUNCTION "public"."verify_shared_device_action_signature"("p_signature_id" "uuid", "p_app_code" "text", "p_action_code" "text", "p_target_table" "text", "p_target_id" "uuid", "p_consume" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."verify_shared_device_action_signature"("p_signature_id" "uuid", "p_app_code" "text", "p_action_code" "text", "p_target_table" "text", "p_target_id" "uuid", "p_consume" boolean) IS 'Verifica que una firma de dispositivo compartido pertenece al auth.uid actual, no expiro y coincide con app/accion/target.';



CREATE OR REPLACE FUNCTION "public"."viso_accounting_dashboard"("p_site_id" "uuid" DEFAULT NULL::"uuid", "p_month" "date" DEFAULT CURRENT_DATE) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_month_start date := date_trunc('month', coalesce(p_month, current_date))::date;
  v_month_end date := (date_trunc('month', coalesce(p_month, current_date)) + interval '1 month')::date;
  v_result jsonb;
begin
  if not public.has_permission('viso.access') then
    raise exception 'permission denied';
  end if;

  with site_scope as (
    select s.id, s.name, s.code
    from public.sites s
    where s.is_active = true
      and (p_site_id is null or s.id = p_site_id)
  ),
  primary_supplier as (
    select distinct on (ps.product_id)
      ps.product_id,
      ps.supplier_id,
      sup.name as supplier_name,
      coalesce(ps.purchase_tax_rate, 0) as iva_rate,
      coalesce(ps.purchase_icui_rate, 0) as icui_rate
    from public.product_suppliers ps
    left join public.suppliers sup on sup.id = ps.supplier_id
    order by ps.product_id, ps.is_primary desc, ps.created_at desc
  ),
  inventory_lines as (
    select
      ss.id as site_id,
      ss.name as site_name,
      p.id as product_id,
      p.name as product_name,
      p.sku,
      p.unit,
      iss.current_qty,
      coalesce(nullif(iss.avg_unit_cost, 0), nullif(p.cost, 0), 0) as unit_cost,
      greatest(iss.current_qty, 0) * coalesce(nullif(iss.avg_unit_cost, 0), nullif(p.cost, 0), 0) as stock_value,
      greatest(iss.current_qty, 0) * coalesce(nullif(iss.avg_unit_cost, 0), nullif(p.cost, 0), 0) * coalesce(ps.iva_rate, 0) / 100.0 as iva_exposure,
      greatest(iss.current_qty, 0) * coalesce(nullif(iss.avg_unit_cost, 0), nullif(p.cost, 0), 0) * coalesce(ps.icui_rate, 0) / 100.0 as icui_exposure,
      coalesce(ps.iva_rate, 0) as iva_rate,
      coalesce(ps.icui_rate, 0) as icui_rate
    from public.inventory_stock_by_site iss
    join site_scope ss on ss.id = iss.site_id
    join public.products p on p.id = iss.product_id
    left join primary_supplier ps on ps.product_id = iss.product_id
  ),
  month_receipt_lines as (
    select
      ie.site_id,
      coalesce(iei.line_total_cost, iei.stock_unit_cost * iei.quantity_received, p.cost * iei.quantity_received, 0) as net_amount,
      coalesce(ps.iva_rate, 0) as iva_rate,
      coalesce(ps.icui_rate, 0) as icui_rate
    from public.inventory_entries ie
    join site_scope ss on ss.id = ie.site_id
    join public.inventory_entry_items iei on iei.entry_id = ie.id
    join public.products p on p.id = iei.product_id
    left join primary_supplier ps on ps.product_id = iei.product_id
    where coalesce(ie.received_at, ie.created_at) >= v_month_start::timestamptz
      and coalesce(ie.received_at, ie.created_at) < v_month_end::timestamptz
      and coalesce(ie.status, '') not in ('cancelled', 'void', 'deleted')
  ),
  purchase_order_lines as (
    select
      po.site_id,
      coalesce(poi.line_total, poi.unit_cost * coalesce(poi.quantity_received, poi.quantity_ordered), 0) as committed_amount
    from public.purchase_orders po
    join site_scope ss on ss.id = po.site_id
    join public.purchase_order_items poi on poi.purchase_order_id = po.id
    where po.created_at >= v_month_start::timestamptz
      and po.created_at < v_month_end::timestamptz
      and coalesce(po.status, '') not in ('cancelled', 'void', 'deleted')
  ),
  inventory_summary as (
    select
      coalesce(sum(stock_value), 0) as total_value,
      coalesce(sum(current_qty) filter (where current_qty > 0), 0) as positive_qty,
      count(*) filter (where current_qty > 0) as stock_rows,
      count(distinct product_id) filter (where current_qty > 0) as products_with_stock,
      count(*) filter (where current_qty > 0 and unit_cost = 0) as rows_missing_cost,
      count(*) filter (where current_qty < 0) as negative_stock_rows,
      coalesce(sum(iva_exposure), 0) as iva_exposure,
      coalesce(sum(icui_exposure), 0) as icui_exposure
    from inventory_lines
  ),
  receipt_summary as (
    select
      coalesce(sum(net_amount), 0) as net_amount,
      coalesce(sum(net_amount * iva_rate / 100.0), 0) as iva_amount,
      coalesce(sum(net_amount * icui_rate / 100.0), 0) as icui_amount,
      count(*) as line_count
    from month_receipt_lines
  ),
  po_summary as (
    select
      coalesce(sum(committed_amount), 0) as committed_amount,
      count(*) as line_count
    from purchase_order_lines
  )
  select jsonb_build_object(
    'period', jsonb_build_object(
      'month_start', v_month_start,
      'month_end', v_month_end
    ),
    'summary', jsonb_build_object(
      'inventory_value', inv.total_value,
      'inventory_positive_qty', inv.positive_qty,
      'stock_rows', inv.stock_rows,
      'products_with_stock', inv.products_with_stock,
      'products_missing_cost', inv.rows_missing_cost,
      'negative_stock_rows', inv.negative_stock_rows,
      'inventory_estimated_iva', inv.iva_exposure,
      'inventory_estimated_icui', inv.icui_exposure,
      'inventory_estimated_tax', inv.iva_exposure + inv.icui_exposure,
      'month_receipts_net', rec.net_amount,
      'month_receipts_iva', rec.iva_amount,
      'month_receipts_icui', rec.icui_amount,
      'month_receipts_tax', rec.iva_amount + rec.icui_amount,
      'month_receipts_gross', rec.net_amount + rec.iva_amount + rec.icui_amount,
      'month_receipt_lines', rec.line_count,
      'month_purchase_orders_committed', po.committed_amount,
      'month_purchase_order_lines', po.line_count
    ),
    'inventory_by_site', coalesce((
      select jsonb_agg(row_to_json(x)::jsonb order by x.inventory_value desc)
      from (
        select
          site_id,
          site_name,
          coalesce(sum(stock_value), 0) as inventory_value,
          count(distinct product_id) filter (where current_qty > 0) as products,
          count(*) filter (where current_qty > 0 and unit_cost = 0) as missing_cost_rows
        from inventory_lines
        group by site_id, site_name
      ) x
    ), '[]'::jsonb),
    'top_inventory_products', coalesce((
      select jsonb_agg(row_to_json(x)::jsonb order by x.stock_value desc)
      from (
        select
          site_name,
          product_id,
          product_name,
          sku,
          unit,
          current_qty,
          unit_cost,
          stock_value,
          iva_rate,
          icui_rate
        from inventory_lines
        where stock_value > 0
        order by stock_value desc
        limit 12
      ) x
    ), '[]'::jsonb),
    'tax_by_site', coalesce((
      select jsonb_agg(row_to_json(x)::jsonb order by x.estimated_tax desc)
      from (
        select
          ss.id as site_id,
          ss.name as site_name,
          coalesce(sum(ml.net_amount * ml.iva_rate / 100.0), 0) as iva,
          coalesce(sum(ml.net_amount * ml.icui_rate / 100.0), 0) as icui,
          coalesce(sum(ml.net_amount * (ml.iva_rate + ml.icui_rate) / 100.0), 0) as estimated_tax
        from site_scope ss
        left join month_receipt_lines ml on ml.site_id = ss.id
        group by ss.id, ss.name
      ) x
    ), '[]'::jsonb)
  )
  into v_result
  from inventory_summary inv
  cross join receipt_summary rec
  cross join po_summary po;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."viso_accounting_dashboard"("p_site_id" "uuid", "p_month" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."viso_enforce_monthly_schedule_publish_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_month_start date;
  v_month_end date;
  v_existing_minutes integer := 0;
  v_new_minutes integer := 0;
  v_total_minutes integer := 0;
  v_limit_minutes constant integer := 11160;
  v_employee_label text;
begin
  -- La regla solo se activa cuando el registro queda publicado.
  -- Cancelar o convertir un turno en descanso siempre debe poder reducir horas.
  if new.published_at is null
    or coalesce(new.status, '') = 'cancelled'
    or coalesce(new.shift_kind, 'laboral') = 'descanso'
  then
    return new;
  end if;

  v_month_start := date_trunc('month', new.shift_date)::date;
  v_month_end := (v_month_start + interval '1 month')::date;

  select coalesce(
    sum(
      case
        when coalesce(es.shift_kind, 'laboral') = 'descanso'
          or coalesce(es.status, '') = 'cancelled'
        then 0
        else greatest(
          0,
          floor(extract(epoch from (es.end_time - es.start_time)) / 60)::integer
          - greatest(coalesce(es.break_minutes, 0), 0)
        )
      end
    ),
    0
  )::integer
  into v_existing_minutes
  from public.employee_shifts es
  where es.employee_id = new.employee_id
    and es.shift_date >= v_month_start
    and es.shift_date < v_month_end
    and (tg_op = 'INSERT' or es.id <> new.id);

  v_new_minutes := case
    when coalesce(new.shift_kind, 'laboral') = 'descanso'
      or coalesce(new.status, '') = 'cancelled'
    then 0
    else greatest(
      0,
      floor(extract(epoch from (new.end_time - new.start_time)) / 60)::integer
      - greatest(coalesce(new.break_minutes, 0), 0)
    )
  end;

  v_total_minutes := v_existing_minutes + v_new_minutes;

  if v_total_minutes > v_limit_minutes then
    select coalesce(e.full_name, e.alias, e.id::text)
    into v_employee_label
    from public.employees e
    where e.id = new.employee_id;

    raise exception using
      errcode = 'P0001',
      message = format(
        'No se puede publicar: %s acumula %s horas en %s y el máximo permitido es 186 horas. Corrige los borradores del mes.',
        coalesce(v_employee_label, new.employee_id::text),
        round(v_total_minutes::numeric / 60, 1),
        to_char(v_month_start, 'YYYY-MM')
      );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."viso_enforce_monthly_schedule_publish_limit"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."viso_enforce_monthly_schedule_publish_limit"() IS 'Impide publicar turnos cuando el plan mensual completo del trabajador supera 186 horas. Permite mantener el exceso en borrador para corrección.';



CREATE OR REPLACE FUNCTION "talento"."advance_application_stage"("p_application_id" "uuid", "p_new_stage" "talento"."stage_code", "p_reason_code" "text" DEFAULT NULL::"text", "p_public_note" "text" DEFAULT NULL::"text", "p_internal_note" "text" DEFAULT NULL::"text", "p_actor_id" "uuid" DEFAULT "auth"."uid"(), "p_force" boolean DEFAULT false) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'talento', 'public'
    AS $$
declare
  v_current_stage talento.stage_code;
  v_current_status talento.application_status;
  v_new_status talento.application_status;
  v_current_rank integer;
  v_new_rank integer;
  v_has_completed_interview boolean;
  v_has_pending_required_items boolean;
begin
  if p_new_stage = 'handoff' then
    raise exception 'Use transfer_candidate_to_employee() for handoff stage';
  end if;

  select a.current_stage_code, a.status
    into v_current_stage, v_current_status
  from talento.applications a
  where a.id = p_application_id
  for update;

  if v_current_stage is null then
    raise exception 'Application not found';
  end if;

  if v_current_status in ('hired', 'rejected', 'withdrawn', 'expired') and not p_force then
    raise exception 'Cannot advance a terminal application';
  end if;

  if v_current_stage = p_new_stage and not p_force then
    return p_application_id;
  end if;

  v_current_rank := talento.stage_rank(v_current_stage);
  v_new_rank := talento.stage_rank(p_new_stage);

  if v_new_rank < v_current_rank and not p_force then
    raise exception 'Backward stage transition requires force=true';
  end if;

  if p_new_stage in ('medical', 'offer') and not p_force then
    select exists (
      select 1
      from talento.interviews i
      where i.application_id = p_application_id
        and i.status = 'completed'
    ) into v_has_completed_interview;

    if not coalesce(v_has_completed_interview, false) then
      raise exception 'Completed interview required before moving to %', p_new_stage;
    end if;
  end if;

  if p_new_stage = 'preboarding' and not p_force then
    select exists (
      select 1
      from talento.application_requirements r
      where r.application_id = p_application_id
        and r.is_required = true
        and r.status in ('pending', 'rejected')
    ) into v_has_pending_required_items;

    if coalesce(v_has_pending_required_items, false) then
      raise exception 'Required items must be approved before preboarding';
    end if;
  end if;

  v_new_status := talento.status_for_stage(p_new_stage);

  update talento.application_stage_history
     set exited_at = now()
   where application_id = p_application_id
     and exited_at is null;

  update talento.applications
     set current_stage_code = p_new_stage,
         status = v_new_status,
         last_stage_changed_at = now()
   where id = p_application_id;

  insert into talento.application_stage_history (
    application_id,
    stage_code,
    status,
    entered_at,
    changed_by,
    reason_code,
    public_note,
    internal_note
  )
  values (
    p_application_id,
    p_new_stage,
    v_new_status,
    now(),
    p_actor_id,
    p_reason_code,
    p_public_note,
    p_internal_note
  );

  perform talento.log_application_event(
    p_application_id,
    'application_stage_changed',
    'internal_user',
    p_actor_id,
    jsonb_build_object(
      'from_stage', v_current_stage,
      'to_stage', p_new_stage,
      'from_status', v_current_status,
      'to_status', v_new_status,
      'reason_code', p_reason_code,
      'forced', p_force
    )
  );

  return p_application_id;
end
$$;


ALTER FUNCTION "talento"."advance_application_stage"("p_application_id" "uuid", "p_new_stage" "talento"."stage_code", "p_reason_code" "text", "p_public_note" "text", "p_internal_note" "text", "p_actor_id" "uuid", "p_force" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "talento"."bootstrap_my_candidate"("p_first_name" "text" DEFAULT NULL::"text", "p_last_name" "text" DEFAULT NULL::"text", "p_phone" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'talento', 'public'
    AS $$
declare
  v_auth_user_id uuid := auth.uid();
  v_claims jsonb := coalesce(auth.jwt(), '{}'::jsonb);
  v_metadata jsonb := coalesce(v_claims -> 'user_metadata', v_claims -> 'raw_user_meta_data', '{}'::jsonb);
  v_email text := nullif(lower(trim(coalesce(v_claims ->> 'email', ''))), '');
  v_phone text := nullif(
    trim(
      coalesce(
        p_phone,
        v_claims ->> 'phone',
        v_metadata ->> 'phone',
        ''
      )
    ),
    ''
  );
  v_first_name text := nullif(
    trim(
      coalesce(
        p_first_name,
        v_metadata ->> 'first_name',
        v_metadata ->> 'firstName',
        ''
      )
    ),
    ''
  );
  v_last_name text := nullif(
    trim(
      coalesce(
        p_last_name,
        v_metadata ->> 'last_name',
        v_metadata ->> 'lastName',
        ''
      )
    ),
    ''
  );
  v_candidate_id uuid;
  v_conflict_candidate_id uuid;
begin
  if v_auth_user_id is null then
    raise exception 'bootstrap_my_candidate() requires an authenticated user';
  end if;

  if v_email is null then
    raise exception 'Authenticated user email is required to bootstrap talento.candidates';
  end if;

  if v_first_name is null then
    v_first_name := split_part(v_email, '@', 1);
  end if;

  if v_last_name is null then
    v_last_name := 'Pendiente';
  end if;

  select c.id
    into v_candidate_id
    from talento.candidates c
   where c.auth_user_id = v_auth_user_id
   limit 1;

  select c.id
    into v_conflict_candidate_id
    from talento.candidates c
   where lower(c.email) = v_email
     and c.auth_user_id is not null
     and c.auth_user_id <> v_auth_user_id
   limit 1;

  if v_conflict_candidate_id is not null then
    raise exception 'The email % is already linked to another candidate account', v_email;
  end if;

  if v_candidate_id is null then
    select c.id
      into v_candidate_id
      from talento.candidates c
     where lower(c.email) = v_email
       and (c.auth_user_id is null or c.auth_user_id = v_auth_user_id)
     order by c.created_at asc
     limit 1;
  end if;

  if v_candidate_id is null then
    insert into talento.candidates (
      auth_user_id,
      email,
      phone,
      first_name,
      last_name,
      status
    )
    values (
      v_auth_user_id,
      v_email,
      v_phone,
      v_first_name,
      v_last_name,
      'active'
    )
    returning id into v_candidate_id;
  else
    update talento.candidates
       set auth_user_id = v_auth_user_id,
           email = v_email,
           phone = coalesce(v_phone, talento.candidates.phone),
           first_name = coalesce(v_first_name, talento.candidates.first_name),
           last_name = coalesce(v_last_name, talento.candidates.last_name),
           updated_at = now()
     where id = v_candidate_id;
  end if;

  insert into talento.candidate_profiles (candidate_id)
  values (v_candidate_id)
  on conflict (candidate_id) do nothing;

  return v_candidate_id;
end;
$$;


ALTER FUNCTION "talento"."bootstrap_my_candidate"("p_first_name" "text", "p_last_name" "text", "p_phone" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "talento"."bootstrap_my_candidate"("p_first_name" "text", "p_last_name" "text", "p_phone" "text") IS 'Creates or binds the authenticated auth user to talento.candidates and ensures candidate_profiles exists.';



CREATE OR REPLACE FUNCTION "talento"."confirm_interview"("p_interview_id" "uuid", "p_public_note" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'talento', 'public'
    AS $$
declare
  v_auth_user_id uuid := auth.uid();
  v_application_id uuid;
  v_status talento.interview_status;
begin
  if v_auth_user_id is null then
    raise exception 'Authentication required';
  end if;

  select i.application_id, i.status
    into v_application_id, v_status
  from talento.interviews i
  join talento.applications a
    on a.id = i.application_id
  where i.id = p_interview_id
    and a.candidate_id = talento.current_candidate_id()
  for update of i;

  if v_application_id is null then
    raise exception 'Interview not found for current candidate';
  end if;

  if v_status = 'confirmed' then
    return p_interview_id;
  end if;

  if v_status <> 'scheduled' then
    raise exception 'Only scheduled interviews can be confirmed';
  end if;

  update talento.interviews
     set status = 'confirmed',
         confirmed_at = now(),
         public_note = coalesce(p_public_note, public_note)
   where id = p_interview_id;

  perform talento.log_application_event(
    v_application_id,
    'interview_confirmed',
    'candidate',
    v_auth_user_id,
    jsonb_build_object(
      'interview_id', p_interview_id,
      'public_note', p_public_note
    )
  );

  return p_interview_id;
end
$$;


ALTER FUNCTION "talento"."confirm_interview"("p_interview_id" "uuid", "p_public_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "talento"."current_candidate_id"() RETURNS "uuid"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'talento', 'public', 'auth', 'storage', 'extensions'
    AS $$
  select c.id
  from talento.candidates c
  where c.auth_user_id = auth.uid()
  limit 1
$$;


ALTER FUNCTION "talento"."current_candidate_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "talento"."handoff_to_anima"("p_application_id" "uuid", "p_target_site_id" "uuid", "p_target_role" "text", "p_actor_id" "uuid" DEFAULT "auth"."uid"(), "p_area_id" "uuid" DEFAULT NULL::"uuid", "p_full_name_override" "text" DEFAULT NULL::"text", "p_selected_site_id" "uuid" DEFAULT NULL::"uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'talento', 'public'
    AS $$
declare
  v_candidate_id uuid;
  v_candidate_auth_user_id uuid;
  v_first_name text;
  v_last_name text;
  v_full_name text;
  v_existing_employee_id uuid;
  v_has_pending_preboarding boolean;
  v_selected_site_id uuid;
begin
  select a.candidate_id
    into v_candidate_id
  from talento.applications a
  where a.id = p_application_id
  for update;

  if v_candidate_id is null then
    raise exception 'Application not found';
  end if;

  if exists (
    select 1
    from talento.candidate_employee_links l
    where l.application_id = p_application_id
  ) then
    raise exception 'Application already transferred';
  end if;

  select c.auth_user_id, c.first_name, c.last_name
    into v_candidate_auth_user_id, v_first_name, v_last_name
  from talento.candidates c
  where c.id = v_candidate_id;

  if v_candidate_auth_user_id is null then
    raise exception 'Candidate has no auth_user_id; cannot provision employee';
  end if;

  if not exists (
    select 1
    from public.sites s
    where s.id = p_target_site_id
  ) then
    raise exception 'Target site does not exist';
  end if;

  if not exists (
    select 1
    from public.roles r
    where r.code = p_target_role
      and coalesce(r.is_active, true) = true
  ) then
    raise exception 'Target role does not exist or is inactive';
  end if;

  if p_area_id is not null and not exists (
    select 1
    from public.areas a
    where a.id = p_area_id
      and a.site_id = p_target_site_id
      and coalesce(a.is_active, true) = true
  ) then
    raise exception 'Area does not exist or does not belong to target site';
  end if;

  select exists (
    select 1
    from talento.preboarding_tasks t
    where t.application_id = p_application_id
      and t.status in ('pending', 'rejected')
  ) into v_has_pending_preboarding;

  if coalesce(v_has_pending_preboarding, false) then
    raise exception 'Pending preboarding tasks prevent handoff';
  end if;

  v_full_name := coalesce(nullif(btrim(p_full_name_override), ''), concat_ws(' ', v_first_name, v_last_name));
  v_selected_site_id := coalesce(p_selected_site_id, p_target_site_id);

  select e.id
    into v_existing_employee_id
  from public.employees e
  where e.id = v_candidate_auth_user_id;

  insert into public.employees (
    id,
    site_id,
    role,
    full_name,
    is_active,
    joined_at,
    updated_at,
    area_id
  ) values (
    v_candidate_auth_user_id,
    p_target_site_id,
    p_target_role,
    v_full_name,
    true,
    now(),
    now(),
    p_area_id
  )
  on conflict (id) do update
  set site_id = excluded.site_id,
      role = excluded.role,
      full_name = excluded.full_name,
      is_active = true,
      updated_at = now(),
      area_id = excluded.area_id;

  update public.employee_sites
     set is_primary = false
   where employee_id = v_candidate_auth_user_id
     and site_id <> p_target_site_id;

  insert into public.employee_sites (
    employee_id,
    site_id,
    is_primary,
    is_active
  ) values (
    v_candidate_auth_user_id,
    p_target_site_id,
    true,
    true
  )
  on conflict (employee_id, site_id) do update
  set is_primary = true,
      is_active = true;

  insert into public.employee_settings (
    employee_id,
    selected_site_id,
    selected_area_id,
    updated_at
  ) values (
    v_candidate_auth_user_id,
    v_selected_site_id,
    p_area_id,
    now()
  )
  on conflict (employee_id) do update
  set selected_site_id = excluded.selected_site_id,
      selected_area_id = excluded.selected_area_id,
      updated_at = now();

  update talento.application_stage_history
     set exited_at = now()
   where application_id = p_application_id
     and exited_at is null;

  update talento.applications
     set current_stage_code = 'handoff',
         status = 'hired',
         last_stage_changed_at = now(),
         is_primary_active = false
   where id = p_application_id;

  insert into talento.application_stage_history (
    application_id,
    stage_code,
    status,
    entered_at,
    changed_by,
    public_note,
    internal_note
  ) values (
    p_application_id,
    'handoff',
    'hired',
    now(),
    p_actor_id,
    'Aprobado para ingreso.',
    coalesce(p_notes, 'Provisioned into ANIMA employee domain.')
  );

  insert into talento.candidate_employee_links (
    candidate_id,
    application_id,
    employee_id,
    transferred_at,
    transferred_by,
    notes
  ) values (
    v_candidate_id,
    p_application_id,
    v_candidate_auth_user_id,
    now(),
    p_actor_id,
    p_notes
  );

  perform talento.log_application_event(
    p_application_id,
    'application_handoff_to_anima',
    'internal_user',
    p_actor_id,
    jsonb_build_object(
      'employee_id', v_candidate_auth_user_id,
      'target_site_id', p_target_site_id,
      'target_role', p_target_role,
      'existing_employee', v_existing_employee_id is not null,
      'selected_site_id', v_selected_site_id,
      'area_id', p_area_id,
      'notes', p_notes
    )
  );

  return v_candidate_auth_user_id;
end
$$;


ALTER FUNCTION "talento"."handoff_to_anima"("p_application_id" "uuid", "p_target_site_id" "uuid", "p_target_role" "text", "p_actor_id" "uuid", "p_area_id" "uuid", "p_full_name_override" "text", "p_selected_site_id" "uuid", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "talento"."log_application_event"("p_application_id" "uuid", "p_event_type" "text", "p_actor_type" "text", "p_actor_id" "uuid" DEFAULT "auth"."uid"(), "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'talento', 'public'
    AS $$
  insert into talento.application_events (
    application_id,
    event_type,
    actor_type,
    actor_id,
    payload
  )
  values (
    p_application_id,
    p_event_type,
    p_actor_type,
    p_actor_id,
    coalesce(p_payload, '{}'::jsonb)
  );
$$;


ALTER FUNCTION "talento"."log_application_event"("p_application_id" "uuid", "p_event_type" "text", "p_actor_type" "text", "p_actor_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "talento"."respond_to_offer"("p_application_id" "uuid", "p_decision" "talento"."offer_status", "p_public_note" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'talento', 'public'
    AS $$
declare
  v_auth_user_id uuid := auth.uid();
  v_candidate_id uuid;
  v_offer_status talento.offer_status;
  v_application_stage talento.stage_code;
  v_offer_id uuid;
begin
  if v_auth_user_id is null then
    raise exception 'Authentication required';
  end if;

  if p_decision not in ('accepted', 'rejected_by_candidate') then
    raise exception 'Invalid offer decision';
  end if;

  select o.id, a.candidate_id, o.status, a.current_stage_code
    into v_offer_id, v_candidate_id, v_offer_status, v_application_stage
  from talento.offers o
  join talento.applications a
    on a.id = o.application_id
  where a.id = p_application_id
    and a.candidate_id = talento.current_candidate_id()
  for update of o, a;

  if v_offer_id is null then
    raise exception 'Offer not found for current candidate';
  end if;

  if v_offer_status <> 'pending' then
    raise exception 'Offer already has a recorded response';
  end if;

  update talento.offers
     set status = p_decision,
         candidate_response_at = now(),
         public_note = coalesce(p_public_note, public_note)
   where id = v_offer_id;

  if p_decision = 'rejected_by_candidate' then
    update talento.application_stage_history
       set exited_at = now()
     where application_id = p_application_id
       and exited_at is null;

    update talento.applications
       set status = 'withdrawn',
           is_primary_active = false,
           last_stage_changed_at = now()
     where id = p_application_id;

    insert into talento.application_stage_history (
      application_id,
      stage_code,
      status,
      entered_at,
      changed_by,
      reason_code,
      public_note,
      internal_note
    )
    values (
      p_application_id,
      v_application_stage,
      'withdrawn',
      now(),
      v_auth_user_id,
      'candidate_rejected_offer',
      coalesce(p_public_note, 'El candidato rechazo la oferta.'),
      'Offer rejected by candidate via respond_to_offer().'
    );
  end if;

  perform talento.log_application_event(
    p_application_id,
    case when p_decision = 'accepted' then 'offer_accepted' else 'offer_rejected_by_candidate' end,
    'candidate',
    v_auth_user_id,
    jsonb_build_object(
      'offer_id', v_offer_id,
      'decision', p_decision,
      'public_note', p_public_note
    )
  );

  return p_application_id;
end
$$;


ALTER FUNCTION "talento"."respond_to_offer"("p_application_id" "uuid", "p_decision" "talento"."offer_status", "p_public_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "talento"."review_candidate_document"("p_document_id" "uuid", "p_status" "talento"."document_status", "p_rejection_reason" "text" DEFAULT NULL::"text", "p_actor_id" "uuid" DEFAULT "auth"."uid"()) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'talento', 'public'
    AS $$
declare
  v_application_id uuid;
  v_candidate_id uuid;
begin
  if p_status not in ('in_review', 'approved', 'rejected') then
    raise exception 'Invalid review status: %', p_status;
  end if;

  update talento.candidate_documents d
     set status = p_status,
         reviewed_at = now(),
         reviewed_by = p_actor_id,
         rejection_reason = case when p_status = 'rejected' then p_rejection_reason else null end
   where d.id = p_document_id
  returning d.application_id, d.candidate_id into v_application_id, v_candidate_id;

  if v_candidate_id is null then
    raise exception 'Document not found';
  end if;

  if v_application_id is not null then
    perform talento.log_application_event(
      v_application_id,
      'document_reviewed',
      'internal_user',
      p_actor_id,
      jsonb_build_object(
        'document_id', p_document_id,
        'status', p_status,
        'rejection_reason', p_rejection_reason
      )
    );
  end if;

  return p_document_id;
end
$$;


ALTER FUNCTION "talento"."review_candidate_document"("p_document_id" "uuid", "p_status" "talento"."document_status", "p_rejection_reason" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "talento"."schedule_interview"("p_application_id" "uuid", "p_scheduled_at" timestamp with time zone, "p_format" "text", "p_location" "text" DEFAULT NULL::"text", "p_meeting_url" "text" DEFAULT NULL::"text", "p_public_note" "text" DEFAULT NULL::"text", "p_internal_note" "text" DEFAULT NULL::"text", "p_actor_id" "uuid" DEFAULT "auth"."uid"()) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'talento', 'public'
    AS $$
declare
  v_interview_id uuid;
  v_current_stage talento.stage_code;
begin
  select current_stage_code
    into v_current_stage
  from talento.applications
  where id = p_application_id
  for update;

  if v_current_stage is null then
    raise exception 'Application not found';
  end if;

  if talento.stage_rank(v_current_stage) < talento.stage_rank('interview') then
    perform talento.advance_application_stage(
      p_application_id,
      'interview',
      'interview_scheduled',
      'Entrevista agendada.',
      'Moved to interview by schedule_interview().',
      p_actor_id,
      false
    );
  end if;

  insert into talento.interviews (
    application_id,
    scheduled_at,
    format,
    location,
    meeting_url,
    status,
    public_note,
    internal_note
  )
  values (
    p_application_id,
    p_scheduled_at,
    p_format,
    p_location,
    p_meeting_url,
    'scheduled',
    p_public_note,
    p_internal_note
  )
  returning id into v_interview_id;

  perform talento.log_application_event(
    p_application_id,
    'interview_scheduled',
    'internal_user',
    p_actor_id,
    jsonb_build_object(
      'interview_id', v_interview_id,
      'scheduled_at', p_scheduled_at,
      'format', p_format,
      'location', p_location,
      'meeting_url', p_meeting_url
    )
  );

  return v_interview_id;
end
$$;


ALTER FUNCTION "talento"."schedule_interview"("p_application_id" "uuid", "p_scheduled_at" timestamp with time zone, "p_format" "text", "p_location" "text", "p_meeting_url" "text", "p_public_note" "text", "p_internal_note" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "talento"."set_primary_application"("p_application_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'talento', 'public'
    AS $$
declare
  v_candidate_id uuid;
  v_auth_user_id uuid;
begin
  v_auth_user_id := auth.uid();
  if v_auth_user_id is null then
    raise exception 'Not authenticated';
  end if;

  select a.candidate_id
    into v_candidate_id
  from talento.applications a
  join talento.candidates c on c.id = a.candidate_id
  where a.id = p_application_id
    and c.auth_user_id = v_auth_user_id;

  if v_candidate_id is null then
    raise exception 'Application not found for current candidate';
  end if;

  update talento.applications
     set is_primary_active = false
   where candidate_id = v_candidate_id
     and is_primary_active = true;

  update talento.applications
     set is_primary_active = true
   where id = p_application_id;

  perform talento.log_application_event(
    p_application_id,
    'application_primary_selected',
    'candidate',
    v_auth_user_id,
    jsonb_build_object('application_id', p_application_id)
  );

  return p_application_id;
end
$$;


ALTER FUNCTION "talento"."set_primary_application"("p_application_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "talento"."set_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'talento', 'public', 'auth', 'storage', 'extensions'
    AS $$
begin
  new.updated_at = now();
  return new;
end
$$;


ALTER FUNCTION "talento"."set_updated_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "talento"."stage_rank"("p_stage" "talento"."stage_code") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'talento', 'public', 'auth', 'storage', 'extensions'
    AS $$
  select case p_stage
    when 'applied' then 10
    when 'documents' then 20
    when 'screening' then 30
    when 'interview' then 40
    when 'medical' then 50
    when 'offer' then 60
    when 'preboarding' then 70
    when 'handoff' then 80
    else 0
  end
$$;


ALTER FUNCTION "talento"."stage_rank"("p_stage" "talento"."stage_code") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "talento"."status_for_stage"("p_stage" "talento"."stage_code") RETURNS "talento"."application_status"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'talento', 'public', 'auth', 'storage', 'extensions'
    AS $$
  select case p_stage
    when 'applied' then 'submitted'::talento.application_status
    when 'documents' then 'in_review'::talento.application_status
    when 'screening' then 'in_review'::talento.application_status
    when 'interview' then 'interview'::talento.application_status
    when 'medical' then 'validation'::talento.application_status
    when 'offer' then 'offer'::talento.application_status
    when 'preboarding' then 'preboarding'::talento.application_status
    when 'handoff' then 'hired'::talento.application_status
  end
$$;


ALTER FUNCTION "talento"."status_for_stage"("p_stage" "talento"."stage_code") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "talento"."storage_object_belongs_to_current_candidate"("p_name" "text") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'talento', 'public', 'auth', 'storage', 'extensions'
    AS $$
  select
    coalesce((storage.foldername(p_name))[1], '') = 'candidate'
    and coalesce((storage.foldername(p_name))[2], '') = coalesce(talento.current_candidate_id()::text, '__none__')
$$;


ALTER FUNCTION "talento"."storage_object_belongs_to_current_candidate"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "talento"."submit_application"("p_vacancy_id" "uuid", "p_source" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'talento', 'public'
    AS $$
declare
  v_auth_user_id uuid;
  v_candidate_id uuid;
  v_existing_application_id uuid;
  v_application_id uuid;
  v_vacancy_status text;
begin
  v_auth_user_id := auth.uid();
  if v_auth_user_id is null then
    raise exception 'Not authenticated';
  end if;

  select c.id
    into v_candidate_id
  from talento.candidates c
  where c.auth_user_id = v_auth_user_id;

  if v_candidate_id is null then
    raise exception 'Candidate profile not found for current user';
  end if;

  select v.status
    into v_vacancy_status
  from talento.vacancies v
  where v.id = p_vacancy_id;

  if v_vacancy_status is null then
    raise exception 'Vacancy not found';
  end if;

  if v_vacancy_status <> 'published' then
    raise exception 'Vacancy is not open for applications';
  end if;

  select a.id
    into v_existing_application_id
  from talento.applications a
  where a.candidate_id = v_candidate_id
    and a.vacancy_id = p_vacancy_id
    and a.status not in ('rejected', 'withdrawn', 'expired', 'hired')
  order by a.created_at desc
  limit 1;

  if v_existing_application_id is not null then
    perform talento.set_primary_application(v_existing_application_id);
    return v_existing_application_id;
  end if;

  update talento.applications
     set is_primary_active = false
   where candidate_id = v_candidate_id
     and is_primary_active = true;

  insert into talento.applications (
    candidate_id,
    vacancy_id,
    status,
    current_stage_code,
    is_primary_active,
    applied_at,
    last_stage_changed_at,
    source,
    metadata
  )
  values (
    v_candidate_id,
    p_vacancy_id,
    'submitted',
    'applied',
    true,
    now(),
    now(),
    p_source,
    coalesce(p_metadata, '{}'::jsonb)
  )
  returning id into v_application_id;

  insert into talento.application_stage_history (
    application_id,
    stage_code,
    status,
    entered_at,
    changed_by,
    public_note,
    internal_note
  )
  values (
    v_application_id,
    'applied',
    'submitted',
    now(),
    v_auth_user_id,
    'Postulacion recibida.',
    'Application created by candidate submit_application().'
  );

  perform talento.log_application_event(
    v_application_id,
    'application_submitted',
    'candidate',
    v_auth_user_id,
    jsonb_build_object(
      'vacancy_id', p_vacancy_id,
      'source', p_source
    )
  );

  return v_application_id;
end
$$;


ALTER FUNCTION "talento"."submit_application"("p_vacancy_id" "uuid", "p_source" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "talento"."transfer_candidate_to_employee"("p_application_id" "uuid", "p_employee_id" "uuid", "p_actor_id" "uuid" DEFAULT "auth"."uid"(), "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'talento', 'public'
    AS $$
declare
  v_candidate_id uuid;
  v_current_status talento.application_status;
  v_has_pending_preboarding boolean;
begin
  select a.candidate_id, a.status
    into v_candidate_id, v_current_status
  from talento.applications a
  where a.id = p_application_id
  for update;

  if v_candidate_id is null then
    raise exception 'Application not found';
  end if;

  if exists (
    select 1
    from talento.candidate_employee_links l
    where l.application_id = p_application_id
  ) then
    raise exception 'Application already transferred';
  end if;

  select exists (
    select 1
    from talento.preboarding_tasks t
    where t.application_id = p_application_id
      and t.status in ('pending', 'rejected')
  ) into v_has_pending_preboarding;

  if coalesce(v_has_pending_preboarding, false) then
    raise exception 'Pending preboarding tasks prevent handoff';
  end if;

  update talento.application_stage_history
     set exited_at = now()
   where application_id = p_application_id
     and exited_at is null;

  update talento.applications
     set current_stage_code = 'handoff',
         status = 'hired',
         last_stage_changed_at = now(),
         is_primary_active = false
   where id = p_application_id;

  insert into talento.application_stage_history (
    application_id,
    stage_code,
    status,
    entered_at,
    changed_by,
    public_note,
    internal_note
  )
  values (
    p_application_id,
    'handoff',
    'hired',
    now(),
    p_actor_id,
    'Aprobado para ingreso.',
    coalesce(p_notes, 'Transferred to employee domain.')
  );

  insert into talento.candidate_employee_links (
    candidate_id,
    application_id,
    employee_id,
    transferred_at,
    transferred_by,
    notes
  )
  values (
    v_candidate_id,
    p_application_id,
    p_employee_id,
    now(),
    p_actor_id,
    p_notes
  );

  perform talento.log_application_event(
    p_application_id,
    'application_transferred_to_employee',
    'internal_user',
    p_actor_id,
    jsonb_build_object(
      'employee_id', p_employee_id,
      'notes', p_notes
    )
  );

  return p_application_id;
end
$$;


ALTER FUNCTION "talento"."transfer_candidate_to_employee"("p_application_id" "uuid", "p_employee_id" "uuid", "p_actor_id" "uuid", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vital"."apply_ai_weekly_plan"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_items jsonb := coalesce(v_payload -> 'weekly_blocks', '[]'::jsonb);
  v_program_version_id uuid;
  v_item jsonb;
  v_inserted integer := 0;
  v_skipped integer := 0;
  v_module_key text;
  v_task_type text;
  v_title text;
  v_days jsonb;
  v_minutes smallint;
  v_payload_item jsonb;
begin
  if v_user_id is null then
    raise exception 'auth.uid() is null';
  end if;

  if jsonb_typeof(v_items) <> 'array' then
    raise exception 'weekly_blocks must be a json array';
  end if;

  select pv.id
    into v_program_version_id
  from vital.program_versions pv
  where pv.user_id = v_user_id
    and pv.is_active
  order by pv.created_at desc
  limit 1;

  if v_program_version_id is null then
    raise exception 'No active program_version found for this user';
  end if;

  for v_item in select value from jsonb_array_elements(v_items)
  loop
    v_module_key := coalesce(nullif(trim(coalesce(v_item ->> 'module_key', '')), ''), 'training');
    v_task_type := coalesce(
      nullif(trim(coalesce(v_item ->> 'task_type', '')), ''),
      case
        when v_module_key = 'nutrition' then 'nutrition'
        when v_module_key = 'recovery' then 'recovery'
        when v_module_key = 'habits' then 'metrics'
        else 'workout'
      end
    );
    v_title := nullif(trim(coalesce(v_item ->> 'title', '')), '');
    v_days := coalesce(v_item -> 'days', '[1,2,3,4,5,6,7]'::jsonb);
    v_minutes := coalesce((v_item ->> 'estimated_minutes')::smallint, 20);
    v_payload_item := coalesce(v_item -> 'payload', '{}'::jsonb);

    if v_title is null then
      v_skipped := v_skipped + 1;
      continue;
    end if;

    insert into vital.task_templates(
      user_id,
      program_version_id,
      module_key,
      task_type,
      title,
      recurrence_rule,
      ordering,
      estimated_minutes,
      payload,
      is_active
    )
    values (
      v_user_id,
      v_program_version_id,
      v_module_key,
      v_task_type,
      v_title,
      jsonb_build_object('days', v_days),
      coalesce((v_item ->> 'ordering')::smallint, 100),
      v_minutes,
      v_payload_item || jsonb_build_object(
        'source', 'ai_weekly_plan_v1',
        'applied_at', now()
      ),
      true
    );

    v_inserted := v_inserted + 1;
  end loop;

  return jsonb_build_object(
    'inserted_templates', v_inserted,
    'skipped_templates', v_skipped
  );
end;
$$;


ALTER FUNCTION "vital"."apply_ai_weekly_plan"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vital"."apply_football_preset"("p_preset_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_preset vital.football_preset_catalog;
  v_modules jsonb;
  v_sport_result jsonb := '{}'::jsonb;
begin
  if v_user_id is null then
    raise exception 'auth.uid() is null';
  end if;

  select *
    into v_preset
  from vital.football_preset_catalog fpc
  where fpc.key = p_preset_key
    and fpc.is_active;

  if v_preset.key is null then
    raise exception 'football preset not found or inactive';
  end if;

  v_modules := coalesce(v_preset.modules, '[]'::jsonb);

  perform vital.upsert_user_module_preferences(
    (
      select jsonb_agg(
        jsonb_build_object(
          'module_key', mc.key,
          'is_enabled', exists (
            select 1
            from jsonb_array_elements_text(v_modules) m
            where m = mc.key
          ),
          'config', '{}'::jsonb
        )
      )
      from vital.module_catalog mc
      where mc.is_active
    )
  );

  perform vital.upsert_sports_profile(
    jsonb_build_object(
      'sports', jsonb_build_array(
        jsonb_build_object('key', 'football', 'priority', 'A', 'level', 'intermediate'),
        jsonb_build_object('key', 'gym', 'priority', 'B', 'level', 'intermediate')
      ),
      'primary_sport', 'football',
      'global_objectives', jsonb_build_array(v_preset.objective_key),
      'constraints', jsonb_build_object(
        'days_per_week', coalesce((v_preset.config ->> 'days_per_week')::int, 5),
        'minutes_per_session', coalesce((v_preset.config ->> 'minutes_per_session')::int, 60)
      ),
      'cycle_config', jsonb_build_object(
        'dominant_focus', v_preset.dominant_focus,
        'cycle_weeks', v_preset.cycle_weeks
      )
    )
  );

  select vital.apply_sport_templates_from_profile(v_preset.objective_key)
    into v_sport_result;

  return jsonb_build_object(
    'preset_key', v_preset.key,
    'objective_key', v_preset.objective_key,
    'dominant_focus', v_preset.dominant_focus,
    'cycle_weeks', v_preset.cycle_weeks,
    'modules', v_modules,
    'sport_templates', coalesce(v_sport_result, '{}'::jsonb)
  );
end
$$;


ALTER FUNCTION "vital"."apply_football_preset"("p_preset_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vital"."apply_sport_templates_from_profile"("p_objective" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_sports jsonb := '[]'::jsonb;
  v_primary_sport text := 'generic';
  v_global_objectives jsonb := '[]'::jsonb;
  v_selected_objective text := coalesce(nullif(trim(p_objective), ''), 'any');
  v_level text := 'all';
  v_module text;
  v_program_id uuid;
  v_program_version_id uuid;
  v_inserted integer := 0;
  v_total_inserted integer := 0;
  v_modules_used jsonb := '[]'::jsonb;
begin
  if v_user_id is null then
    raise exception 'auth.uid() is null';
  end if;

  select sp.sports, sp.primary_sport, sp.global_objectives
    into v_sports, v_primary_sport, v_global_objectives
  from vital.get_sports_profile() as sp(
    sports,
    primary_sport,
    global_objectives,
    constraints,
    cycle_config,
    profile_version,
    updated_at
  );

  v_primary_sport := coalesce(nullif(v_primary_sport, ''), 'generic');

  select coalesce(elem ->> 'level', 'all')
    into v_level
  from jsonb_array_elements(coalesce(v_sports, '[]'::jsonb)) as elem
  where elem ->> 'key' = v_primary_sport
  order by case coalesce(elem ->> 'priority', 'Z') when 'A' then 1 when 'B' then 2 when 'C' then 3 else 9 end
  limit 1;

  v_level := coalesce(nullif(v_level, ''), 'all');

  if v_selected_objective = 'any' and exists (
    select 1 from jsonb_array_elements_text(coalesce(v_global_objectives, '[]'::jsonb)) as go where go = 'performance'
  ) then
    v_selected_objective := 'performance';
  elsif v_selected_objective = 'any' and exists (
    select 1 from jsonb_array_elements_text(coalesce(v_global_objectives, '[]'::jsonb)) as go where go = 'strength'
  ) then
    v_selected_objective := 'strength';
  end if;

  for v_module in
    select ump.module_key
    from vital.get_user_module_preferences() as ump(module_key, is_enabled, config)
    where ump.is_enabled
  loop
    if v_module in ('nutrition', 'habits', 'recovery') then
      select p.id, pv.id
        into v_program_id, v_program_version_id
      from vital.programs p
      join vital.program_versions pv
        on pv.program_id = p.id
       and pv.user_id = p.user_id
       and pv.is_active
      where p.user_id = v_user_id
        and p.is_active
        and p.objective = format('%s_core', v_module)
      order by pv.created_at desc
      limit 1;
    else
      select p.id, pv.id
        into v_program_id, v_program_version_id
      from vital.programs p
      join vital.program_versions pv
        on pv.program_id = p.id
       and pv.user_id = p.user_id
       and pv.is_active
      where p.user_id = v_user_id
        and p.is_active
        and p.objective not like '%_core'
      order by pv.created_at desc
      limit 1;
    end if;

    if v_program_version_id is null then
      continue;
    end if;

    insert into vital.task_templates (
      user_id,
      program_version_id,
      module_key,
      task_type,
      title,
      recurrence_rule,
      ordering,
      estimated_minutes,
      payload,
      is_active
    )
    select
      v_user_id,
      v_program_version_id,
      smtc.module_key,
      smtc.task_type,
      smtc.title,
      jsonb_build_object('type', 'weekly', 'days', to_jsonb(smtc.days_of_week)),
      (100 + smtc.ordering)::smallint,
      smtc.estimated_minutes,
      jsonb_build_object(
        'source', 'sport_template_catalog_v1',
        'sport_key', smtc.sport_key,
        'objective_key', smtc.objective_key,
        'level_key', smtc.level_key
      ) || coalesce(smtc.payload, '{}'::jsonb),
      true
    from vital.sport_module_template_catalog smtc
    where smtc.is_active
      and smtc.module_key = v_module
      and smtc.sport_key in (v_primary_sport, 'generic')
      and smtc.objective_key in (v_selected_objective, 'any')
      and smtc.level_key in (v_level, 'all')
      and not exists (
        select 1
        from vital.task_templates tt
        where tt.user_id = v_user_id
          and tt.program_version_id = v_program_version_id
          and tt.module_key = smtc.module_key
          and tt.title = smtc.title
      );

    get diagnostics v_inserted = row_count;
    if coalesce(v_inserted, 0) > 0 then
      v_total_inserted := v_total_inserted + v_inserted;
      v_modules_used := v_modules_used || to_jsonb(v_module);
    end if;
  end loop;

  return jsonb_build_object(
    'primary_sport', v_primary_sport,
    'objective_key', v_selected_objective,
    'level_key', v_level,
    'templates_inserted', v_total_inserted,
    'modules_touched', v_modules_used
  );
end
$$;


ALTER FUNCTION "vital"."apply_sport_templates_from_profile"("p_objective" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vital"."can_access_user"("target_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
  select (
    auth.uid() = target_user_id
    or vital.is_vital_admin()
    or vital.is_service_role()
  );
$$;


ALTER FUNCTION "vital"."can_access_user"("target_user_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "vital"."task_instances" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "task_template_id" "uuid" NOT NULL,
    "task_date" "date" NOT NULL,
    "window_start" timestamp with time zone,
    "window_end" timestamp with time zone,
    "status" "vital"."task_status" DEFAULT 'pending'::"vital"."task_status" NOT NULL,
    "priority" smallint DEFAULT 50 NOT NULL,
    "snooze_until" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "completion_payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "module_key" "text" DEFAULT 'training'::"text" NOT NULL,
    CONSTRAINT "task_instances_check" CHECK ((("window_end" IS NULL) OR ("window_start" IS NULL) OR ("window_end" >= "window_start"))),
    CONSTRAINT "task_instances_priority_check" CHECK ((("priority" >= 0) AND ("priority" <= 100)))
);


ALTER TABLE "vital"."task_instances" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vital"."complete_task_instance"("p_task_instance_id" "uuid", "p_completion_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "vital"."task_instances"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
declare
  v_row vital.task_instances;
begin
  update vital.task_instances ti
  set
    status = 'completed',
    completed_at = now(),
    completion_payload = coalesce(p_completion_payload, '{}'::jsonb),
    updated_at = now()
  where ti.id = p_task_instance_id
    and ti.user_id = auth.uid()
  returning ti.* into v_row;

  if v_row.id is null then
    raise exception 'task_instance not found or access denied';
  end if;

  return v_row;
end
$$;


ALTER FUNCTION "vital"."complete_task_instance"("p_task_instance_id" "uuid", "p_completion_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vital"."compute_hoy_scores"("p_target_date" "date" DEFAULT (("now"() AT TIME ZONE 'utc'::"text"))::"date") RETURNS TABLE("task_instance_id" "uuid", "module_key" "text", "priority_score" integer, "reason_code" "text", "reason_text" "text", "safety_state" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_blocked_modules jsonb := '[]'::jsonb;
  v_risk_level text := 'low';
  v_adherence integer := 60;
  v_readiness integer := 60;
  v_risk_penalty integer := 0;
begin
  if v_user_id is null then
    raise exception 'auth.uid() is null';
  end if;

  perform 1 from vital.today_tasks(p_target_date);

  select s.blocked_modules, s.risk_level
    into v_blocked_modules, v_risk_level
  from vital.get_safety_status() s;

  select coalesce(
    round(
      100.0
      * sum(case when ti.status = 'completed' then 1 else 0 end)::numeric
      / nullif(count(*), 0)
    )::integer,
    60
  )
  into v_adherence
  from vital.task_instances ti
  where ti.user_id = v_user_id
    and ti.task_date between (p_target_date - 6) and p_target_date;

  select coalesce(
    round(
      (
        dri.sleep_score::numeric
        + (100 - dri.stress_score)::numeric
        + dri.energy_score::numeric
      ) / 3
    )::integer,
    60
  )
  into v_readiness
  from vital.daily_readiness_inputs dri
  where dri.user_id = v_user_id
    and dri.input_date = p_target_date;

  if v_risk_level = 'critical' then
    v_risk_penalty := 100;
  elsif v_risk_level = 'high' then
    v_risk_penalty := 60;
  elsif v_risk_level = 'medium' then
    v_risk_penalty := 30;
  else
    v_risk_penalty := 0;
  end if;

  return query
  with enabled_modules as (
    select ump.module_key
    from vital.get_user_module_preferences() as ump(module_key, is_enabled, config)
    where ump.is_enabled
  ),
  sport_ctx as (
    select
      coalesce(sp.primary_sport, '') as primary_sport,
      coalesce(sp.global_objectives, '[]'::jsonb) as global_objectives
    from vital.get_sports_profile() as sp(
      sports,
      primary_sport,
      global_objectives,
      constraints,
      cycle_config,
      profile_version,
      updated_at
    )
  ),
  yesterday_load as (
    select
      ti.module_key,
      count(*)::integer as tasks_count
    from vital.task_instances ti
    where ti.user_id = v_user_id
      and ti.task_date = (p_target_date - 1)
      and ti.status <> 'skipped'
    group by ti.module_key
  ),
  base as (
    select
      ti.id as task_instance_id,
      ti.module_key,
      coalesce(ti.priority, 50)::integer as task_priority,
      coalesce(tt.ordering, 1)::integer as task_ordering,
      case
        when exists (
          select 1
          from jsonb_array_elements_text(v_blocked_modules) b
          where b = ti.module_key
        ) then 'blocked'
        else 'ok'
      end as safety_state,
      case
        when ti.module_key = 'recovery' then 78
        when ti.module_key = 'training' then 72
        when ti.module_key = 'nutrition' then 66
        else 62
      end as objective_urgency
    from vital.task_instances ti
    join vital.task_templates tt
      on tt.id = ti.task_template_id
     and tt.user_id = ti.user_id
    join enabled_modules em
      on em.module_key = ti.module_key
    where ti.user_id = v_user_id
      and ti.task_date = p_target_date
  ),
  scored as (
    select
      b.*,
      (
        case
          when sc.primary_sport in ('football', 'volleyball', 'taekwondo', 'basketball', 'padel') then
            case
              when b.module_key = 'training' then 8
              when b.module_key = 'recovery' then 7
              when b.module_key = 'nutrition' then 4
              when b.module_key = 'habits' then 3
              else 0
            end
          when sc.primary_sport in ('cycling', 'swimming') then
            case
              when b.module_key = 'training' then 7
              when b.module_key = 'recovery' then 8
              when b.module_key = 'nutrition' then 4
              when b.module_key = 'habits' then 3
              else 0
            end
          when sc.primary_sport = 'gym' then
            case
              when b.module_key = 'training' then 8
              when b.module_key = 'nutrition' then 5
              when b.module_key = 'recovery' then 4
              when b.module_key = 'habits' then 2
              else 0
            end
          else 0
        end
        + case
            when exists (
              select 1
              from jsonb_array_elements_text(sc.global_objectives) go
              where go = 'performance'
            ) and b.module_key in ('training', 'recovery') then 2
            else 0
          end
        + case
            when exists (
              select 1
              from jsonb_array_elements_text(sc.global_objectives) go
              where go = 'aesthetics'
            ) and b.module_key in ('training', 'nutrition') then 2
            else 0
          end
        + case
            when exists (
              select 1
              from jsonb_array_elements_text(sc.global_objectives) go
              where go = 'health'
            ) and b.module_key in ('habits', 'recovery') then 2
            else 0
          end
      )::integer as sports_bonus,
      case
        when b.module_key = 'training' then 4
        when b.module_key = 'recovery' then 2
        when b.module_key = 'nutrition' then 0
        when b.module_key = 'habits' then -3
        else 0
      end as module_bias,
      greatest(0, 6 - coalesce(b.task_ordering, 6))::integer as ordering_boost,
      coalesce((
        select max(mir.next_day_penalty)::integer
        from yesterday_load yl
        join vital.module_interference_rules mir
          on mir.primary_module_key = b.module_key
         and mir.secondary_module_key = yl.module_key
        where yl.tasks_count > 0
      ), 0)::integer as interference_penalty
    from base b
    cross join sport_ctx sc
  ),
  raw_scores as (
    select
      s.*,
      (
        (0.18 * v_adherence)
        + (0.18 * v_readiness)
        + (0.14 * (100 - v_risk_penalty))
        + (0.16 * s.objective_urgency)
        + (0.10 * s.task_priority)
        + least(10, s.sports_bonus)
        + s.module_bias
        + (0.8 * s.ordering_boost)
        - (1.5 * s.interference_penalty)
      )::numeric as raw_score
    from scored s
  ),
  ranked as (
    select
      r.*,
      row_number() over (
        order by
          r.raw_score desc,
          r.sports_bonus desc,
          r.module_bias desc,
          r.task_ordering asc,
          r.task_instance_id
      )::integer as global_rank,
      count(*) over ()::integer as total_rows
    from raw_scores r
  )
  select
    n.task_instance_id,
    n.module_key,
    case
      when n.safety_state = 'blocked' then 0::integer
      else greatest(
        35,
        least(
          95,
          (
            95
            - ((n.global_rank - 1)
               * case
                   when n.total_rows <= 1 then 0
                   else greatest(1, floor(24.0 / (n.total_rows - 1))::integer)
                 end)
            - (n.global_rank - 1)
            + case when n.sports_bonus >= 6 then 1 else 0 end
            - n.interference_penalty
          )
        )
      )::integer
    end as priority_score,
    case
      when n.safety_state = 'blocked' then 'safety_blocked'
      when n.interference_penalty >= 8 then 'interference_load_guard'
      when v_readiness < 45 then 'low_readiness'
      when v_adherence < 50 and n.sports_bonus >= 6 then 'low_adherence_sport_focus'
      when v_adherence < 50 then 'low_adherence'
      when n.sports_bonus >= 6 then 'sport_focus_priority'
      else 'balanced_priority'
    end as reason_code,
    case
      when n.safety_state = 'blocked' then 'Bloqueado por safety gate activo para este modulo.'
      when n.interference_penalty >= 8 then 'Prioridad ajustada por interferencia de carga del dia anterior.'
      when v_readiness < 45 then 'Prioridad ajustada por readiness bajo del dia.'
      when v_adherence < 50 and n.sports_bonus >= 6 then 'Adherencia baja: se prioriza una accion alineada con tu deporte principal para retomar ritmo.'
      when v_adherence < 50 then 'Prioridad ajustada para recuperar adherencia semanal.'
      when n.sports_bonus >= 6 then 'Prioridad reforzada por alineacion con deporte principal y objetivos globales.'
      else 'Prioridad balanceada por adherencia, readiness, riesgo y urgencia.'
    end as reason_text,
    n.safety_state
  from ranked n
  order by priority_score desc, n.task_instance_id;
end
$$;


