    "applied_at" timestamp with time zone,
    CONSTRAINT "ai_plan_proposals_confidence_score_check" CHECK ((("confidence_score" IS NULL) OR (("confidence_score" >= (0)::numeric) AND ("confidence_score" <= (100)::numeric)))),
    CONSTRAINT "ai_plan_proposals_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'applied'::"text", 'rejected'::"text"])))
);


