CREATE OR REPLACE FUNCTION "vital"."create_ai_plan_proposal_v1"("p_context_payload" "jsonb", "p_proposal_payload" "jsonb", "p_confidence_score" numeric DEFAULT NULL::numeric, "p_model_name" "text" DEFAULT NULL::"text", "p_prompt_version" "text" DEFAULT 'v1'::"text") RETURNS "vital"."ai_plan_proposals"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
