CREATE OR REPLACE FUNCTION "vital"."create_initial_bundle_from_onboarding"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_modules jsonb := coalesce(v_payload -> 'modules', '[]'::jsonb);
  v_safety jsonb := coalesce(v_payload -> 'safety', '{}'::jsonb);
  v_objective text := coalesce(nullif(trim(v_payload ->> 'objective'), ''), 'general_health');
  v_days smallint := least(6, greatest(2, coalesce((v_payload ->> 'days_per_week')::smallint, 3)));
  v_minutes smallint := least(90, greatest(20, coalesce((v_payload ->> 'minutes_per_session')::smallint, 45)));
  v_starter_key text := coalesce(nullif(trim(v_payload ->> 'starter_key'), ''), format('starter_%sd', v_days));
  v_blocked_modules jsonb := '[]'::jsonb;
  v_training_requested boolean := false;
  v_training_enabled boolean := false;
  v_program_name text;
  v_created_non_training_templates integer := 0;
  v_created_training boolean := false;
  v_inserted_count integer := 0;
  v_module_record record;
  v_program_id uuid;
  v_program_version_id uuid;
begin
  if v_user_id is null then
    raise exception 'auth.uid() is null';
  end if;

  if jsonb_typeof(v_modules) <> 'array' then
    raise exception 'modules must be json array';
  end if;

  perform vital.submit_safety_intake(v_safety);

  select s.blocked_modules
    into v_blocked_modules
  from vital.get_safety_status() s;

  perform vital.upsert_user_module_preferences(
    (
      select jsonb_agg(
        jsonb_build_object(
          'module_key', mc.key,
          'is_enabled',
            case
              when exists (
                select 1
                from jsonb_array_elements_text(v_modules) m
                where m = mc.key
              ) then true
              else false
            end,
          'config', '{}'::jsonb
        )
      )
      from vital.module_catalog mc
      where mc.is_active
    )
  );

  v_training_requested := exists (
    select 1
    from jsonb_array_elements_text(v_modules) m
    where m = 'training'
  );

  v_training_enabled := v_training_requested and not exists (
    select 1
    from jsonb_array_elements_text(v_blocked_modules) b
    where b = 'training'
  );

  if v_training_enabled then
    v_program_name := format(
      '%s %sD · %smin',
      case
        when v_objective = 'strength' then 'Fuerza'
        when v_objective = 'hypertrophy' then 'Hipertrofia'
        else 'Salud'
      end,
      v_days,
      v_minutes
    );
    perform *
    from vital.create_program_from_starter(v_starter_key, v_program_name);
    v_created_training := true;
  end if;

  for v_module_record in
    select distinct x.value as module_key
    from jsonb_array_elements_text(v_modules) as x(value)
    where x.value in ('nutrition', 'habits', 'recovery')
  loop
    select p.id
      into v_program_id
    from vital.programs p
    where p.user_id = v_user_id
      and p.is_active
      and p.objective = format('%s_core', v_module_record.module_key)
    limit 1;

    if v_program_id is null then
      insert into vital.programs (
        user_id,
        name,
        objective,
        status,
        started_on,
        is_active
      )
      values (
        v_user_id,
        initcap(v_module_record.module_key) || ' Core',
        format('%s_core', v_module_record.module_key),
        'active',
        current_date,
        true
      )
      returning id into v_program_id;

      insert into vital.program_versions (
        user_id,
        program_id,
        version_number,
        archetype,
        generated_from,
        rules_snapshot,
        is_active
      )
      values (
        v_user_id,
        v_program_id,
        1,
        format('%s_v1', v_module_record.module_key),
        jsonb_build_object('source', 'onboarding_v2'),
        '{}'::jsonb,
        true
      )
      returning id into v_program_version_id;

      insert into vital.task_templates (
        user_id,
        program_version_id,
        module_key,
        task_type,
        title,
        recurrence_rule,
        ordering,
        estimated_minutes,
        payload,
        is_active
      )
      select
        v_user_id,
        v_program_version_id,
        mtc.module_key,
        mtc.task_type,
        mtc.title,
        jsonb_build_object(
          'type', 'weekly',
          'days', to_jsonb(mtc.days_of_week)
        ),
        mtc.ordering,
        mtc.estimated_minutes,
        mtc.payload,
        true
      from vital.module_template_catalog mtc
      where mtc.module_key = v_module_record.module_key
        and mtc.is_active;

      get diagnostics v_inserted_count = row_count;
      v_created_non_training_templates := v_created_non_training_templates + coalesce(v_inserted_count, 0);
    end if;
  end loop;

  return jsonb_build_object(
    'training_requested', v_training_requested,
    'training_created', v_created_training,
    'blocked_modules', v_blocked_modules,
    'non_training_templates_created', v_created_non_training_templates,
    'objective', v_objective,
    'days_per_week', v_days,
    'minutes_per_session', v_minutes
  );
end
$$;


ALTER FUNCTION "vital"."create_initial_bundle_from_onboarding"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vital"."create_program_from_starter"("p_starter_key" "text", "p_program_name" "text" DEFAULT NULL::"text") RETURNS TABLE("program_id" "uuid", "program_version_id" "uuid", "templates_created" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_catalog vital.starter_program_catalog%rowtype;
  v_program_id uuid;
  v_program_version_id uuid;
  v_templates_created integer := 0;
begin
  if v_user_id is null then
    raise exception 'auth.uid() is null';
  end if;

  select * into v_catalog
  from vital.starter_program_catalog
  where key = p_starter_key
    and is_active;

  if v_catalog.key is null then
    raise exception 'starter program not found or inactive';
  end if;

  insert into vital.programs (
    user_id,
    name,
    objective,
    status,
    started_on,
    is_active
  )
  values (
    v_user_id,
    coalesce(nullif(btrim(p_program_name), ''), v_catalog.name),
    v_catalog.objective,
    'active',
    current_date,
    true
  )
  returning id into v_program_id;

  insert into vital.program_versions (
    user_id,
    program_id,
    version_number,
    archetype,
    generated_from,
    rules_snapshot,
    is_active
  )
  values (
    v_user_id,
    v_program_id,
    1,
    coalesce(v_catalog.metadata ->> 'archetype', v_catalog.key),
    jsonb_build_object('source', 'starter_catalog', 'starter_key', v_catalog.key),
    '{}'::jsonb,
    true
  )
  returning id into v_program_version_id;

  insert into vital.task_templates (
    user_id,
    program_version_id,
    task_type,
    title,
    recurrence_rule,
    ordering,
    estimated_minutes,
    payload,
    is_active
  )
  select
    v_user_id,
    v_program_version_id,
    spt.task_type,
    spt.title,
    jsonb_build_object('type', 'weekly', 'days', jsonb_build_array(spt.day_of_week)),
    spt.ordering,
    spt.estimated_minutes,
    spt.payload,
    true
  from vital.starter_program_tasks spt
  where spt.starter_key = v_catalog.key;

  get diagnostics v_templates_created = row_count;

  return query
  select v_program_id, v_program_version_id, v_templates_created;
end
$$;


ALTER FUNCTION "vital"."create_program_from_starter"("p_starter_key" "text", "p_program_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vital"."get_ai_context_bundle"("p_target_date" "date" DEFAULT (("now"() AT TIME ZONE 'utc'::"text"))::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_target_date date := coalesce(p_target_date, (now() at time zone 'utc')::date);
  v_week_start date;
begin
  if v_user_id is null then
    raise exception 'auth.uid() is null';
  end if;

  v_week_start := v_target_date - ((extract(isodow from v_target_date)::int) - 1);

  return jsonb_build_object(
    'target_date', v_target_date,
    'week_start', v_week_start,
    'modules', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'module_key', mp.module_key,
          'is_enabled', mp.is_enabled,
          'config', coalesce(mp.config, '{}'::jsonb)
        )
      )
      from vital.get_user_module_preferences() as mp(module_key, is_enabled, config)
    ), '[]'::jsonb),
    'sports_profile', coalesce((
      select to_jsonb(sp)
      from vital.get_sports_profile() as sp(
        sports,
        primary_sport,
        global_objectives,
        constraints,
        cycle_config,
        profile_version,
        updated_at
      )
    ), '{}'::jsonb),
    'safety_status', coalesce((
      select to_jsonb(ss)
      from vital.get_safety_status() as ss(risk_level, blocked_modules, requires_professional_check, updated_at)
    ), '{}'::jsonb),
    'cycle_adjustment', coalesce((
      select jsonb_agg(to_jsonb(ca))
      from vital.plan_cycle_adjustment(v_target_date) as ca(
        module_key,
        phase,
        volume_delta_pct,
        intensity_delta_pct,
        reason_code,
        reason_text
      )
    ), '[]'::jsonb),
    'weekly_plan', coalesce((
      select jsonb_agg(to_jsonb(wp))
      from vital.plan_weekly_fused_schedule(v_week_start, null) as wp(
        plan_date,
        module_key,
        task_type,
        title,
        estimated_minutes,
        blend_weight,
        conflict_penalty,
        priority_hint,
        interference_note
      )
    ), '[]'::jsonb),
    'nutrition_profile', coalesce((
      select to_jsonb(np)
      from vital.user_nutrition_profiles_v1 np
      where np.user_id = v_user_id
    ), '{}'::jsonb)
  );
end;
$$;


ALTER FUNCTION "vital"."get_ai_context_bundle"("p_target_date" "date") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "vital"."user_nutrition_profiles_v1" (
    "user_id" "uuid" NOT NULL,
    "profile_payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "hydration_goal_l" numeric(6,2) DEFAULT 2.00 NOT NULL,
    "meals_per_day" smallint DEFAULT 3 NOT NULL,
    "calories_target" integer,
    "protein_g_target" integer,
    "carbs_g_target" integer,
    "fat_g_target" integer,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "user_nutrition_profiles_v1_calories_target_check" CHECK ((("calories_target" IS NULL) OR (("calories_target" >= 800) AND ("calories_target" <= 7000)))),
    CONSTRAINT "user_nutrition_profiles_v1_carbs_g_target_check" CHECK ((("carbs_g_target" IS NULL) OR (("carbs_g_target" >= 20) AND ("carbs_g_target" <= 1000)))),
    CONSTRAINT "user_nutrition_profiles_v1_fat_g_target_check" CHECK ((("fat_g_target" IS NULL) OR (("fat_g_target" >= 10) AND ("fat_g_target" <= 400)))),
    CONSTRAINT "user_nutrition_profiles_v1_hydration_goal_l_check" CHECK ((("hydration_goal_l" > (0)::numeric) AND ("hydration_goal_l" <= (10)::numeric))),
    CONSTRAINT "user_nutrition_profiles_v1_meals_per_day_check" CHECK ((("meals_per_day" >= 1) AND ("meals_per_day" <= 8))),
    CONSTRAINT "user_nutrition_profiles_v1_protein_g_target_check" CHECK ((("protein_g_target" IS NULL) OR (("protein_g_target" >= 20) AND ("protein_g_target" <= 500))))
);


