CREATE OR REPLACE FUNCTION "vital"."get_nutrition_profile_v1"() RETURNS "vital"."user_nutrition_profiles_v1"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_row vital.user_nutrition_profiles_v1;
begin
  if v_user_id is null then
    raise exception 'auth.uid() is null';
  end if;

  select *
    into v_row
  from vital.user_nutrition_profiles_v1
  where user_id = v_user_id;

  if v_row.user_id is null then
    insert into vital.user_nutrition_profiles_v1(user_id)
    values (v_user_id)
    returning * into v_row;
  end if;

  return v_row;
end;
$$;


