CREATE TABLE IF NOT EXISTS "vital"."user_cycle_states" (
    "user_id" "uuid" NOT NULL,
    "cycle_start_date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "cycle_length_weeks" smallint DEFAULT 4 NOT NULL,
    "current_week" smallint DEFAULT 1 NOT NULL,
    "dominant_focus" "text" DEFAULT 'sport_performance'::"text" NOT NULL,
    "phase" "text" DEFAULT 'build'::"text" NOT NULL,
    "last_readiness" smallint,
    "last_adherence" smallint,
    "last_interference_penalty" smallint,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "user_cycle_states_phase_check" CHECK (("phase" = ANY (ARRAY['build'::"text", 'maintain'::"text", 'deload'::"text"])))
);


ALTER TABLE "vital"."user_cycle_states" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vital"."get_or_create_cycle_state"() RETURNS "vital"."user_cycle_states"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_row vital.user_cycle_states;
  v_cycle_weeks smallint := 4;
  v_focus text := 'sport_performance';
begin
  if v_user_id is null then
    raise exception 'auth.uid() is null';
  end if;

  select
    greatest(2, least(8, coalesce((sp.cycle_config ->> 'cycle_weeks')::smallint, 4))),
    coalesce(nullif(sp.cycle_config ->> 'dominant_focus', ''), 'sport_performance')
    into v_cycle_weeks, v_focus
  from vital.get_sports_profile() as sp(
    sports,
    primary_sport,
    global_objectives,
    constraints,
    cycle_config,
    profile_version,
    updated_at
  );

  insert into vital.user_cycle_states (user_id, cycle_start_date, cycle_length_weeks, current_week, dominant_focus, phase)
  values (v_user_id, current_date, v_cycle_weeks, 1, v_focus, 'build')
  on conflict (user_id) do nothing;

  select * into v_row
  from vital.user_cycle_states ucs
  where ucs.user_id = v_user_id;

  return v_row;
end
$$;


ALTER FUNCTION "vital"."get_or_create_cycle_state"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vital"."get_safety_status"() RETURNS TABLE("risk_level" "text", "blocked_modules" "jsonb", "requires_professional_check" boolean, "updated_at" timestamp with time zone)
    LANGUAGE "sql"
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
  select
    coalesce(si.risk_level, 'low') as risk_level,
    coalesce(si.blocked_modules, '[]'::jsonb) as blocked_modules,
    coalesce(si.requires_professional_check, false) as requires_professional_check,
    si.updated_at
  from vital.safety_intake si
  where si.user_id = auth.uid()
  union all
  select 'low', '[]'::jsonb, false, null
  where not exists (select 1 from vital.safety_intake x where x.user_id = auth.uid())
  limit 1;
$$;


ALTER FUNCTION "vital"."get_safety_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vital"."get_sports_profile"() RETURNS TABLE("sports" "jsonb", "primary_sport" "text", "global_objectives" "jsonb", "constraints" "jsonb", "cycle_config" "jsonb", "profile_version" integer, "updated_at" timestamp with time zone)
    LANGUAGE "sql"
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
  with default_row as (
    select
      '[]'::jsonb as sports,
      null::text as primary_sport,
      '[]'::jsonb as global_objectives,
      '{}'::jsonb as constraints,
      '{"dominant_focus":"balanced","cycle_weeks":4}'::jsonb as cycle_config,
      1::integer as profile_version,
      now() as updated_at
  )
  select
    coalesce(sp.sports, d.sports) as sports,
    coalesce(sp.primary_sport, d.primary_sport) as primary_sport,
    coalesce(sp.global_objectives, d.global_objectives) as global_objectives,
    coalesce(sp.constraints, d.constraints) as constraints,
    coalesce(sp.cycle_config, d.cycle_config) as cycle_config,
    coalesce(sp.profile_version, d.profile_version) as profile_version,
    coalesce(sp.updated_at, d.updated_at) as updated_at
  from default_row d
  left join vital.sports_profiles sp
    on sp.user_id = auth.uid();
$$;


ALTER FUNCTION "vital"."get_sports_profile"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vital"."get_user_module_preferences"() RETURNS TABLE("module_key" "text", "is_enabled" boolean, "config" "jsonb")
    LANGUAGE "sql"
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
  with base as (
    select key as module_key
    from vital.module_catalog
    where is_active
  )
  select
    b.module_key,
    coalesce(ump.is_enabled, b.module_key = 'training') as is_enabled,
    coalesce(ump.config, '{}'::jsonb) as config
  from base b
  left join vital.user_module_preferences ump
    on ump.user_id = auth.uid()
   and ump.module_key = b.module_key
  order by b.module_key;
$$;


ALTER FUNCTION "vital"."get_user_module_preferences"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vital"."is_feature_enabled"("p_flag_key" "text", "p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
  with base as (
    select ff.enabled_by_default
    from vital.feature_flags ff
    where ff.key = p_flag_key
  ),
  override as (
    select uff.enabled
    from vital.user_feature_flags uff
    where uff.flag_key = p_flag_key
      and uff.user_id = p_user_id
  )
  select coalesce((select enabled from override), (select enabled_by_default from base), false);
$$;


