CREATE OR REPLACE FUNCTION "vital"."validate_notification_schedule"("p_schedule" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'vital', 'public', 'auth', 'storage', 'extensions'
    AS $$
declare
  v_type text := coalesce(nullif(trim(p_schedule ->> 'type'), ''), '');
  v_hour int;
  v_minute int;
  v_offset int;
begin
  if p_schedule is null or jsonb_typeof(p_schedule) <> 'object' then
    return false;
  end if;

  if v_type = 'fixed_time' then
    v_hour := (p_schedule ->> 'hour')::int;
    v_minute := (p_schedule ->> 'minute')::int;
    return v_hour between 0 and 23 and v_minute between 0 and 59;
  elsif v_type = 'relative_to_window' then
    v_offset := (p_schedule ->> 'offset_minutes')::int;
    return v_offset between -720 and 720;
  end if;

  return false;
exception
  when others then
    return false;
end
$$;


ALTER FUNCTION "vital"."validate_notification_schedule"("p_schedule" "jsonb") OWNER TO "postgres";


