CREATE OR REPLACE FUNCTION "vital"."log_ai_decision_event"("p_event_name" "text", "p_reason_code" "text", "p_reason_text" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_source" "text" DEFAULT 'ai'::"text", "p_model_name" "text" DEFAULT NULL::"text", "p_prompt_version" "text" DEFAULT 'v1'::"text", "p_occurred_at" timestamp with time zone DEFAULT "now"()) RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_id uuid;
begin
  if v_user_id is null then
    raise exception 'auth.uid() is null';
  end if;

  insert into vital.ai_decision_logs(
    user_id,
    event_name,
    reason_code,
    reason_text,
    payload,
    source,
    model_name,
    prompt_version,
    occurred_at
  )
  values (
    v_user_id,
    coalesce(nullif(trim(coalesce(p_event_name, '')), ''), 'ai_event'),
    coalesce(nullif(trim(coalesce(p_reason_code, '')), ''), 'none'),
    coalesce(nullif(trim(coalesce(p_reason_text, '')), ''), 'no_reason'),
    coalesce(p_payload, '{}'::jsonb),
    coalesce(nullif(trim(coalesce(p_source, '')), ''), 'ai'),
    nullif(trim(coalesce(p_model_name, '')), ''),
    coalesce(nullif(trim(coalesce(p_prompt_version, '')), ''), 'v1'),
    coalesce(p_occurred_at, now())
  )
  returning id into v_id;

  perform vital.track_decision_event(
    coalesce(nullif(trim(coalesce(p_event_name, '')), ''), 'ai_event'),
    coalesce(nullif(trim(coalesce(p_reason_code, '')), ''), 'none'),
    coalesce(nullif(trim(coalesce(p_reason_text, '')), ''), 'no_reason'),
    coalesce(p_payload, '{}'::jsonb),
    coalesce(nullif(trim(coalesce(p_source, '')), ''), 'ai'),
    coalesce(p_occurred_at, now()),
    'v1'
  );

  return v_id;
end;
$$;


ALTER FUNCTION "vital"."log_ai_decision_event"("p_event_name" "text", "p_reason_code" "text", "p_reason_text" "text", "p_payload" "jsonb", "p_source" "text", "p_model_name" "text", "p_prompt_version" "text", "p_occurred_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vital"."plan_cycle_adjustment"("p_target_date" "date" DEFAULT (("now"() AT TIME ZONE 'utc'::"text"))::"date") RETURNS TABLE("module_key" "text", "intensity_delta_pct" integer, "volume_delta_pct" integer, "frequency_delta" integer, "phase" "text", "reason_code" "text", "reason_text" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_state vital.user_cycle_states;
  v_adherence integer := 60;
  v_readiness integer := 60;
  v_interference integer := 0;
  v_phase text := 'build';
  v_weeks_elapsed integer := 1;
begin
  if v_user_id is null then
    raise exception 'auth.uid() is null';
  end if;

  v_state := vital.get_or_create_cycle_state();

  select coalesce(
    round(
      100.0
      * sum(case when ti.status = 'completed' then 1 else 0 end)::numeric
      / nullif(count(*), 0)
    )::integer,
    60
  )
  into v_adherence
  from vital.task_instances ti
  where ti.user_id = v_user_id
    and ti.task_date between (p_target_date - 6) and p_target_date;

  select coalesce(
    round((dri.sleep_score::numeric + (100 - dri.stress_score)::numeric + dri.energy_score::numeric) / 3)::integer,
    60
  )
  into v_readiness
  from vital.daily_readiness_inputs dri
  where dri.user_id = v_user_id
    and dri.input_date = p_target_date;

  select coalesce(sum(mir.next_day_penalty), 0)::integer
  into v_interference
  from vital.task_instances ti
  join vital.module_interference_rules mir
    on mir.secondary_module_key = ti.module_key
  where ti.user_id = v_user_id
    and ti.task_date = p_target_date - 1
    and ti.status <> 'skipped';

  v_weeks_elapsed := greatest(1, ((p_target_date - v_state.cycle_start_date) / 7) + 1);

  if v_readiness < 45 or v_interference >= 10 then
    v_phase := 'deload';
  elsif v_adherence < 50 then
    v_phase := 'maintain';
  elsif (v_weeks_elapsed % greatest(2, v_state.cycle_length_weeks)) = 0 then
    v_phase := 'deload';
  else
    v_phase := 'build';
  end if;

  update vital.user_cycle_states
  set
    current_week = least(v_state.cycle_length_weeks, greatest(1, v_weeks_elapsed::smallint)),
    phase = v_phase,
    last_readiness = v_readiness,
    last_adherence = v_adherence,
    last_interference_penalty = v_interference,
    updated_at = now()
  where user_id = v_user_id;

  return query
  with enabled_modules as (
    select ump.module_key
    from vital.get_user_module_preferences() as ump(module_key, is_enabled, config)
    where ump.is_enabled
  )
  select
    em.module_key,
    case
      when v_phase = 'deload' and em.module_key = 'training' then -25
      when v_phase = 'deload' and em.module_key = 'recovery' then -5
      when v_phase = 'build' and em.module_key = 'training' then 10
      when v_phase = 'build' and em.module_key = 'recovery' then 5
      when v_phase = 'maintain' and em.module_key = 'training' then 0
      else 0
    end::integer as intensity_delta_pct,
    case
      when v_phase = 'deload' and em.module_key = 'training' then -30
      when v_phase = 'deload' and em.module_key = 'recovery' then -10
      when v_phase = 'build' and em.module_key = 'training' then 8
      when v_phase = 'build' and em.module_key = 'nutrition' then 5
      when v_phase = 'maintain' then 0
      else 0
    end::integer as volume_delta_pct,
    case
      when v_phase = 'deload' and em.module_key = 'training' then -1
      when v_phase = 'build' and em.module_key = 'training' then 1
      else 0
    end::integer as frequency_delta,
    v_phase,
    case
      when v_phase = 'deload' and v_interference >= 10 then 'deload_interference_guard'
      when v_phase = 'deload' and v_readiness < 45 then 'deload_low_readiness'
      when v_phase = 'deload' then 'deload_cycle_boundary'
      when v_phase = 'maintain' then 'maintain_low_adherence'
      else 'build_progression'
    end as reason_code,
    case
      when v_phase = 'deload' and v_interference >= 10 then 'Se aplica deload por interferencia alta acumulada del dia anterior.'
      when v_phase = 'deload' and v_readiness < 45 then 'Se aplica deload por readiness bajo para proteger recuperacion.'
      when v_phase = 'deload' then 'Semana de deload por limite de microciclo.'
      when v_phase = 'maintain' then 'Se mantiene carga por adherencia baja hasta estabilizar consistencia.'
      else 'Fase de progresion activa: incremento moderado de carga.'
    end as reason_text
  from enabled_modules em
  order by
    case em.module_key
      when 'training' then 1
      when 'recovery' then 2
      when 'nutrition' then 3
      when 'habits' then 4
      else 9
    end;
end
$$;


ALTER FUNCTION "vital"."plan_cycle_adjustment"("p_target_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vital"."plan_weekly_fused_schedule"("p_week_start" "date" DEFAULT ("date_trunc"('week'::"text", ("now"() AT TIME ZONE 'utc'::"text")))::"date", "p_dominant_objective" "text" DEFAULT NULL::"text") RETURNS TABLE("plan_date" "date", "module_key" "text", "task_type" "text", "title" "text", "estimated_minutes" smallint, "blend_weight" smallint, "conflict_penalty" smallint, "priority_hint" integer, "interference_note" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_week_start date := coalesce(p_week_start, date_trunc('week', (now() at time zone 'utc'))::date);
  v_primary_sport text := 'generic';
  v_global_objectives jsonb := '[]'::jsonb;
  v_dominant_objective text := coalesce(nullif(trim(p_dominant_objective), ''), 'any');
  v_sports jsonb := '[]'::jsonb;
begin
  if v_user_id is null then
    raise exception 'auth.uid() is null';
  end if;

  select sp.sports, sp.primary_sport, sp.global_objectives
    into v_sports, v_primary_sport, v_global_objectives
  from vital.get_sports_profile() as sp(
    sports,
    primary_sport,
    global_objectives,
    constraints,
    cycle_config,
    profile_version,
    updated_at
  );

  v_sports := coalesce(v_sports, '[]'::jsonb);
  v_primary_sport := coalesce(nullif(v_primary_sport, ''), 'generic');

  if v_dominant_objective = 'any' and exists (
    select 1
    from jsonb_array_elements_text(coalesce(v_global_objectives, '[]'::jsonb)) go
    where go = 'performance'
  ) then
    v_dominant_objective := 'performance';
  elsif v_dominant_objective = 'any' and exists (
    select 1
    from jsonb_array_elements_text(coalesce(v_global_objectives, '[]'::jsonb)) go
    where go = 'strength'
  ) then
    v_dominant_objective := 'strength';
  end if;

  return query
  with enabled_modules as (
    select ump.module_key
    from vital.get_user_module_preferences() as ump(module_key, is_enabled, config)
    where ump.is_enabled
  ),
  week_days as (
    select generate_series(v_week_start, v_week_start + 6, interval '1 day')::date as plan_date
  ),
  base_templates as (
    select
      tt.id as task_template_id,
      tt.module_key,
      tt.task_type,
      tt.title,
      coalesce(tt.estimated_minutes, 10)::smallint as estimated_minutes,
      coalesce(tt.ordering, 1)::smallint as ordering,
      coalesce(tt.recurrence_rule, '{}'::jsonb) as recurrence_rule,
      coalesce(tt.payload, '{}'::jsonb) as payload
    from vital.task_templates tt
    join enabled_modules em
      on em.module_key = tt.module_key
    where tt.user_id = v_user_id
      and tt.is_active
  ),
  expanded as (
    select
      wd.plan_date,
      bt.task_template_id,
      bt.module_key,
      bt.task_type,
      bt.title,
      bt.estimated_minutes,
      bt.ordering,
      bt.payload,
      coalesce(nullif(bt.payload ->> 'sport_key', ''), 'generic') as template_sport_key
    from base_templates bt
    join week_days wd on true
    where
      case
        when jsonb_typeof(bt.recurrence_rule -> 'days') = 'array' then
          extract(isodow from wd.plan_date)::int in (
            select value::int
            from jsonb_array_elements_text(bt.recurrence_rule -> 'days')
          )
        else true
      end
  ),
  with_blend as (
    select
      e.*,
      coalesce(sobr.weight_pct, sobr_any.weight_pct, 20)::smallint as base_blend_weight,
      coalesce(sobr.max_sessions_per_week, sobr_any.max_sessions_per_week, 7)::smallint as max_sessions_per_week,
      coalesce((
        select case upper(coalesce(sport_item ->> 'priority', 'C'))
          when 'A' then 1.00
          when 'B' then 0.85
          when 'C' then 0.70
          else 0.65
        end
        from jsonb_array_elements(v_sports) as sport_item
        where sport_item ->> 'key' = e.template_sport_key
        limit 1
      ), case when e.template_sport_key = 'generic' then 0.80 else 0.55 end)::numeric as sport_priority_multiplier
    from expanded e
    left join vital.sport_objective_blend_rules sobr
      on sobr.module_key = e.module_key
     and sobr.sport_key = v_primary_sport
     and sobr.objective_key = v_dominant_objective
    left join vital.sport_objective_blend_rules sobr_any
      on sobr_any.module_key = e.module_key
     and sobr_any.sport_key = 'generic'
     and sobr_any.objective_key = 'any'
  ),
  week_limited as (
    select
      wb.*,
      greatest(8, least(95, round(wb.base_blend_weight::numeric * wb.sport_priority_multiplier)))::smallint as blend_weight,
      row_number() over (partition by wb.module_key order by wb.plan_date, wb.ordering, wb.task_template_id)::int as rn_module_week
    from with_blend wb
  ),
  valid_rows as (
    select *
    from week_limited wl
    where wl.rn_module_week <= wl.max_sessions_per_week
  ),
  same_day_counts as (
    select
      vr.plan_date,
      vr.module_key,
      count(*)::int as module_tasks_count
    from valid_rows vr
    group by vr.plan_date, vr.module_key
  ),
  scored as (
    select
      vr.plan_date,
      vr.module_key,
      vr.task_type,
      vr.title,
      vr.estimated_minutes,
      vr.blend_weight,
      coalesce((
        select max(mir.same_day_penalty)
        from same_day_counts sdc2
        join vital.module_interference_rules mir
          on mir.primary_module_key = vr.module_key
         and mir.secondary_module_key = sdc2.module_key
        where sdc2.plan_date = vr.plan_date
          and sdc2.module_key <> vr.module_key
      ), 0)::smallint as conflict_penalty,
      coalesce((
        select mir.note
        from same_day_counts sdc2
        join vital.module_interference_rules mir
          on mir.primary_module_key = vr.module_key
         and mir.secondary_module_key = sdc2.module_key
        where sdc2.plan_date = vr.plan_date
          and sdc2.module_key <> vr.module_key
        order by mir.same_day_penalty desc
        limit 1
      ), 'Sin interferencias relevantes detectadas.') as interference_note,
      vr.ordering,
      vr.task_template_id
    from valid_rows vr
  )
  select
    s.plan_date,
    s.module_key,
    s.task_type,
    s.title,
    s.estimated_minutes,
    s.blend_weight,
    s.conflict_penalty,
    greatest(
      10,
      least(
        99,
        (40 + (s.blend_weight / 2) - s.conflict_penalty - (s.ordering - 1))::int
      )
    ) as priority_hint,
    s.interference_note
  from scored s
  order by s.plan_date asc, priority_hint desc, s.module_key asc, s.title asc;
end
$$;


ALTER FUNCTION "vital"."plan_weekly_fused_schedule"("p_week_start" "date", "p_dominant_objective" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vital"."reprogram_task_instance"("p_task_instance_id" "uuid", "p_new_date" "date") RETURNS "vital"."task_instances"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
declare
  v_row vital.task_instances;
begin
  if p_new_date is null then
    raise exception 'p_new_date is required';
  end if;

  begin
    update vital.task_instances ti
    set
      task_date = p_new_date,
      status = 'pending',
      snooze_until = null,
      completed_at = null,
      updated_at = now()
    where ti.id = p_task_instance_id
      and ti.user_id = auth.uid()
    returning ti.* into v_row;
  exception
    when unique_violation then
      raise exception 'task already exists for template and date';
  end;

  if v_row.id is null then
    raise exception 'task_instance not found or access denied';
  end if;

  return v_row;
end
$$;


ALTER FUNCTION "vital"."reprogram_task_instance"("p_task_instance_id" "uuid", "p_new_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vital"."set_task_completion_minlog"("p_task_instance_id" "uuid", "p_done" boolean, "p_rpe_simple" numeric DEFAULT NULL::numeric, "p_weight_kg" numeric DEFAULT NULL::numeric) RETURNS "vital"."task_instances"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
declare
  v_row vital.task_instances;
  v_payload jsonb := '{}'::jsonb;
begin
  if p_rpe_simple is not null and (p_rpe_simple < 0 or p_rpe_simple > 10) then
    raise exception 'p_rpe_simple must be between 0 and 10';
  end if;

  if p_weight_kg is not null and p_weight_kg <= 0 then
    raise exception 'p_weight_kg must be greater than 0';
  end if;

  v_payload := jsonb_build_object('done', coalesce(p_done, false));
  if p_rpe_simple is not null then
    v_payload := v_payload || jsonb_build_object('rpe_simple', p_rpe_simple);
  end if;
  if p_weight_kg is not null then
    v_payload := v_payload || jsonb_build_object('weight_kg', p_weight_kg);
  end if;

  update vital.task_instances ti
  set
    status = case when coalesce(p_done, false) then 'completed'::vital.task_status else 'pending'::vital.task_status end,
    completed_at = case when coalesce(p_done, false) then now() else null end,
    completion_payload = coalesce(ti.completion_payload, '{}'::jsonb) || v_payload,
    updated_at = now()
  where ti.id = p_task_instance_id
    and ti.user_id = auth.uid()
  returning ti.* into v_row;

  if v_row.id is null then
    raise exception 'task_instance not found or access denied';
  end if;

  return v_row;
end
$$;


