CREATE OR REPLACE FUNCTION "vital"."staff_weekly_squad_overview"("p_squad_id" "uuid", "p_week_start" "date" DEFAULT ("date_trunc"('week'::"text", ("now"() AT TIME ZONE 'utc'::"text")))::"date") RETURNS TABLE("user_id" "uuid", "display_name" "text", "tasks_planned" integer, "tasks_completed" integer, "adherence_pct" numeric, "training_load" integer, "recovery_load" integer, "last_readiness" integer, "risk_level" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
declare
  v_requester uuid := auth.uid();
  v_allowed boolean := false;
  v_week_start date := coalesce(p_week_start, date_trunc('week', (now() at time zone 'utc'))::date);
begin
  if v_requester is null then
    raise exception 'auth.uid() is null';
  end if;

  if p_squad_id is null then
    raise exception 'p_squad_id is required';
  end if;

  select (
    vital.is_vital_admin()
    or vital.is_service_role()
    or exists (
      select 1
      from vital.squads s
      where s.id = p_squad_id
        and s.owner_user_id = v_requester
    )
    or exists (
      select 1
      from vital.academy_staff_assignments asa
      where asa.squad_id = p_squad_id
        and asa.user_id = v_requester
        and asa.active
    )
  ) into v_allowed;

  if not coalesce(v_allowed, false) then
    raise exception 'access denied for squad overview';
  end if;

  return query
  with members as (
    select distinct sm.user_id
    from vital.squad_memberships sm
    where sm.squad_id = p_squad_id
      and sm.active
  ),
  week_tasks as (
    select
      ti.user_id,
      count(*)::int as tasks_planned,
      sum(case when ti.status = 'completed' then 1 else 0 end)::int as tasks_completed,
      sum(case when ti.module_key = 'training' and ti.status = 'completed' then 1 else 0 end)::int as training_load,
      sum(case when ti.module_key = 'recovery' and ti.status = 'completed' then 1 else 0 end)::int as recovery_load
    from vital.task_instances ti
    join members m on m.user_id = ti.user_id
    where ti.task_date between v_week_start and (v_week_start + 6)
    group by ti.user_id
  ),
  latest_readiness as (
    select distinct on (dri.user_id)
      dri.user_id,
      round((dri.sleep_score + (100 - dri.stress_score) + dri.energy_score) / 3.0)::int as readiness
    from vital.daily_readiness_inputs dri
    join members m on m.user_id = dri.user_id
    where dri.input_date between v_week_start and (v_week_start + 6)
    order by dri.user_id, dri.input_date desc
  )
  select
    m.user_id,
    coalesce(up.display_name, 'Sin nombre') as display_name,
    coalesce(wt.tasks_planned, 0)::int as tasks_planned,
    coalesce(wt.tasks_completed, 0)::int as tasks_completed,
    coalesce(round((100.0 * wt.tasks_completed::numeric) / nullif(wt.tasks_planned, 0), 2), 0)::numeric as adherence_pct,
    coalesce(wt.training_load, 0)::int as training_load,
    coalesce(wt.recovery_load, 0)::int as recovery_load,
    coalesce(lr.readiness, null)::int as last_readiness,
    coalesce(si.risk_level, 'low')::text as risk_level
  from members m
  left join vital.user_profiles up on up.user_id = m.user_id
  left join week_tasks wt on wt.user_id = m.user_id
  left join latest_readiness lr on lr.user_id = m.user_id
  left join vital.safety_intake si on si.user_id = m.user_id
  order by adherence_pct desc, training_load desc, m.user_id;
end
$$;


ALTER FUNCTION "vital"."staff_weekly_squad_overview"("p_squad_id" "uuid", "p_week_start" "date") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "vital"."safety_intake" (
    "user_id" "uuid" NOT NULL,
    "intake_payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "risk_level" "text" DEFAULT 'low'::"text" NOT NULL,
    "blocked_modules" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "requires_professional_check" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "safety_intake_risk_level_check" CHECK (("risk_level" = ANY (ARRAY['low'::"text", 'medium'::"text", 'high'::"text", 'critical'::"text"])))
);


ALTER TABLE "vital"."safety_intake" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vital"."submit_safety_intake"("p_payload" "jsonb") RETURNS "vital"."safety_intake"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_chest_pain boolean := coalesce((v_payload ->> 'chest_pain')::boolean, false);
  v_dizziness boolean := coalesce((v_payload ->> 'dizziness')::boolean, false);
  v_severe_injury boolean := coalesce((v_payload ->> 'severe_injury')::boolean, false);
  v_post_surgery boolean := coalesce((v_payload ->> 'post_surgery')::boolean, false);
  v_pregnancy_risk boolean := coalesce((v_payload ->> 'pregnancy_risk')::boolean, false);
  v_risk_level text := 'low';
  v_blocked_modules jsonb := '[]'::jsonb;
  v_row vital.safety_intake;
begin
  if v_user_id is null then
    raise exception 'auth.uid() is null';
  end if;

  if v_chest_pain or v_dizziness or v_severe_injury or v_post_surgery or v_pregnancy_risk then
    v_risk_level := 'critical';
    v_blocked_modules := '["training"]'::jsonb;
  elsif coalesce((v_payload ->> 'joint_pain')::boolean, false) then
    v_risk_level := 'high';
    v_blocked_modules := '["training"]'::jsonb;
  elsif coalesce((v_payload ->> 'chronic_condition')::boolean, false) then
    v_risk_level := 'medium';
  end if;

  insert into vital.safety_intake (
    user_id,
    intake_payload,
    risk_level,
    blocked_modules,
    requires_professional_check
  )
  values (
    v_user_id,
    v_payload,
    v_risk_level,
    v_blocked_modules,
    v_risk_level in ('high', 'critical')
  )
  on conflict (user_id) do update
  set
    intake_payload = excluded.intake_payload,
    risk_level = excluded.risk_level,
    blocked_modules = excluded.blocked_modules,
    requires_professional_check = excluded.requires_professional_check,
    updated_at = now()
  returning * into v_row;

  return v_row;
end
$$;


ALTER FUNCTION "vital"."submit_safety_intake"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vital"."today_feed"("p_target_date" "date" DEFAULT (("now"() AT TIME ZONE 'utc'::"text"))::"date") RETURNS TABLE("id" "uuid", "user_id" "uuid", "task_template_id" "uuid", "task_date" "date", "status" "vital"."task_status", "priority" smallint, "module_key" "text", "task_type" "text", "title" "text", "estimated_minutes" smallint, "ordering" smallint, "template_payload" "jsonb", "completion_payload" "jsonb", "priority_score" integer, "reason_code" "text", "reason_text" "text", "safety_state" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception 'auth.uid() is null';
  end if;

  perform 1 from vital.today_tasks(p_target_date);

  return query
  with scores as (
    select *
    from vital.compute_hoy_scores(p_target_date)
  )
  select
    ti.id,
    ti.user_id,
    ti.task_template_id,
    ti.task_date,
    ti.status,
    ti.priority,
    ti.module_key,
    tt.task_type,
    tt.title,
    tt.estimated_minutes,
    tt.ordering,
    tt.payload as template_payload,
    ti.completion_payload,
    s.priority_score,
    s.reason_code,
    s.reason_text,
    s.safety_state,
    ti.created_at,
    ti.updated_at
  from vital.task_instances ti
  join vital.task_templates tt
    on tt.id = ti.task_template_id
   and tt.user_id = ti.user_id
  join scores s
    on s.task_instance_id = ti.id
  where ti.user_id = v_user_id
    and ti.task_date = p_target_date
  order by
    case when s.safety_state = 'blocked' then 1 else 0 end asc,
    s.priority_score desc,
    tt.ordering asc,
    ti.created_at asc;
end
$$;


ALTER FUNCTION "vital"."today_feed"("p_target_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vital"."today_notification_intents"("p_target_date" "date" DEFAULT (("now"() AT TIME ZONE 'utc'::"text"))::"date") RETURNS TABLE("task_instance_id" "uuid", "task_type" "text", "title" "text", "notify_at" timestamp with time zone, "schedule_type" "text")
    LANGUAGE "sql"
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
  with ctx as (
    select coalesce(up.timezone, 'UTC') as tz
    from vital.user_profiles up
    where up.user_id = auth.uid()
  )
  select
    t.id as task_instance_id,
    t.task_type,
    t.title,
    case
      when np.schedule ->> 'type' = 'fixed_time' then
        make_timestamptz(
          extract(year from p_target_date)::int,
          extract(month from p_target_date)::int,
          extract(day from p_target_date)::int,
          (np.schedule ->> 'hour')::int,
          (np.schedule ->> 'minute')::int,
          0,
          coalesce(np.schedule ->> 'timezone', (select tz from ctx), 'UTC')
        )
      when np.schedule ->> 'type' = 'relative_to_window'
           and t.window_start is not null then
        t.window_start + make_interval(mins => (np.schedule ->> 'offset_minutes')::int)
      else null
    end as notify_at,
    np.schedule ->> 'type' as schedule_type
  from vital.today_tasks(p_target_date) t
  join vital.notification_plans np
    on np.user_id = t.user_id
   and np.task_type = t.task_type
   and np.enabled
  where t.user_id = auth.uid();
$$;


ALTER FUNCTION "vital"."today_notification_intents"("p_target_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vital"."today_tasks"("p_target_date" "date" DEFAULT (("now"() AT TIME ZONE 'utc'::"text"))::"date") RETURNS TABLE("id" "uuid", "user_id" "uuid", "task_template_id" "uuid", "task_date" "date", "status" "vital"."task_status", "priority" smallint, "window_start" timestamp with time zone, "window_end" timestamp with time zone, "snooze_until" timestamp with time zone, "completed_at" timestamp with time zone, "completion_payload" "jsonb", "task_type" "text", "title" "text", "estimated_minutes" smallint, "ordering" smallint, "template_payload" "jsonb", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception 'auth.uid() is null';
  end if;

  insert into vital.task_instances (
    user_id,
    task_template_id,
    module_key,
    task_date,
    status,
    priority
  )
  select
    tt.user_id,
    tt.id,
    tt.module_key,
    p_target_date,
    'pending'::vital.task_status,
    50::smallint
  from vital.task_templates tt
  join vital.program_versions pv
    on pv.id = tt.program_version_id
   and pv.user_id = tt.user_id
   and pv.is_active
  join vital.programs p
    on p.id = pv.program_id
   and p.user_id = pv.user_id
   and p.is_active
  where tt.user_id = v_user_id
    and tt.is_active
    and vital.should_materialize_on_date(tt.recurrence_rule, p_target_date)
    and not exists (
      select 1
      from vital.task_instances ti
      where ti.task_template_id = tt.id
        and ti.task_date = p_target_date
    );

  return query
  select
    ti.id,
    ti.user_id,
    ti.task_template_id,
    ti.task_date,
    ti.status,
    ti.priority,
    ti.window_start,
    ti.window_end,
    ti.snooze_until,
    ti.completed_at,
    ti.completion_payload,
    tt.task_type,
    tt.title,
    tt.estimated_minutes,
    tt.ordering,
    tt.payload as template_payload,
    ti.created_at,
    ti.updated_at
  from vital.task_instances ti
  join vital.task_templates tt
    on tt.id = ti.task_template_id
   and tt.user_id = ti.user_id
  where ti.user_id = v_user_id
    and ti.task_date = p_target_date
  order by ti.priority desc, tt.ordering asc, ti.created_at asc;
end
$$;


ALTER FUNCTION "vital"."today_tasks"("p_target_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vital"."track_decision_event"("p_event_name" "text", "p_reason_code" "text", "p_reason_text" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_source" "text" DEFAULT 'app'::"text", "p_occurred_at" timestamp with time zone DEFAULT "now"(), "p_event_version" "text" DEFAULT 'v1'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_event_name text := nullif(trim(coalesce(p_event_name, '')), '');
  v_reason_code text := nullif(trim(coalesce(p_reason_code, '')), '');
  v_reason_text text := nullif(trim(coalesce(p_reason_text, '')), '');
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
begin
  if v_user_id is null then
    raise exception 'auth.uid() is null';
  end if;

  if v_event_name is null then
    raise exception 'p_event_name is required';
  end if;

  if v_reason_code is null then
    raise exception 'p_reason_code is required';
  end if;

  if v_reason_text is null then
    raise exception 'p_reason_text is required';
  end if;

  return vital.track_event(
    v_event_name,
    jsonb_build_object(
      'reason_code', v_reason_code,
      'reason_text', v_reason_text,
      'observability_source', 'decision_trace'
    ) || v_payload,
    coalesce(nullif(trim(coalesce(p_source, '')), ''), 'app'),
    coalesce(p_occurred_at, now()),
    coalesce(nullif(trim(coalesce(p_event_version, '')), ''), 'v1')
  );
end
$$;


ALTER FUNCTION "vital"."track_decision_event"("p_event_name" "text", "p_reason_code" "text", "p_reason_text" "text", "p_payload" "jsonb", "p_source" "text", "p_occurred_at" timestamp with time zone, "p_event_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vital"."track_event"("p_event_name" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_source" "text" DEFAULT 'app'::"text", "p_occurred_at" timestamp with time zone DEFAULT "now"(), "p_event_version" "text" DEFAULT 'v1'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_event_name text := nullif(trim(coalesce(p_event_name, '')), '');
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_source text := coalesce(nullif(trim(coalesce(p_source, '')), ''), 'app');
  v_event_version text := coalesce(nullif(trim(coalesce(p_event_version, '')), ''), 'v1');
  v_event_id uuid;
begin
  if v_user_id is null then
    raise exception 'auth.uid() is null';
  end if;

  if v_event_name is null then
    raise exception 'p_event_name is required';
  end if;

  insert into vital.telemetry_events (
    user_id,
    event_name,
    payload,
    source,
    event_version,
    occurred_at
  )
  values (
    v_user_id,
    v_event_name,
    v_payload,
    v_source,
    v_event_version,
    coalesce(p_occurred_at, now())
  )
  returning id into v_event_id;

  return v_event_id;
end
$$;


ALTER FUNCTION "vital"."track_event"("p_event_name" "text", "p_payload" "jsonb", "p_source" "text", "p_occurred_at" timestamp with time zone, "p_event_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vital"."upsert_daily_nutrition_log_v1"("p_input_date" "date", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "vital"."daily_nutrition_logs_v1"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_date date := coalesce(p_input_date, (now() at time zone 'utc')::date);
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_row vital.daily_nutrition_logs_v1;
begin
  if v_user_id is null then
    raise exception 'auth.uid() is null';
  end if;

  insert into vital.daily_nutrition_logs_v1(
    user_id,
    input_date,
    meals_logged,
    hydration_l,
    calories_consumed,
    protein_g,
    carbs_g,
    fat_g,
    adherence_score,
    payload,
    source
  )
  values (
    v_user_id,
    v_date,
    coalesce((v_payload ->> 'meals_logged')::smallint, 0),
    coalesce((v_payload ->> 'hydration_l')::numeric, 0),
    (v_payload ->> 'calories_consumed')::integer,
    (v_payload ->> 'protein_g')::integer,
    (v_payload ->> 'carbs_g')::integer,
    (v_payload ->> 'fat_g')::integer,
    coalesce((v_payload ->> 'adherence_score')::smallint, 0),
    v_payload,
    coalesce(nullif(trim(coalesce(v_payload ->> 'source', '')), ''), 'manual')
  )
  on conflict (user_id, input_date) do update
  set
    meals_logged = excluded.meals_logged,
    hydration_l = excluded.hydration_l,
    calories_consumed = excluded.calories_consumed,
    protein_g = excluded.protein_g,
    carbs_g = excluded.carbs_g,
    fat_g = excluded.fat_g,
    adherence_score = excluded.adherence_score,
    payload = excluded.payload,
    source = excluded.source,
    updated_at = now()
  returning * into v_row;

  return v_row;
end;
$$;


ALTER FUNCTION "vital"."upsert_daily_nutrition_log_v1"("p_input_date" "date", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vital"."upsert_notification_plan"("p_task_type" "text", "p_schedule" "jsonb", "p_enabled" boolean DEFAULT true) RETURNS "vital"."notification_plans"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_row vital.notification_plans;
begin
  if v_user_id is null then
    raise exception 'auth.uid() is null';
  end if;

  if p_task_type is null or btrim(p_task_type) = '' then
    raise exception 'p_task_type is required';
  end if;

  if not vital.validate_notification_schedule(p_schedule) then
    raise exception 'invalid notification schedule payload';
  end if;

  insert into vital.notification_plans (
    user_id,
    task_type,
    schedule,
    enabled
  )
  values (
    v_user_id,
    p_task_type,
    p_schedule,
    coalesce(p_enabled, true)
  )
  on conflict (user_id, task_type)
  do update set
    schedule = excluded.schedule,
    enabled = excluded.enabled,
    updated_at = now()
  returning * into v_row;

  return v_row;
end
$$;


ALTER FUNCTION "vital"."upsert_notification_plan"("p_task_type" "text", "p_schedule" "jsonb", "p_enabled" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vital"."upsert_nutrition_profile_v1"("p_payload" "jsonb") RETURNS "vital"."user_nutrition_profiles_v1"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
