    hydration_goal_l,
    meals_per_day,
    calories_target,
    protein_g_target,
    carbs_g_target,
    fat_g_target
  )
  values (
    v_user_id,
    v_payload,
    coalesce((v_payload ->> 'hydration_goal_l')::numeric, 2.0),
    coalesce((v_payload ->> 'meals_per_day')::smallint, 3),
    (v_payload ->> 'calories_target')::integer,
    (v_payload ->> 'protein_g_target')::integer,
    (v_payload ->> 'carbs_g_target')::integer,
    (v_payload ->> 'fat_g_target')::integer
  )
  on conflict (user_id) do update
  set
    profile_payload = excluded.profile_payload,
    hydration_goal_l = excluded.hydration_goal_l,
    meals_per_day = excluded.meals_per_day,
    calories_target = excluded.calories_target,
    protein_g_target = excluded.protein_g_target,
    carbs_g_target = excluded.carbs_g_target,
    fat_g_target = excluded.fat_g_target,
    updated_at = now()
  returning * into v_row;

  return v_row;
end;
$$;


ALTER FUNCTION "vital"."upsert_nutrition_profile_v1"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "vital"."upsert_sports_profile"("p_payload" "jsonb") RETURNS TABLE("sports" "jsonb", "primary_sport" "text", "global_objectives" "jsonb", "constraints" "jsonb", "cycle_config" "jsonb", "profile_version" integer, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'vital', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_sports jsonb := coalesce(v_payload -> 'sports', '[]'::jsonb);
  v_primary_sport text := nullif(trim(v_payload ->> 'primary_sport'), '');
  v_global_objectives jsonb := coalesce(v_payload -> 'global_objectives', '[]'::jsonb);
  v_constraints jsonb := coalesce(v_payload -> 'constraints', '{}'::jsonb);
  v_cycle_config jsonb := coalesce(v_payload -> 'cycle_config', '{"dominant_focus":"balanced","cycle_weeks":4}'::jsonb);
begin
  if v_user_id is null then
    raise exception 'auth.uid() is null';
  end if;
  if jsonb_typeof(v_sports) <> 'array' then
    raise exception 'sports must be a json array';
  end if;
  if jsonb_typeof(v_global_objectives) <> 'array' then
    raise exception 'global_objectives must be a json array';
  end if;
  if jsonb_typeof(v_constraints) <> 'object' then
    raise exception 'constraints must be a json object';
  end if;
  if jsonb_typeof(v_cycle_config) <> 'object' then
    raise exception 'cycle_config must be a json object';
  end if;
  if v_primary_sport is not null and not exists (
    select 1
    from jsonb_array_elements(v_sports) s
    where s ->> 'key' = v_primary_sport
  ) then
    raise exception 'primary_sport must exist in sports list';
  end if;

  insert into vital.sports_profiles (
    user_id,
    sports,
    primary_sport,
    global_objectives,
    constraints,
    cycle_config
  )
  values (
    v_user_id,
    v_sports,
    v_primary_sport,
    v_global_objectives,
    v_constraints,
    v_cycle_config
  )
  on conflict (user_id) do update
  set
    sports = excluded.sports,
    primary_sport = excluded.primary_sport,
    global_objectives = excluded.global_objectives,
    constraints = excluded.constraints,
    cycle_config = excluded.cycle_config,
    profile_version = vital.sports_profiles.profile_version + 1,
    updated_at = now();

  return query
  select *
  from vital.get_sports_profile();
end
$$;


ALTER FUNCTION "vital"."upsert_sports_profile"("p_payload" "jsonb") OWNER TO "postgres";


