    CONSTRAINT "pass_catalog_item_option_consumption_rules_input_qty_check" CHECK ((("input_quantity_per_option" IS NULL) OR ("input_quantity_per_option" > (0)::numeric))),
    CONSTRAINT "pass_catalog_item_option_consumption_rules_location_strategy_ch" CHECK (((("source_location_strategy" = 'product_production_location'::"text") AND ("source_location_id" IS NULL) AND ("source_location_position_id" IS NULL)) OR (("source_location_strategy" = 'explicit_location'::"text") AND ("source_location_id" IS NOT NULL) AND ("source_location_position_id" IS NULL)) OR (("source_location_strategy" = 'explicit_position'::"text") AND ("source_location_id" IS NOT NULL) AND ("source_location_position_id" IS NOT NULL)))),
    CONSTRAINT "pass_catalog_item_option_consumption_rules_metadata_object" CHECK (("jsonb_typeof"("metadata") = 'object'::"text")),
    CONSTRAINT "pass_catalog_item_option_consumption_rules_name_not_blank" CHECK (("length"("btrim"("name")) > 0)),
    CONSTRAINT "pass_catalog_item_option_consumption_rules_quantity_check" CHECK (("quantity_per_option" > (0)::numeric)),
    CONSTRAINT "pass_catalog_item_option_consumption_rules_strategy_check" CHECK (("source_location_strategy" = ANY (ARRAY['product_production_location'::"text", 'explicit_location'::"text", 'explicit_position'::"text"])))
);


ALTER TABLE "pass"."catalog_item_option_consumption_rules" OWNER TO "postgres";


COMMENT ON TABLE "pass"."catalog_item_option_consumption_rules" IS 'Reglas operativas de consumo para opciones comerciales de Pass. Permiten que un extra/modificador consuma producto/insumo desde el LOC correcto al preparar el pedido.';



COMMENT ON COLUMN "pass"."catalog_item_option_consumption_rules"."option_id" IS 'Opcion comercial visible en Pass. Una opcion puede tener una o varias reglas de consumo.';



COMMENT ON COLUMN "pass"."catalog_item_option_consumption_rules"."product_id" IS 'Producto operacional o insumo que se debe consumir cuando esta opcion sea seleccionada.';



COMMENT ON COLUMN "pass"."catalog_item_option_consumption_rules"."quantity_per_option" IS 'Cantidad en unidad stock que se consume por cada unidad seleccionada de la opcion.';



COMMENT ON COLUMN "pass"."catalog_item_option_consumption_rules"."stock_unit_code" IS 'Unidad stock de referencia para quantity_per_option. Si es null, el consumo futuro debe usar products.stock_unit_code o products.unit.';



COMMENT ON COLUMN "pass"."catalog_item_option_consumption_rules"."input_quantity_per_option" IS 'Cantidad capturada en unidad de entrada/presentacion. Opcional; sirve para mostrar y consumir por perfil UOM.';



COMMENT ON COLUMN "pass"."catalog_item_option_consumption_rules"."input_uom_profile_id" IS 'Perfil UOM opcional para consumir por presentacion fisica. Debe pertenecer al product_id de la regla.';



COMMENT ON COLUMN "pass"."catalog_item_option_consumption_rules"."source_location_strategy" IS 'product_production_location usa product_site_settings.production_location_id del producto base del pedido; explicit_location fuerza LOC; explicit_position fuerza posicion interna.';



COMMENT ON COLUMN "pass"."catalog_item_option_consumption_rules"."source_location_id" IS 'LOC explicito para estrategias explicit_location o explicit_position. Debe pertenecer a la sede del item comercial.';



COMMENT ON COLUMN "pass"."catalog_item_option_consumption_rules"."source_location_position_id" IS 'Posicion interna explicita dentro del LOC cuando source_location_strategy = explicit_position.';



COMMENT ON COLUMN "pass"."catalog_item_option_consumption_rules"."effect_type" IS 'Efecto de esta regla de consumo: additive suma consumo adicional; replacement consume el ingrediente sustituto despues de excluir el ingrediente base mediante catalog_item_option_recipe_effects.';



CREATE TABLE IF NOT EXISTS "pass"."catalog_item_option_groups" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
