    "name" "text" NOT NULL,
    "description" "text",
    "selection_type" "text" DEFAULT 'single'::"text" NOT NULL,
    "is_required" boolean DEFAULT false NOT NULL,
    "min_select" integer DEFAULT 0 NOT NULL,
    "max_select" integer DEFAULT 1 NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "display_type" "text" DEFAULT 'radio'::"text" NOT NULL,
    "is_collapsible" boolean DEFAULT true NOT NULL,
    "default_collapsed" boolean DEFAULT false NOT NULL,
    "helper_text" "text",
    CONSTRAINT "pass_catalog_item_option_groups_code_not_blank" CHECK (("length"("btrim"("code")) > 0)),
    CONSTRAINT "pass_catalog_item_option_groups_display_type_check" CHECK (("display_type" = ANY (ARRAY['radio'::"text", 'checkbox'::"text", 'plus'::"text", 'upsell'::"text"]))),
    CONSTRAINT "pass_catalog_item_option_groups_max_select_check" CHECK (("max_select" >= 1)),
    CONSTRAINT "pass_catalog_item_option_groups_metadata_object" CHECK (("jsonb_typeof"("metadata") = 'object'::"text")),
    CONSTRAINT "pass_catalog_item_option_groups_min_select_check" CHECK (("min_select" >= 0)),
    CONSTRAINT "pass_catalog_item_option_groups_name_not_blank" CHECK (("length"("btrim"("name")) > 0)),
    CONSTRAINT "pass_catalog_item_option_groups_required_min_check" CHECK ((("is_required" = false) OR ("min_select" >= 1))),
    CONSTRAINT "pass_catalog_item_option_groups_select_range_check" CHECK (("max_select" >= "min_select")),
    CONSTRAINT "pass_catalog_item_option_groups_selection_type_check" CHECK (("selection_type" = ANY (ARRAY['single'::"text", 'multiple'::"text"]))),
    CONSTRAINT "pass_catalog_item_option_groups_single_max_check" CHECK ((("selection_type" <> 'single'::"text") OR ("max_select" = 1)))
);


ALTER TABLE "pass"."catalog_item_option_groups" OWNER TO "postgres";


COMMENT ON TABLE "pass"."catalog_item_option_groups" IS 'Grupos de opciones configurables por item comercial de Pass. Ej: leche, tamaño, acompañante, extras. Tabla canonica en schema pass.';



COMMENT ON COLUMN "pass"."catalog_item_option_groups"."catalog_item_id" IS 'Item comercial canonico en pass.catalog_items al que pertenece el grupo de opciones.';



COMMENT ON COLUMN "pass"."catalog_item_option_groups"."selection_type" IS 'single permite una opcion; multiple permite varias opciones dentro del grupo.';



COMMENT ON COLUMN "pass"."catalog_item_option_groups"."is_required" IS 'Si es true, Pass debe exigir al menos min_select opciones antes de agregar el producto.';



COMMENT ON COLUMN "pass"."catalog_item_option_groups"."min_select" IS 'Cantidad minima de opciones que debe seleccionar el cliente en este grupo.';



COMMENT ON COLUMN "pass"."catalog_item_option_groups"."max_select" IS 'Cantidad maxima de opciones seleccionables en este grupo. Para selection_type single debe ser 1.';



COMMENT ON COLUMN "pass"."catalog_item_option_groups"."display_type" IS 'Presentacion visual sugerida en Pass: radio para seleccion unica, checkbox para multiple, plus para adiciones rapidas y upsell para productos recomendados vinculables.';



COMMENT ON COLUMN "pass"."catalog_item_option_groups"."is_collapsible" IS 'Permite que el grupo se pueda contraer/expandir en el modal de Pass.';



COMMENT ON COLUMN "pass"."catalog_item_option_groups"."default_collapsed" IS 'Si es true, el grupo aparece contraido por defecto en el modal de Pass.';



COMMENT ON COLUMN "pass"."catalog_item_option_groups"."helper_text" IS 'Texto de ayuda corto para el modal. Si es null, Pass puede construirlo desde minimo/maximo/obligatorio.';



CREATE TABLE IF NOT EXISTS "pass"."catalog_item_option_recipe_effects" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "option_id" "uuid" NOT NULL,
    "effect_type" "text" NOT NULL,
    "target_ingredient_product_id" "uuid" NOT NULL,
    "recipe_component_code" "text",
    "quantity_mode" "text" DEFAULT 'full_recipe_component'::"text" NOT NULL,
    "quantity_amount" numeric,
    "stock_unit_code" "text",
