    CONSTRAINT "pass_catalog_item_option_recipe_effects_effect_type_check" CHECK (("effect_type" = ANY (ARRAY['removal'::"text", 'replacement'::"text"]))),
    CONSTRAINT "pass_catalog_item_option_recipe_effects_fixed_qty_check" CHECK (((("quantity_mode" = 'full_recipe_component'::"text") AND ("quantity_amount" IS NULL)) OR (("quantity_mode" = 'fixed_quantity'::"text") AND ("quantity_amount" IS NOT NULL) AND ("quantity_amount" > (0)::numeric)))),
    CONSTRAINT "pass_catalog_item_option_recipe_effects_metadata_object" CHECK (("jsonb_typeof"("metadata") = 'object'::"text")),
    CONSTRAINT "pass_catalog_item_option_recipe_effects_quantity_mode_check" CHECK (("quantity_mode" = ANY (ARRAY['full_recipe_component'::"text", 'fixed_quantity'::"text"])))
);


ALTER TABLE "pass"."catalog_item_option_recipe_effects" OWNER TO "postgres";


COMMENT ON TABLE "pass"."catalog_item_option_recipe_effects" IS 'Efectos de una opcion comercial sobre la receta base del producto: removal excluye ingrediente; replacement excluye ingrediente base para consumir sustituto mediante reglas de consumo.';



COMMENT ON COLUMN "pass"."catalog_item_option_recipe_effects"."option_id" IS 'Opcion comercial que activa este efecto sobre receta.';



COMMENT ON COLUMN "pass"."catalog_item_option_recipe_effects"."effect_type" IS 'removal evita consumir el ingrediente objetivo; replacement evita consumir el ingrediente objetivo y debe complementarse con una regla de consumo replacement.';



COMMENT ON COLUMN "pass"."catalog_item_option_recipe_effects"."target_ingredient_product_id" IS 'Ingrediente de public.recipes que se debe excluir o reemplazar cuando la opcion sea seleccionada.';



COMMENT ON COLUMN "pass"."catalog_item_option_recipe_effects"."recipe_component_code" IS 'Codigo funcional opcional del componente de receta, por ejemplo milk, sauce, onion. Sirve para agrupar sustituciones futuras sin depender solo del product_id.';



COMMENT ON COLUMN "pass"."catalog_item_option_recipe_effects"."quantity_mode" IS 'full_recipe_component excluye toda la cantidad de ese ingrediente en la receta base. fixed_quantity excluye solo quantity_amount.';



COMMENT ON COLUMN "pass"."catalog_item_option_recipe_effects"."quantity_amount" IS 'Cantidad fija a excluir cuando quantity_mode = fixed_quantity. Si se excluye todo el componente, debe ser null.';



