ALTER TABLE "pass"."catalog_item_presentation" OWNER TO "postgres";


COMMENT ON TABLE "pass"."catalog_item_presentation" IS 'Configuracion visual por item comercial y superficie. Controla como se presenta un producto en Pass sin mezclarlo con metadata tecnica del catalogo.';



COMMENT ON COLUMN "pass"."catalog_item_presentation"."catalog_item_id" IS 'Item comercial canonico en pass.catalog_items.';



COMMENT ON COLUMN "pass"."catalog_item_presentation"."surface" IS 'Superficie donde aplica esta configuracion visual. MVP: vento_pass_menu.';



