CREATE OR REPLACE VIEW "pass"."sell_products_by_site" WITH ("security_invoker"='true') AS
 WITH "recipe_cost" AS (
         SELECT "r"."product_id",
            "sum"(("r"."quantity" * COALESCE("ing"."cost", (0)::numeric))) AS "recipe_total_cost"
           FROM ("public"."recipes" "r"
             JOIN "public"."products" "ing" ON (("ing"."id" = "r"."ingredient_product_id")))
          WHERE (COALESCE("r"."is_active", true) = true)
          GROUP BY "r"."product_id"
        ), "recipe_yield" AS (
         SELECT "rc_1"."product_id",
            NULLIF("rc_1"."yield_qty", (0)::numeric) AS "yield_qty"
           FROM "public"."recipe_cards" "rc_1"
          WHERE (COALESCE("rc_1"."is_active", true) = true)
        )
 SELECT "pss"."site_id",
    "p"."id" AS "product_id",
    "p"."name",
    "p"."sku",
    "p"."description",
    "p"."price" AS "base_price",
        CASE
            WHEN ("rc"."recipe_total_cost" IS NULL) THEN NULL::numeric
            WHEN ("ry"."yield_qty" IS NULL) THEN GREATEST("rc"."recipe_total_cost", (0)::numeric)
            ELSE GREATEST(("rc"."recipe_total_cost" / "ry"."yield_qty"), (0)::numeric)
        END AS "recipe_cost_amount",
        CASE
            WHEN ("p"."price" IS NULL) THEN NULL::numeric
            WHEN ("rc"."recipe_total_cost" IS NULL) THEN NULL::numeric
            WHEN ("ry"."yield_qty" IS NULL) THEN ("p"."price" - "rc"."recipe_total_cost")
            ELSE ("p"."price" - ("rc"."recipe_total_cost" / "ry"."yield_qty"))
        END AS "base_margin_amount",
        CASE
            WHEN (COALESCE("p"."price", (0)::numeric) <= (0)::numeric) THEN NULL::numeric
            WHEN ("rc"."recipe_total_cost" IS NULL) THEN NULL::numeric
            WHEN ("ry"."yield_qty" IS NULL) THEN "round"(((("p"."price" - "rc"."recipe_total_cost") / "p"."price") * (100)::numeric), 2)
            ELSE "round"(((("p"."price" - ("rc"."recipe_total_cost" / "ry"."yield_qty")) / "p"."price") * (100)::numeric), 2)
        END AS "base_margin_pct"
   FROM (((("public"."product_site_settings" "pss"
     JOIN "public"."products" "p" ON (("p"."id" = "pss"."product_id")))
     LEFT JOIN "public"."product_inventory_profiles" "pip" ON (("pip"."product_id" = "p"."id")))
     LEFT JOIN "recipe_cost" "rc" ON (("rc"."product_id" = "p"."id")))
     LEFT JOIN "recipe_yield" "ry" ON (("ry"."product_id" = "p"."id")))
  WHERE ((COALESCE("pss"."is_active", true) = true) AND (COALESCE("p"."is_active", true) = true) AND ((("lower"(COALESCE("p"."product_type", ''::"text")) = ANY (ARRAY['venta'::"text", 'sale'::"text"])) AND (COALESCE("pss"."sales_enabled", true) = true)) OR (("lower"(COALESCE("p"."product_type", ''::"text")) = 'preparacion'::"text") AND (COALESCE("pip"."inventory_kind", 'finished'::"text") = 'finished'::"text") AND (COALESCE("pss"."sales_enabled", false) = true))));


