    CONSTRAINT "client_billing_profiles_document_type_required" CHECK (("length"(TRIM(BOTH FROM "document_type")) > 0)),
    CONSTRAINT "client_billing_profiles_email_required" CHECK (("length"(TRIM(BOTH FROM "billing_email")) > 0)),
    CONSTRAINT "client_billing_profiles_legal_name_required" CHECK (("length"(TRIM(BOTH FROM "legal_name")) > 0)),
    CONSTRAINT "client_billing_profiles_verification_digit_length" CHECK ((("verification_digit" IS NULL) OR ("length"(TRIM(BOTH FROM "verification_digit")) <= 2)))
);


