CREATE TABLE IF NOT EXISTS "public"."inventory_entry_items" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "entry_id" "uuid" NOT NULL,
    "product_id" "uuid" NOT NULL,
    "quantity_declared" numeric NOT NULL,
    "quantity_received" numeric NOT NULL,
    "unit" "text",
    "notes" "text",
    "discrepancy" numeric GENERATED ALWAYS AS (("quantity_received" - "quantity_declared")) STORED,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "location_id" "uuid",
    "input_qty" numeric,
    "input_unit_code" "text",
    "conversion_factor_to_stock" numeric,
    "stock_unit_code" "text",
    "input_unit_cost" numeric,
    "stock_unit_cost" numeric,
    "line_total_cost" numeric,
    "cost_source" "text",
    "currency" "text" DEFAULT 'COP'::"text",
    "purchase_order_item_id" "uuid",
    "tax_included" boolean,
    "tax_rate" numeric,
    "net_unit_cost" numeric,
    "gross_unit_cost" numeric,
    "lot_number" "text",
    "expiry_date" "date",
    "location_position_id" "uuid",
    "input_uom_profile_id" "uuid",
    "supplier_product_cost_id" "uuid",
    "cost_input_mode" "text",
    "net_total_cost" numeric,
    "gross_total_cost" numeric,
    "tax_amount" numeric,
    "iva_rate" numeric DEFAULT 0,
    "iva_amount" numeric DEFAULT 0,
    "icui_rate" numeric DEFAULT 0,
    "icui_amount" numeric DEFAULT 0,
    "total_tax_rate" numeric DEFAULT 0,
    "qty_base" numeric GENERATED ALWAYS AS (COALESCE("quantity_received",
CASE
    WHEN (("input_qty" IS NOT NULL) AND ("conversion_factor_to_stock" IS NOT NULL)) THEN ("input_qty" * "conversion_factor_to_stock")
    ELSE NULL::numeric
END)) STORED,
    CONSTRAINT "inventory_entry_items_cost_input_mode_chk" CHECK ((("cost_input_mode" IS NULL) OR ("cost_input_mode" = ANY (ARRAY['net'::"text", 'gross'::"text"])))),
    CONSTRAINT "inventory_entry_items_cost_source_chk" CHECK ((("cost_source" IS NULL) OR ("cost_source" = ANY (ARRAY['manual'::"text", 'po_prefill'::"text", 'fallback_product_cost'::"text"])))),
    CONSTRAINT "inventory_entry_items_tax_rate_chk" CHECK ((("tax_rate" IS NULL) OR (("tax_rate" >= (0)::numeric) AND ("tax_rate" <= (100)::numeric))))
);


ALTER TABLE "public"."inventory_entry_items" OWNER TO "postgres";


COMMENT ON COLUMN "public"."inventory_entry_items"."location_position_id" IS 'Optional internal position inside the destination inventory location for received items.';



COMMENT ON COLUMN "public"."inventory_entry_items"."iva_rate" IS 'Porcentaje de IVA aplicado en la línea de recepción ORIGO.';



COMMENT ON COLUMN "public"."inventory_entry_items"."iva_amount" IS 'Valor de IVA calculado para la línea de recepción ORIGO.';



COMMENT ON COLUMN "public"."inventory_entry_items"."icui_rate" IS 'Porcentaje de ICUI aplicado en la línea de recepción ORIGO.';



COMMENT ON COLUMN "public"."inventory_entry_items"."icui_amount" IS 'Valor de ICUI calculado para la línea de recepción ORIGO.';



COMMENT ON COLUMN "public"."inventory_entry_items"."total_tax_rate" IS 'Suma operativa de impuestos aplicados en la línea: IVA + ICUI.';



COMMENT ON COLUMN "public"."inventory_entry_items"."qty_base" IS 'Legacy read alias for received stock quantity. Prefer quantity_received or input_qty with conversion_factor_to_stock.';



