CREATE OR REPLACE VIEW "public"."permission_catalog_human_v1" AS
 SELECT "ap"."id",
    "a"."code" AS "app_code",
    "ap"."code",
    (("a"."code" || '.'::"text") || "ap"."code") AS "full_code",
    COALESCE(NULLIF("ap"."human_label", ''::"text"), NULLIF("ap"."name", ''::"text"), "ap"."code") AS "label",
    COALESCE(NULLIF("ap"."human_description", ''::"text"), NULLIF("ap"."description", ''::"text"), 'Define que puede hacer este rol dentro de Vento OS.'::"text") AS "description",
    COALESCE(NULLIF("ap"."human_group", ''::"text"), 'General'::"text") AS "group_label",
    "ap"."permission_audience",
    "ap"."is_operational",
    "ap"."requires_active_work_context",
    "ap"."human_sort_order",
    "ap"."is_active",
    "ap"."created_at",
    "ap"."updated_at",
    (NULLIF("ap"."human_label", ''::"text") IS NOT NULL) AS "is_human_configured"
   FROM ("public"."app_permissions" "ap"
     JOIN "public"."apps" "a" ON (("a"."id" = "ap"."app_id")));


ALTER VIEW "public"."permission_catalog_human_v1" OWNER TO "postgres";


