    CONSTRAINT "procurement_supplier_product_costs_qty_chk" CHECK ((("conversion_factor_to_stock" > (0)::numeric) AND ("total_input_qty" >= (0)::numeric) AND ("total_stock_qty" >= (0)::numeric) AND ("samples_count" >= 0)))
);


