    CONSTRAINT "product_request_policies_step_positive_chk" CHECK ((("request_step_qty" IS NULL) OR ("request_step_qty" > (0)::numeric))),
    CONSTRAINT "product_request_policies_strict_step_chk" CHECK ((("constraint_mode" <> 'strict_multiple'::"text") OR ("request_step_qty" IS NOT NULL))),
