COMMENT ON COLUMN "public"."restock_request_items"."input_aux_count" IS 'Optional auxiliary count requested/input for count_with_weight products. Example: 12 pieces while quantity is 2850 g.';



COMMENT ON COLUMN "public"."restock_request_items"."prepared_aux_count" IS 'Auxiliary count prepared at origin for count_with_weight products.';



COMMENT ON COLUMN "public"."restock_request_items"."shipped_aux_count" IS 'Auxiliary count shipped from origin for count_with_weight products.';



COMMENT ON COLUMN "public"."restock_request_items"."received_aux_count" IS 'Auxiliary count received at destination for count_with_weight products.';



COMMENT ON COLUMN "public"."restock_request_items"."shortage_aux_count" IS 'Auxiliary count registered as shortage for count_with_weight products.';



CREATE OR REPLACE VIEW "public"."product_request_policy_audit" WITH ("security_invoker"='true') AS
 SELECT 'error'::"text" AS "severity",
    'inventory_product_without_active_policy'::"text" AS "issue_code",
    "p"."id" AS "product_id",
    NULL::"uuid" AS "request_policy_id",
    'Producto inventariable activo sin política de solicitud activa.'::"text" AS "detail"
   FROM ("public"."products" "p"
     JOIN "public"."product_inventory_profiles" "pip" ON ((("pip"."product_id" = "p"."id") AND ("pip"."track_inventory" = true))))
  WHERE (("p"."is_active" = true) AND (NOT (EXISTS ( SELECT 1
           FROM "public"."product_request_policies" "prp"
          WHERE (("prp"."product_id" = "p"."id") AND ("prp"."is_active" = true))))))
UNION ALL
 SELECT 'error'::"text" AS "severity",
    'product_without_active_default_policy'::"text" AS "issue_code",
    "p"."id" AS "product_id",
    NULL::"uuid" AS "request_policy_id",
    'Producto con políticas activas pero sin política predeterminada activa.'::"text" AS "detail"
   FROM "public"."products" "p"
  WHERE (("p"."is_active" = true) AND (EXISTS ( SELECT 1
           FROM "public"."product_request_policies" "prp"
          WHERE (("prp"."product_id" = "p"."id") AND ("prp"."is_active" = true)))) AND (NOT (EXISTS ( SELECT 1
           FROM "public"."product_request_policies" "prp"
          WHERE (("prp"."product_id" = "p"."id") AND ("prp"."is_active" = true) AND ("prp"."is_default" = true))))))
UNION ALL
 SELECT 'error'::"text" AS "severity",
    'policy_base_unit_mismatch'::"text" AS "issue_code",
    "prp"."product_id",
    "prp"."id" AS "request_policy_id",
    'La unidad base de la política no coincide con la unidad base actual del producto.'::"text" AS "detail"
   FROM ("public"."product_request_policies" "prp"
     JOIN "public"."products" "p" ON (("p"."id" = "prp"."product_id")))
  WHERE (("prp"."is_active" = true) AND ("lower"("btrim"("prp"."base_unit_code")) <> "lower"("btrim"(COALESCE(NULLIF("p"."stock_unit_code", ''::"text"), NULLIF("p"."unit", ''::"text"))))))
UNION ALL
 SELECT 'error'::"text" AS "severity",
    'physical_profile_invalid'::"text" AS "issue_code",
    "prp"."product_id",
    "prp"."id" AS "request_policy_id",
    'La presentación física vinculada no existe, está inactiva o pertenece a otro producto.'::"text" AS "detail"
   FROM ("public"."product_request_policies" "prp"
     LEFT JOIN "public"."product_uom_profiles" "pup" ON (("pup"."id" = "prp"."physical_uom_profile_id")))
  WHERE (("prp"."is_active" = true) AND ("prp"."policy_kind" = 'physical_presentation'::"text") AND (("pup"."id" IS NULL) OR ("pup"."is_active" = false) OR ("pup"."product_id" <> "prp"."product_id")))
UNION ALL
 SELECT 'error'::"text" AS "severity",
    'used_policy_missing_snapshot'::"text" AS "issue_code",
    "rri"."product_id",
    "rri"."request_policy_id",
    'Línea con política de solicitud sin snapshot histórico completo.'::"text" AS "detail"
   FROM "public"."restock_request_items" "rri"
  WHERE (("rri"."request_policy_id" IS NOT NULL) AND (("rri"."request_policy_kind" IS NULL) OR ("rri"."request_policy_label" IS NULL) OR ("rri"."requested_policy_qty" IS NULL) OR ("rri"."request_unit_code" IS NULL) OR ("rri"."base_qty_per_request_unit" IS NULL) OR ("rri"."request_constraint_mode" IS NULL) OR ("rri"."request_allow_fraction" IS NULL)))
UNION ALL
 SELECT 'warning'::"text" AS "severity",
    'policy_line_still_requires_package_dispatch'::"text" AS "issue_code",
    "rri"."product_id",
    "rri"."request_policy_id",
    'Línea creada con política explícita pero aún marcada para despacho por paquete de producción.'::"text" AS "detail"
   FROM "public"."restock_request_items" "rri"
  WHERE (("rri"."request_policy_id" IS NOT NULL) AND (COALESCE("rri"."requires_package_dispatch", false) = true));


ALTER VIEW "public"."product_request_policy_audit" OWNER TO "postgres";


COMMENT ON VIEW "public"."product_request_policy_audit" IS 'Hallazgos de consistencia exclusivos del modelo de políticas de solicitud.';



CREATE OR REPLACE VIEW "public"."product_request_policy_audit_summary" WITH ("security_invoker"='true') AS
 WITH "usage_counts" AS (
         SELECT "restock_request_items"."request_policy_id",
            "count"(*) AS "usage_count",
            "count"(*) FILTER (WHERE ((COALESCE("restock_request_items"."request_policy_label", ''::"text") = ''::"text") OR ("restock_request_items"."requested_policy_qty" IS NULL) OR ("restock_request_items"."request_unit_code" IS NULL) OR ("restock_request_items"."base_qty_per_request_unit" IS NULL))) AS "incomplete_snapshot_count"
           FROM "public"."restock_request_items"
          WHERE ("restock_request_items"."request_policy_id" IS NOT NULL)
          GROUP BY "restock_request_items"."request_policy_id"
        ), "policy_rows" AS (
         SELECT "p"."id" AS "product_id",
            "p"."name" AS "product_name",
            "lower"(COALESCE(NULLIF("p"."stock_unit_code", ''::"text"), NULLIF("p"."unit", ''::"text"))) AS "product_base_unit_code",
            "prp"."id" AS "policy_id",
            "prp"."label",
            "prp"."request_unit_code",
            "prp"."base_unit_code",
            "prp"."base_qty_per_request_unit",
            "prp"."constraint_mode",
            "prp"."minimum_request_qty",
            "prp"."request_step_qty",
            "prp"."allow_fraction",
            "prp"."policy_kind",
            "prp"."physical_uom_profile_id",
            "prp"."is_default",
            "prp"."is_active",
            "prp"."version_number",
            "prp"."supersedes_policy_id",
            COALESCE("u"."usage_count", (0)::bigint) AS "usage_count",
            COALESCE("u"."incomplete_snapshot_count", (0)::bigint) AS "incomplete_snapshot_count",
            "pup"."product_id" AS "physical_profile_product_id",
            "pup"."is_active" AS "physical_profile_is_active"
           FROM (((("public"."products" "p"
             JOIN "public"."product_inventory_profiles" "pip" ON ((("pip"."product_id" = "p"."id") AND ("pip"."track_inventory" = true))))
             LEFT JOIN "public"."product_request_policies" "prp" ON (("prp"."product_id" = "p"."id")))
             LEFT JOIN "usage_counts" "u" ON (("u"."request_policy_id" = "prp"."id")))
             LEFT JOIN "public"."product_uom_profiles" "pup" ON (("pup"."id" = "prp"."physical_uom_profile_id")))
          WHERE ("p"."is_active" = true)
        )
 SELECT "product_id",
    "product_name",
    "product_base_unit_code",
    "policy_id",
    "label",
    "request_unit_code",
    "base_unit_code",
    "base_qty_per_request_unit",
    "constraint_mode",
    "minimum_request_qty",
    "request_step_qty",
    "allow_fraction",
    "policy_kind",
    "physical_uom_profile_id",
    "is_default",
    "is_active",
    "version_number",
    "supersedes_policy_id",
    "usage_count",
    "incomplete_snapshot_count",
    "physical_profile_product_id",
    "physical_profile_is_active",
    "array_remove"(ARRAY[
        CASE
            WHEN ("policy_id" IS NULL) THEN 'missing_policy'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("policy_id" IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
               FROM "public"."product_request_policies" "default_policy"
              WHERE (("default_policy"."product_id" = "policy_rows"."product_id") AND "default_policy"."is_active" AND "default_policy"."is_default"))))) THEN 'missing_default'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("policy_id" IS NOT NULL) AND ("base_unit_code" IS DISTINCT FROM "product_base_unit_code")) THEN 'base_unit_mismatch'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("policy_kind" = 'base_unit'::"text") AND (("request_unit_code" IS DISTINCT FROM "base_unit_code") OR ("base_qty_per_request_unit" <> (1)::numeric))) THEN 'invalid_base_policy'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("policy_kind" = 'logical_group'::"text") AND ("physical_uom_profile_id" IS NOT NULL)) THEN 'logical_group_has_physical_profile'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("policy_kind" = 'physical_presentation'::"text") AND ("physical_uom_profile_id" IS NULL)) THEN 'physical_policy_missing_profile'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("physical_uom_profile_id" IS NOT NULL) AND ("physical_profile_product_id" IS DISTINCT FROM "product_id")) THEN 'physical_profile_product_mismatch'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("physical_uom_profile_id" IS NOT NULL) AND (COALESCE("physical_profile_is_active", false) IS FALSE)) THEN 'physical_profile_inactive'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN ("incomplete_snapshot_count" > 0) THEN 'incomplete_historical_snapshot'::"text"
            ELSE NULL::"text"
        END], NULL::"text") AS "issues"
   FROM "policy_rows";


