CREATE OR REPLACE VIEW "public"."product_request_policy_usage" WITH ("security_invoker"='true') AS
 SELECT "p"."id" AS "request_policy_id",
    "p"."product_id",
    "count"("rri"."id") AS "use_count",
    "count"("rri"."id") FILTER (WHERE (("rr"."status" <> ALL (ARRAY['completed'::"text", 'cancelled'::"text"])) OR ("rr"."status" IS NULL))) AS "open_use_count",
    "min"("rri"."created_at") AS "first_used_at",
    "max"("rri"."created_at") AS "last_used_at"
   FROM (("public"."product_request_policies" "p"
     LEFT JOIN "public"."restock_request_items" "rri" ON (("rri"."request_policy_id" = "p"."id")))
     LEFT JOIN "public"."restock_requests" "rr" ON (("rr"."id" = "rri"."request_id")))
  GROUP BY "p"."id", "p"."product_id";


