CREATE TABLE IF NOT EXISTS "public"."restock_item_fulfillments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "request_item_id" "uuid" NOT NULL,
    "product_id" "uuid" NOT NULL,
    "route_id" "uuid",
    "from_site_id" "uuid" NOT NULL,
    "to_site_id" "uuid" NOT NULL,
    "requesting_area_kind" "text",
    "preparing_area_kind" "text",
    "source_location_id" "uuid",
    "destination_location_id" "uuid",
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "requested_base_qty" numeric NOT NULL,
    "reserved_base_qty" numeric DEFAULT 0 NOT NULL,
    "ready_base_qty" numeric DEFAULT 0 NOT NULL,
    "released_base_qty" numeric DEFAULT 0 NOT NULL,
    "cancelled_base_qty" numeric DEFAULT 0 NOT NULL,
    "available_at" timestamp with time zone,
    "shortage_reason" "text",
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid",
    "allocated_base_qty" numeric DEFAULT 0 NOT NULL,
    "supply_mode" "text",
    "production_execution_mode" "text",
    "ready_location_id" "uuid",
    CONSTRAINT "restock_fulfillments_production_mode_check" CHECK ((("production_execution_mode" IS NULL) OR ("production_execution_mode" = ANY (ARRAY['simple'::"text", 'recipe'::"text"])))),
    CONSTRAINT "restock_fulfillments_route_snapshot_check" CHECK (((("supply_mode" = 'production'::"text") AND ("production_execution_mode" IS NOT NULL) AND ("ready_location_id" IS NOT NULL)) OR (("supply_mode" IS DISTINCT FROM 'production'::"text") AND ("production_execution_mode" IS NULL) AND ("ready_location_id" IS NULL)))),
    CONSTRAINT "restock_fulfillments_supply_mode_check" CHECK ((("supply_mode" IS NULL) OR ("supply_mode" = ANY (ARRAY['stock'::"text", 'production'::"text", 'supplier'::"text", 'transfer'::"text", 'manual'::"text"])))),
    CONSTRAINT "restock_item_fulfillments_allocated_base_qty_check" CHECK (("allocated_base_qty" >= (0)::numeric)),
    CONSTRAINT "restock_item_fulfillments_allocated_within_ready" CHECK (("allocated_base_qty" <= "ready_base_qty")),
    CONSTRAINT "restock_item_fulfillments_allocations_within_requested" CHECK (((("reserved_base_qty" + "released_base_qty") + "cancelled_base_qty") <= "requested_base_qty")),
    CONSTRAINT "restock_item_fulfillments_cancelled_base_qty_check" CHECK (("cancelled_base_qty" >= (0)::numeric)),
    CONSTRAINT "restock_item_fulfillments_distinct_sites" CHECK (("from_site_id" <> "to_site_id")),
    CONSTRAINT "restock_item_fulfillments_ready_base_qty_check" CHECK (("ready_base_qty" >= (0)::numeric)),
    CONSTRAINT "restock_item_fulfillments_released_base_qty_check" CHECK (("released_base_qty" >= (0)::numeric)),
    CONSTRAINT "restock_item_fulfillments_requested_base_qty_check" CHECK (("requested_base_qty" > (0)::numeric)),
    CONSTRAINT "restock_item_fulfillments_reserved_base_qty_check" CHECK (("reserved_base_qty" >= (0)::numeric)),
    CONSTRAINT "restock_item_fulfillments_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'reserved'::"text", 'preparing'::"text", 'partially_ready'::"text", 'ready'::"text", 'allocated'::"text", 'blocked'::"text", 'reassigned'::"text", 'released'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."restock_item_fulfillments" OWNER TO "postgres";


COMMENT ON TABLE "public"."restock_item_fulfillments" IS 'Tareas y cantidades de cumplimiento para una necesidad; permite preparación parcial sin cerrar la solicitud.';



COMMENT ON COLUMN "public"."restock_item_fulfillments"."supply_mode" IS 'Copia del modo de abastecimiento de la ruta al crear la tarea. No cambia automaticamente si la ruta se modifica despues.';



COMMENT ON COLUMN "public"."restock_item_fulfillments"."production_execution_mode" IS 'Copia del modo de ejecucion productiva: simple registra cantidad producida sin receta; recipe usa produccion real de FOGO.';



COMMENT ON COLUMN "public"."restock_item_fulfillments"."ready_location_id" IS 'LOC donde el area productora deja el terminado listo para despacho. No representa una posicion interna.';



CREATE TABLE IF NOT EXISTS "public"."restock_request_item_picks" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "request_id" "uuid" NOT NULL,
    "item_id" "uuid" NOT NULL,
    "product_id" "uuid" NOT NULL,
    "source_location_id" "uuid" NOT NULL,
    "source_location_position_id" "uuid",
    "uom_profile_id" "uuid",
    "presentation_qty" numeric DEFAULT 0 NOT NULL,
    "base_qty" numeric DEFAULT 0 NOT NULL,
    "note" "text",
    "created_by" "uuid" DEFAULT "auth"."uid"(),
    "updated_by" "uuid",
    CONSTRAINT "restock_request_item_picks_base_qty_positive_chk" CHECK (("base_qty" > (0)::numeric)),
    CONSTRAINT "restock_request_item_picks_presentation_qty_nonnegative_chk" CHECK (("presentation_qty" >= (0)::numeric)),
    CONSTRAINT "restock_request_item_picks_uom_profile_presentation_chk" CHECK (((("uom_profile_id" IS NULL) AND ("presentation_qty" = (0)::numeric)) OR (("uom_profile_id" IS NOT NULL) AND ("presentation_qty" > (0)::numeric))))
);


ALTER TABLE "public"."restock_request_item_picks" OWNER TO "postgres";


COMMENT ON TABLE "public"."restock_request_item_picks" IS 'Plan físico de salida para remisiones. Una línea de restock_request_items puede tener varios picks por LOC, posición interna y presentación física.';



COMMENT ON COLUMN "public"."restock_request_item_picks"."source_location_position_id" IS 'Posición interna dentro del LOC origen: estantería, nivel, bin, zona interna, etc.';



COMMENT ON COLUMN "public"."restock_request_item_picks"."uom_profile_id" IS 'Presentación física usada para el pick. Null para productos sin presentación física específica o productos por unidad/rendimiento.';



COMMENT ON COLUMN "public"."restock_request_item_picks"."presentation_qty" IS 'Cantidad de presentación física despachada, cuando el pick usa product_uom_profiles. Ej: 2 potes.';



COMMENT ON COLUMN "public"."restock_request_item_picks"."base_qty" IS 'Cantidad en unidad base/stock que se despacha desde este pick.';



