    CONSTRAINT "shared_device_actor_policies_shape_check" CHECK (((("policy_type" = 'same_site_active_worker'::"text") AND ("site_id" IS NOT NULL) AND ("area_id" IS NULL) AND ("role_code" IS NULL) AND ("employee_id" IS NULL)) OR (("policy_type" = 'same_area_active_worker'::"text") AND ("site_id" IS NOT NULL) AND ("area_id" IS NOT NULL) AND ("role_code" IS NULL) AND ("employee_id" IS NULL)) OR (("policy_type" = 'role_in_site'::"text") AND ("site_id" IS NOT NULL) AND ("area_id" IS NULL) AND ("role_code" IS NOT NULL) AND ("employee_id" IS NULL)) OR (("policy_type" = 'role_in_area'::"text") AND ("site_id" IS NOT NULL) AND ("area_id" IS NOT NULL) AND ("role_code" IS NOT NULL) AND ("employee_id" IS NULL)) OR (("policy_type" = 'specific_employee'::"text") AND ("employee_id" IS NOT NULL)) OR (("policy_type" = 'any_active_worker'::"text") AND ("site_id" IS NULL) AND ("area_id" IS NULL) AND ("role_code" IS NULL) AND ("employee_id" IS NULL))))
);


