CREATE OR REPLACE VIEW "public"."v_asset_groups_inventory_status" WITH ("security_invoker"='true') AS
 SELECT "ag"."id",
    "ag"."product_id",
    "p"."name" AS "product_name",
    "p"."sku" AS "product_sku",
    "ag"."group_code",
    "ag"."qr_token",
    "ag"."name",
    "ag"."expected_qty",
    "ag"."unit_code",
    "ag"."condition_status",
    "ag"."lifecycle_status",
    "ag"."site_id",
    "s"."name" AS "site_name",
    "ag"."area_id",
    "a"."name" AS "area_name",
    "a"."kind" AS "area_kind",
    "ag"."location_id",
    "il"."code" AS "location_code",
    "il"."zone" AS "location_zone",
    "ag"."location_position_id",
    "ilp"."code" AS "position_code",
    "ilp"."name" AS "position_name",
    "ag"."responsible_employee_id",
    "e"."full_name" AS "responsible_name",
