CREATE OR REPLACE VIEW "public"."vento_site_operational_role_matrix_v1" WITH ("security_invoker"='true') AS
 SELECT "sor"."id",
    "sor"."site_id",
    "s"."name" AS "site_name",
    "s"."code" AS "site_code",
    "s"."site_type",
    "sor"."area_id",
    "a"."name" AS "area_name",
    "a"."kind" AS "area_kind",
    "sor"."role_code",
    "opr"."label" AS "role_label",
    "opr"."description" AS "role_description",
    "opr"."role_family",
    "opr"."requires_external_checkin",
    "opr"."requires_external_checkout",
    "sor"."is_default",
    "sor"."is_active",
    "sor"."created_at",
    "sor"."updated_at"
   FROM ((("public"."site_operational_roles" "sor"
     JOIN "public"."sites" "s" ON (("s"."id" = "sor"."site_id")))
     LEFT JOIN "public"."areas" "a" ON (("a"."id" = "sor"."area_id")))
     JOIN "public"."operational_roles" "opr" ON (("opr"."code" = "sor"."role_code")));


