CREATE OR REPLACE VIEW "public"."shared_operational_device_templates_admin_v1" AS
 SELECT "t"."id",
    "t"."code",
    "t"."label",
    "t"."description",
    "t"."device_type",
    "t"."default_app_code",
    "t"."requires_actor_pin",
    "t"."requires_active_actor_shift",
    "t"."allow_actor_without_pin",
    "t"."allow_actions_without_actor",
    "t"."is_active",
    "t"."sort_order",
    COALESCE("array_agg"(DISTINCT "ta"."app_code" ORDER BY "ta"."app_code") FILTER (WHERE "ta"."is_active"), '{}'::"text"[]) AS "app_codes",
    COALESCE("jsonb_agg"(DISTINCT "jsonb_build_object"('policy_type', "tp"."policy_type", 'scope_strategy', "tp"."scope_strategy", 'role_code', "tp"."role_code", 'employee_id', "tp"."employee_id", 'notes', "tp"."notes")) FILTER (WHERE "tp"."is_active"), '[]'::"jsonb") AS "actor_policies",
    "t"."metadata",
    "t"."created_at",
    "t"."updated_at",
    "t"."navigation_role"
   FROM (("public"."shared_operational_device_templates" "t"
     LEFT JOIN "public"."shared_operational_device_template_apps" "ta" ON (("ta"."template_id" = "t"."id")))
     LEFT JOIN "public"."shared_operational_device_template_actor_policies" "tp" ON (("tp"."template_id" = "t"."id")))
  GROUP BY "t"."id";



CREATE OR REPLACE VIEW "public"."shared_operational_devices_admin_v1" AS
 SELECT "d"."id",
    "d"."code",
    "d"."label",
    "d"."description",
    "d"."device_type",
    "d"."auth_user_id",
    "d"."site_id",
    "s"."name" AS "site_name",
    "s"."code" AS "site_code",
    "d"."area_id",
    "a"."name" AS "area_name",
    "a"."code" AS "area_code",
    "d"."default_app_code",
    "d"."requires_actor_pin",
    "d"."requires_active_actor_shift",
    "d"."allow_actor_without_pin",
    "d"."allow_actions_without_actor",
    "d"."activation_status",
    "d"."is_active",
    "d"."last_seen_at",
    COALESCE("array_agg"("da"."app_code" ORDER BY "da"."app_code") FILTER (WHERE "da"."is_active"), '{}'::"text"[]) AS "allowed_app_codes",
    "d"."metadata",
    "d"."created_at",
    "d"."updated_at",
    "d"."template_id",
    "t"."code" AS "template_code",
    "t"."label" AS "template_label",
    "d"."navigation_role"
   FROM (((("public"."shared_operational_devices" "d"
     LEFT JOIN "public"."sites" "s" ON (("s"."id" = "d"."site_id")))
     LEFT JOIN "public"."areas" "a" ON (("a"."id" = "d"."area_id")))
     LEFT JOIN "public"."shared_operational_device_templates" "t" ON (("t"."id" = "d"."template_id")))
     LEFT JOIN "public"."shared_operational_device_apps" "da" ON (("da"."device_id" = "d"."id")))
  GROUP BY "d"."id", "s"."id", "a"."id", "t"."id";



CREATE OR REPLACE VIEW "public"."v_asset_count_session_summary" WITH ("security_invoker"='true') AS
 SELECT "acs"."id" AS "session_id",
    "acs"."site_id",
    "s"."name" AS "site_name",
    "acs"."name",
    "acs"."status",
    "acs"."scope_type",
    "acs"."started_at",
    "acs"."closed_at",
    ("count"("acl"."id"))::integer AS "line_count",
    ("count"(*) FILTER (WHERE ("acl"."count_status" = 'found'::"text")))::integer AS "found_count",
    ("count"(*) FILTER (WHERE ("acl"."count_status" = 'missing'::"text")))::integer AS "missing_count",
    ("count"(*) FILTER (WHERE ("acl"."count_status" = 'found_elsewhere'::"text")))::integer AS "found_elsewhere_count",
    ("count"(*) FILTER (WHERE ("acl"."count_status" = 'damaged'::"text")))::integer AS "damaged_count",
    ("count"(*) FILTER (WHERE ("acl"."count_status" = 'extra'::"text")))::integer AS "extra_count"
   FROM (("public"."asset_count_sessions" "acs"
     LEFT JOIN "public"."sites" "s" ON (("s"."id" = "acs"."site_id")))
     LEFT JOIN "public"."asset_count_lines" "acl" ON (("acl"."session_id" = "acs"."id")))
  GROUP BY "acs"."id", "s"."name";



