CREATE POLICY "loyalty_redemptions_select_cashier" ON "pass"."loyalty_redemptions" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM ("public"."employees" "e"
     JOIN "pass"."loyalty_rewards" "r" ON (("r"."id" = "loyalty_redemptions"."reward_id")))
  WHERE (("e"."id" = "auth"."uid"()) AND ("e"."is_active" = true) AND ("e"."role" = ANY (ARRAY['propietario'::"text", 'gerente'::"text", 'gerente_general'::"text", 'cajero'::"text", 'mesero'::"text"])) AND (("e"."site_id" = "r"."site_id") OR (EXISTS ( SELECT 1
           FROM "public"."employee_sites" "es"
          WHERE (("es"."employee_id" = "e"."id") AND ("es"."is_active" = true) AND ("es"."site_id" = "r"."site_id")))))))));



CREATE POLICY "loyalty_redemptions_select_own" ON "pass"."loyalty_redemptions" FOR SELECT TO "authenticated" USING (("user_id" = "auth"."uid"()));



CREATE POLICY "loyalty_redemptions_validate_cashier" ON "pass"."loyalty_redemptions" FOR UPDATE TO "authenticated" USING ((("status" = 'pending'::"text") AND (EXISTS ( SELECT 1
   FROM ("public"."employees" "e"
     JOIN "pass"."loyalty_rewards" "r" ON (("r"."id" = "loyalty_redemptions"."reward_id")))
  WHERE (("e"."id" = "auth"."uid"()) AND ("e"."is_active" = true) AND ("e"."role" = ANY (ARRAY['propietario'::"text", 'gerente'::"text", 'gerente_general'::"text", 'cajero'::"text", 'mesero'::"text"])) AND (("e"."site_id" = "r"."site_id") OR (EXISTS ( SELECT 1
           FROM "public"."employee_sites" "es"
          WHERE (("es"."employee_id" = "e"."id") AND ("es"."is_active" = true) AND ("es"."site_id" = "r"."site_id")))))))))) WITH CHECK ((("status" = 'validated'::"text") AND (EXISTS ( SELECT 1
   FROM ("public"."employees" "e"
     JOIN "pass"."loyalty_rewards" "r" ON (("r"."id" = "loyalty_redemptions"."reward_id")))
  WHERE (("e"."id" = "auth"."uid"()) AND ("e"."is_active" = true) AND ("e"."role" = ANY (ARRAY['propietario'::"text", 'gerente'::"text", 'gerente_general'::"text", 'cajero'::"text", 'mesero'::"text"])) AND (("e"."site_id" = "r"."site_id") OR (EXISTS ( SELECT 1
           FROM "public"."employee_sites" "es"
          WHERE (("es"."employee_id" = "e"."id") AND ("es"."is_active" = true) AND ("es"."site_id" = "r"."site_id"))))))))));



